        content.Children.Add(hint);
        Grid.SetRow(friendsList, 2);
        content.Children.Add(friendsList);
        Grid.SetRow(friendsStatusText, 3);
        content.Children.Add(friendsStatusText);

        friendsPanel.Width = 330;
        friendsPanel.MaxHeight = 520;
        friendsPanel.HorizontalAlignment = HorizontalAlignment.Right;
        friendsPanel.VerticalAlignment = VerticalAlignment.Top;
        friendsPanel.Margin = new Thickness(0, 44, 8, 0);
        friendsPanel.Padding = new Thickness(6);
