    private Control BuildCompactFriendRow(OnlinePlayerProfileDto? friend)
    {
        if (friend == null) return new Border { Height = 1 };
        var row = new Grid
        {
            Width = 306,
            Height = 50,
            ColumnDefinitions = new ColumnDefinitions("38,*,48,48"),
            Margin = new Thickness(0, 0, 0, 5),
            Background = Brushes.Transparent
        };
        var avatar = new WindowsDefaultUserAvatar(
            31,
            new SolidColorBrush(Color.Parse("#59666A")),
            1,
            $"FriendsPanel.Friend.{friend.Id}.Avatar")
        {
            HorizontalAlignment = HorizontalAlignment.Center,
            VerticalAlignment = VerticalAlignment.Center
        };
        BindRemoteAvatar(avatar, friend.AvatarKey, friend.DisplayName);
        row.Children.Add(avatar);
        var identity = new StackPanel
        {
            Margin = new Thickness(4, 0, 4, 0),
            VerticalAlignment = VerticalAlignment.Center,
            Children =
            {
                new TextBlock
                {
                    Text = friend.DisplayName,
                    Foreground = new SolidColorBrush(Color.Parse("#E1E6E7")),
                    FontWeight = FontWeight.SemiBold,
                    FontSize = 11,
                    TextTrimming = TextTrimming.CharacterEllipsis
                },
                new TextBlock
                {
                    Text = friend.IsOnline ? "在线" : "离线",
                    Foreground = new SolidColorBrush(Color.Parse(
                        friend.IsOnline ? "#789B87" : "#6F7A7E")),
                    FontSize = 9
                }
            }
        };
        Grid.SetColumn(identity, 1);
        row.Children.Add(identity);

        var profile = CompactOnlineActionButton("主页");
        AutomationProperties.SetAutomationId(
            profile,
            $"FriendsPanel.Friend.{friend.Id}.Profile");
        profile.Click += async (_, _) =>
        {
            HideFriendsPanel();
            await ShowOnlinePlayerPopupAsync(friend.Id, roomMember: null);
        };
        Grid.SetColumn(profile, 2);
        row.Children.Add(profile);

        var invite = CompactOnlineActionButton("邀请");
        invite.Tag = friend.IsOnline;
        invite.IsEnabled =
            onlineAccountHost?.Session.CurrentRoom != null &&
            onlineAccountHost.Session.CurrentUser?.Id != friend.Id &&
            friend.IsOnline;
        friendInviteButtons[friend.Id] = invite;
        ApplyFriendInviteCooldown(friend.Id, invite);
        AutomationProperties.SetAutomationId(
            invite,
            $"FriendsPanel.Friend.{friend.Id}.Invite");
        invite.Click += async (_, _) =>
            await InviteFriendToCurrentRoomAsync(friend, invite);
        Grid.SetColumn(invite, 3);
        row.Children.Add(invite);
        AutomationProperties.SetName(
            row,
            AvaloniaLocalizationCatalog.Format("好友 {0} · {1}", friend.DisplayName, (friend.IsOnline ? AvaloniaLocalizationCatalog.Text("在线") : AvaloniaLocalizationCatalog.Text("离线"))));
        return row;
    }

    private static Button CompactOnlineActionButton(string text) => new()
    {
        Content = text,
        Width = 44,
        Height = 32,
        Padding = new Thickness(0),
        HorizontalAlignment = HorizontalAlignment.Center,
        VerticalAlignment = VerticalAlignment.Center,
        HorizontalContentAlignment = HorizontalAlignment.Center,
        VerticalContentAlignment = VerticalAlignment.Center,
        Background = Brushes.Transparent,
        Foreground = new SolidColorBrush(Color.Parse("#D3DADB")),
        BorderBrush = new SolidColorBrush(Color.Parse("#344044")),
        BorderThickness = new Thickness(1),
        CornerRadius = new CornerRadius(3)
    };

    private async Task ToggleFriendsPanelAsync()
    {
        startupAccountChoiceHandled = true;
        if (friendsPanel.IsVisible)
        {
            HideFriendsPanel();
            return;
        }
        if (onlineSurfaceCompletion != null || onlineAccountEntryInProgress) return;
        if (onlineAccountHost == null)
        {
            viewModel.SetStatus(
                AvaloniaLocalizationCatalog.Format("好友功能不可用：{0}", onlineHostError ?? AvaloniaLocalizationCatalog.Text("联机配置无效")));
            return;
        }
        try
        {
            if (!onlineAccountHost.Session.IsAuthenticated)
            {
                var accepted =
                    await ShowHostedOnlineAccountAsync(onlineAccountHost.Session);
                UpdateOnlineAccountUi();
                if (!accepted || !onlineAccountHost.Session.IsAuthenticated) return;
            }

            friendsPanel.IsVisible = true;
            friendsStatusText.Text = "正在载入好友…";
            await RefreshFriendsPanelAsync();
        }
        catch (Exception exception)
        {
            // Last-resort boundary for the title-bar async handler; network
            // failures are already reported inside RefreshFriendsPanelAsync.
            Debug.WriteLine($"Friends panel failed: {exception}");
            if (windowCloseTeardownStarted) return;
            viewModel.SetStatus(
                AvaloniaLocalizationCatalog.Format("好友功能不可用：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
        }
    }

    private void HideFriendsPanel()
    {
        // Detach the in-flight load as well as canceling it. Otherwise a quick
        // reopen is deduplicated against the canceled load, which then reports
        // its own cancellation as "载入好友失败" and never reloads.
        friendsPanelLoadCancellation?.Cancel();
        friendsPanelLoadCancellation = null;
        friendsPanel.IsVisible = false;
        friendsStatusText.Text = string.Empty;
    }

    private async Task RefreshFriendsPanelAsync()
    {
        if (friendsPanelLoadCancellation != null ||
            onlineAccountHost?.Session.IsAuthenticated != true)
            return;
        using var timeout = new CancellationTokenSource(TimeSpan.FromSeconds(15));
        friendsPanelLoadCancellation = timeout;
        try
        {
            var directory =
                await onlineAccountHost.Session.GetFriendsAsync(timeout.Token);
            if (!ReferenceEquals(friendsPanelLoadCancellation, timeout) ||
                !friendsPanel.IsVisible)
                return;
            friendsOnlineCountText.Text = AvaloniaLocalizationCatalog.Format("在线 {0:N0}", directory.OnlineCount);
            friendInviteButtons.Clear();
            friendsList.ItemsSource = directory.Players;
            friendsStatusText.Text = directory.Players.Count == 0
                ? "暂无互相关注的好友"
                : AvaloniaLocalizationCatalog.Format("共 {0:N0} 名好友", directory.Players.Count);
        }
        catch (OperationCanceledException) when (
            !ReferenceEquals(friendsPanelLoadCancellation, timeout) ||
            !friendsPanel.IsVisible)
        {
        }
        catch (Exception exception) when (
            exception is OnlineApiException or HttpRequestException or
                OperationCanceledException or JsonException)
        {
            if (ReferenceEquals(friendsPanelLoadCancellation, timeout))
                friendsStatusText.Text = AvaloniaLocalizationCatalog.Format("载入好友失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message));
        }
        finally
        {
            if (ReferenceEquals(friendsPanelLoadCancellation, timeout))
                friendsPanelLoadCancellation = null;
        }
    }

    private async Task InviteFriendToCurrentRoomAsync(
        OnlinePlayerProfileDto friend,
        Button inviteButton)
    {
        var session = onlineAccountHost?.Session;
        if (session?.CurrentRoom == null)
        {
            friendsStatusText.Text = "请先进入联机房间";
            return;
        }
        inviteButton.IsEnabled = false;
        friendsStatusText.Text = AvaloniaLocalizationCatalog.Format("正在邀请 {0}…", friend.DisplayName);
        try
        {
            using var timeout =
                new CancellationTokenSource(TimeSpan.FromSeconds(15));
            _ = await session.InviteToCurrentRoomAsync(
                friend.Id,
                timeout.Token);
            friendInviteCooldowns[friend.Id] =
                DateTimeOffset.UtcNow.AddSeconds(15);
            ApplyFriendInviteCooldown(friend.Id, inviteButton);
            if (!friendInviteCooldownTimer.IsEnabled)
                friendInviteCooldownTimer.Start();
            friendsStatusText.Text = AvaloniaLocalizationCatalog.Format("已邀请 {0}", friend.DisplayName);
        }
        catch (Exception exception) when (
            exception is OnlineApiException or HttpRequestException or
                OperationCanceledException or JsonException)
        {
            friendsStatusText.Text = AvaloniaLocalizationCatalog.Format("邀请失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message));
            inviteButton.IsEnabled = session.CurrentRoom != null;
        }
    }

    private void RefreshFriendInviteCooldownButtons()
    {
        foreach (var pair in friendInviteButtons.ToArray())
            ApplyFriendInviteCooldown(pair.Key, pair.Value);
        if (friendInviteCooldowns.Count == 0)
            friendInviteCooldownTimer.Stop();
    }

    private void ApplyFriendInviteCooldown(long userId, Button button)
    {
        if (friendInviteCooldowns.TryGetValue(userId, out var until))
        {
            var remaining = until - DateTimeOffset.UtcNow;
            if (remaining > TimeSpan.Zero)
            {
                button.Content = $"{Math.Max(1, (int)Math.Ceiling(remaining.TotalSeconds))}s";
                button.IsEnabled = false;
                return;
            }
            friendInviteCooldowns.Remove(userId);
        }

        button.Content = "邀请";
        var session = onlineAccountHost?.Session;
        button.IsEnabled = session?.CurrentRoom != null &&
                           session.CurrentUser?.Id != userId &&
                           button.Tag is true;
    }

    private Control BuildOnlinePlayerPopupLayer()
    {
        onlinePlayerPopupContent.HorizontalAlignment = HorizontalAlignment.Center;
        onlinePlayerPopupContent.VerticalAlignment = VerticalAlignment.Center;
        onlinePlayerPopupContent.MaxWidth = 560;
        onlinePlayerPopupContent.MaxHeight = 760;

        onlinePlayerPopupLayer.HorizontalAlignment = HorizontalAlignment.Stretch;
        onlinePlayerPopupLayer.VerticalAlignment = VerticalAlignment.Stretch;
        onlinePlayerPopupLayer.Padding = new Thickness(18);
        onlinePlayerPopupLayer.Background =
            new SolidColorBrush(Color.Parse("#B0101214"));
        onlinePlayerPopupLayer.IsVisible = false;
        onlinePlayerPopupLayer.Child = onlinePlayerPopupContent;
        AutomationProperties.SetAutomationId(
            onlinePlayerPopupLayer,
            "Online.PlayerPopup");
        AutomationProperties.SetName(onlinePlayerPopupLayer, "玩家主页");
        return onlinePlayerPopupLayer;
    }

    private async Task ShowOnlinePlayerPopupAsync(
        long userId,
        OnlineRoomMemberDto? roomMember)
    {
        var session = onlineAccountHost?.Session;
        if (userId <= 0 || session?.IsAuthenticated != true) return;

        onlinePlayerPopupLoadCancellation?.Cancel();
        onlinePlayerPopupLoadCancellation?.Dispose();
        var timeout = new CancellationTokenSource(TimeSpan.FromSeconds(20));
        onlinePlayerPopupLoadCancellation = timeout;
        onlinePlayerPopupUserId = userId;
        onlinePlayerPopupLayer.IsVisible = true;
        SetOnlinePlayerPopupContent(BuildOnlinePlayerLoadingCard("正在载入玩家主页…"));
        try
        {
            var profile = await session.GetPlayerAsync(
                userId,
                roomMember == null ? null : session.CurrentRoom?.Id,
                timeout.Token);
            if (!ReferenceEquals(onlinePlayerPopupLoadCancellation, timeout) ||
                onlinePlayerPopupUserId != userId)
                return;
            SetOnlinePlayerPopupContent(BuildOnlinePlayerCard(profile, roomMember));
        }
        catch (OperationCanceledException) when (
            !ReferenceEquals(onlinePlayerPopupLoadCancellation, timeout) ||
            onlinePlayerPopupUserId != userId)
        {
        }
        catch (Exception exception) when (
            exception is OnlineApiException or HttpRequestException or
                OperationCanceledException or JsonException)
        {
            if (ReferenceEquals(onlinePlayerPopupLoadCancellation, timeout))
                SetOnlinePlayerPopupContent(
                    BuildOnlinePlayerLoadingCard(AvaloniaLocalizationCatalog.Format("载入玩家主页失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message))));
        }
    }

    private void SetOnlinePlayerPopupContent(Control content)
    {
        onlinePlayerPopupContent.Children.Clear();
        onlinePlayerPopupContent.Children.Add(content);
    }

    private Control BuildOnlinePlayerLoadingCard(string message)
    {
        var close = CompactOnlineActionButton("×");
        close.HorizontalAlignment = HorizontalAlignment.Right;
        close.Click += (_, _) => CloseOnlinePlayerPopup();
        var layout = new Grid
        {
            RowDefinitions = new RowDefinitions("Auto,*")
        };
        layout.Children.Add(close);
        var status = new TextBlock
        {
            Text = message,
            Margin = new Thickness(0, 28, 0, 10),
            Foreground = new SolidColorBrush(Color.Parse("#A8B4B7")),
            TextWrapping = TextWrapping.Wrap,
            HorizontalAlignment = HorizontalAlignment.Center
        };
        Grid.SetRow(status, 1);
        layout.Children.Add(status);
        return OnlinePlayerPopupCard(layout);
    }

    private Control BuildOnlinePlayerCard(
        OnlinePlayerProfileDto profile,
        OnlineRoomMemberDto? initialRoomMember)
    {
        var session = onlineAccountHost?.Session ??
                      throw new InvalidOperationException("联机账号会话不可用。");
        var roomMember = initialRoomMember;
        var status = new TextBlock
        {
            Text = profile.IsOnline ? "当前在线" : "当前离线",
            Foreground = new SolidColorBrush(Color.Parse(
                profile.IsOnline ? "#8FC4A5" : "#788589")),
            FontSize = 9,
            Margin = new Thickness(0, 8, 0, 0),
            TextWrapping = TextWrapping.Wrap
        };
        var close = CompactOnlineActionButton("×");
        close.Width = 26;
        close.Height = 24;
        close.HorizontalAlignment = HorizontalAlignment.Right;
        close.VerticalAlignment = VerticalAlignment.Top;
        close.Click += (_, _) => CloseOnlinePlayerPopup();

        var avatar = new WindowsDefaultUserAvatar(
            62,
            new SolidColorBrush(Color.Parse("#59666A")),
            1,
            $"Online.PlayerPopup.{profile.Id}.Avatar");
        BindRemoteAvatar(avatar, profile.AvatarKey, profile.DisplayName);
        var identity = new StackPanel
        {
            Margin = new Thickness(10, 0, 0, 0),
            VerticalAlignment = VerticalAlignment.Center,
            Spacing = 4,
            Children =
            {
                new TextBlock
                {
                    Text = profile.DisplayName,
                    Foreground = new SolidColorBrush(Color.Parse("#E1E6E7")),
                    FontSize = 19,
                    FontWeight = FontWeight.SemiBold,
                    TextTrimming = TextTrimming.CharacterEllipsis
                },
                new TextBlock
                {
                    Text = AvaloniaLocalizationCatalog.Format("关注 {0:N0} · 粉丝 {1:N0} · 制谱 {2}", profile.FollowingCount, profile.FollowerCount, FormatOnlineChartingDuration(profile.ChartingSeconds)),
                    Foreground = new SolidColorBrush(Color.Parse("#839397")),
                    FontSize = 11,
                    TextWrapping = TextWrapping.Wrap
                }
            }
        };
        var titleRow = new Grid
        {
            ColumnDefinitions = new ColumnDefinitions("*,Auto")
        };
        titleRow.Children.Add(new TextBlock
        {
            Text = "玩家主页",
            Foreground = new SolidColorBrush(Color.Parse("#829B9E")),
            FontSize = 10,
            FontWeight = FontWeight.SemiBold,
            VerticalAlignment = VerticalAlignment.Center
        });
        Grid.SetColumn(close, 1);
        titleRow.Children.Add(close);
        var header = new Grid
        {
            ColumnDefinitions = new ColumnDefinitions("72,*"),
            Margin = new Thickness(0, 12, 0, 0)
        };
        header.Children.Add(avatar);
        Grid.SetColumn(identity, 1);
        header.Children.Add(identity);

        var body = new StackPanel();
        body.Children.Add(titleRow);
        body.Children.Add(header);
        body.Children.Add(new TextBlock
        {
            Text = string.IsNullOrWhiteSpace(profile.Bio) ? "暂无简介" : profile.Bio,
            Foreground = new SolidColorBrush(Color.Parse("#ABB5B8")),
            Margin = new Thickness(0, 14, 0, 0),
            MinHeight = 42,
            TextWrapping = TextWrapping.Wrap
        });

        Button? follow = null;
        if (session.CurrentUser?.Id != profile.Id)
        {
            Button followButton = null!;
            followButton = PrimaryButton(
                profile.IsFollowing ? "取消关注" : "关注",
                async (_, _) =>
                {
                    if (!followButton.IsEnabled) return;
                    followButton.IsEnabled = false;
                    status.Text = profile.IsFollowing ? "正在取消关注…" : "正在关注…";
                    try
                    {
                        using var timeout = new CancellationTokenSource(TimeSpan.FromSeconds(15));
                        await session.SetFollowAsync(profile.Id, !profile.IsFollowing, timeout.Token);
                        // The change is committed server-side now. Flip the local
                        // state before the refresh: if the refresh fails, the button
                        // must not keep offering the action that just succeeded,
                        // where a second click would silently undo it.
                        profile = profile with { IsFollowing = !profile.IsFollowing };
                        followButton.Content = profile.IsFollowing ? "取消关注" : "关注";
                        var refreshed = await session.GetPlayerAsync(
                            profile.Id,
                            roomMember == null ? null : session.CurrentRoom?.Id,
                            timeout.Token);
                        if (onlinePlayerPopupUserId == profile.Id)
                            SetOnlinePlayerPopupContent(
                                BuildOnlinePlayerCard(refreshed, roomMember));
                    }
                    catch (Exception exception) when (
                        exception is OnlineApiException or HttpRequestException or
                            OperationCanceledException or JsonException)
                    {
                        status.Text = exception.Message;
                        status.Foreground = new SolidColorBrush(Color.Parse("#D39A88"));
                        followButton.IsEnabled = true;
                    }
                });
            follow = followButton;
            follow.HorizontalAlignment = HorizontalAlignment.Stretch;
            ApplyOnlinePlayerPrimaryButtonStyle(follow, 36);
        }

        var currentRoom = session.CurrentRoom;
        var canManage = roomMember != null &&
                        currentRoom?.OwnerUserId == session.CurrentUser?.Id &&
                        roomMember.UserId != session.CurrentUser?.Id &&
                        // Static Equals: a server DTO may omit the role.
                        !string.Equals(roomMember.MemberRole, "owner", StringComparison.OrdinalIgnoreCase);
        if (canManage && roomMember != null)
        {
            var memberRole = string.Equals(
                roomMember.MemberRole,
                "viewer",
                StringComparison.OrdinalIgnoreCase)
                ? "viewer"
                : "editor";
            var metadata = PlayerPermissionCheckBox(
                "允许编辑谱面信息",
                roomMember.CanEditMetadata,
                $"Online.PlayerPopup.{profile.Id}.Metadata");
            var timing = PlayerPermissionCheckBox(
                "允许编辑 Effect（Timing Edit 全部功能）",
                roomMember.CanEditTiming,
                $"Online.PlayerPopup.{profile.Id}.Timing");
            var notes = PlayerPermissionCheckBox(
                "允许编辑 Note",
                roomMember.CanEditNotes,
                $"Online.PlayerPopup.{profile.Id}.Notes");
            metadata.Margin = new Thickness(0, 9, 0, 0);
            timing.Margin = new Thickness(0, 7, 0, 0);
            notes.Margin = new Thickness(0, 7, 0, 0);
            Button roleButton = null!;
            roleButton = PrimaryButton(
                memberRole == "viewer" ? "设为编辑者" : "设为观察者",
                async (_, _) =>
                {
                    roleButton.IsEnabled = false;
                    var nextRole = memberRole == "viewer" ? "editor" : "viewer";
                    status.Text = nextRole == "viewer" ? "正在设为观察者…" : "正在设为编辑者…";
                    try
                    {
                        using var timeout = new CancellationTokenSource(TimeSpan.FromSeconds(15));
                        var allowMetadata = nextRole == "editor" && metadata.IsChecked == true;
                        var allowTiming = nextRole == "editor" && timing.IsChecked == true;
                        var allowNotes = nextRole == "editor" && notes.IsChecked == true;
                        await session.UpdateRoomMemberAccessAsync(
                            profile.Id,
                            nextRole,
                            allowMetadata,
                            allowTiming,
                            allowNotes,
                            timeout.Token);
                        memberRole = nextRole;
                        roomMember = roomMember with
                        {
                            MemberRole = nextRole,
                            CanEditMetadata = allowMetadata,
                            CanEditTiming = allowTiming,
                            CanEditNotes = allowNotes
                        };
                        ReplaceOnlineCreatorMember(roomMember);
                        metadata.IsChecked = allowMetadata;
                        timing.IsChecked = allowTiming;
                        notes.IsChecked = allowNotes;
                        var editor = memberRole == "editor";
                        metadata.IsEnabled = editor;
                        timing.IsEnabled = editor;
                        notes.IsEnabled = editor;
                        roleButton.Content = editor ? "设为观察者" : "设为编辑者";
                        status.Text = editor ? "已设为编辑者" : "已设为观察者";
                    }
                    catch (Exception exception) when (
                        exception is OnlineApiException or HttpRequestException or
                            OperationCanceledException or JsonException)
                    {
                        status.Text = exception.Message;
                        status.Foreground = new SolidColorBrush(Color.Parse("#D39A88"));
                    }
                    finally
                    {
                        roleButton.IsEnabled = true;
                    }
                });
            roleButton.HorizontalAlignment = HorizontalAlignment.Stretch;
            ApplyOnlinePlayerSecondaryButtonStyle(roleButton, 36);

            Button save = null!;
            save = PrimaryButton(
                "保存房间权限",
                async (_, _) =>
                {
                    save.IsEnabled = false;
                    status.Text = "正在保存房间权限…";
                    try
                    {
                        using var timeout = new CancellationTokenSource(TimeSpan.FromSeconds(15));
                        await session.UpdateRoomMemberAccessAsync(
                            profile.Id,
                            memberRole,
                            metadata.IsChecked == true,
                            timing.IsChecked == true,
                            notes.IsChecked == true,
                            timeout.Token);
                        roomMember = roomMember with
                        {
                            CanEditMetadata = metadata.IsChecked == true,
                            CanEditTiming = timing.IsChecked == true,
                            CanEditNotes = notes.IsChecked == true
                        };
                        ReplaceOnlineCreatorMember(roomMember);
                        status.Text = "房间权限已保存";
                    }
                    catch (Exception exception) when (
                        exception is OnlineApiException or HttpRequestException or
                            OperationCanceledException or JsonException)
                    {
                        status.Text = exception.Message;
                        status.Foreground = new SolidColorBrush(Color.Parse("#D39A88"));
                    }
                    finally
                    {
                        save.IsEnabled = true;
                    }
                });
            save.HorizontalAlignment = HorizontalAlignment.Stretch;
            save.Margin = new Thickness(0, 10, 0, 0);
            ApplyOnlinePlayerPrimaryButtonStyle(save, 34);

            var permissionPanel = new Border
            {
                Margin = new Thickness(0, 10, 0, 0),
                Padding = new Thickness(11),
                Background = new SolidColorBrush(Color.Parse("#20272A")),
                BorderBrush = new SolidColorBrush(Color.Parse("#425256")),
                BorderThickness = new Thickness(1),
                CornerRadius = new CornerRadius(4),
                Child = new StackPanel
                {
                    Children =
                    {
                        new TextBlock
                        {
                            Text = "房间编辑权限 · 由房主持久分配",
                            Foreground = new SolidColorBrush(Color.Parse("#9DB7B9")),
                            FontSize = 10,
                            FontWeight = FontWeight.SemiBold
                        },
                        metadata,
                        timing,
                        notes,
                        save
                    }
                }
            };
            var isEditor = memberRole == "editor";
            metadata.IsEnabled = isEditor;
            timing.IsEnabled = isEditor;
            notes.IsEnabled = isEditor;
            var actions = new Grid
            {
                ColumnDefinitions = new ColumnDefinitions("*,*"),
                Margin = new Thickness(0, 14, 0, 0)
            };
            if (follow != null)
            {
                follow.Margin = new Thickness(0, 0, 4, 0);
                actions.Children.Add(follow);
                roleButton.Margin = new Thickness(4, 0, 0, 0);
                Grid.SetColumn(roleButton, 1);
            }
            else
            {
                Grid.SetColumnSpan(roleButton, 2);
            }
            actions.Children.Add(roleButton);
            body.Children.Add(actions);
            body.Children.Add(permissionPanel);

            var kick = PrimaryButton(
                "踢出",
                async (_, _) => await RemoveOnlinePlayerFromRoomAsync(
                    profile,
                    banMinutes: 0,
                    status));
            var ban = PrimaryButton(
                "暂时封禁 30 分钟",
                async (_, _) => await RemoveOnlinePlayerFromRoomAsync(
                    profile,
                    banMinutes: 30,
                    status));
            foreach (var button in new[] { kick, ban })
            {
                ApplyOnlinePlayerDangerButtonStyle(button, 34);
                button.HorizontalAlignment = HorizontalAlignment.Stretch;
            }
            var danger = new Grid
            {
                ColumnDefinitions = new ColumnDefinitions("*,*"),
                Margin = new Thickness(0, 8, 0, 0)
            };
            kick.Margin = new Thickness(0, 0, 4, 0);
            ban.Margin = new Thickness(4, 0, 0, 0);
            danger.Children.Add(kick);
            Grid.SetColumn(ban, 1);
            danger.Children.Add(ban);
            body.Children.Add(danger);
        }

        if (!canManage && follow != null)
        {
            follow.Margin = new Thickness(0, 14, 0, 0);
            body.Children.Add(follow);
        }

        body.Children.Add(status);
        return OnlinePlayerPopupCard(new ScrollViewer
        {
            MaxHeight = 704,
            VerticalScrollBarVisibility = ScrollBarVisibility.Auto,
            HorizontalScrollBarVisibility = ScrollBarVisibility.Disabled,
            Content = body
        });
    }

