    private void WindowResize_PointerPressed(
        object? sender,
        PointerPressedEventArgs eventArgs)
    {
        _ = sender;
        if (!CanResize ||
            WindowState != WindowState.Normal ||
            !eventArgs.GetCurrentPoint(this).Properties.IsLeftButtonPressed)
        {
            return;
        }

        var edge = WindowsTitleBarParityPolicy.ResolveResizeEdge(
            eventArgs.GetPosition(this),
            Bounds.Size);
        if (!edge.HasValue) return;
        BeginResizeDrag(edge.Value, eventArgs);
        eventArgs.Handled = true;
    }

    private void TitleBar_PointerPressed(
        Control titleBarSurface,
        PointerPressedEventArgs eventArgs)
    {
        if (!eventArgs
                .GetCurrentPoint(titleBarSurface)
                .Properties
                .IsLeftButtonPressed)
        {
            return;
        }
        if (eventArgs.Source is Control source &&
            (source is Button || source.GetVisualAncestors().OfType<Button>().Any()))
        {
            return;
        }
        if (eventArgs.ClickCount >= 2)
        {
            activeWindowSnapTarget = null;
            windowSnapRestoreBounds = null;
            ToggleMaximize();
            eventArgs.Handled = true;
            return;
        }

        var restoreBoundsForSnap = WindowState == WindowState.Normal
            ? GetCurrentWindowPhysicalBounds()
            : (PixelRect?)null;
        if (activeWindowSnapTarget is WindowsWindowSnapTarget.Left or
                WindowsWindowSnapTarget.Right &&
            windowSnapRestoreBounds is { } restoreBounds)
        {
            if (!WindowsWindowSnapPolicy.TryGetCursorPosition(out var pointer))
                return;
            var snappedBounds = GetCurrentWindowPhysicalBounds();
            var screen =
                Screens?.ScreenFromPoint(pointer) ??
                ScreenFromHost() ??
                Screens?.Primary;
            if (screen != null)
            {
                var titleOffsetPixels = Math.Max(
                    0,
                    pointer.Y - snappedBounds.Y);
                var restored = WindowsWindowSnapPolicy.ResolveRestoreUnderPointer(
                    pointer,
                    snappedBounds,
                    restoreBounds.Size,
                    screen.WorkingArea,
                    titleOffsetPixels);
                ApplyPhysicalWindowBounds(restored, screen.Scaling);
                restoreBoundsForSnap = restored;
            }
            activeWindowSnapTarget = null;
        }

        try
        {
            BeginMoveDrag(eventArgs);
            ScheduleWindowsSnapAfterMove(restoreBoundsForSnap);
            eventArgs.Handled = true;
        }
        catch
        {
            // Ignore transient native drag failures during window teardown.
        }
    }

    private void ScheduleWindowsSnapAfterMove(PixelRect? restoreBoundsBeforeMove)
    {
        CancelPendingWindowSnapApplication();
        windowMoveSnapScheduleCount++;
        windowMoveSnapLastOutcome = "Scheduled";
        UpdateTitleBarAutomationHelpText();
        var timeout = Stopwatch.StartNew();
        var observedPressed = WindowsWindowSnapPolicy.IsPrimaryMouseButtonPressed();
        DispatcherTimer? timer = null;
        timer = new DispatcherTimer(
            TimeSpan.FromMilliseconds(16),
            DispatcherPriority.Input,
            (_, _) =>
            {
                if (WindowsWindowSnapPolicy.IsPrimaryMouseButtonPressed())
                {
                    observedPressed = true;
                    return;
                }
                if (!WindowsWindowSnapPolicy.ShouldApplyAfterMove(
                        observedPressed,
                        isPressed: false,
                        timeout.Elapsed))
                {
                    return;
                }
                timer!.Stop();
                if (ReferenceEquals(windowMoveCompletionTimer, timer))
                    windowMoveCompletionTimer = null;
                ApplyWindowsSnapAfterMove(restoreBoundsBeforeMove);
            });
        timer.Start();
        windowMoveCompletionTimer = timer;
    }

    private void CancelPendingWindowSnapApplication()
    {
        windowMoveCompletionTimer?.Stop();
        windowMoveCompletionTimer = null;
    }

    private void ApplyWindowsSnapAfterMove(PixelRect? restoreBoundsBeforeMove)
    {
        if (!WindowsWindowSnapPolicy.TryGetCursorPosition(out var pointer))
        {
            windowMoveSnapLastOutcome = "CursorUnavailable";
            UpdateTitleBarAutomationHelpText();
            return;
        }
        windowMoveSnapApplyCount++;
        windowMoveSnapLastPointer = pointer;
        var screen =
            Screens?.ScreenFromPoint(pointer) ??
            ScreenFromHost() ??
            Screens?.Primary;
        if (screen == null)
        {
            windowMoveSnapLastOutcome = "ScreenUnavailable";
            UpdateTitleBarAutomationHelpText();
            return;
        }

        var target = WindowsWindowSnapPolicy.ResolveTarget(
            pointer,
            screen.WorkingArea);
        if (target == WindowsWindowSnapTarget.Maximize)
        {
            activeWindowSnapTarget = null;
            windowSnapRestoreBounds = null;
            WindowState = WindowState.Maximized;
            windowMoveSnapLastOutcome = nameof(WindowsWindowSnapTarget.Maximize);
            UpdateTitleBarAutomationHelpText();
            return;
        }
        if (target is WindowsWindowSnapTarget.Left or WindowsWindowSnapTarget.Right)
        {
            windowSnapRestoreBounds =
                restoreBoundsBeforeMove ?? GetCurrentWindowPhysicalBounds();
            var placement = WindowsWindowSnapPolicy.ResolvePlacement(
                target.Value,
                screen.WorkingArea,
                screen.Scaling,
                WindowsTitleBarParityPolicy.MinimumWindowWidth,
                WindowsTitleBarParityPolicy.MinimumWindowHeight);
            ApplyPhysicalWindowBounds(
                new PixelRect(placement.Position, placement.PhysicalSize),
                screen.Scaling);
            activeWindowSnapTarget = target;
            windowMoveSnapLastOutcome = target.Value.ToString();
            UpdateTitleBarAutomationHelpText();
            return;
        }

        activeWindowSnapTarget = null;
        windowMoveSnapNoTargetCount++;
        windowMoveSnapLastOutcome = "None";
        if (WindowState == WindowState.Normal)
            windowSnapRestoreBounds = GetCurrentWindowPhysicalBounds();
        UpdateTitleBarAutomationHelpText();
    }

    private static string FormatWindowSnapPointer(PixelPoint? pointer) =>
        pointer is { } value
            ? $"{value.X},{value.Y}"
            : "None";

    private PixelRect GetCurrentWindowPhysicalBounds()
    {
        var windowHandle = TryGetPlatformHandle()?.Handle ?? IntPtr.Zero;
        if (WindowsWindowSnapPolicy.TryGetNativeWindowBounds(
                windowHandle,
                out var nativeBounds))
        {
            return nativeBounds;
        }

        var screen = ScreenFromHost() ?? Screens?.Primary;
        var scaling = screen?.Scaling ?? 1;
        return new PixelRect(
            Position,
            new PixelSize(
                Math.Max(1, checked((int)Math.Round(Bounds.Width * scaling))),
                Math.Max(1, checked((int)Math.Round(Bounds.Height * scaling)))));
    }

    private void ApplyPhysicalWindowBounds(PixelRect bounds, double scaling)
    {
        if (!double.IsFinite(scaling) || scaling <= 0)
            throw new ArgumentOutOfRangeException(nameof(scaling));
        WindowState = WindowState.Normal;
        Width = bounds.Width / scaling;
        Height = bounds.Height / scaling;
        Position = bounds.Position;
        var windowHandle = TryGetPlatformHandle()?.Handle ?? IntPtr.Zero;
        _ = WindowsWindowSnapPolicy.TryApplyNativeWindowBounds(
            windowHandle,
            bounds);
    }

