    private static Button QuickPaletteButton(
        string text,
        string geometry,
        EventHandler<RoutedEventArgs> handler,
        out TextBlock label,
        out AvaloniaPath icon,
        bool filledIcon = false)
    {
        var iconBrush = new SolidColorBrush(Color.Parse("#B7C0C4"));
        icon = new AvaloniaPath
        {
            Data = StreamGeometry.Parse(geometry),
            Stroke = filledIcon ? null : iconBrush,
            StrokeThickness = 1.5,
            StrokeLineCap = PenLineCap.Round,
            StrokeJoin = PenLineJoin.Round,
            Fill = filledIcon ? iconBrush : null
        };
        var iconCanvas = new Canvas
        {
            Width = 17,
            Height = 17,
            Children = { icon }
        };
        var iconViewport = new Viewbox
        {
            Width = 18,
            Height = 18,
            Stretch = Stretch.Uniform,
            HorizontalAlignment = HorizontalAlignment.Center,
            VerticalAlignment = VerticalAlignment.Center,
            Child = iconCanvas
        };
        label = new TextBlock
        {
            Text = text,
            HorizontalAlignment = HorizontalAlignment.Stretch,
            VerticalAlignment = VerticalAlignment.Center,
            TextAlignment = TextAlignment.Center
        };
        var content = new Grid
        {
            Width = double.NaN,
            HorizontalAlignment = HorizontalAlignment.Center,
            VerticalAlignment = VerticalAlignment.Center,
            ColumnDefinitions = new ColumnDefinitions("18,*"), ColumnSpacing = 4
        };
        content.Children.Add(iconViewport);
        Grid.SetColumn(label, 1);
        content.Children.Add(label);
        var button = new Button
        {
            Height = 35,
            Padding = new Thickness(4, 2),
            HorizontalContentAlignment = HorizontalAlignment.Stretch,
            VerticalContentAlignment = VerticalAlignment.Center,
            Background = Brushes.Transparent,
            Foreground = Brushes.White,
            BorderBrush = Brushes.Transparent,
            BorderThickness = new Thickness(1),
            CornerRadius = new CornerRadius(3),
            Content = content
        };
        button.Click += handler;
        return button;
    }

    private void RegisterQuickShortcutButton(
        string action,
        string description,
        Button button) => quickShortcutButtons[action] = (button, description);

    private void SetQuickShortcutEnabled(string action, bool enabled)
    {
        if (quickShortcutButtons.TryGetValue(action, out var entry))
            entry.Button.IsEnabled = enabled;
    }

    private void QuickEditPaletteHeader_PointerPressed(
        object? sender,
        PointerPressedEventArgs eventArgs)
    {
        if (sender is not Control header || quickEditPaletteCollapseButton.IsPointerOver ||
            !eventArgs.GetCurrentPoint(header).Properties.IsLeftButtonPressed)
            return;
        var current = quickEditPalette.TranslatePoint(new Point(0, 0), editorWorkbench);
        if (!current.HasValue) return;
        quickEditPaletteDragging = true;
        quickEditPaletteDragStart = eventArgs.GetPosition(editorWorkbench);
        quickEditPaletteDragStartX = quickEditPaletteTransform.X;
        quickEditPaletteDragStartY = quickEditPaletteTransform.Y;
        quickEditPaletteBaseLeft = current.Value.X - quickEditPaletteTransform.X;
        quickEditPaletteBaseTop = current.Value.Y - quickEditPaletteTransform.Y;
        eventArgs.Pointer.Capture(header);
        eventArgs.Handled = true;
    }

    private void QuickEditPaletteHeader_PointerMoved(
        object? sender,
        PointerEventArgs eventArgs)
    {
        if (!quickEditPaletteDragging || sender is not Control header ||
            !eventArgs.GetCurrentPoint(header).Properties.IsLeftButtonPressed)
            return;
        var point = eventArgs.GetPosition(editorWorkbench);
        var x = quickEditPaletteDragStartX + point.X - quickEditPaletteDragStart.X;
        var y = quickEditPaletteDragStartY + point.Y - quickEditPaletteDragStart.Y;
        quickEditPaletteTransform.X = Math.Clamp(
            x,
            4 - quickEditPaletteBaseLeft,
            Math.Max(
                4 - quickEditPaletteBaseLeft,
                editorWorkbench.Bounds.Width - quickEditPalette.Bounds.Width -
                quickEditPaletteBaseLeft - 4));
        quickEditPaletteTransform.Y = Math.Clamp(
            y,
            4 - quickEditPaletteBaseTop,
            Math.Max(
                4 - quickEditPaletteBaseTop,
                editorWorkbench.Bounds.Height - quickEditPalette.Bounds.Height -
                quickEditPaletteBaseTop - 4));
        eventArgs.Handled = true;
    }

    private void QuickEditPaletteHeader_PointerReleased(
        object? sender,
        PointerReleasedEventArgs eventArgs)
    {
        _ = sender;
        if (!quickEditPaletteDragging) return;
        // Ends the gesture before releasing capture, so the CaptureLost raised
        // by Capture(null) finds the flag cleared and does not commit twice.
        EndQuickEditPaletteDrag();
        eventArgs.Pointer.Capture(null);
        eventArgs.Handled = true;
    }

    private void EndQuickEditPaletteDrag()
    {
        if (!quickEditPaletteDragging) return;
        quickEditPaletteDragging = false;
        editorViewSettings = editorViewSettings.WithQuickPalette(
            quickEditPaletteTransform.X,
            quickEditPaletteTransform.Y,
            editorViewSettings.QuickPaletteCollapsed);
        editorViewSettingsDirty = true;
        ScheduleEditorViewSettingsSave();
    }

    private void QuickEditPaletteResizeGrip_PointerPressed(
        object? sender,
        PointerPressedEventArgs eventArgs)
    {
        if (sender is not Control grip ||
            !eventArgs.GetCurrentPoint(grip).Properties.IsLeftButtonPressed)
            return;
        quickEditPaletteResizing = true;
        quickEditPaletteResizeStart = eventArgs.GetPosition(editorWorkbench);
        quickEditPaletteResizeStartTransformX = quickEditPaletteTransform.X;
        quickEditPaletteResizeStartWidth = Math.Max(
            180,
            quickEditPaletteScaleHost.Bounds.Width > 0
                ? quickEditPaletteScaleHost.Bounds.Width
                : quickEditPaletteWidth);
        quickEditPaletteResizeStartHeight = Math.Max(
            60,
            quickEditPaletteScaleHost.Bounds.Height > 0
                ? quickEditPaletteScaleHost.Bounds.Height
                : quickEditPaletteHeight ?? 60);
        eventArgs.Pointer.Capture(grip);
        eventArgs.Handled = true;
    }

    private void QuickEditPaletteResizeGrip_PointerMoved(
        object? sender,
        PointerEventArgs eventArgs)
    {
        if (!quickEditPaletteResizing || sender is not Control grip ||
            !eventArgs.GetCurrentPoint(grip).Properties.IsLeftButtonPressed)
            return;
        var point = eventArgs.GetPosition(editorWorkbench);
        var size = WindowsQuickEditPaletteResizePolicy.Resolve(
            quickEditPaletteResizeStartWidth,
            quickEditPaletteResizeStartHeight,
            point.X - quickEditPaletteResizeStart.X,
            point.Y - quickEditPaletteResizeStart.Y,
            editorWorkbench.Bounds.Width,
            editorWorkbench.Bounds.Height);
        quickEditPaletteWidth = size.Width;
        quickEditPaletteHeight = size.Height;
        quickEditPaletteTransform.X = quickEditPaletteResizeStartTransformX +
                                      size.Width - quickEditPaletteResizeStartWidth;
        quickEditPaletteScaleHost.Width = quickEditPaletteWidth;
        quickEditPaletteScaleHost.Height = quickEditPaletteHeight.Value;
        eventArgs.Handled = true;
    }

    private void QuickEditPaletteResizeGrip_PointerReleased(
        object? sender,
        PointerReleasedEventArgs eventArgs)
    {
        _ = sender;
        if (!quickEditPaletteResizing) return;
        EndQuickEditPaletteResize();
        eventArgs.Pointer.Capture(null);
        eventArgs.Handled = true;
    }

    private void EndQuickEditPaletteResize()
    {
        if (!quickEditPaletteResizing) return;
        quickEditPaletteResizing = false;
        ClampFloatingControl(quickEditPalette, quickEditPaletteTransform);
        editorViewSettings = editorViewSettings.WithQuickPalette(
            quickEditPaletteTransform.X,
            quickEditPaletteTransform.Y,
            editorViewSettings.QuickPaletteCollapsed);
        MarkEditorViewSettingsDirty();
    }

    private void ApplyQuickEditPaletteLayout()
    {
        // The saved position is honoured everywhere. This used to read
        // `SupportsDesktopWindowSizing ? saved : 0`, which on a tablet undid
        // every drag the moment anything re-applied the layout — and collapsing
        // or expanding the palette does exactly that, immediately after storing
        // the position it was about to discard, so the palette sprang back to
        // the corner on every toggle.
        //
        // Nothing is lost by trusting the value: a tablet gets its opening
        // placement from the factory floating layout instead
        // (factoryFloatingLayoutPending starts true when
        // SupportsDesktopWindowSizing is false), and the queued clamp pass pulls
        // a palette back inside the workbench whenever the bounds change. On
        // Windows the branch was already taking the saved value, so this is the
        // desktop behaviour the tablets are meant to mirror.
        quickEditPaletteTransform.X = editorViewSettings.QuickPaletteX;
        quickEditPaletteTransform.Y = editorViewSettings.QuickPaletteY;
        quickEditPaletteBody.IsVisible = !editorViewSettings.QuickPaletteCollapsed;
        quickEditPaletteContent.Width = editorViewSettings.QuickPaletteCollapsed
            ? 124
            : WindowsInspectorParityPolicy.QuickEditPaletteExpandedContentWidth;
        quickEditPaletteContent.Height = double.NaN;
        quickEditPaletteScaleHost.Width = editorViewSettings.QuickPaletteCollapsed
            ? 124
            : quickEditPaletteWidth;
        quickEditPaletteScaleHost.Height = editorViewSettings.QuickPaletteCollapsed
            ? double.NaN
            : quickEditPaletteHeight ?? double.NaN;
        quickEditPaletteResizeGrip.IsVisible = !editorViewSettings.QuickPaletteCollapsed;
        quickEditPaletteCollapseButton.Content = editorViewSettings.QuickPaletteCollapsed ? "+" : "−";
        ToolTip.SetTip(
            quickEditPaletteCollapseButton,
            editorViewSettings.QuickPaletteCollapsed ? "展开快捷编辑" : "收起快捷编辑");
    }

