    private Control BuildQuickValueSection(
        string heading,
        TextBlock valueText,
        EventHandler<RoutedEventArgs> increase,
        EventHandler<RoutedEventArgs> decrease,
        Action<Button> showPresets,
        string kind)
    {
        var valueButton = QuickValueButton(string.Empty, (_, _) => { });
        valueButton.Content = valueText;
        valueButton.Click += (_, _) => showPresets(valueButton);
        AutomationProperties.SetAutomationId(valueButton, $"Editor.QuickValues.{kind}.Preset");
        ToolTip.SetTip(valueButton, "左键选择预设 · 右键自定义");

        var editor = new TextBox
        {
            Tag = kind,
            IsVisible = false,
            Height = WindowsInspectorParityPolicy.QuickValuesControlHeight,
            MinHeight = WindowsInspectorParityPolicy.QuickValuesControlHeight,
            FontFamily = new FontFamily("Cascadia Mono, Consolas"),
            FontSize = 10,
            Padding = new Thickness(2, 0),
            Margin = new Thickness(0),
            HorizontalContentAlignment = HorizontalAlignment.Center,
            VerticalContentAlignment = VerticalAlignment.Center
        };
        AutomationProperties.SetAutomationId(editor, $"Editor.QuickValues.{kind}.Editor");
        editor.LostFocus += (_, _) =>
        {
            if (editor.IsVisible) CommitQuickValueEdit(valueButton, editor);
        };
        editor.KeyDown += (_, eventArgs) =>
        {
            if (eventArgs.Key == Key.Enter)
            {
                CommitQuickValueEdit(valueButton, editor);
                timeline.Focus();
                eventArgs.Handled = true;
            }
            else if (eventArgs.Key == Key.Escape)
            {
                EndQuickValueEdit(valueButton, editor);
                timeline.Focus();
                eventArgs.Handled = true;
            }
        };
        editor.ContextRequested += (_, eventArgs) =>
        {
            editor.Focus();
            editor.SelectAll();
            eventArgs.Handled = true;
        };
        editor.AddHandler(
            InputElement.PointerPressedEvent,
            (_, eventArgs) =>
            {
                if (eventArgs.GetCurrentPoint(editor).Properties.PointerUpdateKind !=
                    PointerUpdateKind.RightButtonPressed) return;
                editor.Focus();
                editor.SelectAll();
                eventArgs.Handled = true;
            },
            RoutingStrategies.Tunnel,
            handledEventsToo: true);
        editor.AddHandler(
            InputElement.PointerReleasedEvent,
            (_, eventArgs) =>
            {
                if (eventArgs.GetCurrentPoint(editor).Properties.PointerUpdateKind !=
                    PointerUpdateKind.RightButtonReleased) return;
                editor.Focus();
                editor.SelectAll();
                eventArgs.Handled = true;
            },
            RoutingStrategies.Tunnel,
            handledEventsToo: true);
        valueButton.AddHandler(
            InputElement.PointerPressedEvent,
            (_, eventArgs) =>
            {
                if (eventArgs.GetCurrentPoint(valueButton).Properties.PointerUpdateKind !=
                    PointerUpdateKind.RightButtonPressed) return;
                eventArgs.Handled = true;
            },
            RoutingStrategies.Tunnel,
            handledEventsToo: true);
        valueButton.AddHandler(
            InputElement.PointerReleasedEvent,
            (_, eventArgs) =>
            {
                if (eventArgs.GetCurrentPoint(valueButton).Properties.PointerUpdateKind !=
                    PointerUpdateKind.RightButtonReleased) return;
                BeginQuickValueEdit(valueButton, editor, kind);
                eventArgs.Handled = true;
            },
            RoutingStrategies.Tunnel,
            handledEventsToo: true);

        var valueHost = new Grid
        {
            HorizontalAlignment = HorizontalAlignment.Stretch,
            Children = { valueButton, editor }
        };
        var increaseButton = QuickValueButton("▲", increase, new Thickness(0, 3, 0, 0));
        var decreaseButton = QuickValueButton("▼", decrease);
        increaseButton.Click += (_, _) => timeline.Focus();
        decreaseButton.Click += (_, _) => timeline.Focus();
        AutomationProperties.SetAutomationId(increaseButton, $"Editor.QuickValues.{kind}.Up");
        AutomationProperties.SetAutomationId(decreaseButton, $"Editor.QuickValues.{kind}.Down");
        return new StackPanel
        {
            Width = 100,
            HorizontalAlignment = HorizontalAlignment.Stretch,
            Margin = kind == "Rate"
                ? new Thickness(0)
                : new Thickness(
                    0,
                    0,
                    0,
                    WindowsInspectorParityPolicy.QuickValuesSectionGap),
            Children =
            {
                new TextBlock
                {
                    Text = heading,
                    Foreground = new SolidColorBrush(Color.Parse("#7F898D")),
                    FontSize = 9,
                    HorizontalAlignment = HorizontalAlignment.Stretch,
                    TextAlignment = TextAlignment.Center
                },
                increaseButton,
                valueHost,
                decreaseButton
            }
        };
    }

    private static Button QuickValueButton(
