    private static void ApplyCompactPlayerListStyles(
        ListBox list,
        bool showSelection = true,
        string itemBackground = "#00000000")
    {
        var item = new Style(selector => selector.OfType<ListBoxItem>());
        item.Setters.Add(new Setter(
            TemplatedControl.BackgroundProperty,
            new SolidColorBrush(Color.Parse(itemBackground))));
        item.Setters.Add(new Setter(TemplatedControl.BorderBrushProperty, Brushes.Transparent));
        item.Setters.Add(new Setter(TemplatedControl.BorderThicknessProperty, new Thickness(0)));
        item.Setters.Add(new Setter(ContentControl.PaddingProperty, new Thickness(0)));
        item.Setters.Add(new Setter(ContentControl.HorizontalContentAlignmentProperty,
            HorizontalAlignment.Stretch));
        list.Styles.Add(item);

        var hover = new Style(selector =>
            selector.OfType<ListBoxItem>().Class(":pointerover"));
        hover.Setters.Add(new Setter(
            TemplatedControl.BackgroundProperty,
            new SolidColorBrush(Color.Parse("#22292C"))));
        list.Styles.Add(hover);

        var selected = new Style(selector =>
            selector.OfType<ListBoxItem>().Class(":selected"));
        selected.Setters.Add(new Setter(
            TemplatedControl.BackgroundProperty,
            showSelection
                ? new SolidColorBrush(Color.Parse("#252D30"))
                : Brushes.Transparent));
        selected.Setters.Add(new Setter(
            TemplatedControl.BorderBrushProperty,
            showSelection
                ? new SolidColorBrush(Color.Parse("#6C979A"))
                : Brushes.Transparent));
        selected.Setters.Add(new Setter(
            TemplatedControl.BorderThicknessProperty,
            showSelection ? new Thickness(1) : new Thickness(0)));
        list.Styles.Add(selected);
    }

    private Control BuildRoomMemberRow(OnlineRoomMemberDto? member)
    {
        if (member == null) return new Border { Height = 1 };
        var memberAvatar = new WindowsDefaultUserAvatar(
            25,
            new SolidColorBrush(Color.Parse("#56666A")),
            1,
            $"RoomCollaboration.Member.{member.UserId}.Avatar");
        BindRemoteAvatar(memberAvatar, member.AvatarKey, member.DisplayName);
        var avatar = new Grid
        {
            Width = 25,
            Height = 25,
            Children =
            {
                memberAvatar,
                new global::Avalonia.Controls.Shapes.Ellipse
                {
                    Width = 7,
                    Height = 7,
                    HorizontalAlignment = HorizontalAlignment.Right,
                    VerticalAlignment = VerticalAlignment.Bottom,
                    Fill = new SolidColorBrush(Color.Parse(
                        member.IsOnline ? "#668070" : "#626B6F")),
                    Stroke = new SolidColorBrush(Color.Parse("#182023")),
                    StrokeThickness = 1,
                    Opacity = member.IsOnline ? 1 : .65
                }
            }
        };
        var row = new Grid
        {
            Width = 270,
            Height = 34,
            ColumnDefinitions = new ColumnDefinitions("30,*"),
            Background = Brushes.Transparent
        };
        row.Children.Add(avatar);
        var name = new TextBlock
        {
            Text = member.DisplayName,
            Margin = new Thickness(5, 0, 0, 0),
            VerticalAlignment = VerticalAlignment.Center,
            Foreground = new SolidColorBrush(Color.Parse("#D7DEDF")),
            FontSize = 11,
            FontWeight = FontWeight.SemiBold,
            TextTrimming = TextTrimming.CharacterEllipsis
        };
        Grid.SetColumn(name, 1);
        row.Children.Add(name);
        AutomationProperties.SetName(
            row,
            $"{member.DisplayName} · {(member.IsOnline ? "在线" : "离线")} · {member.MemberRole}");
        return row;
    }

    private Control BuildRoomChatRow(OnlineRoomChatMessageDto? message)
    {
        if (message == null) return new Border { Height = 1 };
        var messageAvatar = new WindowsDefaultUserAvatar(
            17,
            new SolidColorBrush(Color.Parse("#56666A")),
            1,
            $"RoomCollaboration.Message.{message.Id}.Avatar");
        BindRemoteAvatar(messageAvatar, message.AvatarKey, message.DisplayName);
        var header = new Grid
        {
            ColumnDefinitions = new ColumnDefinitions("20,*,Auto")
        };
        header.Children.Add(messageAvatar);
        var author = new TextBlock
        {
            Text = message.DisplayName,
            Foreground = new SolidColorBrush(Color.Parse("#DDE4E5")),
            FontWeight = FontWeight.SemiBold,
            FontSize = 10,
            VerticalAlignment = VerticalAlignment.Center
        };
        Grid.SetColumn(author, 1);
        header.Children.Add(author);
        var time = new TextBlock
        {
            Text = message.CreatedAt.ToLocalTime().ToString("HH:mm"),
            Foreground = new SolidColorBrush(Color.Parse("#68767A")),
            FontFamily = new FontFamily("Cascadia Mono,Consolas"),
            FontSize = 8
        };
        Grid.SetColumn(time, 2);
        header.Children.Add(time);
        return new Border
        {
            Width = 270,
