    private void ApplyRoomCollaborationCollapsedState()
    {
        roomCollaborationBody.IsVisible = !roomCollaborationCollapsed;
        roomCollaborationPanel.Width = roomCollaborationCollapsed ? 188 : 292;
        roomCollaborationToggleButton.Content =
            roomCollaborationCollapsed ? "+" : "−";
        ToolTip.SetTip(
            roomCollaborationToggleButton,
            roomCollaborationCollapsed
                ? "展开成员与聊天"
                : "收起成员与聊天");
        QueueFloatingPaletteClamp();
    }

    private void RefreshRoomCollaborationPanelVisibility()
    {
        var visible =
            onlineAccountHost?.Session.CurrentRoom?.Id == roomChartSyncRoomId &&
            roomChartSyncTab != null &&
            ReferenceEquals(viewModel.ActiveTab, roomChartSyncTab) &&
            editorView.IsVisible;
        roomCollaborationPanel.IsVisible = visible;
        if (visible && IsRoomChatActivelyVisible())
            SetRoomChatUnread(false);
        if (visible) QueueFloatingPaletteClamp();
    }

    private bool IsRoomChatActivelyVisible() =>
        IsActive &&
        roomCollaborationPanel.IsVisible &&
        roomCollaborationBody.IsVisible;

    private void SetRoomChatUnread(bool unread)
    {
        roomChatHasUnread = unread;
        roomChatUnreadDot.IsVisible = unread;
        AutomationProperties.SetHelpText(
            roomCollaborationPanel,
            $"Unread={unread}; Messages={roomChatMessages.Count}; " +
            $"LatestMessageId={latestRoomMessageId}; " +
            $"Collapsed={roomCollaborationCollapsed}");
    }

    private void ResetRoomChatUi(bool reveal)
    {
        roomChatMessages.Clear();
        latestRoomMessageId = 0;
        roomChatInitialized = false;
        roomChatStatusText.Text = string.Empty;
        roomChatInputBox.Text = string.Empty;
        roomChatList.ItemsSource = Array.Empty<OnlineRoomChatMessageDto>();
        roomMemberList.ItemsSource = Array.Empty<OnlineRoomMemberDto>();
        roomMemberCountText.Text = "0 / 8";
        roomCollaborationTitle.Text = roomChartSyncRoomName.Length == 0
            ? "联机房间"
            : roomChartSyncRoomName;
        if (reveal)
        {
            roomCollaborationCollapsed = false;
            ApplyRoomCollaborationCollapsedState();
        }
        SetRoomChatUnread(false);
        RefreshRoomCollaborationPanelVisibility();
    }

    private void AppendRoomChatMessages(
        IReadOnlyList<OnlineRoomChatMessageDto> messages,
        long latestMessageId)
    {
        var currentUserId =
            onlineAccountHost?.Session.CurrentUser?.Id ?? 0;
        var incoming = messages
            .Where(message => roomChatMessages.All(existing =>
                existing.Id != message.Id))
            .OrderBy(message => message.Id)
            .ToArray();
        var initializedBeforeAppend = roomChatInitialized;
        foreach (var message in incoming)
        {
            roomChatMessages.Add(message);
            latestRoomMessageId = Math.Max(latestRoomMessageId, message.Id);
            if (initializedBeforeAppend &&
                message.UserId != currentUserId &&
                !IsRoomChatActivelyVisible())
                SetRoomChatUnread(true);
        }
        latestRoomMessageId = Math.Max(latestRoomMessageId, latestMessageId);
        roomChatInitialized = true;
        if (roomChatMessages.Count > 200)
            roomChatMessages.RemoveRange(0, roomChatMessages.Count - 200);
        if (incoming.Length == 0) return;
        roomChatList.ItemsSource = roomChatMessages.ToArray();
        roomChatList.ScrollIntoView(roomChatMessages[^1]);
    }

    private async Task SendRoomChatAsync()
    {
        var session = onlineAccountHost?.Session;
        var message = roomChatInputBox.Text?.Trim() ?? string.Empty;
        if (roomChatSendInProgress || session?.CurrentRoom == null ||
            message.Length == 0)
            return;
        roomChatSendInProgress = true;
        sendRoomChatButton.IsEnabled = false;
        roomChatStatusText.Text = "正在发送…";
        try
        {
            using var timeout =
                new CancellationTokenSource(TimeSpan.FromSeconds(15));
            var result = await session.SendRoomChatAsync(
                message,
                timeout.Token);
            if (result.Outcome != OnlineRoomLifecycleOutcome.Success ||
                result.Value == null)
            {
                roomChatStatusText.Text = "消息未发送：房间已结束或无发送权限";
                return;
            }
            AppendRoomChatMessages(
                [result.Value],
                Math.Max(latestRoomMessageId, result.Value.Id));
            // The box stays editable while sending; only clear it when it still
            // holds the sent message, so text typed meanwhile is not swallowed.
            if (string.Equals(
                    roomChatInputBox.Text?.Trim() ?? string.Empty,
                    message,
                    StringComparison.Ordinal))
                roomChatInputBox.Text = string.Empty;
            roomChatStatusText.Text = string.Empty;
            SetRoomChatUnread(false);
        }
        catch (Exception exception) when (
            exception is OnlineApiException or HttpRequestException or
                OperationCanceledException or JsonException)
        {
            roomChatStatusText.Text = AvaloniaLocalizationCatalog.Format("发送失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message));
        }
        finally
        {
            roomChatSendInProgress = false;
            sendRoomChatButton.IsEnabled =
                onlineAccountHost?.Session.CurrentRoom != null;
        }
    }

    private void RoomCollaborationHeader_PointerPressed(
        object? sender,
        PointerPressedEventArgs eventArgs)
    {
        if (sender is not Control header ||
            roomCollaborationToggleButton.IsPointerOver ||
            !eventArgs.GetCurrentPoint(header).Properties.IsLeftButtonPressed)
            return;
        var current = roomCollaborationPanel.TranslatePoint(
            new Point(0, 0),
            editorWorkbench);
        if (!current.HasValue) return;
        roomCollaborationDragging = true;
        roomCollaborationDragStart =
            eventArgs.GetPosition(editorWorkbench);
        roomCollaborationDragStartX = roomCollaborationTransform.X;
        roomCollaborationDragStartY = roomCollaborationTransform.Y;
        roomCollaborationBaseLeft =
            current.Value.X - roomCollaborationTransform.X;
        roomCollaborationBaseTop =
            current.Value.Y - roomCollaborationTransform.Y;
        eventArgs.Pointer.Capture(header);
        eventArgs.Handled = true;
    }

    private void RoomCollaborationHeader_PointerMoved(
        object? sender,
        PointerEventArgs eventArgs)
    {
        if (!roomCollaborationDragging ||
            sender is not Control header ||
            !eventArgs.GetCurrentPoint(header).Properties.IsLeftButtonPressed)
            return;
        var point = eventArgs.GetPosition(editorWorkbench);
        var x = roomCollaborationDragStartX +
                point.X - roomCollaborationDragStart.X;
        var y = roomCollaborationDragStartY +
                point.Y - roomCollaborationDragStart.Y;
        roomCollaborationTransform.X = Math.Clamp(
            x,
            4 - roomCollaborationBaseLeft,
            Math.Max(
                4 - roomCollaborationBaseLeft,
                editorWorkbench.Bounds.Width -
                roomCollaborationPanel.Bounds.Width -
                roomCollaborationBaseLeft - 4));
        roomCollaborationTransform.Y = Math.Clamp(
            y,
            4 - roomCollaborationBaseTop,
            Math.Max(
                4 - roomCollaborationBaseTop,
                editorWorkbench.Bounds.Height -
                roomCollaborationPanel.Bounds.Height -
                roomCollaborationBaseTop - 4));
        eventArgs.Handled = true;
    }

    private void RoomCollaborationHeader_PointerReleased(
        object? sender,
        PointerReleasedEventArgs eventArgs)
    {
        _ = sender;
        if (!roomCollaborationDragging) return;
        roomCollaborationDragging = false;
        eventArgs.Pointer.Capture(null);
        eventArgs.Handled = true;
    }

    private void ClampRoomCollaborationPosition()
    {
        if (roomCollaborationDragging ||
            editorWorkbench.Bounds.Width <= 0 ||
            editorWorkbench.Bounds.Height <= 0 ||
            roomCollaborationPanel.Bounds.Width <= 0)
            return;
        var current = roomCollaborationPanel.TranslatePoint(
            new Point(0, 0),
            editorWorkbench);
        if (!current.HasValue) return;
        var baseLeft = current.Value.X - roomCollaborationTransform.X;
        var baseTop = current.Value.Y - roomCollaborationTransform.Y;
        roomCollaborationTransform.X = Math.Clamp(
            roomCollaborationTransform.X,
            4 - baseLeft,
            Math.Max(
                4 - baseLeft,
                editorWorkbench.Bounds.Width -
                roomCollaborationPanel.Bounds.Width - baseLeft - 4));
        roomCollaborationTransform.Y = Math.Clamp(
            roomCollaborationTransform.Y,
            4 - baseTop,
            Math.Max(
                4 - baseTop,
                editorWorkbench.Bounds.Height -
                roomCollaborationPanel.Bounds.Height - baseTop - 4));
    }

