    private static Button ExtensionPaletteButton(
        string text,
        Control? icon,
        EventHandler<RoutedEventArgs> handler,
        bool modeButton = false)
    {
        Control content;
        if (icon == null)
        {
            content = new TextBlock
            {
                Text = text,
                HorizontalAlignment = HorizontalAlignment.Center,
                VerticalAlignment = VerticalAlignment.Center
            };
        }
        else
        {
            content = new StackPanel
            {
                Orientation = Orientation.Horizontal,
                HorizontalAlignment = HorizontalAlignment.Center,
                VerticalAlignment = VerticalAlignment.Center,
                Children =
                {
                    icon,
                    new TextBlock
                    {
                        Text = text,
                        Margin = new Thickness(7, 0, 0, 0),
                        VerticalAlignment = VerticalAlignment.Center
                    }
                }
            };
        }

        var button = new Button
        {
            Padding = new Thickness(7, 4),
            Background = modeButton
                ? new SolidColorBrush(Color.Parse("#202428"))
                : Brushes.Transparent,
            Foreground = Brushes.White,
            BorderBrush = StrokeBrush,
            BorderThickness = new Thickness(1),
            CornerRadius = new CornerRadius(3),
            Content = content
        };
        button.Click += handler;
        return button;
    }

    private void ToggleExtensionPalette()
    {
        extensionPalette.IsVisible = !extensionPalette.IsVisible;
        if (extensionMenuButton != null)
        {
            extensionMenuButton.Tag = extensionPalette.IsVisible ? "Active" : null;
            extensionMenuButton.Background = extensionPalette.IsVisible
                ? new SolidColorBrush(Color.Parse("#22282A"))
                : Brushes.Transparent;
            extensionMenuButton.BorderBrush = extensionPalette.IsVisible
                ? new SolidColorBrush(Color.Parse("#5F7E82"))
                : Brushes.Transparent;
            extensionMenuButton.Foreground = extensionPalette.IsVisible
                ? new SolidColorBrush(Color.Parse("#F0F2F2"))
                : new SolidColorBrush(Color.Parse("#D0D4D6"));
            AutomationProperties.SetHelpText(
                extensionMenuButton,
                extensionPalette.IsVisible ? "拓展功能已展开" : "拓展功能已收起");
        }
        if (extensionPalette.IsVisible)
            Dispatcher.UIThread.Post(ClampExtensionPalettePosition, DispatcherPriority.Loaded);
        timeline.Focus();
    }

    private void FilterSelectionByNoteType(bool longNotes)
    {
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        var count = WindowsNoteTypeTransformCommand.FilterSelectionByNoteType(
            tab.Session,
            longNotes,
            tab.HiddenGroups);
        timeline.SetSelectedTiming(null);
        SyncTimingListSelection([]);
        UpdateSelectionUi();
        viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("已保留 {0} 个{1}", count, (longNotes ? AvaloniaLocalizationCatalog.Text("面") : AvaloniaLocalizationCatalog.Text("米"))));
    }

    private void ToggleLongNoteBodyVisibility()
    {
        var enabled = !timeline.HideLongNoteBodies;
        timeline.SetHideLongNoteBodies(enabled);
        if (hideLongNoteBodiesButton != null)
        {
            ApplyQuickPaletteModeState(hideLongNoteBodiesButton, enabled);
            AutomationProperties.SetHelpText(
                hideLongNoteBodiesButton,
                enabled ? "隐藏面身已开启" : "隐藏面身已关闭");
        }
        viewModel.SetStatus(enabled
            ? "已隐藏 LN 身体和尾部：头部 Note 以边框色区分"
            : "已恢复 LN 身体显示");
        timeline.Focus();
    }

    private void ExtensionPaletteHeader_PointerPressed(
        object? sender,
        PointerPressedEventArgs eventArgs)
    {
        if (sender is not Control header ||
            !eventArgs.GetCurrentPoint(header).Properties.IsLeftButtonPressed)
            return;
        var current = extensionPalette.TranslatePoint(new Point(0, 0), timeline);
        if (!current.HasValue) return;
        extensionPaletteDragging = true;
        extensionPaletteDragStart = eventArgs.GetPosition(timeline);
        extensionPaletteDragStartX = extensionPaletteTransform.X;
        extensionPaletteDragStartY = extensionPaletteTransform.Y;
        extensionPaletteBaseLeft = current.Value.X - extensionPaletteTransform.X;
        extensionPaletteBaseTop = current.Value.Y - extensionPaletteTransform.Y;
        eventArgs.Pointer.Capture(header);
        eventArgs.Handled = true;
    }

    private void ExtensionPaletteHeader_PointerMoved(
        object? sender,
        PointerEventArgs eventArgs)
    {
        if (!extensionPaletteDragging || sender is not Control header ||
            !eventArgs.GetCurrentPoint(header).Properties.IsLeftButtonPressed)
            return;
        var point = eventArgs.GetPosition(timeline);
        extensionPaletteTransform.X = extensionPaletteDragStartX + point.X - extensionPaletteDragStart.X;
        extensionPaletteTransform.Y = extensionPaletteDragStartY + point.Y - extensionPaletteDragStart.Y;
        ClampExtensionPalettePosition();
        eventArgs.Handled = true;
    }

    private void ExtensionPaletteHeader_PointerReleased(
        object? sender,
        PointerReleasedEventArgs eventArgs)
    {
        _ = sender;
        if (!extensionPaletteDragging) return;
        extensionPaletteDragging = false;
        eventArgs.Pointer.Capture(null);
        eventArgs.Handled = true;
    }

    private void ClampExtensionPalettePosition()
    {
        if (timeline.Bounds.Width <= 0 || timeline.Bounds.Height <= 0 ||
            extensionPalette.Bounds.Width <= 0 || extensionPalette.Bounds.Height <= 0)
            return;
        var current = extensionPalette.TranslatePoint(new Point(0, 0), timeline);
        if (!current.HasValue) return;
        var baseLeft = current.Value.X - extensionPaletteTransform.X;
        var baseTop = current.Value.Y - extensionPaletteTransform.Y;
        extensionPaletteTransform.X = Math.Clamp(
            extensionPaletteTransform.X,
            4 - baseLeft,
            Math.Max(
                4 - baseLeft,
                timeline.Bounds.Width - extensionPalette.Bounds.Width - baseLeft - 4));
        extensionPaletteTransform.Y = Math.Clamp(
            extensionPaletteTransform.Y,
            4 - baseTop,
            Math.Max(
                4 - baseTop,
                timeline.Bounds.Height - extensionPalette.Bounds.Height - baseTop - 4));
    }

