    private void AddQuickTimelineToolButton(
        StackPanel panel,
        TimelineTool tool,
        string text,
        string geometry,
        bool filledIcon = false)
    {
        var button = QuickPaletteButton(
            text,
            geometry,
            (_, _) => SetTimelineTool(tool),
            out _,
            filledIcon);
        AutomationProperties.SetAutomationId(button, $"Editor.QuickTool.{tool}");
        quickTimelineToolButtons.Add(tool, button);
        RegisterQuickShortcutButton(
            tool switch
            {
                TimelineTool.Select => "ToolSelect",
                TimelineTool.Tap => "ToolTap",
                TimelineTool.Hold => "ToolHold",
                TimelineTool.Erase => "ToolErase",
                _ => throw new ArgumentOutOfRangeException(nameof(tool), tool, null)
            },
            AvaloniaLocalizationCatalog.Format("{0}工具", text),
            button);
        panel.Children.Add(button);
    }

