            RowSpacing = 6
        };
        anchorGrid.Children.Add(anchorLineButton);
        anchorGrid.Children.Add(anchorLineAboveButton);
        anchorGrid.Children.Add(anchorCellButton);
        anchorGrid.Children.Add(anchorCellBottomButton);
