            AvaloniaLocalizationCatalog.Format("{0:0.00} DIP 基准", editorViewSettings.SubdivisionLineThickness);
        judgementLinePositionValueText.Text = $"{editorViewSettings.JudgementLinePosition:P0}";
        judgementLineThicknessValueText.Text =
            $"{editorViewSettings.JudgementLineThickness:0.0} DIP";
