            ? AvaloniaLocalizationCatalog.Format("自动备份已启用：每 {0} 分钟", editorViewSettings.AutoBackupMinutes)
            : "自动备份已关闭");
    }

    private void AutoBackupIntervalSlider_ValueChanged(
        object? sender,
        RangeBaseValueChangedEventArgs eventArgs)
    {
        _ = sender;
        _ = eventArgs;
