    private void ConfigureAutoBackupTimer()
    {
        autoBackupTimer.Stop();
        autoBackupTimer.Interval = evidenceChartMode &&
                                   evidenceAutoBackupDelayMilliseconds > 0
            ? TimeSpan.FromMilliseconds(evidenceAutoBackupDelayMilliseconds)
            : TimeSpan.FromMinutes(editorViewSettings.AutoBackupMinutes);
        if (initialized &&
            (editorViewSettings.AutoBackupEnabled ||
             evidenceChartMode && evidenceAutoBackupDelayMilliseconds > 0) &&
            !windowClosePreflightInProgress)
            autoBackupTimer.Start();
    }

    private async void AutoBackupTimer_Tick(object? sender, EventArgs eventArgs)
    {
        _ = sender;
        _ = eventArgs;
        if (autoBackupInProgress || !editorViewSettings.AutoBackupEnabled) return;
        activeBackupTask = RunAutomaticBackupAsync();
        await activeBackupTask;
    }

    private async Task RunAutomaticBackupAsync()
    {
        var targets = viewModel.Tabs
            .Where(tab =>
                tab.Session.IsDirty &&
                (!lastBackupChangeSerials.TryGetValue(tab.Id, out var serial) ||
                 serial != tab.Session.ChangeSerial))
            .ToArray();
        if (targets.Length == 0) return;

        autoBackupInProgress = true;
        var completed = 0;
        var failures = new List<string>();
        try
        {
            foreach (var tab in targets)
            {
                try
                {
                    await BackupTabAsync(tab);
                    completed++;
                }
                catch (Exception exception)
                {
                    failures.Add($"{tab.DisplayTitle}：{exception.Message}");
                }
            }
            if (completed > 0)
            {
                var message =
                    WindowsTransientToastParityPolicy.FormatAutomaticBackupSuccess(completed);
                backupCacheStatusText.Text = message;
                ShowEditorToast(message);
                viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("自动备份完成：{0} 张谱面", completed));
            }
            if (failures.Count > 0)
            {
                backupCacheStatusText.Text = AvaloniaLocalizationCatalog.Format("自动备份失败：{0}", failures[0]);
                viewModel.SetStatus(backupCacheStatusText.Text);
            }
        }
        finally
        {
            autoBackupInProgress = false;
        }
    }

    private async Task<string> BackupTabAsync(DesktopChartTab tab)
    {
        ArgumentNullException.ThrowIfNull(tab);
        var snapshot = tab.Session.CaptureCommittedDocument();
        var serial = tab.Session.ChangeSerial;
        var sourcePath = tab.SourcePath;
        var path = await Task.Run(() => ChartBackupArchiveService.CreateBackup(
            AvaloniaAppPaths.EditorBackupRoot,
            snapshot,
            sourcePath));
        lastBackupChangeSerials[tab.Id] = serial;
        return path;
    }

    private async Task BackupCurrentTabAsync()
    {
        var tab = viewModel.ActiveTab;
        if (tab == null)
        {
            await ShowSettingsMessageAsync("备份", "请先打开一张谱面。");
            return;
        }
        if (!TryApplyPendingMetadataEditor(
                tab,
                enforceCommunityRules: false))
            return;
        if (autoBackupInProgress)
        {
            backupCacheStatusText.Text = "自动备份正在进行，请稍后。";
            return;
        }

        autoBackupInProgress = true;
        try
        {
            backupCacheStatusText.Text = "正在备份…";
            var path = await BackupTabAsync(tab);
            backupCacheStatusText.Text = AvaloniaLocalizationCatalog.Format("已备份：{0}", Path.GetFileName(path));
            viewModel.SetStatus(backupCacheStatusText.Text);
            await ShowSettingsMessageAsync("备份完成", path);
        }
        catch (Exception exception)
        {
            backupCacheStatusText.Text = AvaloniaLocalizationCatalog.Format("备份失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message));
            await ShowSettingsMessageAsync("备份失败", exception.Message);
        }
        finally
        {
            autoBackupInProgress = false;
        }
    }

    private async Task RestoreBackupAsync()
    {
        // Both buttons call this from async handlers. The picker preamble (backup
        // folder creation, storage lookup, platform picker) used to sit outside
        // any try, so an unreachable backup root ended the process.
        try
        {
            await RestoreBackupCoreAsync();
        }
        catch (Exception exception)
        {
            Debug.WriteLine($"Restoring a backup failed: {exception}");
            if (windowCloseTeardownStarted) return;
            backupCacheStatusText.Text = AvaloniaLocalizationCatalog.Format("恢复备份失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message));
            await ShowSettingsMessageAsync("恢复备份失败", exception.Message);
        }
    }

    private async Task RestoreBackupCoreAsync()
    {
        Directory.CreateDirectory(AvaloniaAppPaths.EditorBackupRoot);
        var start = await StorageProvider.TryGetFolderFromPathAsync(AvaloniaAppPaths.EditorBackupRoot);
        var path = await PickLocalFileAsync(
            new FilePickerOpenOptions
            {
                Title = "选择 LumaChart 谱面备份",
                AllowMultiple = false,
                SuggestedStartLocation = start,
                FileTypeFilter =
                [
                    // No registered MIME type describes .mcbackup, so a document
                    // picker that filters by type must not narrow this at all.
                    new FilePickerFileType("LumaChart 备份")
                        { Patterns = ["*.mcbackup"], MimeTypes = ["*/*"] }
                ]
            },
            PickedFileRetention.Transient);
        if (string.IsNullOrWhiteSpace(path)) return;

        ChartBackupArchive backup;
        try
        {
            backup = await Task.Run(() => ChartBackupArchiveService.LoadBackup(path));
        }
        catch (Exception exception)
        {
            await ShowSettingsMessageAsync("无法读取备份", exception.Message);
            return;
        }

        var existing = !string.IsNullOrWhiteSpace(backup.OriginalPath)
            ? viewModel.Tabs.FirstOrDefault(tab => PathsEqual(tab.SourcePath, backup.OriginalPath))
            : null;
        if (existing?.Session.IsReadOnly == true)
        {
            // A room observer's tab is read-only: replacing its document would
            // bypass that and feed the backup into the room. Refuse rather than
            // improvise a new tab; the backup file stays where it is.
            await ShowSettingsMessageAsync("恢复备份", "当前谱面为只读状态，不能执行该编辑命令。");
            return;
        }
        var originalExists = !string.IsNullOrWhiteSpace(backup.OriginalPath) &&
                             File.Exists(backup.OriginalPath);
        var destination = existing != null
            ? AvaloniaLocalizationCatalog.Format("已打开的标签“{0}”", existing.DisplayTitle)
            : originalExists
                ? backup.OriginalPath!
                : "工作目录中的新建恢复谱面";
        var source = string.IsNullOrWhiteSpace(backup.OriginalPath)
            ? "原路径未记录"
            : backup.OriginalPath;
        var confirmed = await ShowSettingsConfirmationAsync(
            "恢复备份",
            AvaloniaLocalizationCatalog.Format("备份：{0} [{1}]\n时间：{2:yyyy-MM-dd HH:mm:ss}\n原谱面：{3}\n\n将恢复到：{4}\n恢复后会标记为未保存，确认内容后再手动保存。", backup.Document.Metadata.Title, backup.Document.Metadata.Version, backup.CreatedAt.ToLocalTime(), source, destination),
            "恢复",
            dangerous: false);
        if (!confirmed) return;

        // Activating or creating the target tab repopulates the metadata panel,
        // which silently dropped its unapplied input. Commit it to the current
        // tab first (so the safety backup below also captures it); stay if the
        // input is invalid, the panel already reports why.
        if (viewModel.ActiveTab is { } activeTab &&
            !TryApplyPendingMetadataEditor(activeTab, enforceCommunityRules: false))
            return;

        try
        {
            if (existing?.Session.IsDirty == true) await BackupTabAsync(existing);
            DesktopChartTab target;
            if (existing != null)
            {
                target = existing;
                viewModel.Activate(target.Id);
            }
            else if (originalExists)
            {
                await viewModel.OpenAsync(backup.OriginalPath!);
                target = viewModel.ActiveTab ??
                         throw new InvalidOperationException("原谱面未能进入编辑缓存。");
            }
            else
            {
                await viewModel.CreateAsync(
                    AvaloniaLocalizationCatalog.Format("{0} 恢复", backup.Document.Metadata.Title),
                    backup.Document.Metadata.Creator);
                target = viewModel.ActiveTab ??
                         throw new InvalidOperationException("恢复谱面未能进入编辑缓存。");
            }

            // Checked again at the point of no return: room permissions can turn
            // the tab read-only while the confirmation was open.
            if (target.Session.IsReadOnly)
                throw new InvalidOperationException("当前谱面为只读状态，不能执行该编辑命令。");
            var restored = backup.Document.Clone();
            restored.FilePath = target.WorkingPath;
            target.Session.ReplaceDocument(restored, markDirty: true);
            lastBackupChangeSerials[target.Id] = target.Session.ChangeSerial;
            if (!await viewModel.PersistAsync())
                throw new IOException(viewModel.Status);
            timeline.SetCurrentBeat(0);
            viewModel.UpdateCurrentBeat(0);
            ShowEditorSurface();
            backupCacheStatusText.Text = AvaloniaLocalizationCatalog.Format("已恢复备份：{0}", Path.GetFileName(backup.BackupPath));
            viewModel.SetStatus(backupCacheStatusText.Text);
        }
        catch (Exception exception)
        {
            backupCacheStatusText.Text = AvaloniaLocalizationCatalog.Format("恢复备份失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message));
            await ShowSettingsMessageAsync("恢复备份失败", exception.Message);
        }
    }

    private void OpenBackupFolder()
    {
        try
        {
            Directory.CreateDirectory(AvaloniaAppPaths.EditorBackupRoot);
            Process.Start(new ProcessStartInfo
            {
                FileName = "explorer.exe",
                Arguments = $"\"{AvaloniaAppPaths.EditorBackupRoot}\"",
                UseShellExecute = true
            });
        }
        catch (Exception exception)
        {
            backupCacheStatusText.Text = AvaloniaLocalizationCatalog.Format("无法打开备份目录：{0}", AvaloniaLocalizationCatalog.Text(exception.Message));
        }
    }

    private async Task CleanSelectedCacheAsync()
    {
        if (autoBackupInProgress)
        {
            backupCacheStatusText.Text = "自动备份正在进行，请稍后再清理。";
            return;
        }
        if (cacheResourceFilesBox.IsChecked == true && roomChartSyncRoomId != null)
        {
            backupCacheStatusText.Text = "活动联机房间正在使用资源；请先离开房间再清理联机缓存。";
            return;
        }

        var categories = new List<string>();
        if (cacheBackupFilesBox.IsChecked == true)
            categories.Add("自动备份文件");
        if (cacheEditingFilesBox.IsChecked == true)
            categories.Add("未打开的编辑缓存");
        if (cacheResourceFilesBox.IsChecked == true)
            categories.Add("联机资源缓存");
        if (categories.Count == 0)
        {
            backupCacheStatusText.Text = "请至少勾选一个需要清理的类别。";
            return;
        }

        var editingWarning = cacheEditingFilesBox.IsChecked == true
            ? AvaloniaLocalizationCatalog.Format("\n\n未打开的编辑缓存可能包含上次异常退出后尚未保存的内容；当前打开的谱面会自动跳过。")
            : string.Empty;
        // Stop automatic backups before the modal confirmation, not after it: a
        // backup started while the dialog is open would be writing into the
        // folder that is about to be cleaned.
        autoBackupTimer.Stop();
        cleanSelectedCacheButton.IsEnabled = false;
        try
        {
            var confirmed = await ShowSettingsConfirmationAsync(
                "缓存管理",
                AvaloniaLocalizationCatalog.Format("即将清理：{0}。此操作不可撤销。{1}\n\n是否继续？", string.Join("、", categories), editingWarning),
                "继续清理",
                dangerous: true);
            if (!confirmed) return;
            // Re-check the preconditions the confirmation waited on.
            if (autoBackupInProgress)
            {
                backupCacheStatusText.Text = "自动备份正在进行，请稍后再清理。";
                return;
            }
            if (cacheResourceFilesBox.IsChecked == true && roomChartSyncRoomId != null)
            {
                backupCacheStatusText.Text = "活动联机房间正在使用资源；请先离开房间再清理联机缓存。";
                return;
            }

            // Build the targets only after the confirmation. The editing caches
            // an open tab, a suspended previous session or the manifest still
            // needs are protected by the workspace itself, inside its gate, so
            // no tab can open while the cleanup runs.
            var targets = new List<ManagedStorageCleanupTarget>();
            if (cacheBackupFilesBox.IsChecked == true)
                targets.Add(new ManagedStorageCleanupTarget(AvaloniaAppPaths.EditorBackupRoot));
            if (cacheEditingFilesBox.IsChecked == true)
                targets.Add(new ManagedStorageCleanupTarget(
                    AvaloniaAppPaths.DesktopDocumentCacheRoot));
            if (cacheResourceFilesBox.IsChecked == true)
                targets.Add(new ManagedStorageCleanupTarget(
                    AvaloniaAppPaths.OnlineRoomResourceCacheRoot));

            backupCacheStatusText.Text = "正在安全清理…";
            var result = await viewModel.RunCacheCleanupAsync(targets);
            var summary =
                AvaloniaLocalizationCatalog.Format("已清理 {0} 个文件、{1} 个目录，释放 {2}", result.FilesDeleted, result.DirectoriesDeleted, FormatTransferBytes(result.BytesFreed));
            if (result.Failures.Count > 0)
                summary += AvaloniaLocalizationCatalog.Format("；{0} 项因占用或安全检查被跳过", result.Failures.Count);
            backupCacheStatusText.Text = summary;
            viewModel.SetStatus(summary);
            if (result.Failures.Count > 0)
            {
                await ShowSettingsMessageAsync(
                    "缓存清理完成",
                    $"{summary}\n\n{string.Join("\n", result.Failures.Take(6))}");
            }
        }
        catch (Exception exception)
        {
            backupCacheStatusText.Text = "缓存清理失败。";
            await ShowSettingsMessageAsync("缓存清理失败", exception.Message);
        }
        finally
        {
            cleanSelectedCacheButton.IsEnabled = true;
            ConfigureAutoBackupTimer();
        }
    }

    private Task<bool> ShowSettingsConfirmationAsync(
        string title,
        string message,
        string primaryText,
        bool dangerous) =>
        new SettingsActionDialog(
                title,
                message,
                primaryText,
                showCancel: true,
                dangerous,
                displayScaleSettings.UiScale,
                displayScaleSettings.FontScale)
            .ShowDialog<bool>(this);

    private async Task ShowSettingsMessageAsync(string title, string message)
    {
        await new SettingsActionDialog(
                title,
                message,
                "知道了",
                showCancel: false,
                dangerous: false,
                displayScaleSettings.UiScale,
                displayScaleSettings.FontScale)
            .ShowDialog<bool>(this);
    }

    private static bool PathsEqual(string left, string? right)
    {
        if (string.IsNullOrWhiteSpace(right)) return false;
        try
        {
            return string.Equals(
                Path.TrimEndingDirectorySeparator(Path.GetFullPath(left)),
                Path.TrimEndingDirectorySeparator(Path.GetFullPath(right)),
                StringComparison.OrdinalIgnoreCase);
        }
        catch (Exception)
        {
            return false;
        }
    }

    private Control BuildMetadataEditor()
    {
        metadataTitleBox.PlaceholderText = "本地谱面不限字符";
        metadataTitleOriginalBox.PlaceholderText = "歌曲名原文";
