        static ColumnDefinitions MetadataPairColumns() => new(
            $"*,{WindowsInspectorParityPolicy.MetadataPairGap.ToString(CultureInfo.InvariantCulture)},*");
        static ColumnDefinitions MetadataActionColumns(double width) => new(
            $"*,{width.ToString(CultureInfo.InvariantCulture)}");
        static Grid MetadataActionRow(
            Control field,
            Button action,
            double actionWidth)
        {
            field.MinWidth = 0;
            field.HorizontalAlignment = HorizontalAlignment.Stretch;
            field.ClipToBounds = true;
            action.MinWidth = 0;
            action.MaxWidth = actionWidth - 4;
            action.HorizontalAlignment = HorizontalAlignment.Stretch;
            var row = new Grid
            {
                MinWidth = 0,
                HorizontalAlignment = HorizontalAlignment.Stretch,
                ClipToBounds = true,
                ColumnDefinitions = MetadataActionColumns(actionWidth)
            };
            row.Children.Add(new InspectorFlexibleField { Child = field });
            Grid.SetColumn(action, 1);
            row.Children.Add(action);
            return row;
        }

        // Half-width metadata columns must stay half width. A long creator name
        // or a BPM such as 170.0000000000001 otherwise widens its star column
        // and drags the neighbouring column past the inspector edge.
        static StackPanel MetadataPairField(string label, Control value) =>
            TimingField(label, new InspectorFlexibleField { Child = value });

