        metadataBackgroundFileBox.Margin = new Thickness(0, 0, 7, 0);
        var backgroundRow = MetadataActionRow(
            metadataBackgroundFileBox,
            metadataBackgroundSelectButton,
            WindowsInspectorParityPolicy.MetadataFileActionColumnWidth);

        var analysisButtons = new StackPanel
        {
            Spacing = 0,
            Children =
            {
                metadataAnalyzeSingleTempoButton,
                metadataAnalyzeVariableTempoButton,
                metadataAnalyzeManualTempoButton
            }
        };

        metadataPreviewTimeBox.Margin = new Thickness(0, 0, 7, 0);
        var previewRow = MetadataActionRow(
            metadataPreviewTimeBox,
            metadataPreviewHereButton,
            WindowsInspectorParityPolicy.MetadataPreviewActionColumnWidth);

        var offsetPreview = TimingField("预览时间（ms）", previewRow);
        timingMetadataSection = new StackPanel { Spacing = 8, Margin = new Thickness(16, 12), Children =
        {
            new TextBlock { Text = "参考 BPM / 音频 Offset", FontSize = 16, Foreground = Brushes.White },
            TimingField("参考 BPM（显示/速度补偿）", metadataBpmBox),
            TimingField("音频 Offset（ms）", metadataOffsetBox),
            analysisButtons, metadataAudioAnalysisText,
            PrimaryButton("应用 Timing 基础信息", (_, _) => ApplyTimingMetadata())
        } };

        var metadataStatsGrid =
            new Grid { ColumnDefinitions = new ColumnDefinitions("*,*,*") };
        var metadataStatValues = new[]
        {
            metadataStatsNotesText,
            metadataStatsHoldsText,
            metadataStatsTimingText
        };
        for (var index = 0; index < metadataStatValues.Length; index++)
        {
            var value = metadataStatValues[index];
            value.FontSize = WindowsInspectorParityPolicy.MetadataStatValueFontSize;
            value.FontWeight = FontWeight.SemiBold;
            value.Foreground = new SolidColorBrush(Color.Parse("#E2E5E6"));
            AutomationProperties.SetAutomationId(
                value,
                $"Metadata.Stats.{WindowsInspectorParityPolicy.Wpf110MetadataStatLabels[index]}");
            var label = new TextBlock
            {
                Text = WindowsInspectorParityPolicy.Wpf110MetadataStatLabels[index],
