            ],
            WindowsInspectorParityPolicy.ResolveNoteTabIndex);
    }

    private static void ApplyWpf110InspectorTabOrder(
        string inspectorName,
        IReadOnlyList<Control> controls,
        Func<string?, int> resolveTabIndex)
    {
        var assignedIndices = new HashSet<int>();
        foreach (var control in controls)
        {
            var automationId = AutomationProperties.GetAutomationId(control);
            var tabIndex = resolveTabIndex(automationId);
            if (tabIndex < 0 || !assignedIndices.Add(tabIndex))
            {
                throw new InvalidOperationException(
                    $"Invalid WPF 1.1.0 {inspectorName} focus target: " +
                    $"{automationId ?? "<null>"} -> {tabIndex}");
            }

            KeyboardNavigation.SetTabIndex(control, tabIndex);
        }

        if (assignedIndices.Count != controls.Count ||
            !Enumerable.Range(0, controls.Count).All(assignedIndices.Contains))
        {
            throw new InvalidOperationException(
                $"WPF 1.1.0 {inspectorName} focus order is not contiguous.");
        }
    }

