            "Group 分配选择",
            AssignSelectionToGroup);
        ConfigureGroupButton(
            groupShowAllButton,
            "全部显示",
            "Group 全部显示",
            ShowAllGroups);
        ConfigureGroupButton(
            groupHideNonzeroButton,
            "隐藏非零组",
            "Group 隐藏非零",
            HideNonzeroGroups);
        ConfigureGroupButton(
            groupClearSelectedButton,
            "清除分组",
            "Group 清除分组",
            ClearSelectedGroups);
        ApplyWpfPrimaryButtonStyle(groupCreateAndUseButton);
        ApplyWpfPrimaryButtonStyle(groupSetCurrentButton);
        ApplyWpfAssignButtonStyle(groupAssignButton);
        ApplyWpfToolButtonStyle(groupShowAllButton);
        ApplyWpfToolButtonStyle(groupHideNonzeroButton);
        ApplyWpfToolButtonStyle(groupClearSelectedButton);
        AutomationProperties.SetAutomationId(
            groupCreateAndUseButton,
            "Inspector.Group.CreateAndUse");
        AutomationProperties.SetAutomationId(groupIdBox, "Inspector.Group.Id");
        AutomationProperties.SetAutomationId(
            groupSetCurrentButton,
            "Inspector.Group.SetCurrent");
        AutomationProperties.SetAutomationId(
            groupAssignButton,
            "Inspector.Group.AssignSelection");
        AutomationProperties.SetAutomationId(
            groupShowAllButton,
            "Inspector.Group.ShowAll");
        AutomationProperties.SetAutomationId(
            groupHideNonzeroButton,
            "Inspector.Group.HideNonzero");
        AutomationProperties.SetAutomationId(
            groupClearSelectedButton,
            "Inspector.Group.ClearSelection");
        ApplyWpf110InspectorTabOrder(
            "Group",
            [
                groupCreateAndUseButton,
                groupIdBox,
                groupSetCurrentButton,
                groupAssignButton,
                groupShowAllButton,
                groupHideNonzeroButton,
                groupClearSelectedButton
            ],
            WindowsInspectorParityPolicy.ResolveGroupStaticTabIndex);

        var heading = new Grid { ColumnDefinitions = new ColumnDefinitions("*,Auto") };
        heading.Children.Add(new StackPanel
        {
            Children =
            {
                new TextBlock
                {
                    Text = "Group Manager",
                    Foreground = Brushes.White,
                    FontSize = WindowsInspectorParityPolicy.GroupTitleFontSize,
                    FontWeight = FontWeight.SemiBold
                },
                new TextBlock
                {
                    Text = "按音色组织 Note · 隐藏只影响编辑显示",
                    Foreground = MutedBrush,
                    FontSize = 10
                }
            }
        });
        Grid.SetColumn(groupCreateAndUseButton, 1);
        heading.Children.Add(groupCreateAndUseButton);

        var current = new Border
        {
            Background = PanelBrush,
            BorderBrush = StrokeBrush,
            BorderThickness = new Thickness(1),
            CornerRadius = new CornerRadius(4),
            Padding = new Thickness(9, 7),
            Margin = new Thickness(0, 12, 0, 2),
            Child = new Grid
            {
                ColumnDefinitions = new ColumnDefinitions("*,Auto"),
                Children =
                {
                    new TextBlock
                    {
                        Text = "当前放置分组",
                        Foreground = MutedBrush,
                        VerticalAlignment = VerticalAlignment.Center
                    },
                    currentPlacementGroupText
                }
            }
        };
        Grid.SetColumn(currentPlacementGroupText, 1);

        var idAndUse = new Grid { ColumnDefinitions = new ColumnDefinitions("82,8,*") };
        idAndUse.Children.Add(groupIdBox);
        Grid.SetColumn(groupSetCurrentButton, 2);
        idAndUse.Children.Add(groupSetCurrentButton);

        var visibilityActions = new UniformGrid { Columns = 3 };
        visibilityActions.Children.Add(groupShowAllButton);
        visibilityActions.Children.Add(groupHideNonzeroButton);
        visibilityActions.Children.Add(groupClearSelectedButton);

        return new StackPanel
        {
            Spacing = 8,
            Children =
            {
                heading,
                current,
                groupManagerHint,
                idAndUse,
                groupAssignButton,
                visibilityActions,
                new Border { Height = 1, Background = StrokeBrush, Margin = new Thickness(0, 4) },
                groupListPanel
            }
        };
    }

    private static void ConfigureGroupButton(
        Button button,
        string content,
        string automationName,
        Action action)
    {
        button.Content = content;
        button.Click += (_, _) => action();
        ApplyPrimaryButtonStyle(button);
        button.Padding = new Thickness(7, 6);
        AutomationProperties.SetName(button, automationName);
    }

    private Control BuildAudioTransport()
    {
        audioPlayPauseButton.Content = "▶ 播放";
        audioPlayPauseButton.Click += async (_, _) => await ToggleAudioPlaybackAsync();
        ApplyPrimaryButtonStyle(audioPlayPauseButton);
        AutomationProperties.SetAutomationId(audioPlayPauseButton, "Audio.PlayPause");

        audioStopButton.Content = "■ 停止";
        audioStopButton.Click += async (_, _) => await StopAudioAsync();
        ApplyPrimaryButtonStyle(audioStopButton);
        AutomationProperties.SetAutomationId(audioStopButton, "Audio.Stop");

        audioRefreshDeviceButton.Content = SupportsDesktopWindowSizing
            ? "刷新输出设备"
            : "重建音频输出";
        audioRefreshDeviceButton.Click += async (_, _) =>
            await RefreshEditorAudioDeviceAsync();
        ApplyPrimaryButtonStyle(audioRefreshDeviceButton);
        AutomationProperties.SetAutomationId(audioRefreshDeviceButton, "Audio.RefreshDevice");

        audioPositionSlider.Minimum = 0;
        audioPositionSlider.Maximum = 1;
        audioPositionSlider.Value = 0;
        ConstrainInspectorSlider(audioPositionSlider);
        AutomationProperties.SetAutomationId(audioPositionSlider, "Audio.Position");
        audioPositionSlider.AddHandler(
            InputElement.PointerPressedEvent,
            (_, _) => audioPositionPointerDown = true,
            RoutingStrategies.Tunnel);
        audioPositionSlider.AddHandler(
            InputElement.PointerReleasedEvent,
            async (_, _) =>
            {
                audioPositionPointerDown = false;
                await SeekAudioFromSliderAsync();
            },
            RoutingStrategies.Tunnel);
        audioPositionSlider.PointerCaptureLost += async (_, _) =>
        {
            if (!audioPositionPointerDown) return;
            audioPositionPointerDown = false;
            await SeekAudioFromSliderAsync();
        };
        audioPositionSlider.ValueChanged += async (_, _) =>
        {
            if (!suppressAudioControls && !audioPositionPointerDown && audioPositionSlider.IsFocused)
                await SeekAudioFromSliderAsync();
        };

        audioVolumeSlider.Minimum = 0;
        audioVolumeSlider.Maximum = 100;
        audioVolumeSlider.Value = 80;
        ConstrainInspectorSlider(audioVolumeSlider);
        AutomationProperties.SetAutomationId(audioVolumeSlider, "Audio.Volume");
        audioVolumeSlider.ValueChanged += async (_, eventArgs) =>
        {
            if (suppressAudioControls) return;
            audioVolumeText.Text = $"{eventArgs.NewValue:0}%";
            var volume = Math.Clamp(eventArgs.NewValue / 100, 0, 1);
            await audioTransport.SetVolumeAsync((float)volume);
            editorViewSettings = editorViewSettings.WithMusicVolume(volume);
            MarkEditorViewSettingsDirty();
        };

        audioRateSlider.Minimum = .2;
        audioRateSlider.Maximum = 2;
        audioRateSlider.Value = 1;
        audioRateSlider.SmallChange = .05;
        audioRateSlider.LargeChange = .1;
        ConstrainInspectorSlider(audioRateSlider);
        AutomationProperties.SetAutomationId(audioRateSlider, "Audio.Rate");
        audioRateSlider.ValueChanged += async (_, eventArgs) =>
        {
            if (suppressAudioControls) return;
            var rate = Math.Round(eventArgs.NewValue, 2);
            audioRateText.Text = $"{rate:0.00}x";
            await SetEditorPlaybackRateAsync(rate);
        };

        audioPreservePitchBox.Content = "变速不变调";
        audioPreservePitchBox.Foreground = Brushes.White;
        AutomationProperties.SetAutomationId(audioPreservePitchBox, "Audio.PreservePitch");
        audioPreservePitchBox.IsCheckedChanged += async (_, _) =>
        {
            if (!suppressAudioControls)
                await SetEditorPreservePitchAsync(audioPreservePitchBox.IsChecked == true);
        };

        waveformBackgroundBox.Content = "背景波形";
        waveformBackgroundBox.Foreground = Brushes.White;
        waveformBackgroundBox.IsChecked = evidenceEnableBackgroundWaveform;
        ToolTip.SetTip(
            waveformBackgroundBox,
            "WPF 默认是展开的侧栏波形；背景模式默认关闭，勾选后铺在可玩轨道背景");
        waveformBackgroundBox.IsCheckedChanged += (_, _) =>
        {
            if (!suppressAudioPanelControls)
                SetAudioPanelBackgroundMode(
                    WindowsAudioPanelKind.Waveform,
                    waveformBackgroundBox.IsChecked == true);
        };
        spectrogramBackgroundBox.Content = "背景频谱";
        spectrogramBackgroundBox.Foreground = Brushes.White;
        spectrogramBackgroundBox.IsChecked = evidenceEnableBackgroundSpectrogram;
        ToolTip.SetTip(
            spectrogramBackgroundBox,
            "WPF 默认折叠频谱；勾选后在可玩轨道背景显示 L/M/H 频谱");
        spectrogramBackgroundBox.IsCheckedChanged += (_, _) =>
        {
            if (!suppressAudioPanelControls)
                SetAudioPanelBackgroundMode(
                    WindowsAudioPanelKind.Spectrogram,
                    spectrogramBackgroundBox.IsChecked == true);
        };
        audioVisualizationStatusText.Text = "没有打开的谱面";
        audioVisualizationStatusText.Foreground = MutedBrush;
        audioVisualizationStatusText.FontSize = 11;
        audioVisualizationStatusText.TextWrapping = TextWrapping.Wrap;
        var visualizationToggles = new StackPanel
        {
            Orientation = Orientation.Horizontal,
            Spacing = 12,
            Children = { waveformBackgroundBox, spectrogramBackgroundBox }
        };

        audioTimeText.Text = "00:00.000 / 00:00.000";
        audioTimeText.Foreground = Brushes.White;
        audioTimeText.FontFamily = new FontFamily("Cascadia Mono, Consolas");
        audioTimeText.FontSize = 11;
        AutomationProperties.SetAutomationId(audioTimeText, "Audio.Time");
        audioRateText.Text = "1.00x";
        audioRateText.Foreground = MutedBrush;
        AutomationProperties.SetAutomationId(audioRateText, "Audio.RateText");
        audioVolumeText.Text = "80%";
        audioVolumeText.Foreground = MutedBrush;
        AutomationProperties.SetAutomationId(audioVolumeText, "Audio.VolumeText");
        audioStatusText.Text = "没有打开的谱面";
        audioStatusText.Foreground = MutedBrush;
        audioStatusText.FontSize = 11;
        audioStatusText.TextWrapping = TextWrapping.Wrap;
        AutomationProperties.SetAutomationId(audioStatusText, "Audio.RuntimeStatus");

        var transportButtons = new Grid
        {
            ColumnDefinitions = new ColumnDefinitions("*,*,Auto"),
            ColumnSpacing = 6,
            Children = { audioPlayPauseButton, audioStopButton, audioRefreshDeviceButton }
        };
        Grid.SetColumn(audioStopButton, 1);
        Grid.SetColumn(audioRefreshDeviceButton, 2);

        var rateRow = new Grid
        {
            ColumnDefinitions = new ColumnDefinitions("Auto,*,46"),
            ColumnSpacing = 8,
            Children =
            {
                new TextBlock
                {
                    Text = "倍速",
                    Foreground = MutedBrush,
                    VerticalAlignment = VerticalAlignment.Center
                },
                audioRateSlider,
                audioRateText
            }
        };
        Grid.SetColumn(audioRateSlider, 1);
        Grid.SetColumn(audioRateText, 2);
        audioRateText.VerticalAlignment = VerticalAlignment.Center;

        audioVolumeText.Margin = new Thickness(0, 5, 0, 10);

        audioPreservePitchBox.Margin = new Thickness(2, 10, 0, 2);
        ToolTip.SetTip(
            audioPreservePitchBox,
            "开启后只改变播放速度，不改变音高；切换时保持当前播放位置");
        return new StackPanel
        {
            Spacing = 7,
            Children =
            {
                TimingField("音乐音量", audioVolumeSlider),
                audioVolumeText,
                BuildKeySoundPanel(),
                audioPreservePitchBox,
                new TextBlock
                {
                    Text = "开启会使用时间伸缩处理；关闭则随倍速改变音高，性能开销更低。",
                    Foreground = MutedBrush,
                    FontSize = 10,
                    TextWrapping = TextWrapping.Wrap,
                    Margin = new Thickness(22, 3, 0, 2)
                }
            }
        };
    }

    private Control BuildKeySoundPanel()
    {
        keySoundEnabledBox.Content = "播放时启用 Key 音";
        keySoundEnabledBox.Foreground = Brushes.White;
        keySoundEnabledBox.IsCheckedChanged += (_, _) =>
        {
            if (suppressKeySoundControls) return;
            ApplyKeySoundSettings(new WindowsKeySoundSettings(
                keySoundEnabledBox.IsChecked == true,
                keySoundSettings.Volume,
                keySoundSettings.Preset,
                keySoundSettings.CustomFilePath,
                keySoundSettings.PlayLongNoteEndSound,
                keySoundSettings.GlobalOffset,
                keySoundSettings.PerChartOffsets));
        };
        AutomationProperties.SetAutomationId(keySoundEnabledBox, "KeySound.Enabled");

        keySoundPresetBox.ItemsSource = new KeySoundPresetChoice[]
        {
            new("Snare", KeySoundPreset.Snare),
            new("Tambourine", KeySoundPreset.BrightTick),
            new("Hand Drum", KeySoundPreset.HandDrum),
            new("Clap", KeySoundPreset.HandDrum2),
            new("Kick", KeySoundPreset.DeepPulse),
            new("自定义", KeySoundPreset.Custom)
        };
        keySoundPresetBox.SelectionChanged += (_, _) =>
        {
            if (suppressKeySoundControls ||
                keySoundPresetBox.SelectedItem is not KeySoundPresetChoice choice) return;
            ApplyKeySoundSettings(new WindowsKeySoundSettings(
                keySoundSettings.EnableKeySounds,
                keySoundSettings.Volume,
                choice.Preset,
                keySoundSettings.CustomFilePath,
                keySoundSettings.PlayLongNoteEndSound,
                keySoundSettings.GlobalOffset,
                keySoundSettings.PerChartOffsets));
        };
        AutomationProperties.SetAutomationId(keySoundPresetBox, "KeySound.Preset");

        keySoundCustomFileButton.Content = "选择文件";
        keySoundCustomFileButton.Click += async (_, _) => await SelectKeySoundFileAsync();
        ApplyPrimaryButtonStyle(keySoundCustomFileButton);
        AutomationProperties.SetAutomationId(keySoundCustomFileButton, "KeySound.CustomFile");

        var presetRow = new Grid
        {
            ColumnDefinitions = new ColumnDefinitions(
                $"*,{WindowsInspectorParityPolicy.SettingsKeySoundActionWidth}"),
            ColumnSpacing = 6,
            Children = { keySoundPresetBox, keySoundCustomFileButton }
        };
        Grid.SetColumn(keySoundCustomFileButton, 1);

        keySoundCustomFileText.Text = "未选择自定义音频";
        keySoundCustomFileText.Foreground = MutedBrush;
        keySoundCustomFileText.FontSize = 10;
        keySoundCustomFileText.TextTrimming = TextTrimming.CharacterEllipsis;
        AutomationProperties.SetAutomationId(keySoundCustomFileText, "KeySound.CustomFilePath");

        keySoundVolumeSlider.Minimum = 0;
        keySoundVolumeSlider.Maximum = 100;
        keySoundVolumeSlider.Value = WindowsKeySoundSettings.DefaultVolume * 100;
        ConstrainInspectorSlider(keySoundVolumeSlider);
        keySoundVolumeSlider.ValueChanged += (_, eventArgs) =>
        {
            if (suppressKeySoundControls) return;
            ApplyKeySoundSettings(new WindowsKeySoundSettings(
                keySoundSettings.EnableKeySounds,
                eventArgs.NewValue / 100d,
                keySoundSettings.Preset,
                keySoundSettings.CustomFilePath,
                keySoundSettings.PlayLongNoteEndSound,
                keySoundSettings.GlobalOffset,
                keySoundSettings.PerChartOffsets));
        };
        AutomationProperties.SetAutomationId(keySoundVolumeSlider, "KeySound.Volume");
        keySoundVolumeText.Foreground = MutedBrush;

        var volumeRow = new Grid
        {
            ColumnDefinitions = new ColumnDefinitions("Auto,*,42"),
            ColumnSpacing = 8,
            Children =
            {
                new TextBlock
                {
                    Text = "Key 音音量",
                    Foreground = MutedBrush,
                    VerticalAlignment = VerticalAlignment.Center
                },
                keySoundVolumeSlider,
                keySoundVolumeText
            }
        };
        Grid.SetColumn(keySoundVolumeSlider, 1);
        Grid.SetColumn(keySoundVolumeText, 2);
        keySoundVolumeText.VerticalAlignment = VerticalAlignment.Center;

        keySoundLongNoteEndBox.Content = "LN 尾部也播放 Key 音";
        keySoundLongNoteEndBox.Foreground = Brushes.White;
        keySoundLongNoteEndBox.IsCheckedChanged += (_, _) =>
        {
            if (suppressKeySoundControls) return;
            ApplyKeySoundSettings(new WindowsKeySoundSettings(
                keySoundSettings.EnableKeySounds,
                keySoundSettings.Volume,
                keySoundSettings.Preset,
                keySoundSettings.CustomFilePath,
                keySoundLongNoteEndBox.IsChecked == true,
                keySoundSettings.GlobalOffset,
                keySoundSettings.PerChartOffsets));
        };
        AutomationProperties.SetAutomationId(keySoundLongNoteEndBox, "KeySound.LongNoteEnd");

        ConfigureKeySoundOffsetSlider(keySoundGlobalOffsetSlider, "KeySound.GlobalOffset");
        keySoundGlobalOffsetSlider.ValueChanged += (_, eventArgs) =>
        {
            if (suppressKeySoundControls) return;
            ApplyKeySoundSettings(new WindowsKeySoundSettings(
                keySoundSettings.EnableKeySounds,
                keySoundSettings.Volume,
                keySoundSettings.Preset,
                keySoundSettings.CustomFilePath,
                keySoundSettings.PlayLongNoteEndSound,
                (int)Math.Round(eventArgs.NewValue),
                keySoundSettings.PerChartOffsets));
        };
        keySoundGlobalOffsetText.Foreground = MutedBrush;
        keySoundGlobalOffsetText.FontSize = 10;

        ConfigureKeySoundOffsetSlider(keySoundChartOffsetSlider, "KeySound.ChartOffset");
        keySoundChartOffsetSlider.ValueChanged += (_, eventArgs) =>
        {
            if (suppressKeySoundControls || keySoundActiveTab == null) return;
            ApplyKeySoundSettings(keySoundSettings.SetChartOffset(
                keySoundActiveTab.SourcePath,
                eventArgs.NewValue));
        };
        keySoundChartOffsetText.Foreground = MutedBrush;
        keySoundChartOffsetText.FontSize = 10;
        keySoundChartOffsetText.TextWrapping = TextWrapping.Wrap;

        keySoundRuntimeStatusText.Foreground = MutedBrush;
        keySoundRuntimeStatusText.FontSize = 10;
        keySoundRuntimeStatusText.TextWrapping = TextWrapping.Wrap;
        AutomationProperties.SetAutomationId(keySoundRuntimeStatusText, "KeySound.RuntimeStatus");

        var keySoundHeader = new TextBlock
        {
            Text = "Key 音",
            Foreground = Brushes.White,
            FontSize = WindowsInspectorParityPolicy.SettingsSectionTitleFontSize,
            FontWeight = FontWeight.SemiBold,
            Margin = new Thickness(0, 14, 0, 2)
        };
        // Border is purely visual in Avalonia and does not create a Windows UIA
        // peer. Put the panel anchor on its visible heading so GUI acceptance can
        // locate and scroll the real panel without inventing a hidden test control.
        AutomationProperties.SetAutomationId(keySoundHeader, "KeySound.Panel");

        keySoundPanel.Background = Brushes.Transparent;
        keySoundPanel.BorderThickness = new Thickness(0);
        keySoundPanel.Padding = new Thickness(0);
        keySoundPanel.Margin = new Thickness(0);
        keySoundPanel.Child = new StackPanel
        {
            Spacing = 6,
            Children =
            {
                keySoundHeader,
                keySoundEnabledBox,
                new TextBlock
                {
                    Text = "Note 自带 sound 时优先播放真实采音；否则使用下面的全局音色。",
                    Foreground = MutedBrush,
                    FontSize = 10,
                    TextWrapping = TextWrapping.Wrap
                },
                presetRow,
                keySoundCustomFileText,
                volumeRow,
                keySoundLongNoteEndBox,
                TimingField("Key 音全局同步补偿", keySoundGlobalOffsetSlider),
                keySoundGlobalOffsetText,
                TimingField("当前谱面额外补偿", keySoundChartOffsetSlider),
                keySoundChartOffsetText,
                new TextBlock
                {
                    Text = "负数让 Key 音提前，正数让 Key 音延后；当前谱面的值会单独记忆。",
                    Foreground = MutedBrush,
                    FontSize = 10,
                    TextWrapping = TextWrapping.Wrap,
                    Margin = new Thickness(0, 2, 0, 8)
                },
                new TextBlock
                {
                    Text = AvaloniaLocalizationCatalog.Format("程序会实时读取当前音频输出队列并自动补偿；上面两项只用于特殊驱动或素材的微调。"),
                    Foreground = new SolidColorBrush(Color.Parse("#789DA0")),
                    FontSize = 10,
                    TextWrapping = TextWrapping.Wrap,
                    Margin = new Thickness(0, 0, 0, 8)
                },
                keySoundRuntimeStatusText
            }
        };
        return keySoundPanel;
    }

    private static void ConfigureKeySoundOffsetSlider(Slider slider, string automationId)
    {
        slider.Minimum = WindowsKeySoundSettings.MinimumOffsetMilliseconds;
        slider.Maximum = WindowsKeySoundSettings.MaximumOffsetMilliseconds;
        slider.SmallChange = 1;
        slider.LargeChange = 10;
        ConstrainInspectorSlider(slider);
        AutomationProperties.SetAutomationId(slider, automationId);
    }

    private Control BuildTimingEditor()
    {
        timingBeatBox.Text = "0:0/1";
        timingBeatBox.PlaceholderText = "1:0/1 或十进制";
        timingBpmBox.Text = "120";
        timingBpmBox.PlaceholderText = "留空表示无 BPM";
        timingDelayBox.Text = "0";
        timingValueBox.Text = "1.0";
        timingCustomFieldBox.PlaceholderText = "custom.field";
        timingEffectBox.ItemsSource =
            WindowsInspectorParityPolicy.Wpf110TimingEffectOptions;
        timingEffectBox.SelectedIndex = 0;

        ConfigureInspectorInput(timingBeatBox, "Inspector.Timing.Beat", "Timing Beat");
        ConfigureInspectorInput(timingDelayBox, "Inspector.Timing.Delay", "Timing Delay");
        ConfigureInspectorInput(timingBpmBox, "Inspector.Timing.Bpm", "Timing BPM");
        ConfigureInspectorInput(timingValueBox, "Inspector.Timing.Value", "Timing Effect Value");
        ConfigureInspectorInput(
            timingCustomFieldBox,
            "Inspector.Timing.CustomField",
            "Timing Custom Field");
        ConfigureInspectorComboBox(
            timingEffectBox,
            "Inspector.Timing.Effect",
            "Timing Effect");

        var customFieldPanel = InspectorField("自定义字段名", timingCustomFieldBox);
        customFieldPanel.Margin = new Thickness(0, 8, 0, 0);
        customFieldPanel.IsVisible = false;
        timingEffectBox.SelectionChanged += (_, _) =>
        {
            customFieldPanel.IsVisible =
                timingEffectBox.SelectedItem is WindowsTimingEffectOption
                {
                    Value: "Custom"
                };
            if (customFieldPanel.IsVisible &&
                string.IsNullOrWhiteSpace(timingCustomFieldBox.Text))
                timingCustomFieldBox.Text =
                    timingEffectMemory.Current.CustomFieldName;
            MarkTimingEditorDirty();
        };
        foreach (var textBox in new[]
                 {
                     timingBeatBox,
                     timingBpmBox,
                     timingDelayBox,
                     timingValueBox,
                     timingCustomFieldBox
                 })
            textBox.TextChanged += (_, _) => MarkTimingEditorDirty();
        timingPermissionText.Foreground = new SolidColorBrush(Color.Parse("#C28B79"));
        timingPermissionText.FontSize = 10;
        timingPermissionText.TextWrapping = TextWrapping.Wrap;
        timingPermissionText.Margin = new Thickness(0, 0, 0, 5);
        timingPermissionText.IsVisible = false;
        AutomationProperties.SetAutomationId(
            timingPermissionText,
            "Inspector.Timing.Permission");

        timingList.Height = double.NaN;
        timingList.MinHeight = 80;
        timingList.HorizontalAlignment = HorizontalAlignment.Stretch;
        timingList.VerticalAlignment = VerticalAlignment.Stretch;
        timingList.Margin = new Thickness(
            0,
            WindowsInspectorParityPolicy.TimingListTopMargin,
            0,
            0);
        timingList.Background = Brushes.Transparent;
        timingList.BorderThickness = new Thickness(0);
        timingList.SelectionMode = SelectionMode.Multiple;
        timingList.ItemTemplate = new FuncDataTemplate<TimingListItem>(
            (item, _) => item == null ? new Border() : BuildTimingListRow(item),
            supportsRecycling: false);
        ConfigureTimingListStyles();
        AutomationProperties.SetAutomationId(timingList, "Inspector.Timing.List");
        AutomationProperties.SetName(timingList, "Timing 列表");
        timingList.SelectionChanged += TimingList_SelectionChanged;
        timingList.AddHandler(
            InputElement.PointerPressedEvent,
            TimingList_PointerPressed,
            RoutingStrategies.Tunnel);
        timingList.AddHandler(
            InputElement.KeyDownEvent,
            TimingList_KeyDown,
            RoutingStrategies.Tunnel);
        timingList.DoubleTapped += (_, _) => JumpToSelectedTiming();

        timingAddButton = InspectorActionButton(
            WindowsInspectorParityPolicy.Wpf110TimingActionLabels[0],
            "Inspector.Timing.Add",
            InspectorButtonTone.Primary,
            (_, _) => AddTimingFromFields());
        timingApplyButton = InspectorActionButton(
            WindowsInspectorParityPolicy.Wpf110TimingActionLabels[1],
            "Inspector.Timing.Apply",
            InspectorButtonTone.Tool,
            (_, _) => ApplyTimingFromFields());
        timingDeleteButton = InspectorActionButton(
            WindowsInspectorParityPolicy.Wpf110TimingActionLabels[2],
            "Inspector.Timing.Delete",
            InspectorButtonTone.Tool,
            (_, _) => DeleteSelectedTiming());
        timingCopyButton = InspectorActionButton(
            WindowsInspectorParityPolicy.Wpf110TimingActionLabels[3],
            "Inspector.Timing.CopyEffect",
            InspectorButtonTone.Tool,
            (_, _) => CopyTimingSelection());
        timingPasteButton = InspectorActionButton(
            WindowsInspectorParityPolicy.Wpf110TimingActionLabels[4],
            "Inspector.Timing.PasteAtRedLine",
            InspectorButtonTone.Assign,
            (_, _) => PasteTimingSelection());
        ApplyWpf110InspectorTabOrder(
            "Timing",
            [
                timingBeatBox,
                timingDelayBox,
                timingBpmBox,
                timingEffectBox,
                timingValueBox,
                timingCustomFieldBox,
                timingList,
                timingAddButton,
                timingApplyButton,
                timingDeleteButton,
                timingCopyButton,
                timingPasteButton
            ],
            WindowsInspectorParityPolicy.ResolveTimingTabIndex);

        var header = new StackPanel
        {
            Children =
            {
                new TextBlock
                {
                    Text = "Timing Edit",
                    Foreground = Brushes.White,
                    FontSize = WindowsInspectorParityPolicy.TimingTitleFontSize,
                    FontWeight = FontWeight.SemiBold
                },
                new StackPanel
                {
                    Orientation = Orientation.Horizontal,
                    Margin = new Thickness(0, 3),
                    Children =
                    {
                        new Border
                        {
                            Background = Brushes.Transparent,
                            BorderBrush = new SolidColorBrush(Color.Parse("#485054")),
                            BorderThickness = new Thickness(1),
                            CornerRadius = new CornerRadius(3),
                            Padding = new Thickness(7, 3),
                            Child = new TextBlock
                            {
                                Text = "BPM / SV",
                                Foreground = new SolidColorBrush(Color.Parse("#A7B1B4")),
                                FontSize = 9
                            }
                        },
                        new TextBlock
                        {
                            Text = "Beat · Delay · BPM · Effect",
                            Foreground = MutedBrush,
                            FontSize = 11,
                            Margin = new Thickness(8, 0, 0, 0),
                            VerticalAlignment = VerticalAlignment.Center
                        }
                    }
                },
                timingPermissionText
            }
        };

        var beatDelayBpm = new Grid
        {
            RowDefinitions = new RowDefinitions("Auto,Auto"),
            ColumnDefinitions = new ColumnDefinitions("*,10,*")
        };
        var beatField = InspectorField("Beat（新增时自动取红线）", timingBeatBox);
        var delayField = InspectorField("Delay（ms）", timingDelayBox);
        var bpmField = InspectorField("BPM（可留空）", timingBpmBox);
        Grid.SetColumn(delayField, 2);
        Grid.SetRow(bpmField, 1);
        beatDelayBpm.Children.Add(beatField);
        beatDelayBpm.Children.Add(delayField);
        beatDelayBpm.Children.Add(bpmField);

        var effectAndList = new Grid
        {
            RowDefinitions = new RowDefinitions("Auto,Auto,*")
        };
        var effectFields = new Grid
        {
            ColumnDefinitions = new ColumnDefinitions("*,10,*")
        };
        var effectField = InspectorField("Effect", timingEffectBox);
        var valueField = InspectorField("Value", timingValueBox);
        Grid.SetColumn(valueField, 2);
        effectFields.Children.Add(effectField);
        effectFields.Children.Add(valueField);
        effectAndList.Children.Add(effectFields);
        Grid.SetRow(customFieldPanel, 1);
        effectAndList.Children.Add(customFieldPanel);
        Grid.SetRow(timingList, 2);
        effectAndList.Children.Add(timingList);

        var primaryActions = new Grid
        {
            ColumnDefinitions = new ColumnDefinitions("*,*,*")
        };
        Grid.SetColumn(timingApplyButton, 1);
        Grid.SetColumn(timingDeleteButton, 2);
        primaryActions.Children.Add(timingAddButton);
        primaryActions.Children.Add(timingApplyButton);
        primaryActions.Children.Add(timingDeleteButton);
        var clipboardActions = new Grid
        {
            ColumnDefinitions = new ColumnDefinitions("*,*"),
            Margin = new Thickness(
                0,
                WindowsInspectorParityPolicy.TimingClipboardActionsTopMargin,
                0,
                0)
        };
        Grid.SetColumn(timingPasteButton, 1);
        clipboardActions.Children.Add(timingCopyButton);
        clipboardActions.Children.Add(timingPasteButton);
        var actions = new StackPanel
        {
            Margin = new Thickness(
                0,
                WindowsInspectorParityPolicy.TimingActionsTopMargin,
                0,
                0),
            Children = { primaryActions, clipboardActions }
        };

        var root = new Grid
        {
            Margin = WindowsInspectorParityPolicy.TimingContentMargin,
            RowDefinitions = new RowDefinitions("Auto,Auto,*,Auto")
        };
        root.Children.Add(header);
        Grid.SetRow(beatDelayBpm, 1);
        root.Children.Add(beatDelayBpm);
        Grid.SetRow(effectAndList, 2);
        root.Children.Add(effectAndList);
        Grid.SetRow(actions, 3);
        root.Children.Add(actions);
        AutomationProperties.SetAutomationId(root, "Inspector.Timing.Root");
        timingList.MinHeight = 160;
        timingList.MaxHeight = 240;
        root.MinHeight = 420;
        return new ScrollViewer { Content = new StackPanel { Children = { timingMetadataSection!, root } },
            HorizontalScrollBarVisibility = ScrollBarVisibility.Disabled, VerticalScrollBarVisibility = ScrollBarVisibility.Auto };
    }

    private enum InspectorButtonTone
    {
        Tool,
        Primary,
        Assign
    }

