#if LUMACHART_SHARED
    private global::Avalonia.Controls.ApplicationLifetimes.IActivatableLifetime? activatableLifetime;
    private bool backgroundPreservationRunning;

    /// <summary>
    /// A SingleView host never raises Closing: the system suspends or kills
    /// the process from the background instead. Without this hook unsaved
    /// edits (only persisted on save, close or playtest), debounced settings
    /// and running playback were all left to that kill. Desktop builds keep
    /// their Window_Closing preflight and never compile this.
    /// </summary>
    private void AttachMobileLifecycle()
    {
        if (activatableLifetime != null) return;
        activatableLifetime = global::Avalonia.Application.Current?
            .TryGetFeature<global::Avalonia.Controls.ApplicationLifetimes.IActivatableLifetime>();
        if (activatableLifetime != null)
            activatableLifetime.Deactivated += ActivatableLifetime_Deactivated;
    }

    private void ActivatableLifetime_Deactivated(
        object? sender,
        global::Avalonia.Controls.ApplicationLifetimes.ActivatedEventArgs eventArgs)
    {
        _ = sender;
        if (eventArgs.Kind != global::Avalonia.Controls.ApplicationLifetimes.ActivationKind.Background)
            return;
        if (Dispatcher.UIThread.CheckAccess())
            _ = PreserveStateForBackgroundAsync();
        else
            Dispatcher.UIThread.Post(() => _ = PreserveStateForBackgroundAsync());
    }

    private async Task PreserveStateForBackgroundAsync()
    {
        if (backgroundPreservationRunning ||
            !startupInitializationCompleted ||
            windowClosePreflightInProgress ||
            windowCloseTeardownStarted)
            return;
        backgroundPreservationRunning = true;
        try
        {
            // What Window_Closing flushes on a desktop close, minus the prompts:
            // the process may be killed any time after this without notice.
            PersistPendingProGridColumns();
            PersistPendingKeySoundSettings();
            PersistPendingDisplayScaleSettings();
            PersistPendingEditorViewSettings();
            PersistPendingShortcutSettings();
            PersistPendingAudioPanelSettings();
            await PauseAllEditorPlaybackAsync();
            await PersistPendingNavigationMarkersAsync();
            await viewModel.PersistAsync();
        }
        catch (Exception exception)
        {
            // Best effort only: a failure is reported by the persistence paths
            // themselves and must never fault the lifecycle callback.
            Debug.WriteLine($"Background preservation failed: {exception}");
        }
        finally
        {
            backgroundPreservationRunning = false;
        }
    }
#endif

    /// <summary>
    /// Last-chance persistence of the tab working copies for the fatal
    /// dispatcher handler, which is about to shut the process down. The
    /// workspace persistence runs on the thread pool, so none of its
    /// continuations need the UI thread this call blocks; the caller's thread
    /// being blocked also means nothing mutates the documents meanwhile. Waits
    /// at most <paramref name="timeout"/> and never throws. Returns null when
    /// there was nothing to persist (or it was already attempted), otherwise
    /// whether the working copies were written in time.
    /// </summary>
    internal bool? TryEmergencyPersistWorkingCopies(TimeSpan timeout)
    {
        try
        {
            if (emergencyPersistAttempted || windowCloseTeardownStarted) return null;
            emergencyPersistAttempted = true;
            if (!viewModel.Tabs.Any(tab => tab.Session.IsDirty)) return null;
            var persist = Task.Run(() => viewModel.PersistAsync());
            return persist.Wait(timeout) && persist.Result;
        }
        catch (Exception)
        {
            return false;
        }
    }

    private async void Window_Closing(object? sender, WindowClosingEventArgs eventArgs)
    {
        // Before anything else tears down: a file handed over by the operating
        // system while the editor is closing must queue for the next one rather
        // than reach a window that is on its way out.
        PlatformIncomingFiles.ClearHandler();
        viewModel.CancelLibraryScan();
        CancelPendingWindowSnapApplication();
        onlineSurfaceCompletion?.TrySetResult(false);
        friendsPanelLoadCancellation?.Cancel();
        evidenceTimer?.Stop();
        editorToastTimer.Stop();
        audioUiTimer.Stop();
        StopEditorHighRateFramePump();
        autoBackupTimer.Stop();
        roomInvitationTimer.Stop();
        followNotificationTimer.Stop();
        chartingHeartbeatTimer.Stop();
        followNotificationToastTimer.Stop();
        settingsSnapCommitTimer.Stop();
        settingsFixedSnapCommitTimer.Stop();
        navigationMarkerSaveTimer.Stop();
        _ = CancelPendingEditorSeek();
        PersistPendingProGridColumns();
        PersistPendingKeySoundSettings(force: true);
        PersistPendingDisplayScaleSettings(force: true);
        if (!windowClosePreflightComplete)
        {
            // The debounce timers were stopped above; commit a value typed
            // within the last debounce interval like a focus loss would. The
            // fixed-snap box used to be skipped here.
            CommitSettingsSnapBoxText(restoreInvalidText: false);
            CommitSettingsFixedSnapBoxText(restoreInvalidText: false);
        }
        PersistPendingEditorViewSettings(force: true);
        PersistPendingShortcutSettings(force: true);
        PersistPendingAudioPanelSettings(force: true);
        if (windowClosePreflightComplete) return;
        var hasPendingMetadataDraft =
            viewModel.ActiveTab is { } metadataTab &&
            metadataEditorTabId == metadataTab.Id &&
            metadataEditorDirty;
        var hasUnsavedDocuments =
            hasPendingMetadataDraft || trackWorkspaces.Values.Any(w => w.HasPendingChanges) ||
            viewModel.Tabs.Any(tab => tab.Session.IsDirty);
        var hasBlockingExternalShutdownWork =
            HasBlockingExternalApplicationShutdownWork();
        var hasActiveOnlineRoom =
            roomChartSyncRoomId != null ||
            onlineAccountHost?.Session.CurrentRoom != null;
        var canCloseForExternalApplicationShutdown =
            WindowsExternalApplicationShutdownPolicy.CanCloseImmediately(
                eventArgs.CloseReason,
                eventArgs.IsProgrammatic,
                hasUnsavedDocuments,
                hasBlockingExternalShutdownWork,
                hasActiveOnlineRoom);
        WriteExternalApplicationShutdownEvidence(
            eventArgs,
            hasUnsavedDocuments,
            hasBlockingExternalShutdownWork,
            hasActiveOnlineRoom,
            canCloseForExternalApplicationShutdown);
        if (canCloseForExternalApplicationShutdown)
        {
            // Windows Restart Manager can send a non-programmatic WM_CLOSE while
            // replacing installed files (and may use WM_QUERYENDSESSION on other
            // Windows builds). Avalonia requires Closing to answer synchronously.
            // A clean idle workspace is already recoverable on disk, so let the
            // platform close it immediately. The app's programmatic Close() path,
            // dirty documents, active transfer/analysis, backup, deletion, and
            // rooms all keep the normal asynchronous preflight below.
            windowClosePreflightComplete = true;
            return;
        }
        eventArgs.Cancel = true;
        if (windowClosePreflightInProgress) return;

        windowClosePreflightInProgress = true;
        var fullscreenSuspendedForClosePreflight =
            SuspendFullscreenForClosePreflight();
        try
        {
            await SaveTrackWorkspacesAsync();
            if (!await PersistPendingNavigationMarkersAsync(force: true))
            {
                // A persistent failure (read-only or full disk) used to cancel
                // every close attempt. The markers are the only thing at stake,
                // so let the user decide instead of trapping them.
                var exitWithoutMarkers = await ShowSettingsConfirmationAsync(
                    "无法保存跳转标记",
                    AvaloniaLocalizationCatalog.Format("{0}\n\n跳转标记无法写入。可以取消退出，检查工作目录权限或磁盘空间后重试；也可以仍然退出，但尚未保存的跳转标记会丢失。", viewModel.Status),
                    "仍然退出",
                    dangerous: true);
                if (!exitWithoutMarkers) return;
            }
            if (viewModel.ActiveTab is { } activeTab &&
                !TryApplyPendingMetadataEditor(
                    activeTab,
                    enforceCommunityRules: false))
                return;

            // Every user confirmation comes first. Background work (export,
            // imports, analysis, romanization) is canceled only once the exit is
            // decided, so answering "Cancel" to a prompt below no longer
            // discards an export or import that was still running.
            foreach (var tab in viewModel.Tabs.Where(tab => tab.Session.IsDirty).ToArray())
            {
                if (retainedOnlineRoomTabIds.Contains(tab.Id))
                {
                    var retainedChoice = await new PreservedRoomDraftCloseDialog(
                            tab.DisplayTitle,
                            displayScaleSettings.UiScale,
                            displayScaleSettings.FontScale)
                        .ShowDialog<PreservedRoomDraftCloseChoice>(this);
                    if (retainedChoice == PreservedRoomDraftCloseChoice.Cancel) return;
                    if (retainedChoice != PreservedRoomDraftCloseChoice.SaveAs) continue;
                    var retainedSaved = await PickAndSaveAsAsync(tab.Id);
                    if (retainedSaved?.StructurallyEqual != true || tab.Session.IsDirty) return;
                    continue;
                }

                var unsavedChoice = await new UnsavedChangesDialog(
                        tab.DisplayTitle,
                        applicationClosing: true,
                        displayScaleSettings.UiScale,
                        displayScaleSettings.FontScale)
                    .ShowDialog<UnsavedChangesChoice>(this);
                if (unsavedChoice == UnsavedChangesChoice.Cancel) return;
                if (unsavedChoice != UnsavedChangesChoice.Save) continue;
                var saved = await SaveAndVerifyWithPreflightAsync(tab.Id);
                if (saved?.StructurallyEqual != true || tab.Session.IsDirty)
                {
                    // Tell the user why the window is still open; the failed
                    // save used to cancel the exit without a word.
                    await ShowSettingsMessageAsync(
                        "保存失败",
                        AvaloniaLocalizationCatalog.Format("“{0}”未能保存，本次退出已取消，编辑内容仍保留在编辑器中。\n\n{1}", tab.DisplayTitle, viewModel.Status));
                    return;
                }
            }

            if (!await ConfirmOnlineRoomExitAsync()) return;

            // The exit is decided: only now cancel and drain background work.
            await StopBackgroundWorkForCloseAsync();
            // Work that finished while the prompts were open (romanization) may
            // have written into the metadata form; keep that input as well.
            if (viewModel.ActiveTab is { } finishedTab &&
                !TryApplyPendingMetadataEditor(
                    finishedTab,
                    enforceCommunityRules: false))
                return;

            // Do not explicitly close tabs here. WPF retains every tab cache on a
            // normal application exit; explicit tab closes are the cache-deleting path.
            if (!await viewModel.PersistAsync())
            {
                WindowsNativeMessageBox.Show(
                    this,
                    new WindowsNativeMessageBoxRequest(
                        AvaloniaLocalizationCatalog.Format("{0}\n\n为避免丢失可恢复的标签与编辑缓存，本次退出已取消。请检查工作目录权限或磁盘空间后重试。", viewModel.Status),
                        "无法保存工作区",
                        WindowsNativeMessageBoxIcon.Error));
                return;
            }
            windowCloseTeardownStarted = true;
            try
            {
                ReleaseChartBackgroundForShutdown();
                viewModel.StateChanged -= ViewModel_StateChanged;
                audioTransport.StateChanged -= AudioTransport_StateChanged;
                audioVisualization.StateChanged -= AudioVisualization_StateChanged;
                await StopRoomChartSyncAsync(
                    resetRetainedTab:
                    WindowsOnlineRoomRetentionPolicy.ShouldPreserveDraftOnConfirmedExit(
                        WindowsOnlineRoomExitContext.ApplicationClose));
                await LeaveCurrentRoomBeforeShutdownAsync();
                await StopOnlineRoomPresenceLoopAsync();
                await CancelPendingEditorSeek();
                keySoundPlanDebounceTimer.Stop();
                keySoundSettingsSaveTimer.Stop();
                displayScaleSettingsSaveTimer.Stop();
                editorViewSettingsSaveTimer.Stop();
                settingsSnapCommitTimer.Stop();
                settingsFixedSnapCommitTimer.Stop();
                navigationMarkerSaveTimer.Stop();
                shortcutSettingsSaveTimer.Stop();
                audioPanelSettingsSaveTimer.Stop();
                editorSeekCommitTimer.Stop();
                editorHighRateFramePump.Dispose();
                DetachKeySoundActiveSession();
                keySoundRuntime.StateChanged -= KeySoundRuntime_StateChanged;
                await keySoundRuntime.DisposeAsync();
                keySoundRuntimeDisposed = true;
                await audioVisualization.DisposeAsync();
                await audioTransport.DisposeAsync();
                onlineCreatorAvatarLifetime.Cancel();
                if (onlineCreatorAvatarLoads.Count > 0)
                {
                    try { await Task.WhenAll(onlineCreatorAvatarLoads.Values); }
                    catch (Exception exception) when (
                        exception is OnlineApiException or HttpRequestException or System.Net.WebException or OperationCanceledException or
                            JsonException)
                    {
                    }
                }
                timeline.SetOnlineCreators(
                    new Dictionary<long, OnlineCreatorAppearance>());
                foreach (var avatar in onlineCreatorAvatarCache.Values) avatar.Dispose();
                onlineCreatorAvatarCache.Clear();
                onlineCreatorAvatarLoads.Clear();
                onlineCreatorAvatarLifetime.Dispose();
                onlineRestoreCancellation?.Cancel();
                onlineRestoreCancellation?.Dispose();
                onlineRestoreCancellation = null;
                followNotificationPollingCancellation.Cancel();
                chartingHeartbeatLifetime.Cancel();
                try { await activeChartingHeartbeatTask; }
                catch (OperationCanceledException) { }
                if (onlineAccountHost != null)
                {
                    onlineAccountHost.Session.Changed -= OnlineAccountSession_Changed;
                    onlineAccountHost.Session.NotificationsReceived -=
                        OnlineAccountSession_NotificationsReceived;
                    onlineAccountHost.Dispose();
                }
                followNotificationPollingCancellation.Dispose();
                chartingHeartbeatLifetime.Dispose();
            }
            catch (Exception exception)
            {
                // Past the point of no return: the workspace is persisted and the
                // services are half torn down, so returning to the editor would
                // leave it unusable. Record the fault and finish closing rather
                // than falling into the canceled-close branch below, which would
                // restart timers against disposed services.
                Debug.WriteLine($"Window close teardown failed: {exception}");
            }
            windowClosePreflightComplete = true;
            Close();
        }
        catch (Exception exception) when (!windowCloseTeardownStarted)
        {
            // An unexpected preflight fault (a dialog, the room-exit request) must
            // not end the process from this async void handler: that would skip
            // the unsaved-work handling entirely. Keep the window open instead.
            Debug.WriteLine($"Window close preflight failed: {exception}");
            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("退出前检查失败，窗口保持打开：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
        }
        finally
        {
            windowClosePreflightInProgress = false;
            if (!windowClosePreflightComplete)
            {
                audioUiTimer.Start();
                ConfigureEditorFrameRateRuntime(resetCounters: true);
                if (keySoundSettingsDirty) ScheduleKeySoundSettingsSave();
                if (displayScaleSettingsDirty) ScheduleDisplayScaleSettingsSave();
                if (editorViewSettingsDirty) ScheduleEditorViewSettingsSave();
                if (shortcutSettingsDirty) MarkShortcutSettingsDirty();
                if (audioPanelSettingsDirty) ScheduleAudioPanelSettingsSave();
                if (navigationMarkerSettingsDirty) ScheduleNavigationMarkerSave();
                ConfigureAutoBackupTimer();
                roomInvitationTimer.Start();
                followNotificationTimer.Start();
                ReconcileChartingHeartbeatTimer();
                if (followNotificationToastVisible)
                    followNotificationToastTimer.Start();
                if (fullscreenSuspendedForClosePreflight)
                    RestoreFullscreenAfterCanceledClosePreflight();
            }
        }
    }

    /// <summary>
    /// Cancels and drains every background operation once the exit is
    /// confirmed. Each wait tolerates any fault: the foreground command has
    /// already reported its own failure, and shutdown only needs the worker to
    /// stop touching UI state. A faulted task must not escape Window_Closing.
    /// </summary>
    private async Task StopBackgroundWorkForCloseAsync()
    {
        difficultyAnalysisCancellation?.Cancel();
        await AwaitBackgroundWorkForCloseAsync(activeDifficultyAnalysisTask, "difficulty analysis");
        audioAnalysisCancellation?.Cancel();
        await AwaitBackgroundWorkForCloseAsync(activeAudioAnalysisTask, "tempo analysis");
        audioImportCancellation?.Cancel();
        await AwaitBackgroundWorkForCloseAsync(activeAudioImportTask, "audio import");
        imageImportCancellation?.Cancel();
        await AwaitBackgroundWorkForCloseAsync(activeImageImportTask, "image import");
        missingAudioRecoveryCancellation?.Cancel();
        await AwaitBackgroundWorkForCloseAsync(activeMissingAudioRecoveryTask, "missing audio recovery");
        titleRomanizationCancellation?.Cancel();
        artistRomanizationCancellation?.Cancel();
        await AwaitBackgroundWorkForCloseAsync(
            Task.WhenAll(activeTitleRomanizationTask, activeArtistRomanizationTask),
            "romanization");
        await AwaitBackgroundWorkForCloseAsync(activeBackupTask, "backup");
        if (exportInProgress)
        {
            viewModel.SetStatus("正在取消谱包导出…");
            activeExportCancellation?.Cancel();
            await AwaitBackgroundWorkForCloseAsync(activeExportTask, "export");
        }
    }

    private static async Task AwaitBackgroundWorkForCloseAsync(Task task, string operation)
    {
        try
        {
            await task;
        }
        catch (Exception exception)
        {
            if (exception is not OperationCanceledException)
                Debug.WriteLine(
                    $"Close preflight: {operation} ended with {exception.GetType().Name}: {exception.Message}");
        }
    }

    private bool HasBlockingExternalApplicationShutdownWork() =>
        exportInProgress ||
        audioAnalysisInProgress ||
        audioImportInProgress ||
        imageImportInProgress ||
        titleRomanizationInProgress ||
        artistRomanizationInProgress ||
        libraryDeletionInProgress ||
        autoBackupInProgress ||
        navigationMarkerSettingsDirty ||
        !activeDifficultyAnalysisTask.IsCompleted ||
        !activeExportTask.IsCompleted ||
        !activeAudioAnalysisTask.IsCompleted ||
        !activeAudioImportTask.IsCompleted ||
        !activeImageImportTask.IsCompleted ||
        !activeTitleRomanizationTask.IsCompleted ||
        !activeArtistRomanizationTask.IsCompleted ||
        !activeBackupTask.IsCompleted;

    private void ReleaseChartBackgroundForShutdown()
    {
        if (!WindowsClosePreflightResourcePolicy.CanReleaseEditorVisuals(
                windowCloseTeardownStarted))
            return;
        backgroundImageLoadCancellation?.Cancel();
        timeline.SetChartBackgroundImage(null);
    }

    private void WriteExternalApplicationShutdownEvidence(
        WindowClosingEventArgs eventArgs,
        bool hasUnsavedDocuments,
        bool hasBlockingWork,
        bool hasActiveOnlineRoom,
        bool canCloseImmediately)
    {
        if (!evidenceChartMode || string.IsNullOrWhiteSpace(evidenceOutputPath))
            return;

        try
        {
            var path = evidenceOutputPath + ".shutdown.json";
            var payload = new
            {
                schema =
                    "lumachart.windows.avalonia.external-application-shutdown.v1",
                generatedUtc = DateTimeOffset.UtcNow,
                closeReason = eventArgs.CloseReason.ToString(),
                eventArgs.IsProgrammatic,
                hasUnsavedDocuments,
                hasBlockingWork,
                hasActiveOnlineRoom,
                canCloseImmediately,
                blockingWork = new
                {
                    exportInProgress,
                    audioAnalysisInProgress,
                    audioImportInProgress,
                    imageImportInProgress,
                    titleRomanizationInProgress,
                    artistRomanizationInProgress,
                    libraryDeletionInProgress,
                    autoBackupInProgress,
                    activeDifficultyAnalysis = !activeDifficultyAnalysisTask.IsCompleted,
                    activeExport = !activeExportTask.IsCompleted,
                    activeAudioAnalysis = !activeAudioAnalysisTask.IsCompleted,
                    activeAudioImport = !activeAudioImportTask.IsCompleted,
                    activeImageImport = !activeImageImportTask.IsCompleted,
                    activeTitleRomanization = !activeTitleRomanizationTask.IsCompleted,
                    activeArtistRomanization = !activeArtistRomanizationTask.IsCompleted,
                    activeBackup = !activeBackupTask.IsCompleted
                }
            };
            File.WriteAllText(
                path,
                System.Text.Json.JsonSerializer.Serialize(
                    payload,
                    new System.Text.Json.JsonSerializerOptions
                    {
                        WriteIndented = true
                    }),
                new System.Text.UTF8Encoding(
                    encoderShouldEmitUTF8Identifier: false));
        }
        catch
        {
            // Evidence diagnostics must never change the shutdown decision.
        }
    }

    private async void StartEvidenceProbe()
    {
        const int targetRenderSamples = 240;
        const int warmupTickTarget = 120;
        var tab = viewModel.ActiveTab;
        if (tab == null || string.IsNullOrWhiteSpace(evidenceOutputPath))
        {
            viewModel.SetStatus("GUI evidence 未启动：没有打开真实谱面");
            return;
        }
        // Persist startup recommendation before the measured render loop so the
        // evidence can prove the independent settings file without timing races.
        PersistPendingDisplayScaleSettings();
        if (evidenceFocusSettingsCache)
        {
            editorViewSettingsDirty = true;
            PersistPendingEditorViewSettings();
        }
        if (evidenceFocusAudioPanels)
        {
            audioPanelSettingsDirty = true;
            PersistPendingAudioPanelSettings();
        }

        var orderedTimings = tab.Session.Document.Timing
            .Where(timing => timing.Effect.HasValue)
            .OrderBy(timing => timing.Beat)
            .ThenBy(timing => timing.Id)
            .ToArray();
        var orderedNotes = tab.Session.Document.Notes
            .Where(note => !note.IsDraft)
            .OrderBy(note => note.Beat)
            .ThenBy(note => note.Lane)
            .ThenBy(note => note.Id)
            .ToArray();
        var orderedHolds = orderedNotes
            .Where(note => note.EndBeat.HasValue)
            .OrderBy(note => note.EndBeat)
            .ThenBy(note => note.Lane)
            .ToArray();
        var orderedTaps = orderedNotes
            .Where(note => !note.EndBeat.HasValue)
            .ToArray();
        var groupFocusNote = evidenceFocusGroupBeat is { } authoredGroupFocusBeat
            ? orderedTaps.FirstOrDefault(note =>
                note.Beat.Bar == authoredGroupFocusBeat.Bar &&
                note.Beat.Numerator == authoredGroupFocusBeat.Numerator &&
                note.Beat.Denominator == authoredGroupFocusBeat.Denominator)
            : orderedTaps.ElementAtOrDefault(orderedTaps.Length / 2);
        if (evidenceFocusChartValidation)
        {
            var presentation = DesktopChartValidationPresenter.Create(
                tab.Session.Document,
                tab.HiddenGroups);
            lastChartValidationPresentation = presentation;
            tab.Session.Selection.Clear();
            timeline.SetSelectedTiming(null);
            evidenceBaseBeat = presentation.FirstIssue?.Beat.Value ?? 0;
        }
        else if (evidenceFocusProEditor)
        {
            evidenceBaseBeat = .5;
        }
        else if (evidenceFocusGroup && groupFocusNote != null)
        {
            var focusNote = groupFocusNote;
            tab.Session.Selection.Clear();
            tab.Session.Selection.Add(focusNote.Id);
            timeline.SetSelectedTiming(null);
            evidenceBaseBeat = focusNote.Beat.Value;
            editorInspectorTabs.SelectedItem = groupInspectorTab;
        }
        else if (TryApplyEvidenceNotePropertyFocus(tab))
        {
        }
        else if (evidenceFocusHoldTail && orderedHolds.Length > 0)
        {
            var focusHold = orderedHolds[orderedHolds.Length / 2];
            tab.Session.Selection.Clear();
            tab.Session.Selection.Add(focusHold.Id);
            timeline.SetSelectedTiming(null);
            evidenceBaseBeat = focusHold.EndBeat!.Value.Value;
        }
        else if (evidenceFocusTiming && orderedTimings.Length > 0)
        {
            var focusTiming = orderedTimings[orderedTimings.Length / 2];
            tab.Session.Selection.Clear();
            timeline.SetSelectedTiming(focusTiming.Id);
            evidenceBaseBeat = focusTiming.Beat.Value;
            editorInspectorTabs.SelectedItem = timingInspectorTab;
        }
        else
        {
            if (orderedNotes.Length > 0)
            {
                var focusNote = orderedNotes[orderedNotes.Length / 2];
                tab.Session.Selection.Clear();
                tab.Session.Selection.Add(focusNote.Id);
                evidenceBaseBeat = focusNote.Beat.Value;
            }
            else
            {
                evidenceBaseBeat = 0;
            }
        }

        FocusKeySoundEvidencePanel();
        FocusDisplayScaleEvidencePanel();
        FocusSettingsCacheEvidencePanel();
        if (evidenceUsePlacementProbeViewport)
            evidenceBaseBeat = 0;
        timeline.SetCurrentBeat(evidenceBaseBeat);
        UpdateInspector();
        if (evidenceFocusAudioPanels ||
            evidenceEnableBackgroundWaveform || evidenceEnableBackgroundSpectrogram)
        {
            viewModel.SetStatus("正在等待真实音频波形 / 频谱后台生成…");
            try
            {
                await audioVisualization.PendingLoad.WaitAsync(TimeSpan.FromSeconds(45));
            }
            catch (TimeoutException)
            {
                viewModel.SetStatus("音频可视化生成超过 45 秒；将写入未就绪状态供门禁拒绝");
            }
            catch (OperationCanceledException)
            {
                viewModel.SetStatus("音频可视化生成被新的标签或源 revision 取代");
            }
            UpdateAudioVisualizationUi();
            var sceneDeadline = DateTimeOffset.UtcNow.AddSeconds(8);
            while (audioVisualization.LastError == null &&
                   !AreRequiredAudioVisualizationScenesReady() &&
                   DateTimeOffset.UtcNow < sceneDeadline)
            {
                timeline.InvalidateVisual();
                waveformSideSurface.InvalidateVisual();
                spectrogramSideSurface.InvalidateVisual();
                await Task.Delay(50);
            }
        }
        timeline.Performance.Reset();
        waveformSideSurface.Performance.Reset();
        spectrogramSideSurface.Performance.Reset();
        evidenceTicks = 0;
        evidenceStopwatch = new Stopwatch();
        var warmupTicks = 0;
        var recording = false;
        evidenceTimer = new DispatcherTimer(DispatcherPriority.Render)
        {
            Interval = TimeSpan.FromMilliseconds(4)
        };
        evidenceTimer.Tick += async (_, _) =>
        {
            if (!recording)
            {
                warmupTicks++;
                var warmupPhase = ((warmupTicks % 120) - 60) / 60d;
                timeline.MarkSyntheticInput();
                timeline.SetCurrentBeat(Math.Max(0, evidenceBaseBeat + warmupPhase * 2));
                if (warmupTicks < warmupTickTarget) return;

                GC.Collect(2, GCCollectionMode.Forced, blocking: true, compacting: true);
                GC.WaitForPendingFinalizers();
                timeline.Performance.Reset();
                waveformSideSurface.Performance.Reset();
                spectrogramSideSurface.Performance.Reset();
                evidenceTicks = 0;
                evidenceStopwatch.Restart();
                recording = true;
                viewModel.SetStatus("预热完成，正在采集稳态窗口自绘性能…");
                return;
            }

            evidenceTicks++;
            var phase = ((evidenceTicks % 240) - 120) / 120d;
            timeline.MarkSyntheticInput();
            timeline.SetCurrentBeat(Math.Max(0, evidenceBaseBeat + phase * 2));
            var snapshot = timeline.Performance.Snapshot();
            if (snapshot.RenderMilliseconds.Samples < targetRenderSamples &&
                evidenceStopwatch.Elapsed < TimeSpan.FromSeconds(12))
                return;

            evidenceTimer.Stop();
            evidenceStopwatch.Stop();
            timeline.SetCurrentBeat(evidenceBaseBeat);
            var evidence = GuiRuntimeEvidenceWriter.Capture(
                this,
                timeline,
                audioTransport,
                audioVisualization,
                tab,
                tab.SourcePath,
                evidenceSyntheticNoteCount > 0 ? "generated-100000-note-render-workload" : "real-chart-document",
                evidenceSyntheticNoteCount > 0 ? evidenceSyntheticNoteCount : null,
                evidenceStopwatch.Elapsed,
                warmupTicks,
                evidenceTicks,
                targetRenderSamples,
                keySoundRuntime,
                keySoundSettings,
                displayScaleController,
                displayScaleSettings,
                CaptureAudioPanelsRuntime(),
                CaptureLibraryDeletionRuntime(),
                CaptureChartValidationRuntime(),
                evidenceSuppressExportReveal,
                evidenceFollowActiveTab,
                evidenceFilePickerStartDirectory != null,
                evidenceFilePickerStartDirectory);
            try
            {
                await GuiRuntimeEvidenceWriter.WriteAtomicAsync(evidenceOutputPath, evidence);
                viewModel.SetStatus(
                    AvaloniaLocalizationCatalog.Format("GUI evidence 已写入 · Render {0} 帧", evidence.Timeline.Performance.RenderMilliseconds.Samples));
                if (!string.IsNullOrWhiteSpace(evidenceInteractionOutputPath))
                {
                    // The capture harness performs a real Win32 pointer gesture
                    // after observing the primary file. Sample the resulting UI
                    // state only after that press/move/hold/release window ends.
                    await Task.Delay(evidenceInteractionDelayMilliseconds);
                    var interactionTab = evidenceFollowActiveTab
                        ? viewModel.ActiveTab ?? tab
                        : tab;
                    if (evidenceFollowActiveTab && !ReferenceEquals(interactionTab, tab))
                        TryApplyEvidenceNotePropertyFocus(interactionTab);
                    var interactionEvidence = GuiRuntimeEvidenceWriter.Capture(
                        this,
                        timeline,
                        audioTransport,
                        audioVisualization,
                        interactionTab,
                        interactionTab.SourcePath,
                        evidenceSyntheticNoteCount > 0
                            ? "generated-100000-note-render-workload"
                            : "real-chart-document",
                        evidenceSyntheticNoteCount > 0 ? evidenceSyntheticNoteCount : null,
                        evidenceStopwatch.Elapsed,
                        warmupTicks,
                        evidenceTicks,
                        targetRenderSamples,
                        keySoundRuntime,
                        keySoundSettings,
                        displayScaleController,
                        displayScaleSettings,
                        CaptureAudioPanelsRuntime(),
                        CaptureLibraryDeletionRuntime(),
                        CaptureChartValidationRuntime(),
                        evidenceSuppressExportReveal,
                        evidenceFollowActiveTab,
                        evidenceFilePickerStartDirectory != null,
                        evidenceFilePickerStartDirectory);
                    await GuiRuntimeEvidenceWriter.WriteAtomicAsync(
                        evidenceInteractionOutputPath,
                        interactionEvidence);
                    viewModel.SetStatus(
                        AvaloniaLocalizationCatalog.Format("GUI 实际输入 evidence 已写入 · Beat {0:0.###}", interactionEvidence.Timeline.CurrentBeat));
                }
            }
            catch (Exception exception)
            {
                viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("GUI evidence 写入失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
            }
        };
        evidenceTimer.Start();
        viewModel.SetStatus("正在预热 Windows 实际窗口自绘路径…");
    }

    private async void StartLibraryVirtualizationEvidenceProbe()
    {
        const int scrollSampleCount = 180;
        if (!evidenceFocusLibraryVirtualization ||
            string.IsNullOrWhiteSpace(evidenceOutputPath))
            return;
        if (viewModel.LibraryFolders.Count == 0)
        {
            viewModel.SetStatus("大曲库 evidence 未启动：隔离曲库为空");
            return;
        }

        try
        {
            ShowLibrary();
            UpdateUi();
            await YieldToLibraryRenderAsync();
            var panelType = libraryList.GetVisualDescendants()
                .FirstOrDefault(control => control is VirtualizingStackPanel)
                ?.GetType()
                .FullName;
            var initialContainers = CaptureRealizedLibraryContainers();
            var realizedCounts = new List<int>(scrollSampleCount);
            var scrollSettleMilliseconds = new List<double>(scrollSampleCount);
            var inputQueueDelayMilliseconds = new List<double>(scrollSampleCount);
            var observedItems = new HashSet<ListBoxItem>(ReferenceEqualityComparer.Instance);
            var observedCards = new HashSet<LibraryFolderCard>(
                ReferenceEqualityComparer.Instance);
            var staleBindingMismatchCount = 0;
            var maximumMaterializedCollapsedChartRows = 0;

            foreach (var warmupIndex in new[]
                     {
                         0,
                         viewModel.LibraryFolders.Count - 1,
                         viewModel.LibraryFolders.Count / 2,
                         0
                     })
            {
                libraryList.ScrollIntoView(warmupIndex);
                await YieldToLibraryRenderAsync();
            }

            GC.Collect(2, GCCollectionMode.Forced, blocking: true, compacting: true);
            GC.WaitForPendingFinalizers();
            using var process = Process.GetCurrentProcess();
            process.Refresh();
            var managedBytesBefore = GC.GetTotalMemory(forceFullCollection: false);
            var managedBytesPeak = managedBytesBefore;
            var privateBytesBefore = process.PrivateMemorySize64;
            var workingSetBytesBefore = process.WorkingSet64;

            viewModel.SetStatus(
                AvaloniaLocalizationCatalog.Format("正在测量 {0:N0} 项曲库回收与滚动响应…", viewModel.LibraryFolders.Count));
            for (var sample = 0; sample < scrollSampleCount; sample++)
            {
                var targetIndex = (int)((long)sample * 7919 %
                                        viewModel.LibraryFolders.Count);
                if ((sample & 1) != 0)
                    targetIndex = viewModel.LibraryFolders.Count - 1 - targetIndex;

                var inputStopwatch = Stopwatch.StartNew();
                var inputOperation = Dispatcher.UIThread.InvokeAsync(
                    () => inputStopwatch.Elapsed.TotalMilliseconds,
                    DispatcherPriority.Input);
                var scrollStopwatch = Stopwatch.StartNew();
                libraryList.ScrollIntoView(targetIndex);
                var inputDelay = await inputOperation;
                await YieldToLibraryRenderAsync();
                scrollStopwatch.Stop();

                inputQueueDelayMilliseconds.Add(inputDelay);
                scrollSettleMilliseconds.Add(scrollStopwatch.Elapsed.TotalMilliseconds);
                var snapshot = CaptureRealizedLibraryContainers();
                realizedCounts.Add(snapshot.ListBoxItems.Count);
                foreach (var item in snapshot.ListBoxItems) observedItems.Add(item);
                foreach (var card in snapshot.Cards)
                {
                    observedCards.Add(card);
                    var diagnostics = card.CaptureDiagnostics();
                    if (!diagnostics.IsExpanded)
                        maximumMaterializedCollapsedChartRows = Math.Max(
                            maximumMaterializedCollapsedChartRows,
                            diagnostics.MaterializedChartRowCount);
                    if (card.DataContext is not DesktopLibraryFolderView boundView ||
                        !string.Equals(
                            diagnostics.FolderPath,
                            boundView.Folder.FolderPath,
                            StringComparison.OrdinalIgnoreCase))
                        staleBindingMismatchCount++;
                }

                managedBytesPeak = Math.Max(
                    managedBytesPeak,
                    GC.GetTotalMemory(forceFullCollection: false));
            }

            libraryList.ScrollIntoView(viewModel.LibraryFolders.Count / 2);
            await YieldToLibraryRenderAsync();
            GC.Collect(2, GCCollectionMode.Forced, blocking: true, compacting: true);
            GC.WaitForPendingFinalizers();
            process.Refresh();
            var managedBytesAfter = GC.GetTotalMemory(forceFullCollection: false);
            var privateBytesAfter = process.PrivateMemorySize64;
            var workingSetBytesAfter = process.WorkingSet64;
            var finalSnapshot = CaptureRealizedLibraryContainers();
            var evidenceCard = finalSnapshot.Cards.ElementAtOrDefault(
                                   Math.Min(2, finalSnapshot.Cards.Count - 1))
                               ?? throw new InvalidOperationException(
                                   "No realized recyclable library card was available for GUI expansion.");
            var evidenceView = evidenceCard.DataContext as DesktopLibraryFolderView
                               ?? throw new InvalidOperationException(
                                   "The realized evidence card had no folder data context.");
            if (!evidenceCard.SetExpanded(true))
                throw new InvalidOperationException(
                    "The realized evidence card rejected expansion.");
            var evidenceFolderIndex = viewModel.LibraryFolders.IndexOf(evidenceView);
            if (evidenceFolderIndex < 0)
                throw new InvalidOperationException(
                    "The expanded evidence folder was not present in the current library.");
            await YieldToLibraryRenderAsync();
            libraryList.ScrollIntoView(evidenceFolderIndex);
            await YieldToLibraryRenderAsync();
            var evidenceReboundCard = CaptureRealizedLibraryContainers()
                .Cards
                .FirstOrDefault(card => string.Equals(
                    card.CaptureDiagnostics().FolderPath,
                    evidenceView.Folder.FolderPath,
                    StringComparison.OrdinalIgnoreCase))
                ?? throw new InvalidOperationException(
                    "The expanded evidence folder did not rematerialize after recycling.");
            var evidenceExpandedDiagnostics =
                evidenceReboundCard.CaptureDiagnostics();
            var evidenceChart = evidenceView.VisibleCharts.FirstOrDefault()
                                ?? throw new InvalidOperationException(
                                    "The realized evidence folder had no visible chart.");
            var evidenceExpandedBindingMatched =
                string.Equals(
                    evidenceExpandedDiagnostics.FolderPath,
                    evidenceView.Folder.FolderPath,
                    StringComparison.OrdinalIgnoreCase) &&
                evidenceExpandedDiagnostics.MaterializedChartRowCount ==
                evidenceView.VisibleCharts.Count;
            var evidence = new WindowsLibraryVirtualizationRuntimeEvidence(
                Schema: "lumachart.windows.avalonia.library-virtualization-runtime.v1",
                GeneratedUtc: DateTimeOffset.UtcNow,
                Status: "captured-migration-incomplete",
                Platform: "Windows Avalonia only",
                ProcessId: Environment.ProcessId,
                WorkspaceRoot: viewModel.ResolvedWorkspaceRoot,
                IndexedChartCount: viewModel.LibraryEntries.Count,
                IndexedFolderCount: viewModel.IndexedLibraryFolderCount,
                VisibleFolderCount: viewModel.LibraryFolders.Count,
                InitializationMilliseconds: evidenceLibraryInitializationMilliseconds,
                ContainerTemplateOwnsStableCard: true,
                FuncDataTemplateUsed: false,
                ItemsPanelType: panelType,
                ScrollSampleCount: scrollSampleCount,
                InitialRealizedContainerCount: initialContainers.ListBoxItems.Count,
                MinimumRealizedContainerCount: realizedCounts.Min(),
                MaximumRealizedContainerCount: realizedCounts.Max(),
                UniqueListBoxItemInstances: observedItems.Count,
                UniqueCardInstances: observedCards.Count,
                StaleBindingMismatchCount: staleBindingMismatchCount,
                MaximumMaterializedCollapsedChartRows:
                maximumMaterializedCollapsedChartRows,
                EvidenceExpandedFolderPath: evidenceView.Folder.FolderPath,
                EvidenceExpandedDisplayTitle: evidenceView.Folder.DisplayTitle,
                EvidenceExpandedChartRowCount:
                evidenceExpandedDiagnostics.MaterializedChartRowCount,
                EvidenceExpandedChartPath: evidenceChart.ChartPath,
                EvidenceExpandedBindingMatched: evidenceExpandedBindingMatched,
                ScrollSettleMilliseconds: SummarizeLibraryMetric(
                    scrollSettleMilliseconds),
                InputQueueDelayMilliseconds: SummarizeLibraryMetric(
                    inputQueueDelayMilliseconds),
                Memory: new WindowsLibraryVirtualizationMemoryEvidence(
                    managedBytesBefore,
                    managedBytesAfter,
                    managedBytesPeak,
                    privateBytesBefore,
                    privateBytesAfter,
                    workingSetBytesBefore,
                    workingSetBytesAfter),
                RenderScaling: RenderScaling,
                RefreshRate: null);
            await WindowsLibraryVirtualizationRuntimeEvidenceWriter.WriteAtomicAsync(
                evidenceOutputPath,
                evidence);
            AutomationProperties.SetHelpText(
                libraryList,
                $"folders={evidence.VisibleFolderCount}; " +
                $"containers={evidence.MaximumRealizedContainerCount}; " +
                $"scrollP95={evidence.ScrollSettleMilliseconds.P95:0.00}ms; " +
                $"inputP95={evidence.InputQueueDelayMilliseconds.P95:0.00}ms; " +
                $"stale={evidence.StaleBindingMismatchCount}");
            viewModel.SetStatus(
                AvaloniaLocalizationCatalog.Format("{0:N0} 项回收完成 · 容器≤{1} · 滚动 P95 {2:0.0}ms · 输入 P95 {3:0.0}ms", evidence.VisibleFolderCount, evidence.MaximumRealizedContainerCount, evidence.ScrollSettleMilliseconds.P95, evidence.InputQueueDelayMilliseconds.P95));
        }
        catch (Exception exception)
        {
            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("大曲库 evidence 失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
        }
    }

    private async Task YieldToLibraryRenderAsync()
    {
        await Dispatcher.UIThread.InvokeAsync(
            () => { },
            DispatcherPriority.Render);
        await Dispatcher.UIThread.InvokeAsync(
            () => { },
            DispatcherPriority.Background);
    }

    private LibraryRealizedContainerSnapshot CaptureRealizedLibraryContainers()
    {
        var descendants = libraryList.GetVisualDescendants().ToArray();
        return new LibraryRealizedContainerSnapshot(
            descendants.OfType<ListBoxItem>().ToArray(),
            descendants.OfType<LibraryFolderCard>().ToArray());
    }

    private static WindowsLibraryVirtualizationMetricSummary SummarizeLibraryMetric(
        IReadOnlyCollection<double> values)
    {
        if (values.Count == 0)
            return new WindowsLibraryVirtualizationMetricSummary(0, 0, 0, 0, 0, 0);
        var ordered = values.Order().ToArray();
        static double Percentile(IReadOnlyList<double> sorted, double percentile)
        {
            var index = Math.Clamp(
                (int)Math.Ceiling(sorted.Count * percentile) - 1,
                0,
                sorted.Count - 1);
            return sorted[index];
        }

        return new WindowsLibraryVirtualizationMetricSummary(
            ordered.Length,
            ordered[0],
            Percentile(ordered, .50),
            Percentile(ordered, .95),
            Percentile(ordered, .99),
            ordered[^1]);
    }

    private bool TryApplyEvidenceNotePropertyFocus(DesktopChartTab tab)
    {
        if (!evidenceChartMode || !evidenceFocusNoteProperty) return false;
        var focusNote = EvidenceNoteFocusPolicy.Resolve(
            tab.Session.Document.Notes,
            evidenceFocusNotePropertyBeat);
        if (focusNote == null) return false;

        tab.Session.Selection.Clear();
        tab.Session.Selection.Add(focusNote.Id);
        timeline.SetSelectedTiming(null);
        evidenceBaseBeat = focusNote.Beat.Value;
        timeline.SetCurrentBeat(evidenceBaseBeat);
        editorInspectorTabs.SelectedItem = noteInspectorTab;
        UpdateInspector();
        return true;
    }

