    private bool AreRequiredAudioVisualizationScenesReady()
    {
        var waveform = audioPanelSettings.Waveform;
        var spectrogram = audioPanelSettings.Spectrogram;
        var backgroundRequired =
            (!waveform.Collapsed && waveform.Mode == WindowsAudioPanelDisplayMode.Background) ||
            (!spectrogram.Collapsed && spectrogram.Mode == WindowsAudioPanelDisplayMode.Background);
        if (backgroundRequired && !timeline.GetAudioBackgroundDiagnostics().SceneReady)
            return false;

        if (!waveform.Collapsed && waveform.Mode == WindowsAudioPanelDisplayMode.Side &&
            !waveformSideSurface.GetDiagnostics().SceneReady)
            return false;
        if (!spectrogram.Collapsed && spectrogram.Mode == WindowsAudioPanelDisplayMode.Side &&
            !spectrogramSideSurface.GetDiagnostics().SceneReady)
            return false;
        return true;
    }

    private void PrepareSyntheticEvidenceWorkload()
    {
        if (evidenceSyntheticNoteCount <= 0) return;
        var tab = viewModel.ActiveTab;
        if (tab == null) return;

        var document = tab.Session.Document.Clone();
        document.Metadata.Title = $"{document.Metadata.Title} · {evidenceSyntheticNoteCount:N0} Note Probe";
        document.Notes = new List<ChartNote>(evidenceSyntheticNoteCount);
        for (var index = 0; index < evidenceSyntheticNoteCount; index++)
        {
            var beat = BeatPosition.Preserve(index / 32, index % 32, 32);
            document.Notes.Add(new ChartNote
            {
                Lane = index % document.KeyCount,
                Beat = beat,
                EndBeat = index % 17 == 0
                    ? BeatPosition.Preserve(index / 32, index % 32 + 16, 32)
                    : null
            });
        }
        tab.Session.ReplaceDocument(document, markDirty: false);
        viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("已生成 {0:N0} Note 的 Windows GUI 渲染负载", evidenceSyntheticNoteCount));
    }

    private void PrepareChartValidationEvidenceWorkload()
    {
        if (!evidenceChartMode || !evidenceFocusChartValidation) return;
        var tab = viewModel.ActiveTab;
        if (tab == null) return;

        if (evidenceSyntheticNoteCount > 0)
            throw new InvalidOperationException(
                "Chart-validation evidence requires an unchanged real-chart baseline; synthetic notes are not allowed.");

        var document = tab.Session.Document.Clone();
        var baseline = DesktopChartValidationPresenter.Create(document, []);
        if (!baseline.CanSave)
            throw new InvalidOperationException(
                $"Chart-validation evidence requires a valid baseline chart, but found {baseline.TotalIssueCount} issue(s).");
        if (document.Notes.Any(note => note.Group is 7 or 8))
            throw new InvalidOperationException(
                "Chart-validation evidence reserves empty groups 7 and 8 for deterministic hidden-group navigation.");
        var maximumBeat = document.Notes
            .SelectMany(note => note.EndBeat is { } endBeat
                ? new[] { note.Beat.Value, endBeat.Value }
                : new[] { note.Beat.Value })
            .Concat(document.Timing.Select(timing => timing.Beat.Value))
            .DefaultIfEmpty(0)
            .Max();
        var baseBar = checked((int)Math.Ceiling(maximumBeat) + 8);
        var overlapBeat = BeatPosition.Preserve(baseBar, 0, 1);
        document.Notes.Add(new ChartNote
        {
            Lane = 0,
            Beat = overlapBeat,
            Group = 7
        });
        document.Notes.Add(new ChartNote
        {
            Lane = 0,
            Beat = overlapBeat,
            Group = 7
        });

        var crossingLane = Math.Min(1, Math.Max(0, document.KeyCount - 1));
        document.Notes.Add(new ChartNote
        {
            Lane = crossingLane,
            Beat = BeatPosition.Preserve(baseBar + 4, 0, 1),
            EndBeat = BeatPosition.Preserve(baseBar + 8, 0, 1),
            Group = 8
        });
        document.Notes.Add(new ChartNote
        {
            Lane = crossingLane,
            Beat = BeatPosition.Preserve(baseBar + 6, 0, 1),
            EndBeat = BeatPosition.Preserve(baseBar + 10, 0, 1),
            Group = 8
        });

        var injected = DesktopChartValidationPresenter.Create(document, [7, 8]);
        if (injected.TotalIssueCount != 2 ||
            injected.OverlappingNoteCount != 1 ||
            injected.CrossingLongNoteCount != 1)
            throw new InvalidOperationException(
                "Chart-validation evidence injection did not produce exactly one overlap and one crossing-LN issue.");

        tab.Session.ReplaceDocument(document, markDirty: true);
        tab.HiddenGroups.Add(7);
        tab.HiddenGroups.Add(8);
        chartValidationEvidenceInjected = true;
        viewModel.SetStatus("已注入 2 项内存谱面检查 evidence；源文件保持未写入");
    }

    private async void Window_KeyDown(object? sender, KeyEventArgs eventArgs)
    {
        if (noteSoundExistingPopup.IsOpen)
        {
            NoteSoundPicker_KeyDown(sender, eventArgs);
            if (eventArgs.Handled) return;
        }

        var textEditing = IsTextEditingEvent(eventArgs);
        var reservedSpace = eventArgs.Key == Key.Space && eventArgs.KeyModifiers == KeyModifiers.None &&
            WindowsAvaloniaEditorInputPolicy.FindTextEditingControl(eventArgs.Source as Control) is not TextBox &&
            WindowsAvaloniaEditorInputPolicy.FindTextEditingControl(FocusManager?.GetFocusedElement() as Control) is not TextBox;
        imeDuplicateCommitGuard.ObserveKeyDown(
            eventArgs.Key,
            eventArgs.KeyModifiers,
            textEditing,
            Environment.TickCount64);
        if (!reservedSpace && textEditing && WindowsAvaloniaEditorInputPolicy.DeferToTextInputMethod(
                eventArgs.Key,
                eventArgs.KeyModifiers))
            return;

        var key = WindowsEditorShortcutGesture.ResolveReportedKey(
            eventArgs.Key,
            eventArgs.PhysicalKey,
            eventArgs.KeySymbol,
            eventArgs.Key is Key.System or Key.ImeProcessed or Key.DeadCharProcessed
                ? WindowsShortcutPhysicalKeyState.TryResolvePressedKey()
                : null);
        if (onlinePlayerPopupLayer.IsVisible && key == Key.Escape)
        {
            CloseOnlinePlayerPopup();
            eventArgs.Handled = true;
            return;
        }
        if (WindowsOnlineSurfaceParityPolicy.SuppressEditorShortcutRouting(
                onlineSurfaceLayer.IsVisible ||
                onlinePlayerPopupLayer.IsVisible ||
                aboutLayer.IsVisible ||
                updateLayer.IsVisible))
            return;
        if (libraryView.IsVisible)
        {
            if (key == Key.F && eventArgs.KeyModifiers == KeyModifiers.Control)
            {
                librarySearchBox.Focus();
                librarySearchBox.SelectAll();
                eventArgs.Handled = true;
            }
            return;
        }

        if (capturingShortcutAction != null)
        {
            eventArgs.Handled = true;
            if (key is Key.System or Key.ImeProcessed or Key.DeadCharProcessed)
            {
                shortcutStatusText.Text =
                    AvaloniaLocalizationCatalog.Format("中文输入法按键尚未解析：Key={0} · Physical={1} · Symbol={2}", eventArgs.Key, eventArgs.PhysicalKey, eventArgs.KeySymbol ?? AvaloniaLocalizationCatalog.Text("(空)"));
                return;
            }
            await HandleShortcutCaptureAsync(key, eventArgs.KeyModifiers);
            return;
        }

        if (key == Key.Escape && WindowState == WindowState.FullScreen)
        {
            ToggleFullscreen();
            eventArgs.Handled = true;
            return;
        }

        if (reservedSpace)
        {
            eventArgs.Handled = true;
            if (oneShotShortcutState.TryPress(Key.Space))
            {
                try { await ToggleAudioPlaybackAsync(); }
                catch (Exception exception) { viewModel.SetStatus($"播放切换失败：{exception.Message}"); }
            }
            return;
        }

        if (textEditing && IsTextEditingShortcut(key, eventArgs.KeyModifiers)) return;
        var spacePanKeyDown = spacePanGestureState.HandleKeyDown(
            key,
            eventArgs.KeyModifiers,
            timeline.ProEditorEnabled,
            timeline.IsPointerOver);
        if (spacePanKeyDown != WindowsEditorSpacePanKeyDownAction.None)
        {
            if (spacePanKeyDown == WindowsEditorSpacePanKeyDownAction.Arm)
                timeline.SetSpacePanModifier(enabled: true);
            eventArgs.Handled = true;
            return;
        }

        var action = WindowsEditorShortcutGesture.Resolve(
            shortcutSettings,
            key,
            eventArgs.KeyModifiers,
            textEditing);
        if (action == null) return;
        eventArgs.Handled = true;
        if (action.Id.Equals("PlayPause", StringComparison.OrdinalIgnoreCase) &&
            !oneShotShortcutState.TryPress(key))
            return;
        try
        {
            await ExecuteShortcutAsync(action.Id);
        }
        catch (Exception exception)
        {
            // Every editor command is reachable from this async void handler; a
            // fault in one must not end the process with unsaved work open.
            Debug.WriteLine($"Shortcut {action.Id} failed: {exception}");
            if (!windowCloseTeardownStarted)
                viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("快捷键操作失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
        }
    }

    private void Window_TextInput(object? sender, TextInputEventArgs eventArgs)
    {
        if (eventArgs.Handled) return;
        var target = WindowsAvaloniaEditorInputPolicy.FindTextEditingControl(
                         eventArgs.Source as Control) ??
                     WindowsAvaloniaEditorInputPolicy.FindTextEditingControl(
                         FocusManager?.GetFocusedElement() as Control);
        if (target == null)
        {
            imeDuplicateCommitGuard.Reset();
            return;
        }
        if (imeDuplicateCommitGuard.ShouldSuppressReplay(
                target,
                eventArgs.Text,
                Environment.TickCount64))
            eventArgs.Handled = true;
    }

    private async Task HandleShortcutCaptureAsync(Key key, KeyModifiers modifiers)
    {
        var action = capturingShortcutAction;
        if (action == null) return;
        var intent = WindowsEditorShortcutGesture.InterpretCapture(key, modifiers);
        if (intent.Kind == WindowsEditorShortcutCaptureKind.Cancel)
        {
            CancelShortcutCapture();
            return;
        }
        if (intent.Kind == WindowsEditorShortcutCaptureKind.IgnoreModifier) return;
        if (intent.Kind == WindowsEditorShortcutCaptureKind.Clear)
        {
            shortcutSettings.Assign(action, string.Empty, replaceConflict: true);
            capturingShortcutAction = null;
            shortcutStatusText.Text = AvaloniaLocalizationCatalog.Format("已清除“{0}”快捷键", ShortcutLabel(action));
            MarkShortcutSettingsDirty();
            RefreshShortcutButtons();
            RefreshShortcutLabels();
            return;
        }

        var captured = intent.Gesture;
        var assignment = shortcutSettings.Assign(action, captured, replaceConflict: false);
        if (!assignment.Applied && !string.IsNullOrWhiteSpace(assignment.ConflictAction))
        {
            var conflictAction = assignment.ConflictAction;
            var confirmed = await ShowSettingsConfirmationAsync(
                "快捷键冲突",
                AvaloniaLocalizationCatalog.Format("{0} 已用于“{1}”。\n\n是否改为当前操作并清除原绑定？", captured, ShortcutLabel(conflictAction)),
                "改为当前操作",
                dangerous: false);
            if (!confirmed)
            {
                shortcutStatusText.Text = AvaloniaLocalizationCatalog.Format("{0} 仍保留给“{1}”", captured, ShortcutLabel(conflictAction));
                RefreshShortcutButtons();
                return;
            }
            assignment = shortcutSettings.Assign(action, captured, replaceConflict: true);
        }

        if (!assignment.Applied) return;
        capturingShortcutAction = null;
        shortcutStatusText.Text = assignment.ConflictAction == null
            ? AvaloniaLocalizationCatalog.Format("“{0}”已设为 {1}", ShortcutLabel(action), captured)
            : AvaloniaLocalizationCatalog.Format("“{0}”已设为 {1}；原冲突绑定已清除", ShortcutLabel(action), captured);
        MarkShortcutSettingsDirty();
        RefreshShortcutButtons();
        RefreshShortcutLabels();
    }

    private async Task ExecuteShortcutAsync(string action)
    {
        if (TryExecuteTrackCommand(action)) return;
        var command = WindowsEditorShortcutRouting.Resolve(action);
        switch (command.Route)
        {
            case WindowsEditorShortcutRoute.New:
                await CreateChartAsync();
                break;
            case WindowsEditorShortcutRoute.Open:
                await PickAndOpenChartAsync();
                break;
            case WindowsEditorShortcutRoute.Save:
                await SaveAndVerifyWithPreflightAsync();
                break;
            case WindowsEditorShortcutRoute.SaveAs:
                await PickAndSaveAsAsync();
                break;
            case WindowsEditorShortcutRoute.Undo:
                ExecuteHistoryCommand(redo: false);
                break;
            case WindowsEditorShortcutRoute.Redo:
                ExecuteHistoryCommand(redo: true);
                break;
            case WindowsEditorShortcutRoute.Cut:
                CutMixedSelection();
                break;
            case WindowsEditorShortcutRoute.Copy:
                CopyMixedSelection();
                break;
            case WindowsEditorShortcutRoute.Paste:
                PasteMixedSelection();
                break;
            case WindowsEditorShortcutRoute.SelectAll:
                SelectAllVisibleObjects();
                break;
            case WindowsEditorShortcutRoute.ToolSelect:
                SetTimelineToolFromShortcut(TimelineTool.Select);
                break;
            case WindowsEditorShortcutRoute.ToolTap:
                SetTimelineToolFromShortcut(TimelineTool.Tap);
                break;
            case WindowsEditorShortcutRoute.ToolHold:
                SetTimelineToolFromShortcut(TimelineTool.Hold);
                break;
            case WindowsEditorShortcutRoute.ToolErase:
                SetTimelineToolFromShortcut(TimelineTool.Erase);
                break;
            case WindowsEditorShortcutRoute.PlayPause:
                await ToggleAudioPlaybackAsync();
                break;
            case WindowsEditorShortcutRoute.Delete:
                DeleteMixedSelection();
                break;
            case WindowsEditorShortcutRoute.StepForward:
                NudgeSelectionOrRedLine(1);
                break;
            case WindowsEditorShortcutRoute.StepBack:
                NudgeSelectionOrRedLine(-1);
                break;
            case WindowsEditorShortcutRoute.GoHome:
                timeline.SetCurrentBeat(0);
                break;
            case WindowsEditorShortcutRoute.TogglePro:
                timeline.SetProEditor(!timeline.ProEditorEnabled);
                RefreshProEditorControls();
                timeline.Focus();
                break;
            case WindowsEditorShortcutRoute.ToggleFullscreen:
                ToggleFullscreen();
                break;
            case WindowsEditorShortcutRoute.Group:
                SetPlacementGroup(command.Group ?? 0);
                break;
            case WindowsEditorShortcutRoute.SnapIncrease:
                AdjustQuickSnap(1);
                break;
            case WindowsEditorShortcutRoute.SnapDecrease:
                AdjustQuickSnap(-1);
                break;
            case WindowsEditorShortcutRoute.SnapSetFixed:
                SetQuickSnapDivision(editorViewSettings.FixedSnapDivision);
                break;
        }
    }

    private async void Window_KeyUp(object? sender, KeyEventArgs eventArgs)
    {
        if (eventArgs.Key != Key.Space && IsTextEditingEvent(eventArgs) && WindowsAvaloniaEditorInputPolicy.DeferToTextInputMethod(
                eventArgs.Key,
                eventArgs.KeyModifiers))
            return;
        var key = WindowsEditorShortcutGesture.ResolveReportedKey(
            eventArgs.Key,
            eventArgs.PhysicalKey,
            eventArgs.KeySymbol,
            eventArgs.Key is Key.System or Key.ImeProcessed or Key.DeadCharProcessed
                ? WindowsShortcutPhysicalKeyState.TryResolvePressedKey()
                : null);
        var releasedOneShotShortcut = oneShotShortcutState.Release(key);
        if (releasedOneShotShortcut && key == Key.Space)
            eventArgs.Handled = true;
        if (key != Key.Space || !spacePanGestureState.IsArmed) return;
        var panned = timeline.EndSpacePanModifier();
        var release = spacePanGestureState.HandleKeyUp(key, panned);
        if (release == WindowsEditorSpacePanKeyUpAction.TogglePlayback &&
            !IsTextEditingFocused())
            await ToggleAudioPlaybackAsync();
        eventArgs.Handled = true;
    }

    /// <summary>
    /// Same gate as DrainSingleInstanceRequestsAsync: a drop during startup
    /// initialization or the close preflight would open or import into a
    /// workspace that is not ready or is being torn down.
    /// </summary>
    private bool CanAcceptFileDrop() =>
        startupInitializationCompleted &&
        !windowClosePreflightInProgress &&
        !windowClosePreflightComplete &&
        !windowCloseTeardownStarted;

    private void Window_DragOver(object? sender, DragEventArgs eventArgs)
    {
        var hasSupportedFile = CanAcceptFileDrop() &&
            eventArgs.DataTransfer.TryGetFiles()?
            .Select(file => file.TryGetLocalPath())
            .Any(WindowsFileDropPolicy.IsSupportedExistingFile) == true;
        eventArgs.DragEffects = hasSupportedFile ? DragDropEffects.Copy : DragDropEffects.None;
        eventArgs.Handled = true;
    }

    private async void Window_Drop(object? sender, DragEventArgs eventArgs)
    {
        eventArgs.Handled = true;
        if (!CanAcceptFileDrop()) return;
        var plan = WindowsFileDropPolicy.CreatePlan(
            eventArgs.DataTransfer.TryGetFiles()?
            .Select(file => file.TryGetLocalPath())
            ?? []);
        if (plan.ChartAndArchivePaths.Count > 0)
        {
            try
            {
                foreach (var path in plan.ChartAndArchivePaths)
                    await OpenChartOrArchiveAsync(path);
            }
            catch (Exception exception)
            {
                // async void: nothing above this handler would catch it.
                Debug.WriteLine($"Opening dropped files failed: {exception}");
                if (!windowCloseTeardownStarted)
                    viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("打开谱面失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
            }
            return;
        }

        var audioPath = plan.AudioPath;
        if (audioPath == null) return;
        try
        {
            if (libraryVisible || viewModel.ActiveTab == null)
            {
                await CreateChartFromAudioPathAsync(audioPath);
                return;
            }

            // Through the single-flight entry, like the metadata audio button:
            // calling the core import directly let two imports cancel each
            // other and clear the in-progress state early.
            await ImportChartAudioPathAsync(viewModel.ActiveTab, audioPath);
        }
        catch (Exception exception)
        {
            Debug.WriteLine($"Importing dropped audio failed: {exception}");
            if (!windowCloseTeardownStarted)
                SetMetadataAudioStatus(AvaloniaLocalizationCatalog.Format("无法导入音频：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)), error: true);
        }
    }

    internal void AcceptSingleInstanceRequest(WindowsSingleInstanceOpenRequest request)
    {
        ArgumentNullException.ThrowIfNull(request);
        if (!Dispatcher.UIThread.CheckAccess())
        {
            Dispatcher.UIThread.Post(
                () => AcceptSingleInstanceRequest(request),
                DispatcherPriority.Input);
            return;
        }

        singleInstanceRequests.Enqueue(request);
        if (request.Activate) ActivateFromSingleInstanceRequest();
        _ = DrainSingleInstanceRequestsAsync();
    }

    private void ActivateFromSingleInstanceRequest()
    {
        if (WindowState == WindowState.Minimized)
            WindowState = WindowState.Normal;
        if (!IsVisible) Show();
        Activate();
    }

    private async Task DrainSingleInstanceRequestsAsync()
    {
        if (!startupInitializationCompleted ||
            singleInstanceDrainRunning ||
            windowClosePreflightInProgress ||
            windowCloseTeardownStarted)
            return;

        if (!IsEnabled)
        {
            if (!singleInstanceDrainRetryScheduled)
            {
                singleInstanceDrainRetryScheduled = true;
                DispatcherTimer.RunOnce(
                    () =>
                    {
                        singleInstanceDrainRetryScheduled = false;
                        _ = DrainSingleInstanceRequestsAsync();
                    },
                    TimeSpan.FromMilliseconds(250),
                    DispatcherPriority.Background);
            }
            return;
        }

        singleInstanceDrainRunning = true;
        try
        {
            while (singleInstanceRequests.TryDequeue(out var request))
            {
                if (request.Activate) ActivateFromSingleInstanceRequest();
                foreach (var path in request.Paths)
                    await OpenChartOrArchiveAsync(path);
                if (request.Paths.Count == 0)
                    viewModel.SetStatus("LumaChart Studio 已在此窗口运行");
                else
                    viewModel.SetStatus(
                        AvaloniaLocalizationCatalog.Format("已接收另一次启动请求 · {0:N0} 个文件", request.Paths.Count));
            }
        }
        finally
        {
            singleInstanceDrainRunning = false;
        }
    }

