    private void UpdateQuickPlayPresentation()
    {
        var snapshot = audioTransport.PlaybackSnapshot;
        var isPlaying = snapshot?.IsPlaying == true ||
                        keySoundRuntime.Snapshot.IsSilentPlaying ||
                        editorSeekPending && editorSeekResumeRequested;
