    private void AudioUiTimer_Tick(object? sender, EventArgs eventArgs)
    {
        ConfigureEditorFrameRateRuntime();
        if (UsesEditorAnimationFrames()) return;
        RunEditorFrame(updateVisuals: true);
    }

    private bool UsesEditorAnimationFrames() => IsEditorPlaybackActive();

    private void RequestEditorAnimationFrame()
    {
        if (editorAnimationFrameRequested ||
            windowClosePreflightInProgress ||
            windowClosePreflightComplete ||
            playtestInProgress ||
            !UsesEditorAnimationFrames())
            return;
        editorAnimationFrameRequested = true;
        RequestAnimationFrame(EditorAnimationFrame);
    }

    private void EditorAnimationFrame(TimeSpan compositionTimestamp)
    {
        _ = compositionTimestamp;
        editorAnimationFrameRequested = false;
        if (windowClosePreflightInProgress ||
            windowClosePreflightComplete ||
            !UsesEditorAnimationFrames())
            return;

        var limit = EffectiveFrameRateLimit();
        if (editorCompositionFrameGate.Limit != limit)
            editorCompositionFrameGate.SetLimit(limit);
        RunEditorFrame(editorCompositionFrameGate.ShouldRender());
        RequestEditorAnimationFrame();
    }

    private void RunEditorFrame(bool updateVisuals)
    {
        var pump = editorViewSettings.FrameRateLimit > WindowsFrameRateOptions.CompositionDrivenRate &&
                   TryReadEditorHighRateSample(out var sampled)
            ? sampled
            : keySoundPlanRebuildPending
                ? CapturePlaybackClockWithoutScheduling()
                : keySoundRuntime.Pump();
        if (!updateVisuals) return;

        editorFrameUpdates++;
        RefreshFrameRateStatus(IsEditorPlaybackActive());
        if (editorSeekPending)
        {
            // The timeline already shows the explicit latest target. Do not let
            // the paused pre-seek clock snap it back while input is coalescing.
            UpdateAudioUi();
            return;
        }
        var updatePositionUi = audioPositionUiClock.ElapsedMilliseconds >= 50;
        if (updatePositionUi)
        {
            audioPositionUiClock.Restart();
            UpdateAudioUi();
        }
        if (pump.Output == WindowsKeySoundPlaybackOutput.None) return;
        var tab = viewModel.ActiveTab;
        if (tab == null || !ReferenceEquals(tab, keySoundActiveTab)) return;
        if (!TryGetCachedAudioTimingMap(tab, out var timingMap)) return;

        var durationMilliseconds = Math.Max(
            0,
            timingMap.BeatToMilliseconds(BeatPosition.FromDouble(tab.Session.Document.EndBeat)));
        if (pump.Output == WindowsKeySoundPlaybackOutput.SilentEditorClock &&
            pump.PositionMilliseconds >= durationMilliseconds)
        {
            keySoundRuntime.StopSilent();
            SetProgrammaticPlaybackBeat(tab.Session.Document.EndBeat);
            return;
        }
        if (audioPositionPointerDown) return;

        var beat = Math.Max(0, timingMap.MillisecondsToBeat(pump.PositionMilliseconds).Value);
        SetProgrammaticPlaybackBeat(beat);
        UpdateAudioPanelPlaybackBeat(beat);
        if (updatePositionUi) UpdatePlaybackPositionUi(beat);
    }

    /// <summary>
    /// The stored cap held down to what the display can present. A setting
    /// persisted from another device, or one chosen before the panel was known,
    /// must never drive the runtime past the panel's rate.
    /// </summary>
    private int EffectiveFrameRateLimit() =>
        WindowsFrameRateOptions.ClampToPresentable(
            editorViewSettings.FrameRateLimit,
            PlatformDisplayRefreshRates.Current);

    private static TimeSpan WindowsEditorFrameInterval(int frameRateLimit)
    {
        var normalized = WindowsFrameRateOptions.Normalize(frameRateLimit);
        var visualRate = normalized;
        return TimeSpan.FromMilliseconds(1000d / visualRate);
    }

    private bool IsEditorPlaybackActive()
    {
        if (keySoundRuntimeDisposed) return false;
        return audioTransport.PlaybackSnapshot?.IsPlaying == true ||
               keySoundRuntime.Snapshot.IsSilentPlaying;
    }

    private void ConfigureEditorFrameRateRuntime(bool resetCounters = false)
    {
        if (!Dispatcher.UIThread.CheckAccess())
        {
            Dispatcher.UIThread.Post(() => ConfigureEditorFrameRateRuntime(resetCounters));
            return;
        }
        var isPlaying = IsEditorPlaybackActive();
        var playbackStarted = isPlaying && !editorPlaybackWasActive;
        editorPlaybackWasActive = isPlaying;
        timeline.SetPlaybackActive(isPlaying);
        if (!frameRateRuntimeReady) return;

        var limit = EffectiveFrameRateLimit();
        var usesAnimationFrames = UsesEditorAnimationFrames();
        var interval = usesAnimationFrames || !isPlaying
            ? TimeSpan.FromMilliseconds(50)
            : WindowsEditorFrameInterval(limit);
        if (Math.Abs((audioUiTimer.Interval - interval).TotalMilliseconds) > .001)
            audioUiTimer.Interval = interval;
        if (editorCompositionFrameGate.Limit != limit)
            editorCompositionFrameGate.SetLimit(limit);
        if (usesAnimationFrames) RequestEditorAnimationFrame();

        var shouldRunHighRate =
            !windowClosePreflightInProgress &&
            !windowClosePreflightComplete &&
            // The audio UI timer calls this every tick; it must not restart the
            // editor pump underneath a running playtest.
            !playtestInProgress &&
            limit > WindowsFrameRateOptions.CompositionDrivenRate &&
            isPlaying;
        if (shouldRunHighRate &&
            (!editorHighRateFramePumpRunning ||
             editorHighRateFramePump.FramesPerSecond != limit))
        {
            StopEditorHighRateFramePump();
            Interlocked.Exchange(ref editorHighRateSampleVersion, 0);
            editorHighRateFramePump.Start(limit, SampleEditorHighRateFrame);
            editorHighRateFramePumpRunning = true;
        }
        else if (!shouldRunHighRate && editorHighRateFramePumpRunning)
        {
            StopEditorHighRateFramePump();
        }

        if (!resetCounters && !playbackStarted) return;
        editorFrameUpdates = 0;
        editorHighRateFramePump.TakeTickCount();
        editorFrameClock.Restart();
        audioPositionUiClock.Restart();
        if (playbackStarted) timeline.Performance.Reset();
        RefreshFrameRateStatus(isPlaying, force: true);
    }

    private void StopEditorHighRateFramePump()
    {
        editorHighRateFramePump.Stop();
        editorHighRateFramePumpRunning = false;
        Interlocked.Exchange(ref editorHighRateSampleVersion, 0);
        Volatile.Write(ref editorHighRateOutput, (int)WindowsKeySoundPlaybackOutput.None);
    }

    private void SampleEditorHighRateFrame()
    {
        if (keySoundRuntimeDisposed || !IsEditorPlaybackActive()) return;
        var sample = Volatile.Read(ref keySoundPlanRebuildPending)
            ? CapturePlaybackClockWithoutScheduling()
            : keySoundRuntime.Pump();
        if (sample.Output == WindowsKeySoundPlaybackOutput.None) return;

        Interlocked.Exchange(
            ref editorHighRatePositionBits,
            BitConverter.DoubleToInt64Bits(sample.PositionMilliseconds));
        Volatile.Write(ref editorHighRateOutput, (int)sample.Output);
        Interlocked.Increment(ref editorHighRateSampleVersion);
    }

    private bool TryReadEditorHighRateSample(out WindowsKeySoundPlaybackPumpResult sample)
    {
        for (var attempt = 0; attempt < 2; attempt++)
        {
            var before = Interlocked.Read(ref editorHighRateSampleVersion);
            if (before <= 0) break;
            var position = BitConverter.Int64BitsToDouble(
                Interlocked.Read(ref editorHighRatePositionBits));
            var output = (WindowsKeySoundPlaybackOutput)Volatile.Read(ref editorHighRateOutput);
            var after = Interlocked.Read(ref editorHighRateSampleVersion);
            if (before != after || output == WindowsKeySoundPlaybackOutput.None) continue;
            sample = new WindowsKeySoundPlaybackPumpResult(
                output,
                position,
                audioTransport.PlaybackRate,
                0,
                0,
                0);
            return true;
        }

        sample = WindowsKeySoundPlaybackPumpResult.Idle;
        return false;
    }

    /// <summary>
    /// Gate for localized labels written from the per-tick audio UI path. The
    /// localization controller swaps the written source text for its
    /// translation, so rewriting an unchanged source every tick flips the
    /// label back and forth and schedules a full-tree rescan each time.
    /// </summary>
    private static bool TryAdvanceLocalizedTickSource(
        ref string? lastSource,
        string? source)
    {
        if (string.Equals(lastSource, source, StringComparison.Ordinal))
            return false;
        lastSource = source;
        return true;
    }

    private void RefreshFrameRateStatus(bool isPlaying, bool force = false)
    {
        if (!isPlaying)
        {
            // Track what was last written instead of comparing the control's
            // Text: the localization controller replaces it with the translated
            // value, so the source-text comparison never matched outside Chinese
            // and rewrote the label (and re-triggered translation) every tick.
            if (force || !frameRateStatusIdleShown)
            {
                frameRateStatusText.Text = "空闲 · 播放时测量帧率";
                frameRateStatusIdleShown = true;
                AutomationProperties.SetName(frameRateStatusText, frameRateStatusText.Text);
            }
            editorFrameUpdates = 0;
            editorHighRateFramePump.TakeTickCount();
            editorFrameClock.Restart();
            return;
        }
        if (!force && editorFrameClock.ElapsedMilliseconds < 500) return;

        var seconds = Math.Max(.001, editorFrameClock.Elapsed.TotalSeconds);
        var limit = editorViewSettings.FrameRateLimit;
        var performance = timeline.Performance.Snapshot();
        frameRateStatusIdleShown = false;
        frameRateStatusText.Text = limit > WindowsFrameRateOptions.CompositionDrivenRate
            ? AvaloniaLocalizationCatalog.Format("时钟采样: {0:0} · 画面更新: {1:0}", editorHighRateFramePump.TakeTickCount() / seconds, editorFrameUpdates / seconds)
            : AvaloniaLocalizationCatalog.Format("画面: {0:0} · 更新回调: {1:0}", editorFrameUpdates / seconds, editorFrameUpdates / seconds);
        AutomationProperties.SetName(frameRateStatusText, frameRateStatusText.Text);
        AutomationProperties.SetHelpText(
            frameRateStatusText,
            $"FrameRateLimit={limit}; " +
            $"HighRateClock={limit > WindowsFrameRateOptions.CompositionDrivenRate}; " +
            $"FrameDriver={(limit <= WindowsFrameRateOptions.CompositionDrivenRate ? "TopLevel.RequestAnimationFrame" : "DispatcherTimer")}; " +
            $"AudioClockIndependent=true; " +
            $"TimerIntervalMs={audioUiTimer.Interval.TotalMilliseconds:F6}; " +
            $"RenderSamples={performance.RenderMilliseconds.Samples}; " +
            $"RenderMsP50={performance.RenderMilliseconds.P50:F6}; " +
            $"RenderMsP95={performance.RenderMilliseconds.P95:F6}; " +
            $"RenderMsP99={performance.RenderMilliseconds.P99:F6}; " +
            $"FrameMsP50={performance.FrameIntervalMilliseconds.P50:F6}; " +
            $"FrameMsP95={performance.FrameIntervalMilliseconds.P95:F6}; " +
            $"FrameMsP99={performance.FrameIntervalMilliseconds.P99:F6}; " +
            $"InputMsP50={performance.InputToRenderMilliseconds.P50:F6}; " +
            $"InputMsP95={performance.InputToRenderMilliseconds.P95:F6}; " +
            $"InputMsP99={performance.InputToRenderMilliseconds.P99:F6}; " +
            $"MaximumVisitedNotes={performance.MaximumVisitedNotes}");
        editorFrameUpdates = 0;
        editorFrameClock.Restart();
    }

    private async Task ToggleAudioPlaybackAsync()
    {
        var tab = viewModel.ActiveTab;
        if (tab == null || !ReferenceEquals(tab, keySoundActiveTab))
        {
            viewModel.SetStatus("没有活动谱面可播放");
            return;
        }

        var pendingLogicalPlayback = editorSeekPending &&
                                     ReferenceEquals(editorSeekTab, tab) &&
                                     editorSeekResumeRequested;
        await CancelPendingEditorSeek();
        if (!IsCurrentKeySoundTab(tab)) return;
        var snapshot = audioTransport.PlaybackSnapshot;
        if (pendingLogicalPlayback)
        {
            // A click during a coalesced seek means Pause, matching WPF's logical
            // transport state even if the physical stream has already paused.
            if (snapshot?.IsPlaying == true && audioTransport.ActiveTabId == tab.Id)
            {
                keySoundRuntime.InvalidatePlayback();
                await audioTransport.TogglePlayPauseAsync();
            }
            else if (keySoundRuntime.Snapshot.IsSilentPlaying)
            {
                keySoundRuntime.PauseSilent();
            }
            return;
        }

        if (snapshot?.IsLoaded == true && audioTransport.ActiveTabId == tab.Id)
        {
            keySoundRuntime.InvalidatePlayback();
            if (!snapshot.IsPlaying)
            {
                var timingMap = GetAudioTimingMap(tab);
                var milliseconds = Math.Max(
                    0,
                    timingMap.BeatToMilliseconds(BeatPosition.FromDouble(timeline.CurrentBeat)));
                var requestedPosition = TimeSpan.FromMilliseconds(milliseconds);
                if (WindowsAudioResumePolicy.RequiresSeek(snapshot.Position, requestedPosition))
                {
                    await audioTransport.SeekAsync(requestedPosition);
                    if (audioTransport.LastError != null || !IsCurrentKeySoundTab(tab)) return;
                }
            }
            await audioTransport.TogglePlayPauseAsync();
            if (audioTransport.LastError == null && IsCurrentKeySoundTab(tab))
                ResetKeySoundPlaybackAtCurrent(tab);
            return;
        }

        if (keySoundResolvedAudioPath != null)
        {
            viewModel.SetStatus("音频未就绪，客户端正在自动恢复播放链…");
            if (!await audioTransport.EnsureAudioReadyAsync(tab) ||
                !IsCurrentKeySoundTab(tab))
            {
                viewModel.SetStatus(audioTransport.Status);
                return;
            }

            snapshot = audioTransport.PlaybackSnapshot;
            if (snapshot?.IsLoaded != true || audioTransport.ActiveTabId != tab.Id)
            {
                viewModel.SetStatus(audioTransport.Status);
                return;
            }

            keySoundRuntime.InvalidatePlayback();
            var timingMap = GetAudioTimingMap(tab);
            var milliseconds = Math.Max(
                0,
                timingMap.BeatToMilliseconds(BeatPosition.FromDouble(timeline.CurrentBeat)));
            await audioTransport.SeekAsync(TimeSpan.FromMilliseconds(milliseconds));
            if (audioTransport.LastError != null || !IsCurrentKeySoundTab(tab)) return;
            await audioTransport.TogglePlayPauseAsync();
            if (audioTransport.LastError == null && IsCurrentKeySoundTab(tab))
                ResetKeySoundPlaybackAtCurrent(tab);
            return;
        }

        var runtime = keySoundRuntime.Snapshot;
        if (runtime.IsSilentPlaying)
        {
            keySoundRuntime.PauseSilent();
            return;
        }

        var silentStart = Math.Max(
            0,
            GetAudioTimingMap(tab).BeatToMilliseconds(BeatPosition.FromDouble(timeline.CurrentBeat)));
        keySoundRuntime.SeekSilent(silentStart);
        keySoundRuntime.SetSilentRate(audioTransport.PlaybackRate);
        _ = RequestKeySoundPlanNow();
        if (!await keySoundRuntime.StartSilentAsync() && IsCurrentKeySoundTab(tab))
            viewModel.SetStatus(keySoundRuntime.Snapshot.Status);
    }

    private async Task StopAudioAsync()
    {
        var tab = viewModel.ActiveTab;
        if (tab == null || !ReferenceEquals(tab, keySoundActiveTab)) return;
        await CancelPendingEditorSeek();
        if (!IsCurrentKeySoundTab(tab)) return;
        var snapshot = audioTransport.PlaybackSnapshot;
        if (snapshot?.IsLoaded == true && audioTransport.ActiveTabId == tab.Id)
        {
            keySoundRuntime.InvalidatePlayback();
            await audioTransport.StopAsync();
            if (audioTransport.LastError != null || !IsCurrentKeySoundTab(tab)) return;
            keySoundRuntime.ResetPlaybackCursor(0, audioTransport.PlaybackRate);
        }
        else
        {
            keySoundRuntime.StopSilent();
        }
        SetProgrammaticPlaybackBeat(0);
    }

    private async Task SeekAudioFromSliderAsync()
    {
        if (suppressAudioControls) return;
        var milliseconds = Math.Clamp(
            audioPositionSlider.Value,
            audioPositionSlider.Minimum,
            audioPositionSlider.Maximum);
        var tab = viewModel.ActiveTab;
        if (tab == null || !ReferenceEquals(tab, keySoundActiveTab)) return;
        await CancelPendingEditorSeek();
        if (!IsCurrentKeySoundTab(tab)) return;
        var snapshot = audioTransport.PlaybackSnapshot;
        if (snapshot?.IsLoaded == true && audioTransport.ActiveTabId == tab.Id)
        {
            keySoundRuntime.InvalidatePlayback();
            await audioTransport.SeekAsync(TimeSpan.FromMilliseconds(milliseconds));
            if (audioTransport.LastError != null || !IsCurrentKeySoundTab(tab)) return;
            keySoundRuntime.ResetPlaybackCursor(milliseconds, audioTransport.PlaybackRate);
        }
        else
        {
            keySoundRuntime.SeekSilent(milliseconds);
        }

        var timingMap = GetAudioTimingMap(tab);
        SetProgrammaticPlaybackBeat(Math.Max(0, timingMap.MillisecondsToBeat(milliseconds).Value));
    }

    private async Task SetEditorPlaybackRateAsync(double rate)
    {
        var tab = viewModel.ActiveTab;
        if (tab != null && IsCurrentKeySoundTab(tab)) keySoundRuntime.InvalidatePlayback();
        if (keySoundRuntime.Snapshot.IsSilentPlaying) keySoundRuntime.SetSilentRate(rate);
        await audioTransport.SetPlaybackRateAsync(rate);
        editorViewSettings = editorViewSettings.WithPlaybackRate(audioTransport.PlaybackRate);
        MarkEditorViewSettingsDirty();
        if (tab != null && audioTransport.LastError == null && IsCurrentKeySoundTab(tab) &&
            audioTransport.PlaybackSnapshot?.IsLoaded == true)
            ResetKeySoundPlaybackAtCurrent(tab);
    }

    private async Task SetEditorPreservePitchAsync(bool preservePitch)
    {
        var tab = viewModel.ActiveTab;
        if (tab != null && IsCurrentKeySoundTab(tab)) keySoundRuntime.InvalidatePlayback();
        await audioTransport.SetPreservePitchAsync(preservePitch);
        editorViewSettings = editorViewSettings.WithPreservePitch(audioTransport.PreservePitch);
        MarkEditorViewSettingsDirty();
        if (tab != null && audioTransport.LastError == null && IsCurrentKeySoundTab(tab))
            ResetKeySoundPlaybackAtCurrent(tab);
    }

    private async Task RefreshEditorAudioDeviceAsync()
    {
        var tab = viewModel.ActiveTab;
        if (tab != null && IsCurrentKeySoundTab(tab)) keySoundRuntime.InvalidatePlayback();
        await audioTransport.RefreshDefaultOutputDeviceAsync();
        if (tab != null && audioTransport.LastError == null && IsCurrentKeySoundTab(tab))
            ResetKeySoundPlaybackAtCurrent(tab);
    }

    private TimingMap GetAudioTimingMap(DesktopChartTab tab)
    {
        return audioTimingMapCache.Get(
            tab.Id,
            tab.Session.Document,
            tab.Session.ChangeSerial);
    }

    private bool TryGetCachedAudioTimingMap(DesktopChartTab tab, out TimingMap timingMap)
    {
        return audioTimingMapCache.TryGet(
            tab.Id,
            tab.Session.Document,
            tab.Session.ChangeSerial,
            out timingMap);
    }

    private void UpdateAudioUi()
    {
        var snapshot = audioTransport.PlaybackSnapshot;
        var loaded = snapshot?.IsLoaded == true;
        var recoverableDeviceFault =
            snapshot?.State == WindowsAudioPlaybackState.Faulted &&
            !string.IsNullOrWhiteSpace(snapshot.SourcePath);
        var tab = viewModel.ActiveTab;
        var runtime = keySoundRuntime.Snapshot;
        var pendingSeekMatches = tab != null && editorSeekPending &&
                                 ReferenceEquals(editorSeekTab, tab);
        var silentAvailable = tab != null && ReferenceEquals(tab, keySoundActiveTab) &&
                               keySoundResolvedAudioPath == null;
        var audioRecoveryAvailable = tab != null &&
                                     ReferenceEquals(tab, keySoundActiveTab) &&
                                     keySoundResolvedAudioPath != null;
        var canPlay = loaded || silentAvailable || audioRecoveryAvailable;
        var silentPlaying = silentAvailable && runtime.RequestedTabId == tab?.Id && runtime.IsSilentPlaying;
        var position = pendingSeekMatches
            ? TimeSpan.FromMilliseconds(pendingEditorSeekMilliseconds)
            : loaded
            ? snapshot!.Position
            : TimeSpan.FromMilliseconds(Math.Max(0, runtime.PositionMilliseconds));
        var positionObservedUtc = DateTimeOffset.UtcNow;
        var duration = loaded
            ? snapshot!.Duration
            : tab != null && TryGetCachedAudioTimingMap(tab, out var timingMap)
                ? TimeSpan.FromMilliseconds(Math.Max(
                    0,
                    timingMap.BeatToMilliseconds(BeatPosition.FromDouble(tab.Session.Document.EndBeat))))
                : TimeSpan.Zero;
        var overviewAudioEndBeat = loaded && tab != null
            ? GetAudioTimingMap(tab).MillisecondsToBeat(duration.TotalMilliseconds).Value
            : 0;
        editorOverview.SetExternalEndBeat(overviewAudioEndBeat);
        difficultyOverview.SetEndBeat(Math.Max(
            tab?.Session.Document.EndBeat ?? 1,
            overviewAudioEndBeat));
        suppressAudioControls = true;
        try
        {
            audioPlayPauseButton.IsEnabled = canPlay;
            if (commandPlayButton != null)
            {
                commandPlayButton.IsEnabled = canPlay;
                if (commandPlayButton.Content is AvaloniaPath commandPlayIcon)
                {
                    var playing = snapshot?.IsPlaying == true || silentPlaying ||
                                  (pendingSeekMatches && editorSeekResumeRequested);
                    commandPlayIcon.Data = Geometry.Parse(playing
                        ? "M3,2 H6 V14 H3 Z M9,2 H12 V14 H9 Z"
                        : "M2,1 L13,7.5 L2,14 Z");
                    var commandPlayName = playing ? "暂停" : "播放";
                    if (TryAdvanceLocalizedTickSource(
                            ref commandPlayButtonNameSource,
                            commandPlayName))
                        AutomationProperties.SetName(commandPlayButton, commandPlayName);
                }
            }
            SetQuickShortcutEnabled("PlayPause", canPlay);
            var audioPlayPauseContent = snapshot?.IsPlaying == true || silentPlaying ||
                                        (pendingSeekMatches && editorSeekResumeRequested)
                ? "Ⅱ 暂停"
                : "▶ 播放";
            if (TryAdvanceLocalizedTickSource(
                    ref audioPlayPauseButtonContentSource,
                    audioPlayPauseContent))
                audioPlayPauseButton.Content = audioPlayPauseContent;
            audioStopButton.IsEnabled = loaded || silentAvailable;
            if (commandStopButton != null) commandStopButton.IsEnabled = loaded || silentAvailable;
            audioRefreshDeviceButton.IsEnabled = loaded || recoverableDeviceFault;
            audioPositionSlider.IsEnabled = loaded || silentAvailable;
            audioPositionSlider.Maximum = Math.Max(1, duration.TotalMilliseconds);
            if (!audioPositionPointerDown)
                audioPositionSlider.Value = Math.Clamp(
                    position.TotalMilliseconds,
                    audioPositionSlider.Minimum,
                    audioPositionSlider.Maximum);
            audioVolumeSlider.Value = audioTransport.Volume * 100;
            audioRateSlider.Value = audioTransport.PlaybackRate;
            SyncFixedPlaybackRate();
        SyncAdjustmentZoom();
            audioPreservePitchBox.IsChecked = audioTransport.PreservePitch;
            audioPreservePitchBox.IsEnabled =
                WindowsInspectorParityPolicy.SettingsPreservePitchEnabledWithoutLoadedAudio;
            audioVolumeText.Text = $"{audioTransport.Volume:P0}";
            audioRateText.Text = $"{audioTransport.PlaybackRate:0.00}x";
            audioTimeText.Text =
                $"{FormatAudioTime(position)}  ({audioTransport.PlaybackRate:0.00}x)";
            var audioStatusSource = silentPlaying
                ? "当前谱面没有可用音乐 · 正在使用无音乐编辑时钟"
                : audioTransport.LastError == null
                    ? audioTransport.Status
                    : $"{audioTransport.Status}\n{audioTransport.LastError.GetType().Name}";
            if (TryAdvanceLocalizedTickSource(
                    ref audioStatusTextSource,
                    audioStatusSource))
                audioStatusText.Text = audioStatusSource;
            audioStatusText.Foreground = audioTransport.LastError == null
                ? MutedBrush
                : Brushes.IndianRed;
            AutomationProperties.SetName(audioTimeText, audioTimeText.Text);
            AutomationProperties.SetName(audioRateText, audioRateText.Text);
            AutomationProperties.SetName(audioVolumeText, audioVolumeText.Text);
            AutomationProperties.SetName(audioStatusText, audioStatusText.Text);
            var deviceDiagnostics = audioTransport.DeviceDiagnostics;
            var waveformDiagnostics = waveformSideSurface.GetRuntimeCounters();
            var spectrogramDiagnostics = spectrogramSideSurface.GetRuntimeCounters();
            var transportDiagnostics =
                $"State={snapshot?.State.ToString() ?? "Empty"}; " +
                $"IsLoaded={loaded}; " +
                $"IsPlaying={snapshot?.IsPlaying == true}; " +
                $"PositionObservedUtc={positionObservedUtc:O}; " +
                $"PositionMs={position.TotalMilliseconds.ToString("F3", CultureInfo.InvariantCulture)}; " +
                $"DurationMs={duration.TotalMilliseconds.ToString("F3", CultureInfo.InvariantCulture)}; " +
                $"PlaybackRate={audioTransport.PlaybackRate.ToString("F3", CultureInfo.InvariantCulture)}; " +
                $"PreservePitch={audioTransport.PreservePitch}; " +
                $"Volume={audioTransport.Volume.ToString("F3", CultureInfo.InvariantCulture)}; " +
                $"ActiveTabId={audioTransport.ActiveTabId?.ToString("D") ?? string.Empty}; " +
                $"SourcePath={snapshot?.SourcePath ?? string.Empty}; " +
                $"SilentPlaying={silentPlaying}; " +
                $"RecoveryAvailable={audioRecoveryAvailable}; " +
                $"PendingSeek={pendingSeekMatches}; " +
                $"UnexpectedOutputStops={deviceDiagnostics.UnexpectedPlaybackStopCount}; " +
                $"TransientMusicZeros={deviceDiagnostics.TransientMusicZeroCount}; " +
                $"WaveSceneReady={waveformDiagnostics.SceneReady}; " +
                $"WaveSceneBuilds={waveformDiagnostics.CompletedSceneBuilds}; " +
                $"SpecSceneReady={spectrogramDiagnostics.SceneReady}; " +
                $"SpecSceneBuilds={spectrogramDiagnostics.CompletedSceneBuilds}; " +
                $"SpecBitmapUiLastMs={spectrogramDiagnostics.LastUiThreadCpuBitmapMaterializationMilliseconds.ToString("F3", CultureInfo.InvariantCulture)}; " +
                $"SpecBitmapUiMaxMs={spectrogramDiagnostics.MaximumUiThreadCpuBitmapMaterializationMilliseconds.ToString("F3", CultureInfo.InvariantCulture)}; " +
                $"LastUnexpectedOutputStopError={deviceDiagnostics.LastUnexpectedPlaybackStopError ?? string.Empty}; " +
                $"LastError={audioTransport.LastError?.GetType().Name ?? string.Empty}";
            AutomationProperties.SetHelpText(audioStatusText, transportDiagnostics);
            if (commandPlayButton != null)
                AutomationProperties.SetHelpText(commandPlayButton, transportDiagnostics);
            if (commandStopButton != null)
                AutomationProperties.SetHelpText(commandStopButton, transportDiagnostics);
            if (quickPlayPauseButton != null)
                AutomationProperties.SetHelpText(quickPlayPauseButton, transportDiagnostics);
            ToolTip.SetTip(audioStatusText, snapshot?.SourcePath);
        }
        finally
        {
            suppressAudioControls = false;
        }
    }

    private void UpdateAudioVisualizationUi()
    {
        var tab = viewModel.ActiveTab;
        var matchesActiveTab = tab != null && audioVisualization.ActiveTabId == tab.Id;
        var visualization = matchesActiveTab ? audioVisualization.Visualization : null;
        var timingMap = tab == null ? null : GetAudioTimingMap(tab);
        var waveformBackground =
            audioPanelSettings.Waveform.Mode == WindowsAudioPanelDisplayMode.Background &&
            !audioPanelSettings.Waveform.Collapsed;
        var spectrogramBackground =
            audioPanelSettings.Spectrogram.Mode == WindowsAudioPanelDisplayMode.Background &&
            !audioPanelSettings.Spectrogram.Collapsed;
        timeline.SetAudioVisualization(
            visualization,
            timingMap,
            waveformBackground,
            spectrogramBackground);
        timeline.SetSpectrogramAppearance(
            audioPanelSettings.BackgroundSpectrogramStrength,
            audioPanelSettings.SpectrogramDetail);
        waveformSideSurface.SetVisualization(visualization, timingMap);
        spectrogramSideSurface.SetSpectrogramDetail(audioPanelSettings.SpectrogramDetail);
        spectrogramSideSurface.SetVisualization(visualization, timingMap);
        UpdateAudioPanelViewports();
        suppressAudioPanelControls = true;
        try
        {
            waveformBackgroundBox.IsChecked = waveformBackground;
            spectrogramBackgroundBox.IsChecked = spectrogramBackground;
            waveformBackgroundBox.IsEnabled = tab != null;
            spectrogramBackgroundBox.IsEnabled = tab != null;
        }
        finally
        {
            suppressAudioPanelControls = false;
        }
        audioVisualizationStatusText.Text = AvaloniaLocalizationCatalog.Format(
            "{0} · 背景波形{1} / 频谱{2}",
            audioVisualization.Status,
            waveformBackground
                ? AvaloniaLocalizationCatalog.Text("开")
                : AvaloniaLocalizationCatalog.Text("关"),
            spectrogramBackground
                ? AvaloniaLocalizationCatalog.Text("开")
                : AvaloniaLocalizationCatalog.Text("关"));
        audioVisualizationStatusText.Foreground = audioVisualization.LastError == null
            ? MutedBrush
            : Brushes.IndianRed;
        QueueAudioPanelLayout();
    }

    private static string FormatAudioTime(TimeSpan value)
    {
        if (value < TimeSpan.Zero || value == TimeSpan.MaxValue) value = TimeSpan.Zero;
        var totalMinutes = (int)value.TotalMinutes;
        return $"{totalMinutes:00}:{value.Seconds:00}.{value.Milliseconds:000}";
    }

    private void TryApplyApplicationIcon()
    {
#if LUMACHART_IOS
        // Nothing to apply on a single-view host: there is no window chrome, and
        // PlatformWindow.Icon is an inert property there. Attempting it anyway
        // is not merely useless, it is guaranteed to fail twice over — the URI
        // names the desktop assembly, which is not what the shared source
        // compiles into on this platform, and the asset is only contributed by
        // LumaChart.Avalonia.csproj, so it is not in the bundle either. The
        // catch below swallowed both, leaving a FileNotFoundException at every
        // startup that reads exactly like a real missing resource.
#else
        try
        {
            using var stream = AssetLoader.Open(
                new Uri("avares://SimpleManiaEditor/Assets/app-icon.png"));
            Icon = new WindowIcon(stream);
        }
        catch (Exception exception) when (
            exception is IOException or InvalidOperationException or UriFormatException)
        {
            // The executable still carries its native .ico. A missing runtime
            // resource must not prevent the editor from opening.
        }
#endif
    }

    private WindowsKeySoundPlaybackPumpResult CapturePlaybackClockWithoutScheduling()
    {
        var tab = keySoundActiveTab;
        if (tab == null) return WindowsKeySoundPlaybackPumpResult.Idle;
        var audio = audioTransport.PlaybackSnapshot;
        if (audioTransport.ActiveTabId == tab.Id && audio?.IsPlaying == true)
        {
            return new WindowsKeySoundPlaybackPumpResult(
                WindowsKeySoundPlaybackOutput.SharedMusicClock,
                audio.Position.TotalMilliseconds,
                audio.PlaybackRate,
                0,
                0,
                0);
        }

        var runtime = keySoundRuntime.Snapshot;
        return runtime.RequestedTabId == tab.Id && runtime.IsSilentPlaying
            ? new WindowsKeySoundPlaybackPumpResult(
                WindowsKeySoundPlaybackOutput.SilentEditorClock,
                runtime.PositionMilliseconds,
                runtime.PlaybackRate,
                0,
                0,
                0)
            : WindowsKeySoundPlaybackPumpResult.Idle;
    }

    private bool QueueEditorSeek(
        DesktopChartTab tab,
        double milliseconds,
        bool resumeAfterSeek = true)
    {
        if (!IsCurrentKeySoundTab(tab) || keySoundRuntimeDisposed) return false;
        if (editorSeekPending && ReferenceEquals(editorSeekTab, tab))
        {
            if (!resumeAfterSeek) editorSeekResumeRequested = false;
            if (shortcutSettings.Profile != EditorInteractionProfile.OsuMania) EnsurePendingEditorSeekTransportPaused();
            UpdatePendingEditorSeekTarget(milliseconds);
            return true;
        }

        var audio = audioTransport.PlaybackSnapshot;
        var usesMusic = audioTransport.ActiveTabId == tab.Id && audio?.IsLoaded == true;
        var musicWasPlaying = usesMusic && audio!.IsPlaying;
        var usesSilent = !usesMusic && keySoundRuntime.Snapshot.IsSilentPlaying;
        if (!usesMusic && !usesSilent) return false;

        _ = CancelPendingEditorSeek();
        var generation = ++editorSeekGeneration;
        editorSeekPending = true;
        editorSeekTab = tab;
        editorSeekUsesMusic = usesMusic;
        editorSeekResumeRequested = resumeAfterSeek && (musicWasPlaying || usesSilent);
        keySoundRuntime.InvalidatePlayback();
        if (musicWasPlaying && shortcutSettings.Profile != EditorInteractionProfile.OsuMania)
        {
            editorSeekPauseTask = PauseMusicForEditorSeekAsync(generation, tab);
        }
        else
        {
            keySoundRuntime.PauseSilent();
            editorSeekPauseTask = Task.CompletedTask;
        }
        UpdatePendingEditorSeekTarget(milliseconds);
        return true;
    }

    private void UpdatePendingEditorSeekTarget(double milliseconds)
    {
        pendingEditorSeekMilliseconds = Math.Max(0, milliseconds);
        editorSeekTargetVersion++;
        keySoundRuntime.ResetPlaybackCursor(
            pendingEditorSeekMilliseconds,
            audioTransport.PlaybackRate);
        // Schedule from the first wheel event; a continuous scroll must not keep
        // postponing the commit until the user stops moving the wheel.
        if (!editorSeekCommitTimer.IsEnabled) editorSeekCommitTimer.Start();
    }

    private async Task PauseMusicForEditorSeekAsync(long generation, DesktopChartTab tab)
    {
        if (!IsPendingEditorSeek(generation, tab)) return;
        var snapshot = audioTransport.PlaybackSnapshot;
        if (audioTransport.ActiveTabId != tab.Id || snapshot?.IsPlaying != true) return;
        await audioTransport.TogglePlayPauseAsync();
    }

    private void EnsurePendingEditorSeekTransportPaused()
    {
        if (shortcutSettings.Profile == EditorInteractionProfile.OsuMania) return;
        var tab = editorSeekTab;
        if (!editorSeekPending || tab == null || !IsCurrentKeySoundTab(tab)) return;
        if (editorSeekUsesMusic)
        {
            var snapshot = audioTransport.PlaybackSnapshot;
            if (editorSeekPauseTask.IsCompleted &&
                audioTransport.ActiveTabId == tab.Id &&
                snapshot?.IsPlaying == true)
                editorSeekPauseTask = PauseMusicForEditorSeekAsync(editorSeekGeneration, tab);
        }
        else if (keySoundRuntime.Snapshot.IsSilentPlaying)
        {
            keySoundRuntime.PauseSilent();
        }
    }

    private async Task CommitPendingEditorSeekAsync()
    {
        if (editorSeekCommitRunning || !editorSeekPending) return;
        editorSeekCommitRunning = true;
        var generation = editorSeekGeneration;
        var tab = editorSeekTab;
        try
        {
            if (tab == null) return;
            await editorSeekPauseTask;
            if (!IsPendingEditorSeek(generation, tab)) return;

            var targetVersion = editorSeekTargetVersion;
            var milliseconds = pendingEditorSeekMilliseconds;
            var usesMusic = editorSeekUsesMusic;
            var resume = editorSeekResumeRequested;
            if (usesMusic)
            {
                var snapshot = audioTransport.PlaybackSnapshot;
                if (audioTransport.ActiveTabId != tab.Id || snapshot?.IsLoaded != true)
                {
                    CompletePendingEditorSeek(generation, tab);
                    return;
                }
                await audioTransport.SeekAsync(TimeSpan.FromMilliseconds(milliseconds));
                if (!IsPendingEditorSeek(generation, tab) ||
                    targetVersion != editorSeekTargetVersion) return;
                if (audioTransport.LastError != null)
                {
                    CompletePendingEditorSeek(generation, tab);
                    return;
                }
            }
            else
            {
                keySoundRuntime.SeekSilent(milliseconds);
            }

            if (!IsPendingEditorSeek(generation, tab) ||
                targetVersion != editorSeekTargetVersion) return;
            keySoundRuntime.ResetPlaybackCursor(milliseconds, audioTransport.PlaybackRate);
            if (resume)
            {
                if (usesMusic)
                {
                    var snapshot = audioTransport.PlaybackSnapshot;
                    if (audioTransport.ActiveTabId == tab.Id &&
                        snapshot?.IsLoaded == true &&
                        !snapshot.IsPlaying)
                        await audioTransport.TogglePlayPauseAsync();
                    if (!IsPendingEditorSeek(generation, tab) ||
                        targetVersion != editorSeekTargetVersion) return;
                    if (audioTransport.LastError != null)
                    {
                        CompletePendingEditorSeek(generation, tab);
                        return;
                    }
                }
                else if (!await keySoundRuntime.StartSilentAsync())
                {
                    if (IsPendingEditorSeek(generation, tab))
                        CompletePendingEditorSeek(generation, tab);
                    return;
                }
            }

            if (IsPendingEditorSeek(generation, tab) &&
                targetVersion == editorSeekTargetVersion)
                CompletePendingEditorSeek(generation, tab);
        }
        catch (Exception exception)
        {
            if (tab != null && IsPendingEditorSeek(generation, tab))
            {
                viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("定位音频失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
                CompletePendingEditorSeek(generation, tab);
            }
        }
        finally
        {
            editorSeekCommitRunning = false;
            if (editorSeekPending && !editorSeekCommitTimer.IsEnabled)
            {
                EnsurePendingEditorSeekTransportPaused();
                editorSeekCommitTimer.Stop();
                editorSeekCommitTimer.Start();
            }
        }
    }

    private bool IsPendingEditorSeek(long generation, DesktopChartTab tab) =>
        editorSeekPending &&
        editorSeekGeneration == generation &&
        ReferenceEquals(editorSeekTab, tab) &&
        IsCurrentKeySoundTab(tab);

    private void CompletePendingEditorSeek(long generation, DesktopChartTab tab)
    {
        if (editorSeekGeneration != generation || !ReferenceEquals(editorSeekTab, tab)) return;
        editorSeekCommitTimer.Stop();
        editorSeekPending = false;
        editorSeekTab = null;
        editorSeekUsesMusic = false;
        editorSeekResumeRequested = false;
    }

    private Task CancelPendingEditorSeek()
    {
        editorSeekCommitTimer.Stop();
        var pauseTask = editorSeekPauseTask;
        if (editorSeekPending || editorSeekCommitRunning)
        {
            editorSeekGeneration++;
            editorSeekTargetVersion++;
            editorSeekPending = false;
            editorSeekTab = null;
            editorSeekUsesMusic = false;
            editorSeekResumeRequested = false;
            if (!keySoundRuntimeDisposed) keySoundRuntime.InvalidatePlayback();
        }
        // A stale coalesced seek is invalidated by the generation above. Do not
        // await its commit task from a new Play command: a device/decoder seek
        // may still be unwinding and must not make the foreground control look
        // permanently unresponsive.
        return pauseTask.IsCompletedSuccessfully
            ? Task.CompletedTask
            : pauseTask;
    }

    private void SetProgrammaticPlaybackBeat(double beat)
    {
        var previous = settingProgrammaticPlaybackBeat;
        settingProgrammaticPlaybackBeat = true;
        try { timeline.SetCurrentBeat(beat); }
        finally { settingProgrammaticPlaybackBeat = previous; }
    }

    private bool IsCurrentKeySoundTab(DesktopChartTab tab) =>
        ReferenceEquals(tab, keySoundActiveTab) &&
        ReferenceEquals(tab.Session, keySoundActiveSession) &&
        ReferenceEquals(tab, viewModel.ActiveTab);

    private void ResetKeySoundPlaybackAtCurrent(DesktopChartTab tab)
    {
        if (!IsCurrentKeySoundTab(tab) || keySoundRuntimeDisposed) return;
        var snapshot = audioTransport.PlaybackSnapshot;
        var position = snapshot?.IsLoaded == true && audioTransport.ActiveTabId == tab.Id
            ? snapshot.Position.TotalMilliseconds
            : keySoundRuntime.Snapshot.PositionMilliseconds;
        keySoundRuntime.ResetPlaybackCursor(Math.Max(0, position), audioTransport.PlaybackRate);
    }

    private void EnsureKeySoundActiveTab(DesktopChartTab? tab, string? resolvedAudioPath)
    {
        if (tab == null)
        {
            if (keySoundActiveTab == null) return;
            _ = CancelPendingEditorSeek();
            DetachKeySoundActiveSession();
            keySoundActiveTab = null;
            keySoundObservedDocument = null;
            keySoundObservedChangeSerial = -1;
            keySoundObservedSourcePath = null;
            keySoundResolvedAudioPath = null;
            keySoundObservedHiddenGroups.Clear();
            keySoundPlanDebounceTimer.Stop();
            keySoundPlanRebuildPending = false;
            if (!keySoundRuntimeDisposed) keySoundRuntime.Deactivate();
            RefreshKeySoundSettingsUi();
            return;
        }

        if (ReferenceEquals(tab, keySoundActiveTab) &&
            ReferenceEquals(tab.Session, keySoundActiveSession))
        {
            var documentChanged = !ReferenceEquals(keySoundObservedDocument, tab.Session.Document) ||
                                  keySoundObservedChangeSerial != tab.Session.ChangeSerial ||
                                  !string.Equals(
                                      keySoundObservedSourcePath,
                                      tab.SourcePath,
                                      StringComparison.OrdinalIgnoreCase);
            var audioPathChanged = !string.Equals(
                keySoundResolvedAudioPath,
                resolvedAudioPath,
                StringComparison.OrdinalIgnoreCase);
            if (!documentChanged && !audioPathChanged) return;

            _ = CancelPendingEditorSeek();
            keySoundResolvedAudioPath = resolvedAudioPath;
            if (audioPathChanged && resolvedAudioPath != null &&
                keySoundRuntime.Snapshot.IsSilentPlaying)
                keySoundRuntime.PauseSilent();
            ObserveKeySoundDocumentState(tab);
            RefreshKeySoundSettingsUi();
            ScheduleKeySoundPlanRebuild();
            return;
        }

        _ = CancelPendingEditorSeek();
        DetachKeySoundActiveSession();
        if (!keySoundRuntimeDisposed) keySoundRuntime.Deactivate();
        keySoundActiveTab = tab;
        keySoundActiveSession = tab.Session;
        keySoundActiveSession.Changed += KeySoundActiveSession_Changed;
        keySoundResolvedAudioPath = resolvedAudioPath;
        ObserveKeySoundDocumentState(tab);
        RefreshKeySoundSettingsUi();
        ScheduleKeySoundPlanRebuild();
    }

    private void DetachKeySoundActiveSession()
    {
        if (keySoundActiveSession != null)
            keySoundActiveSession.Changed -= KeySoundActiveSession_Changed;
        keySoundActiveSession = null;
    }

    private void KeySoundActiveSession_Changed(object? sender, EventArgs eventArgs)
    {
        if (!Dispatcher.UIThread.CheckAccess())
        {
            Dispatcher.UIThread.Post(() => KeySoundActiveSession_Changed(sender, eventArgs));
            return;
        }

        var tab = keySoundActiveTab;
        if (tab == null || !ReferenceEquals(sender, keySoundActiveSession) ||
            !IsCurrentKeySoundTab(tab)) return;
        if (ReferenceEquals(keySoundObservedDocument, tab.Session.Document) &&
            keySoundObservedChangeSerial == tab.Session.ChangeSerial &&
            string.Equals(
                keySoundObservedSourcePath,
                tab.SourcePath,
                StringComparison.OrdinalIgnoreCase)) return;

        keySoundResolvedAudioPath = WindowsAudioTransportViewModel.ResolveDocumentAudioPath(tab);
        if (keySoundResolvedAudioPath != null && keySoundRuntime.Snapshot.IsSilentPlaying)
            keySoundRuntime.PauseSilent();
        ObserveKeySoundDocumentState(tab);
        _ = GetAudioTimingMap(tab);
        RefreshKeySoundSettingsUi();
        ScheduleKeySoundPlanRebuild();
    }

    private void ObserveKeySoundDocumentState(DesktopChartTab tab)
    {
        keySoundObservedDocument = tab.Session.Document;
        keySoundObservedChangeSerial = tab.Session.ChangeSerial;
        keySoundObservedSourcePath = tab.SourcePath;
        keySoundObservedHiddenGroups = tab.HiddenGroups.ToHashSet();
    }

    private void SyncKeySoundHiddenGroups(DesktopChartTab tab)
    {
        if (!IsCurrentKeySoundTab(tab) || keySoundObservedHiddenGroups.SetEquals(tab.HiddenGroups)) return;
        keySoundObservedHiddenGroups = tab.HiddenGroups.ToHashSet();
        ScheduleKeySoundPlanRebuild();
    }

    private void ScheduleKeySoundPlanRebuild()
    {
        if (keySoundRuntimeDisposed || keySoundActiveTab == null) return;
        keySoundPlanRebuildPending = true;
        keySoundRuntime.InvalidatePlayback();
        keySoundPlanDebounceTimer.Stop();
        keySoundPlanDebounceTimer.Start();
    }

    private Task RequestKeySoundPlanNow()
    {
        keySoundPlanDebounceTimer.Stop();
        var tab = keySoundActiveTab;
        if (keySoundRuntimeDisposed || tab == null || !IsCurrentKeySoundTab(tab))
        {
            keySoundPlanRebuildPending = false;
            return Task.CompletedTask;
        }

        try
        {
            // EditorSession is mutable and UI-owned. Capture one committed clone
            // here; the runtime performs planning, file probes and decoding off UI.
            var document = tab.Session.CaptureCommittedDocument();
            var position = CurrentEditorPlaybackPositionMilliseconds(tab);
            var options = new WindowsKeySoundPlaybackOptions(
                keySoundSettings.EnableKeySounds,
                keySoundSettings.Preset,
                keySoundSettings.CustomFilePath,
                keySoundSettings.PlayLongNoteEndSound,
                keySoundSettings.GlobalOffsetMilliseconds,
                keySoundSettings.GetChartOffset(tab.SourcePath));
            keySoundPlanRebuildPending = false;
            return keySoundRuntime.RequestPlanAsync(
                tab.Id,
                document,
                tab.SourcePath,
                tab.HiddenGroups.ToHashSet(),
                options,
                position,
                audioTransport.PlaybackRate);
        }
        catch (Exception exception)
        {
            // Keep scheduling suspended rather than falling back to a stale plan.
            keySoundPlanRebuildPending = true;
            keySoundRuntimeStatusText.Text = AvaloniaLocalizationCatalog.Format("Key 音计划快照失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message));
            keySoundRuntimeStatusText.Foreground = Brushes.IndianRed;
            return Task.CompletedTask;
        }
    }

    private double CurrentEditorPlaybackPositionMilliseconds(DesktopChartTab tab)
    {
        var audio = audioTransport.PlaybackSnapshot;
        if (audioTransport.ActiveTabId == tab.Id && audio?.IsLoaded == true)
            return Math.Max(0, audio.Position.TotalMilliseconds);
        var runtime = keySoundRuntime.Snapshot;
        if (runtime.RequestedTabId == tab.Id)
            return Math.Max(0, runtime.PositionMilliseconds);
        return Math.Max(
            0,
            GetAudioTimingMap(tab).BeatToMilliseconds(BeatPosition.FromDouble(timeline.CurrentBeat)));
    }

    private void ApplyKeySoundSettings(WindowsKeySoundSettings next)
    {
        keySoundSettings = next.Normalize();
        keySoundRuntime.Volume = (float)keySoundSettings.Volume;
        keySoundSettingsDirty = true;
        RefreshKeySoundSettingsUi();
        ScheduleKeySoundSettingsSave();
        ScheduleKeySoundPlanRebuild();
    }

    private void RefreshKeySoundSettingsUi()
    {
        var previous = suppressKeySoundControls;
        suppressKeySoundControls = true;
        try
        {
            keySoundEnabledBox.IsChecked = keySoundSettings.EnableKeySounds;
            keySoundPresetBox.SelectedItem = keySoundPresetBox.Items
                .OfType<KeySoundPresetChoice>()
                .FirstOrDefault(item => item.Preset == keySoundSettings.Preset);
            keySoundCustomFileText.Text = string.IsNullOrWhiteSpace(keySoundSettings.CustomFilePath)
                ? "未选择自定义音频"
                : keySoundSettings.CustomFilePath;
            ToolTip.SetTip(keySoundCustomFileText, keySoundSettings.CustomFilePath);
            keySoundVolumeSlider.Value = keySoundSettings.Volume * 100;
            keySoundVolumeText.Text = $"{keySoundSettings.Volume:P0}";
            keySoundLongNoteEndBox.IsChecked = keySoundSettings.PlayLongNoteEndSound;
            keySoundGlobalOffsetSlider.Value = keySoundSettings.GlobalOffsetMilliseconds;
            keySoundGlobalOffsetText.Text =
                AvaloniaLocalizationCatalog.Format("全局 {0}", FormatSignedMilliseconds(keySoundSettings.GlobalOffsetMilliseconds));
            var chartOffset = keySoundActiveTab == null
                ? 0
                : keySoundSettings.GetChartOffset(keySoundActiveTab.SourcePath);
            keySoundChartOffsetSlider.Value = chartOffset;
            keySoundChartOffsetSlider.IsEnabled = keySoundActiveTab != null;
            keySoundChartOffsetText.Text = keySoundActiveTab == null
                ? "当前没有活动谱面 · 合计仅使用全局值"
                : AvaloniaLocalizationCatalog.Format("当前谱面 {0} · 合计 {1}", FormatSignedMilliseconds(chartOffset), FormatSignedMilliseconds(keySoundSettings.GlobalOffsetMilliseconds + chartOffset));
            UpdateKeySoundRuntimeUi();
        }
        finally
        {
            suppressKeySoundControls = previous;
        }
    }

    private void UpdateKeySoundRuntimeUi()
    {
        if (keySoundRuntimeDisposed) return;
        var runtime = keySoundRuntime.Snapshot;
        keySoundRuntimeStatusText.Text = runtime.LastError == null
            ? runtime.Status
            : $"{runtime.Status}\n{runtime.LastError.GetType().Name}";
        keySoundRuntimeStatusText.Foreground = runtime.LastError == null
            ? MutedBrush
            : Brushes.IndianRed;
        var counters = runtime.Counters;
        AutomationProperties.SetHelpText(
            keySoundRuntimeStatusText,
            $"Preparing={runtime.IsPreparing}; " +
            $"HasPlan={runtime.HasPlan}; " +
            $"Enabled={runtime.IsEnabled}; " +
            $"PlanEvents={runtime.PlannedEventCount}; " +
            $"PlanPreloads={runtime.PlannedPreloadCount}; " +
            $"PlanFailures={counters.PlanFailures}; " +
            $"PreloadAccepted={counters.PreloadAccepted}; " +
            $"PreloadRejected={counters.PreloadRejected}; " +
            $"PreviewAccepted={counters.PreviewAccepted}; " +
            $"PreviewRejected={counters.PreviewRejected}; " +
            $"TriggersDue={counters.TriggersDue}; " +
            $"TriggersAccepted={counters.TriggersAccepted}; " +
            $"TriggersRejected={counters.TriggersRejected}; " +
            $"SharedAccepted={counters.SharedAccepted}; " +
            $"SharedRejected={counters.SharedRejected}; " +
            $"StandaloneAccepted={counters.StandaloneAccepted}; " +
            $"StandaloneRejected={counters.StandaloneRejected}; " +
            $"LastError={runtime.LastError?.GetType().Name ?? "none"}");
    }

