    private void RefreshDisplayScaleSettingsUi()
    {
        var previous = suppressDisplayScaleControls;
        suppressDisplayScaleControls = true;
        try
        {
            uiScaleSlider.Value = displayScaleSettings.UiScale * 100;
            fontScaleSlider.Value = displayScaleSettings.FontScale * 100;
            uiScaleValueText.Text = $"{displayScaleSettings.UiScale:P0}";
            fontScaleValueText.Text = $"{displayScaleSettings.FontScale:P0}";
            uiScaleDecreaseButton.IsEnabled =
                uiScaleSlider.Value > uiScaleSlider.Minimum;
            uiScaleIncreaseButton.IsEnabled =
                uiScaleSlider.Value < uiScaleSlider.Maximum;
            fontScaleDecreaseButton.IsEnabled =
                fontScaleSlider.Value > fontScaleSlider.Minimum;
            fontScaleIncreaseButton.IsEnabled =
                fontScaleSlider.Value < fontScaleSlider.Maximum;
            displayScaleStatusText.Text = displayScaleSettings.DisplayScaleInitialized
                ? AvaloniaLocalizationCatalog.Format("当前已应用：界面 {0:P0} · 字体 {1:P0}", displayScaleSettings.UiScale, displayScaleSettings.FontScale)
                : "首次显示窗口时将按主屏有效分辨率初始化。";
            displayScaleStatusText.Foreground = MutedBrush;
        }
        finally
        {
            suppressDisplayScaleControls = previous;
        }
    }

    private global::Avalonia.Platform.Screen? ResolveDisplayScaleScreen()
    {
        try
        {
            // WPF 1.1.0 bases both recommendation and minimum-size clamping on
            // SystemParameters' primary-screen values. Keep runtime slider
            // updates on that same authority instead of silently switching the
            // policy when the window happens to sit on another monitor.
            return Screens?.Primary;
        }
        catch (InvalidOperationException)
        {
            return null;
        }
    }

