    private void RefreshProEditorControls(ProEditorTrackPanState? panState = null)
    {
        var tab = viewModel.ActiveTab;
        var enabled = tab != null && timeline.ProEditorEnabled;
        suppressProEditorControls = true;
        try
        {
            proEditorButton.IsEnabled = tab != null;
            proModeLabel.Text = timeline.ProEditorEnabled ? "Pro ON" : "Pro OFF";
            proEditorButton.Background = enabled
                ? new SolidColorBrush(Color.Parse("#22282A"))
                : Brushes.Transparent;
            proEditorButton.Foreground = enabled
                ? new SolidColorBrush(Color.Parse("#F0F2F2"))
                : new SolidColorBrush(Color.Parse("#D0D4D6"));
            proEditorButton.BorderBrush = enabled
                ? new SolidColorBrush(Color.Parse("#5F7E82"))
                : Brushes.Transparent;

            var keyCount = tab?.Session.Document.KeyCount ?? 1;
            proGridColumnSlider.Minimum = keyCount;
            proGridColumnSlider.Maximum = ProEditorWorkspaceGeometry.MaximumTotalColumns;
            proGridColumnSlider.Value = Math.Clamp(
                timeline.ProGridColumnCount,
                keyCount,
                ProEditorWorkspaceGeometry.MaximumTotalColumns);
            proGridColumnSlider.IsEnabled = tab != null;
            proGridColumnText.Text = AvaloniaLocalizationCatalog.Format("{0} 列", timeline.ProGridColumnCount);
            proGridColumnText.IsEnabled = tab != null;

            var state = panState ?? timeline.GetTrackPanState();
            proTrackPanBar.IsVisible = enabled;
            proTrackPanSlider.Minimum = state.Minimum;
            proTrackPanSlider.Maximum = Math.Max(state.Minimum, state.Maximum);
            proTrackPanSlider.Value = Math.Clamp(
                state.Value,
                proTrackPanSlider.Minimum,
                proTrackPanSlider.Maximum);
            proTrackPanSlider.IsEnabled = enabled && state.Enabled;
        }
        finally
        {
            suppressProEditorControls = false;
        }
    }

    private void ToggleSubdivisionCheck()
    {
        var enabled = subdivisionCheckButton.IsChecked == true;
        timeline.SetSubdivisionCheckEnabled(enabled);
        RefreshSubdivisionCheckControls();
        if (!enabled)
        {
            viewModel.SetStatus("分度检查已关闭");
            timeline.Focus();
            return;
        }

        var notes = viewModel.ActiveTab?.Session.Document.Notes ?? [];
        var abnormalNoteCount = notes.Count(note =>
            !TimelineSubdivisionCheckPalette.IsSupportedDenominator(note.Beat.Denominator) ||
            note.EndBeat is { } endBeat &&
            !TimelineSubdivisionCheckPalette.IsSupportedDenominator(endBeat.Denominator));
        var subdivisionCount = notes
            .SelectMany(note => note.EndBeat is { } endBeat
                ? new[]
                {
                    TimelineSubdivisionCheckPalette.NormalizeDenominator(note.Beat.Denominator),
                    TimelineSubdivisionCheckPalette.NormalizeDenominator(endBeat.Denominator)
                }
                : [TimelineSubdivisionCheckPalette.NormalizeDenominator(note.Beat.Denominator)])
            .Distinct()
            .Count();
        viewModel.SetStatus(abnormalNoteCount == 0
            ? AvaloniaLocalizationCatalog.Format("分度检查已开启：{0} 种分度，未发现非常规分度 Note", subdivisionCount)
            : AvaloniaLocalizationCatalog.Format("分度检查已开启：{0} 种分度；{1} 个非常规分度 Note 已标红", subdivisionCount, abnormalNoteCount));
        timeline.Focus();
    }

    private void RefreshSubdivisionCheckControls()
    {
        var enabled = timeline.SubdivisionCheckEnabled;
        subdivisionCheckButton.IsEnabled = viewModel.ActiveTab != null;
        subdivisionCheckButton.IsChecked = enabled;
