            ? new SolidColorBrush(Color.Parse("#253336"))
            : Brushes.Transparent;
        subdivisionCheckButton.Foreground = enabled
            ? new SolidColorBrush(Color.Parse("#F0F2F2"))
            : new SolidColorBrush(Color.Parse("#D0D4D6"));
        subdivisionCheckButton.BorderBrush = enabled
            ? new SolidColorBrush(Color.Parse("#628B90"))
