    private void TimingList_PointerPressed(object? sender, PointerPressedEventArgs eventArgs)
    {
        CaptureTimingListSelectionModifiers(eventArgs.KeyModifiers);
        if (!eventArgs.GetCurrentPoint(timingList).Properties.IsRightButtonPressed) return;

        var current = eventArgs.Source as Control;
        while (current != null && current != timingList && current is not ListBoxItem)
            current = current.Parent as Control;
        if (current is not ListBoxItem item) return;
        if (!item.IsSelected)
        {
            timingList.SelectedItems?.Clear();
            item.IsSelected = true;
        }
        DeleteSelectedTiming();
        eventArgs.Handled = true;
    }

    private void TimingList_KeyDown(object? sender, KeyEventArgs eventArgs)
    {
        CaptureTimingListSelectionModifiers(eventArgs.KeyModifiers);
        var command = WindowsInspectorParityPolicy.ResolveTimingListShortcut(
            eventArgs.Key,
            eventArgs.PhysicalKey,
            eventArgs.KeySymbol,
            eventArgs.KeyModifiers,
            eventArgs.Key is Key.System or Key.ImeProcessed or Key.DeadCharProcessed
                ? WindowsShortcutPhysicalKeyState.TryResolvePressedKey()
                : null);
        switch (command)
        {
            case WindowsTimingListShortcutCommand.Delete:
                DeleteSelectedTiming();
                eventArgs.Handled = true;
                break;
            case WindowsTimingListShortcutCommand.CopyEffect:
                CopyTimingSelection();
                eventArgs.Handled = true;
                break;
            case WindowsTimingListShortcutCommand.PasteEffect:
                PasteTimingSelection();
                eventArgs.Handled = true;
                break;
        }
    }

    private void CaptureTimingListSelectionModifiers(KeyModifiers modifiers)
    {
        timingListSelectionModifiers = modifiers;
        var version = ++timingListInputVersion;
        Dispatcher.UIThread.Post(() =>
        {
            if (version == timingListInputVersion)
                timingListSelectionModifiers = KeyModifiers.None;
        });
    }

    private void TimingList_SelectionChanged(object? sender, SelectionChangedEventArgs eventArgs)
    {
        if (suppressTimingSelection) return;
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        if (!WindowsAvaloniaEditorInputPolicy.PreserveNotesForTimingListSelection(
                timingListSelectionModifiers))
            tab.Session.Selection.Clear();

        var ids = SelectedTimingListIds();
        var primary = timingList.SelectedItem as TimingListItem;
        var previous = suppressTimingSelection;
        suppressTimingSelection = true;
        try
        {
            timeline.SetSelectedTimings(ids, primary?.Id);
        }
        finally
        {
            suppressTimingSelection = previous;
        }
        if (primary != null) PopulateTimingFields(primary.Id);
        UpdateSelectionUi();
    }

    private void UpdateUi()
    {
        if (!WindowsInspectorParityPolicy.AllowWindowUiMutation(
                windowCloseTeardownStarted,
                windowClosePreflightComplete))
            return;
        var activeTabId = viewModel.ActiveTab?.Id;
        if (audioAnalysisCancellation != null && audioAnalysisTabId != activeTabId)
            audioAnalysisCancellation.Cancel();
        if (imageImportCancellation != null && imageImportTabId != activeTabId)
            imageImportCancellation.Cancel();
        if (titleRomanizationCancellation != null && titleRomanizationTabId != activeTabId)
            titleRomanizationCancellation.Cancel();
        if (artistRomanizationCancellation != null && artistRomanizationTabId != activeTabId)
            artistRomanizationCancellation.Cancel();
        workspaceText.Text = AvaloniaLocalizationCatalog.Format("工作目录  {0}", viewModel.WorkspaceRoot);
        AutomationProperties.SetName(workspaceText, workspaceText.Text);
        statusText.Text = viewModel.Status;
        libraryStatusText.Text = viewModel.Status;
        var activeTitleTab = viewModel.ActiveTab;
        if (activeTitleTab == null) libraryVisible = true;
        if (evidenceFocusLibraryDeletion || evidenceFocusLibraryVirtualization)
            libraryVisible = true;
        var surface = WindowsLibrarySurfacePolicy.Resolve(
            libraryVisible,
            activeTitleTab != null,
            activeTitleTab?.Session.Document.Metadata.Title,
            activeTitleTab?.Session.IsDirty == true);
        libraryVisible = surface.LibraryVisible;
        titleSaveStateText.IsVisible = surface.SaveStateVisible;
        titleSaveStateText.Text = activeTitleTab?.Session.IsDirty == true
            ? "· 未保存"
            : "· 已保存";
        titleSaveStateText.Foreground = activeTitleTab?.Session.IsDirty == true
            ? new SolidColorBrush(Color.Parse("#D6A35C"))
            : new SolidColorBrush(Color.Parse("#7FAE93"));
        // Translated here rather than left to the localization pass: this runs on
        // every UI refresh, so an asynchronous pass would keep racing it and the
        // title bar would flip back to the source language.
        Title = localizationController.Translate(surface.WindowTitle).Replace("LumaChart Studio", SimpleManiaProduct.Name, StringComparison.Ordinal);
#if LUMACHART_SHARED
        RefreshTabletLibraryCards();
#else
        libraryList.ItemsSource = viewModel.LibraryFolders;
#endif
        var libraryContent = WindowsLibraryContentPolicy.Resolve(
            viewModel.LibraryEntries.Count,
            viewModel.LibraryFolders.Count,
            viewModel.LibrarySearchQuery,
            viewModel.IsScanning);
#if LUMACHART_SHARED
        tabletLibraryScroll.IsVisible = libraryContent.ShowLibraryList;
#else
        libraryList.IsVisible = libraryContent.ShowLibraryList;
#endif
        emptyLibraryPanel.IsVisible = libraryContent.ShowEmptyPanel;
        emptyLibraryActions.IsVisible = libraryContent.ShowLauncherActions;
        emptyLibraryTitleText.Text = libraryContent.EmptyTitle;
        emptyLibrarySubtitleText.Text = libraryContent.EmptySubtitle;
        libraryTitle.Text = "曲库";
        libraryCountText.Text = viewModel.IsScanning
            ? "扫描中"
            : AvaloniaLocalizationCatalog.Format("{0:N0} 个文件夹  ·  {1:N0} 张谱面", viewModel.LibraryFolders.Count, viewModel.LibraryFolders.Sum(folder => folder.VisibleCharts.Count));
        UpdateLibrarySelectionUi();
        RebuildTabs();
        if (viewModel.ActiveTab != null)
        {
            editorView.IsVisible = surface.EditorVisible;
            libraryView.IsVisible = surface.LibraryVisible;
            audioTransport.Activate(viewModel.ActiveTab);
            var audioPath = WindowsAudioTransportViewModel.ResolveDocumentAudioPath(viewModel.ActiveTab);
            RequestMissingAudioRecovery(viewModel.ActiveTab, audioPath);
            audioVisualization.Activate(
                viewModel.ActiveTab.Id,
                audioPath,
                viewModel.ActiveTab.Session.Document.Metadata.AudioFile);
            var activeTab = viewModel.ActiveTab;
            WindowsGroupManagerCommand.RemoveHiddenSelection(activeTab);
            timeline.Session = activeTab.Session;
            editorOverview.Session = activeTab.Session;
            editorOverview.SetIssues(timeline.ChartIssues);
            editorOverview.SetNavigationMarkers(activeTab.NavigationMarkers);
            editorOverview.SetCurrentBeat(activeTab.CurrentBeat);
            RefreshNavigationMarkerUi();
            miniNoteCountText.Text = activeTab.Session.Document.Notes.Count.ToString(
                "N0",
                CultureInfo.InvariantCulture);
            persistedProGridColumns = Math.Max(
                persistedProGridColumns,
                activeTab.Session.Document.KeyCount);
            timeline.SetProGridColumnCount(persistedProGridColumns);
            timeline.PlacementGroup = activeTab.ActivePlacementGroup;
            if (quickGroupLabel != null)
                quickGroupLabel.Text = AvaloniaLocalizationCatalog.Format("分组 {0}", activeTab.ActivePlacementGroup);
            timeline.SetHiddenGroups(activeTab.HiddenGroups);
            RefreshTimelineOnlineCreators();
            SetProgrammaticPlaybackBeat(activeTab.CurrentBeat);
            activeTab.Session.SnapDivision = editorViewSettings.SnapDivision;
            divisionPicker.SelectedItem = activeTab.Session.SnapDivision;
            SyncSettingsSnapBox(activeTab.Session.SnapDivision);
            RefreshQuickValuesPaletteValues();
            _ = GetAudioTimingMap(activeTab);
            EnsureKeySoundActiveTab(activeTab, audioPath);
            RefreshTimingList();
        }
        else
        {
            editorView.IsVisible = false;
            libraryView.IsVisible = true;
            audioTransport.Activate(null);
            CancelMissingAudioRecovery();
            audioVisualization.Activate(null, null);
            timeline.Session = null;
            editorOverview.Session = null;
            editorOverview.SetIssues([]);
            editorOverview.SetNavigationMarkers([]);
            editorOverview.SetExternalEndBeat(0);
            RefreshNavigationMarkerUi();
            miniNoteCountText.Text = "0";
            timeline.PlacementGroup = 0;
            if (quickGroupLabel != null) quickGroupLabel.Text = "分组 0";
            timeline.SetHiddenGroups([]);
            RefreshTimelineOnlineCreators();
            timingList.ItemsSource = Array.Empty<TimingListItem>();
            timingListTabId = null;
            timingListChangeSerial = -1;
            SyncTimingListSelection([]);
            audioTimingMapCache.Clear();
            EnsureKeySoundActiveTab(null, null);
        }
        RefreshTrackWorkspace(viewModel.ActiveTab);
        // The library-deletion evidence run intentionally keeps a real survivor
        // tab open while exercising a different folder. Session-selection
        // changes during the render probe can raise another workspace update;
        // keep the explicitly requested library view visible across those events.
        // WPF keeps command, permission and save feedback visible while the
        // editor is active. The WPF library uses its own footer row, so keeping
        // the shared editor footer visible there added a duplicate 30-DIP strip.
        statusBar.IsVisible = surface.EditorStatusVisible;
        RefreshDifficultyUi();
        UpdateInspector();
        UpdateChartBackground(viewModel.ActiveTab);
        UpdateEditorAvailability();
        UpdateAudioUi();
        UpdateAudioVisualizationUi();
        RefreshProEditorControls();
        RefreshSubdivisionCheckControls();
        RefreshRoomCollaborationPanelVisibility();
        QueueDisplayScaleMaterializedContentScan();
        QueueFactoryFloatingLayout();
    }

    private void RequestMissingAudioRecovery(DesktopChartTab tab, string? resolvedAudioPath)
    {
        var reference = tab.Session.Document.Metadata.AudioFile;
        if (!string.IsNullOrWhiteSpace(resolvedAudioPath) || string.IsNullOrWhiteSpace(reference))
        {
            CancelMissingAudioRecovery();
            return;
        }

        var key = string.Concat(
            tab.Id.ToString("N"),
            "\0",
            tab.WorkingPath,
            "\0",
            tab.SourcePath,
            "\0",
            reference);
        if (string.Equals(missingAudioRecoveryKey, key, StringComparison.Ordinal)) return;

        missingAudioRecoveryCancellation?.Cancel();
        var cancellation = new CancellationTokenSource();
        missingAudioRecoveryCancellation = cancellation;
        missingAudioRecoveryKey = key;
        activeMissingAudioRecoveryTask = RecoverMissingAudioAsync(
            tab,
            reference,
            key,
            cancellation);
    }

    private async Task RecoverMissingAudioAsync(
        DesktopChartTab tab,
        string reference,
        string recoveryKey,
        CancellationTokenSource cancellation)
    {
        try
        {
            var roots = AvaloniaAppPaths.EnumerateCompatibilityWorkspaceRoots();
            var candidate = await Task.Run(
                () => ChartAssetImportService.FindRelatedAsset(
                    tab.WorkingPath,
                    tab.SourcePath,
                    reference,
                    roots,
                    cancellation.Token),
                cancellation.Token);
            if (candidate == null) return;

            var imported = await Task.Run(
                () => ChartAssetImportService.ImportAudio(
                    tab.WorkingPath,
                    candidate,
                    tab.SourcePath,
                    preferredFileName: reference),
                cancellation.Token);
            cancellation.Token.ThrowIfCancellationRequested();
            if (viewModel.ActiveTab?.Id != tab.Id ||
                !string.Equals(missingAudioRecoveryKey, recoveryKey, StringComparison.Ordinal))
                return;

            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("已从曲库自动恢复音频：{0}", imported.FileName));
            UpdateUi();
        }
        catch (OperationCanceledException)
        {
        }
        catch (Exception exception) when (
            exception is ArgumentException or IOException or NotSupportedException or UnauthorizedAccessException)
        {
            if (viewModel.ActiveTab?.Id == tab.Id &&
                string.Equals(missingAudioRecoveryKey, recoveryKey, StringComparison.Ordinal))
                viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("自动恢复音频失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
        }
        finally
        {
            if (ReferenceEquals(missingAudioRecoveryCancellation, cancellation))
                missingAudioRecoveryCancellation = null;
            cancellation.Dispose();
        }
    }

    private void CancelMissingAudioRecovery()
    {
        missingAudioRecoveryCancellation?.Cancel();
        missingAudioRecoveryKey = null;
    }

    private void UpdateInspector()
    {
        var tab = viewModel.ActiveTab;
        RefreshMetadataEditor(tab);
        UpdateNoteInspector(tab);
        RefreshGroupPanel();
        if (tab == null)
        {
            inspectorText.Text = "没有打开的谱面";
            return;
        }
        var document = tab.Session.Document;
        var selected = document.Notes.Where(note =>
            tab.Session.Selection.Contains(note.Id) &&
            !tab.HiddenGroups.Contains(note.Group)).ToArray();
        var selectedTimingCount = timeline.SelectedTimingIds.Count(id =>
            document.Timing.Any(timing => timing.Id == id));
        var selectedText = selected.Length == 0
            ? "未选择 Note"
            : string.Join("\n", selected.Take(4).Select(note =>
                (note.IsDraft
                    ? $"Draft D:{note.DraftColumn} · {note.Beat}"
                    : $"Lane {note.Lane + 1} · {note.Beat}") +
                (note.EndBeat.HasValue ? $" → {note.EndBeat}" : string.Empty)));
        inspectorText.Text =
            AvaloniaLocalizationCatalog.Format("{0}\n{1} · {2}K\nNote {3:N0} · LN {4:N0}\nTiming {5:N0}\n红线 {6:F3}\n分度 1/{7}\n选择 {8:N0} Note · {9:N0} Timing\n权限：只读 {10} · Note {11} · Timing {12} · 元数据 {13}\n房主锁：{14:N0} Note · {15:N0} 连续区域\n未保存：{16}\n\n{17}", tab.DisplayTitle, tab.FormatBadge, document.KeyCount, document.Notes.Count, document.Notes.Count(note => note.IsHold), document.Timing.Count, timeline.CurrentBeat, tab.Session.SnapDivision, selected.Length, selectedTimingCount, (tab.Session.IsReadOnly ? AvaloniaLocalizationCatalog.Text("是") : AvaloniaLocalizationCatalog.Text("否")), (tab.Session.CanEditNotes ? AvaloniaLocalizationCatalog.Text("可编辑") : AvaloniaLocalizationCatalog.Text("禁用")), (tab.Session.CanEditTiming ? AvaloniaLocalizationCatalog.Text("可编辑") : AvaloniaLocalizationCatalog.Text("禁用")), (tab.Session.CanEditMetadata ? AvaloniaLocalizationCatalog.Text("可编辑") : AvaloniaLocalizationCatalog.Text("禁用")), tab.Session.OwnerProtectedNotes.Count, tab.Session.OwnerProtectedRegions.Count, (tab.Session.IsDirty ? AvaloniaLocalizationCatalog.Text("是") : AvaloniaLocalizationCatalog.Text("否")), selectedText);
    }

    private void MetadataEditorControlChanged(object? sender, EventArgs eventArgs)
    {
        if (!suppressMetadataEditorControls) metadataEditorDirty = true;
    }

    private async void MetadataKeyCountSelectionChanged(
        object? sender,
        SelectionChangedEventArgs eventArgs)
    {
        if (suppressMetadataEditorControls ||
            metadataKeyCountChangeInProgress ||
            metadataKeyCountBox.SelectedItem is not WindowsMetadataKeyCountOption option ||
            viewModel.ActiveTab is not { } tab ||
            option.Value == tab.Session.Document.KeyCount)
            return;

        metadataEditorDirty = true;
        metadataKeyCountChangeInProgress = true;
        try
        {
            // The count shown in the confirmation is a snapshot; room sync can
            // add Notes on the removed lanes while the dialog is open. Recount
            // after each confirmation and ask again if more would be deleted
            // than the user agreed to.
            var confirmedRemoved = 0;
            while (true)
            {
                var removed = tab.Session.Document.Notes.Count(
                    note => !note.IsDraft && note.Lane >= option.Value);
                if (removed <= confirmedRemoved) break;
                var confirmed = await ShowSettingsConfirmationAsync(
                    "更改轨道数",
                    AvaloniaLocalizationCatalog.Format("切换为 {0}K 会删除最右侧的 {1} 个 Note，继续吗？", option.Value, removed),
                    "继续",
                    dangerous: true);
                if (!confirmed ||
                    viewModel.ActiveTab?.Id != tab.Id)
                {
                    RestoreMetadataKeyCountSelection(tab);
                    return;
                }
                confirmedRemoved = removed;
            }

            if (!ApplyMetadataEditor())
                RestoreMetadataKeyCountSelection(tab);
        }
        catch (Exception exception)
        {
            // async void handler: keep the editor alive and the old key count.
            Debug.WriteLine($"Changing the key count failed: {exception}");
            if (!windowCloseTeardownStarted)
            {
                RestoreMetadataKeyCountSelection(tab);
                viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("谱面信息未应用：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
            }
        }
        finally
        {
            metadataKeyCountChangeInProgress = false;
        }
    }

    private void RestoreMetadataKeyCountSelection(DesktopChartTab tab)
    {
        var previous = suppressMetadataEditorControls;
        suppressMetadataEditorControls = true;
        try
        {
            metadataKeyCountBox.SelectedItem =
                WindowsInspectorParityPolicy.Wpf110MetadataKeyCountOptions
                    .FirstOrDefault(option =>
                        option.Value == tab.Session.Document.KeyCount);
        }
        finally
        {
            suppressMetadataEditorControls = previous;
        }
        metadataEditorDirty = !ChartMetadataEditingService.DraftEquals(
            CaptureMetadataEditorDraft(tab),
            ChartMetadataEditingService.Capture(tab.Session.Document));
    }

    private Task RomanizeMetadataAsync(bool title)
    {
        if (title ? titleRomanizationInProgress : artistRomanizationInProgress)
            return title ? activeTitleRomanizationTask : activeArtistRomanizationTask;
        var operation = RomanizeMetadataCoreAsync(title);
        if (title) activeTitleRomanizationTask = operation;
        else activeArtistRomanizationTask = operation;
        return operation;
    }

    private async Task RomanizeMetadataCoreAsync(bool title)
    {
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        if (tab.Session.IsReadOnly || !tab.Session.CanEditMetadata)
        {
            metadataStatusText.Text = tab.Session.IsReadOnly
                ? "观察者不能修改谱面信息。"
                : "转罗马音需要谱面信息权限。";
            metadataStatusText.Foreground = Brushes.OrangeRed;
            return;
        }
        var source = title ? metadataTitleOriginalBox : metadataArtistOriginalBox;
        var destination = title ? metadataTitleBox : metadataArtistBox;
        var button = title ? metadataRomanizeTitleButton : metadataRomanizeArtistButton;
        var sourceSnapshot = source.Text ?? string.Empty;
        var cancellation = new CancellationTokenSource();
        if (title)
        {
            titleRomanizationCancellation?.Cancel();
            titleRomanizationCancellation?.Dispose();
            titleRomanizationCancellation = cancellation;
            titleRomanizationTabId = tab.Id;
            titleRomanizationInProgress = true;
        }
        else
        {
            artistRomanizationCancellation?.Cancel();
            artistRomanizationCancellation?.Dispose();
            artistRomanizationCancellation = cancellation;
            artistRomanizationTabId = tab.Id;
            artistRomanizationInProgress = true;
        }

        button.Content = "分析读音…";
        UpdateEditorAvailability();
        try
        {
            var romanized = await WindowsJapaneseRomanizer.RomanizeAsync(
                sourceSnapshot,
                cancellation.Token);
            cancellation.Token.ThrowIfCancellationRequested();
            if (viewModel.ActiveTab?.Id != tab.Id ||
                !string.Equals(source.Text ?? string.Empty, sourceSnapshot, StringComparison.Ordinal))
                throw new OperationCanceledException("读音分析期间谱面或原文已变化。", cancellation.Token);

            destination.Text = romanized;
            metadataEditorDirty = true;
            metadataStatusText.Text = string.IsNullOrWhiteSpace(romanized)
                ? "原文为空，已清空对应的 ASCII 栏。"
                : AvaloniaLocalizationCatalog.Format("已生成罗马音：{0}", romanized);
            metadataStatusText.Foreground = MutedBrush;
            viewModel.SetStatus(metadataStatusText.Text);
        }
        catch (OperationCanceledException)
        {
            metadataStatusText.Text = "读音分析已取消，未覆盖当前输入。";
            metadataStatusText.Foreground = MutedBrush;
        }
        catch (Exception exception)
        {
            // The status line only has room for the message, and a BCL message
            // arrives as a bare resource key where UseSystemResourceKeys is on.
            // The stack is what says which library call failed, so it goes to the
            // Avalonia log sink — which the iOS host forwards into the launch log
            // and Windows leaves unattached.
            Logger.TryGet(LogEventLevel.Warning, LogArea.Control)?.Log(
                this,
                "Japanese romanization failed: {Error}",
                exception);
            metadataStatusText.Text = AvaloniaLocalizationCatalog.Format("无法分析这段日文的读音：{0}；可以直接在英文栏手动填写罗马音。", AvaloniaLocalizationCatalog.Text(exception.Message));
            metadataStatusText.Foreground = Brushes.OrangeRed;
            viewModel.SetStatus(metadataStatusText.Text);
        }
        finally
        {
            if (title)
            {
                if (ReferenceEquals(titleRomanizationCancellation, cancellation))
                {
                    titleRomanizationCancellation = null;
                    titleRomanizationTabId = null;
                }
                titleRomanizationInProgress = false;
                metadataRomanizeTitleButton.Content = "转罗马音";
            }
            else
            {
                if (ReferenceEquals(artistRomanizationCancellation, cancellation))
                {
                    artistRomanizationCancellation = null;
                    artistRomanizationTabId = null;
                }
                artistRomanizationInProgress = false;
                metadataRomanizeArtistButton.Content = "转罗马音";
            }
            cancellation.Dispose();
            UpdateEditorAvailability();
        }
    }

    private void RefreshMetadataEditor(DesktopChartTab? tab, bool force = false)
    {
        RefreshMetadataStats(tab);
        if (tab == null)
        {
            metadataEditorTabId = null;
            metadataEditorChangeSerial = -1;
            metadataEditorDirty = false;
            metadataEditorBaseline = null;
            metadataStatusText.Text = "没有打开的谱面。";
            return;
        }
        var tabChanged = metadataEditorTabId != tab.Id;
        if (!force && !tabChanged && metadataEditorChangeSerial == tab.Session.ChangeSerial) return;

        var authoritative = ChartMetadataEditingService.Capture(tab.Session.Document);
        var rebased = !force &&
                      !tabChanged &&
                      metadataEditorDirty &&
                      metadataEditorBaseline != null
            ? ChartMetadataEditingService.RebaseDraftWithDiagnostics(
                CaptureMetadataEditorDraft(tab),
                metadataEditorBaseline,
                authoritative)
            : null;
        var draft = rebased?.Draft ?? authoritative;
        PopulateMetadataEditorDraft(tab, draft);
        metadataEditorTabId = tab.Id;
        metadataEditorChangeSerial = tab.Session.ChangeSerial;
        metadataEditorBaseline = authoritative;
        metadataEditorDirty = rebased?.HasLocalChanges == true;
        metadataStatusText.Foreground = MutedBrush;
        if (rebased is { UpdatedAuthoritativeFieldCount: > 0, HasLocalChanges: true })
        {
            metadataStatusText.Text =
                "远端谱面信息已同步；未应用的本地输入已保留";
            return;
        }
        metadataStatusText.Text = tab.Session.IsReadOnly
            ? "观察者只读：谱面信息不可修改。"
            : !tab.Session.CanEditMetadata
                ? "没有谱面信息权限；请向房主索要。"
                : "Metadata、KeyCount 与 Offset 以一个撤销步骤原子应用。";
    }

    private void RefreshMetadataStats(DesktopChartTab? tab)
    {
        var stats = tab == null
            ? new WindowsMetadataStats(0, 0, 0)
            : WindowsInspectorParityPolicy.MeasureMetadataStats(
                tab.Session.Document);
        metadataStatsNotesText.Text =
            stats.Notes.ToString(CultureInfo.InvariantCulture);
        metadataStatsHoldsText.Text =
            stats.Holds.ToString(CultureInfo.InvariantCulture);
        metadataStatsTimingText.Text =
            stats.Timing.ToString(CultureInfo.InvariantCulture);
    }

    private ChartMetadataDraft CaptureMetadataEditorDraft(DesktopChartTab tab) =>
        new(
            metadataTitleBox.Text ?? string.Empty,
            metadataTitleOriginalBox.Text ?? string.Empty,
            metadataArtistBox.Text ?? string.Empty,
            metadataArtistOriginalBox.Text ?? string.Empty,
            metadataCreatorBox.Text ?? string.Empty,
            metadataVersionBox.Text ?? string.Empty,
            metadataPreviewTimeBox.Text ?? string.Empty,
            metadataBpmBox.Text ?? string.Empty,
            metadataOffsetBox.Text ?? string.Empty,
            metadataKeyCountBox.SelectedItem is WindowsMetadataKeyCountOption keyCount
                ? keyCount.Value
                : tab.Session.Document.KeyCount,
            metadataOverallDifficultyBox.Text ?? string.Empty,
            metadataHpDrainRateBox.Text ?? string.Empty,
            metadataCoverFileBox.Text ?? string.Empty,
            metadataBackgroundFileBox.Text ?? string.Empty);

    private void PopulateMetadataEditorDraft(
        DesktopChartTab tab,
        ChartMetadataDraft draft)
    {
        var previous = suppressMetadataEditorControls;
        suppressMetadataEditorControls = true;
        try
        {
            metadataTitleBox.Text = draft.Title;
            metadataTitleOriginalBox.Text = draft.TitleOriginal;
            metadataArtistBox.Text = draft.Artist;
            metadataArtistOriginalBox.Text = draft.ArtistOriginal;
            metadataCreatorBox.Text = draft.Creator;
            metadataVersionBox.Text = draft.Version;
            metadataPreviewTimeBox.Text = draft.PreviewTime;
            metadataBpmBox.Text = draft.Bpm;
            metadataOffsetBox.Text = draft.Offset;
            metadataKeyCountBox.SelectedItem =
                WindowsInspectorParityPolicy.Wpf110MetadataKeyCountOptions
                    .FirstOrDefault(option => option.Value == draft.KeyCount);
            metadataOverallDifficultyBox.Text = draft.OverallDifficulty;
            metadataHpDrainRateBox.Text = draft.HpDrainRate;
            metadataAudioFileBox.Text = tab.Session.Document.Metadata.AudioFile;
            metadataCoverFileBox.Text = draft.CoverFile;
            metadataBackgroundFileBox.Text = draft.BackgroundFile;
        }
        finally
        {
            suppressMetadataEditorControls = previous;
        }
    }

    private bool ApplyMetadataEditor(bool enforceCommunityRules = false, bool includeTiming = true)
    {
        lastMetadataApplyError = null;
        var tab = viewModel.ActiveTab;
        if (tab == null) return false;
        var draft = CaptureMetadataEditorDraft(tab);
        if (!includeTiming)
        {
            var timing = ChartMetadataEditingService.Capture(tab.Session.Document);
            draft = draft with { Bpm = timing.Bpm, Offset = timing.Offset };
        }
        ChartMetadataEdit? edit;
        string error;
        var parsed = enforceCommunityRules
            ? ChartMetadataEditingService.TryParseDraft(
                draft,
                out edit,
                out error)
            : ChartMetadataEditingService.TryParseDraftForLocalPreservation(
                draft,
                tab.Session.Document,
                out edit,
                out error);
        if (!parsed || edit == null)
        {
            lastMetadataApplyError = error;
            metadataStatusText.Text = error;
            metadataStatusText.Foreground = Brushes.OrangeRed;
            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("谱面信息未应用：{0}", error));
            return false;
        }

        try
        {
            var result = ChartMetadataEditingService.Apply(
                tab.Session,
                edit,
                enforceCommunityRules);
            metadataStatusText.Text = result.Message;
            metadataStatusText.Foreground = result.Status == ChartMetadataApplyStatus.Denied
                ? Brushes.OrangeRed
                : MutedBrush;
            viewModel.SetStatus(result.Message);
            if (result.Status == ChartMetadataApplyStatus.Denied &&
                WindowsRoomPermissionNoticePolicy.MetadataApplyDenied(
                    result.PermissionCategory) is { } denied)
                ShowRoomPermissionNotice(denied);
            if (result.Status == ChartMetadataApplyStatus.Denied) return false;
            if (result.Status != ChartMetadataApplyStatus.Applied)
            {
                metadataEditorDirty = false;
                metadataEditorBaseline =
                    ChartMetadataEditingService.Capture(tab.Session.Document);
                return true;
            }
            metadataEditorDirty = false;
            RefreshMetadataEditor(tab, force: true);
            RequestChartBackground(tab, tab.Session.Document.Metadata.BackgroundFile);
            metadataStatusText.Text = result.Message;
            return true;
        }
        catch (Exception exception) when (exception is InvalidOperationException or ArgumentException)
        {
            lastMetadataApplyError = exception.Message;
            metadataStatusText.Text = AvaloniaLocalizationCatalog.Format("谱面信息未应用：{0}", AvaloniaLocalizationCatalog.Text(exception.Message));
            metadataStatusText.Foreground = Brushes.OrangeRed;
            viewModel.SetStatus(metadataStatusText.Text);
            return false;
        }
    }

    private bool TryApplyPendingMetadataEditor(
        DesktopChartTab tab,
        bool enforceCommunityRules)
    {
        if (metadataEditorTabId != tab.Id || !metadataEditorDirty) return true;
        if (!ReferenceEquals(viewModel.ActiveTab, tab)) return false;
        return ApplyMetadataEditor(enforceCommunityRules);
    }

    private void SetMetadataPreviewToCurrentPosition()
    {
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        try
        {
            var snapshot = audioTransport.PlaybackSnapshot;
            var playingCurrentAudio = snapshot?.IsPlaying == true && audioTransport.ActiveTabId == tab.Id;
            var previewTime = ChartMetadataEditingService.ResolvePreviewTime(
                playingCurrentAudio,
                snapshot?.Position.TotalMilliseconds ?? 0,
                tab.Session.Document.Timing,
                BeatPosition.FromDouble(timeline.CurrentBeat));
            var result = ChartMetadataEditingService.SetPreviewTime(tab.Session, previewTime);
            if (result.Status != ChartMetadataApplyStatus.Denied)
            {
                var authoritative = ChartMetadataEditingService.Capture(tab.Session.Document);
                var current = CaptureMetadataEditorDraft(tab) with
                {
                    PreviewTime = previewTime.ToString(CultureInfo.InvariantCulture)
                };
                var rebased = ChartMetadataEditingService.RebaseDraftWithDiagnostics(
                    current,
                    metadataEditorBaseline ?? authoritative,
                    authoritative);
                PopulateMetadataEditorDraft(tab, rebased.Draft);
                metadataEditorBaseline = authoritative;
                metadataEditorDirty = rebased.HasLocalChanges;
            }
            metadataEditorTabId = tab.Id;
            metadataEditorChangeSerial = tab.Session.ChangeSerial;
            metadataStatusText.Text = result.Message;
            metadataStatusText.Foreground = result.Status == ChartMetadataApplyStatus.Denied
                ? Brushes.OrangeRed
                : MutedBrush;
            viewModel.SetStatus(result.Message);
            if (result.Status == ChartMetadataApplyStatus.Denied)
                ShowRoomPermissionNotice(
                    WindowsRoomPermissionNoticePolicy.PreviewTimeDenied(
                        tab.Session.IsReadOnly));
        }
        catch (Exception exception)
        {
            metadataStatusText.Text = AvaloniaLocalizationCatalog.Format("无法读取当前播放位置：{0}", AvaloniaLocalizationCatalog.Text(exception.Message));
            metadataStatusText.Foreground = Brushes.OrangeRed;
            viewModel.SetStatus(metadataStatusText.Text);
        }
    }

    private Task ImportCurrentChartAudioAsync()
    {
        if (!activeAudioImportTask.IsCompleted) return activeAudioImportTask;
        var operation = ImportCurrentChartAudioCoreAsync();
        activeAudioImportTask = operation;
        return operation;
    }

    /// <summary>
    /// Single-flight import of a known audio path (file drop). Registers the
    /// operation as the active import so the close preflight waits for it and
    /// a second import cannot cancel this one mid-copy.
    /// </summary>
    private Task ImportChartAudioPathAsync(DesktopChartTab tab, string sourcePath)
    {
        if (!activeAudioImportTask.IsCompleted)
        {
            viewModel.SetStatus("音频导入进行中，请稍后再试。");
            return activeAudioImportTask;
        }
        var operation = ImportChartAudioPathCoreAsync(tab, sourcePath);
        activeAudioImportTask = operation;
        return operation;
    }

    private Task ImportCurrentChartImageAsync(bool background)
    {
        if (imageImportInProgress) return activeImageImportTask;
        var operation = ImportCurrentChartImageCoreAsync(background);
        activeImageImportTask = operation;
        return operation;
    }

    private async Task ImportCurrentChartImageCoreAsync(bool background)
    {
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        if (tab.Session.IsReadOnly || !tab.Session.CanEditMetadata)
        {
            metadataStatusText.Text = tab.Session.IsReadOnly
                ? "观察者不能修改谱面图片。"
                : "选择谱面图片需要谱面信息权限。";
            metadataStatusText.Foreground = Brushes.OrangeRed;
            return;
        }

        imageImportCancellation?.Cancel();
        imageImportCancellation?.Dispose();
        var cancellation = new CancellationTokenSource();
        imageImportCancellation = cancellation;
        imageImportTabId = tab.Id;
        imageImportInProgress = true;
        UpdateEditorAvailability();
        ChartAssetImportResult? imported = null;
        try
        {
            var sourcePath = await PickLocalFileAsync(
                new FilePickerOpenOptions
                {
                    Title = "选择图片",
                    AllowMultiple = false,
                    FileTypeFilter =
                    [
                        new FilePickerFileType("图片文件")
                        {
                            Patterns = ["*.png", "*.jpg", "*.jpeg", "*.webp", "*.bmp"],
                            MimeTypes = ["image/*"]
                        }
                    ]
                },
                PickedFileRetention.Transient,
                cancellation.Token);
            if (string.IsNullOrWhiteSpace(sourcePath)) return;

            imported = await Task.Run(
                () => ChartAssetImportService.ImportImage(
                    tab.WorkingPath,
                    Path.GetFullPath(sourcePath),
                    tab.SourcePath),
                cancellation.Token);
            cancellation.Token.ThrowIfCancellationRequested();
            if (viewModel.ActiveTab?.Id != tab.Id)
                throw new OperationCanceledException("导入期间已切换谱面。", cancellation.Token);

            if (background)
            {
                metadataBackgroundFileBox.Text = imported.FileName;
                RequestChartBackground(tab, imported.FileName);
            }
            else
            {
                metadataCoverFileBox.Text = imported.FileName;
            }
            metadataEditorTabId = tab.Id;
            metadataEditorChangeSerial = tab.Session.ChangeSerial;
            metadataEditorDirty = true;
            metadataStatusText.Text =
                AvaloniaLocalizationCatalog.Format("{0}已导入：{1}；点击“应用谱面信息与 Offset”后写入谱面。", (background ? AvaloniaLocalizationCatalog.Text("背景图片") : AvaloniaLocalizationCatalog.Text("歌曲封面")), imported.FileName);
            metadataStatusText.Foreground = MutedBrush;
            viewModel.SetStatus(metadataStatusText.Text);
        }
        catch (OperationCanceledException)
        {
            if (imported?.Created == true) TryDeleteImportedAsset(imported.DestinationPath);
            metadataStatusText.Text = "图片导入已取消，未修改当前谱面。";
            metadataStatusText.Foreground = MutedBrush;
        }
        catch (Exception exception)
        {
            if (imported?.Created == true) TryDeleteImportedAsset(imported.DestinationPath);
            metadataStatusText.Text = AvaloniaLocalizationCatalog.Format("无法导入图片：{0}", AvaloniaLocalizationCatalog.Text(exception.Message));
            metadataStatusText.Foreground = Brushes.OrangeRed;
            viewModel.SetStatus(metadataStatusText.Text);
            WindowsNativeMessageBox.Show(
                this,
                WindowsLibraryLauncherParityPolicy.CreateOperationError(
                    "无法复制图片到谱面目录",
                    exception));
        }
        finally
        {
            if (ReferenceEquals(imageImportCancellation, cancellation))
            {
                imageImportCancellation = null;
                imageImportTabId = null;
            }
            cancellation.Dispose();
            imageImportInProgress = false;
            UpdateEditorAvailability();
        }
    }

    private void UpdateChartBackground(DesktopChartTab? tab)
    {
        var reference = tab == null
            ? null
            : metadataEditorDirty && metadataEditorTabId == tab.Id
                ? metadataBackgroundFileBox.Text
                : tab.Session.Document.Metadata.BackgroundFile;
        RequestChartBackground(tab, reference);
    }

    /// <summary>
    /// Forgets which background is currently loaded, so the next
    /// <see cref="UpdateChartBackground"/> reloads it instead of deciding that
    /// the right one is already there.
    ///
    /// Needed after test play. On a tablet the playtest surface is a modal
    /// overlay, which means the editor's whole visual tree is detached from the
    /// host and re-attached on the way back — unlike Windows, where playtest is a
    /// separate window and the editor is never taken down. Coming back, the
    /// chart background was gone on both mobile clients while the notes and grid
    /// drew normally, and none of the three places that clear the bitmap had
    /// run: the field still held it, the opacity was untouched, and
    /// RequestChartBackground's "same tab, same path" guard then decided there
    /// was nothing to do. The bitmap survives the trip as an object without
    /// surviving it as something drawable.
    ///
    /// The mechanism behind that is not identified — this restores the image
    /// rather than explaining it. It is cheap (one decode after a playtest
    /// session) and it reports itself: the reload writes either
    /// "背景预览已加载" or "背景图片无法解码" to the status line, so a
    /// recurrence says which half is at fault.
    /// </summary>
    private void InvalidateChartBackgroundCache()
    {
        backgroundImageTabId = null;
        backgroundImagePath = null;
    }

    private void RequestChartBackground(DesktopChartTab? tab, string? reference)
    {
        var path = tab == null
            ? null
            : ChartAssetImportService.ResolveAssetPath(tab.WorkingPath, tab.SourcePath, reference);
        if (backgroundImageTabId == tab?.Id &&
            string.Equals(backgroundImagePath, path, StringComparison.OrdinalIgnoreCase))
            return;

        backgroundImageLoadCancellation?.Cancel();
        backgroundImageLoadCancellation = null;
        var generation = ++backgroundImageLoadGeneration;
        backgroundImageTabId = tab?.Id;
        backgroundImagePath = path;
        timeline.SetChartBackgroundImage(null);
        if (tab == null || path == null) return;

        var cancellation = new CancellationTokenSource();
        var cancellationToken = cancellation.Token;
        backgroundImageLoadCancellation = cancellation;
        _ = LoadChartBackgroundAsync(path, tab.Id, generation, cancellation, cancellationToken);
    }

    private async Task LoadChartBackgroundAsync(
        string path,
        Guid tabId,
        long generation,
        CancellationTokenSource cancellation,
        CancellationToken cancellationToken)
    {
        Bitmap? bitmap = null;
        try
        {
            bitmap = await Task.Run(() =>
            {
                cancellationToken.ThrowIfCancellationRequested();
                using var stream = new FileStream(
                    path,
                    FileMode.Open,
                    FileAccess.Read,
                    FileShare.ReadWrite,
                    64 * 1024,
                    FileOptions.SequentialScan);
                var decoded = Bitmap.DecodeToWidth(
                    stream,
                    2560,
                    BitmapInterpolationMode.HighQuality);
                cancellationToken.ThrowIfCancellationRequested();
                return decoded;
            }, cancellationToken);
            if (generation != backgroundImageLoadGeneration ||
                cancellationToken.IsCancellationRequested ||
                viewModel.ActiveTab?.Id != tabId ||
                !string.Equals(backgroundImagePath, path, StringComparison.OrdinalIgnoreCase))
            {
                bitmap.Dispose();
                return;
            }
            timeline.SetChartBackgroundImage(bitmap);
            bitmap = null;
            metadataStatusText.Text = AvaloniaLocalizationCatalog.Format("背景预览已加载：{0}。", Path.GetFileName(path));
            metadataStatusText.Foreground = MutedBrush;
            viewModel.SetStatus(metadataStatusText.Text);
        }
        catch (OperationCanceledException)
        {
            bitmap?.Dispose();
        }
        catch
        {
            bitmap?.Dispose();
            if (generation == backgroundImageLoadGeneration && viewModel.ActiveTab?.Id == tabId)
            {
                timeline.SetChartBackgroundImage(null);
                metadataStatusText.Text = AvaloniaLocalizationCatalog.Format("背景图片无法解码：{0}。", Path.GetFileName(path));
                metadataStatusText.Foreground = Brushes.OrangeRed;
                viewModel.SetStatus(metadataStatusText.Text);
            }
        }
        finally
        {
            if (ReferenceEquals(backgroundImageLoadCancellation, cancellation))
                backgroundImageLoadCancellation = null;
            cancellation.Dispose();
        }
    }

    private async Task ImportCurrentChartAudioCoreAsync()
    {
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        if (tab.Session.IsReadOnly || !tab.Session.CanEditMetadata)
        {
            SetMetadataAudioStatus(
                tab.Session.IsReadOnly
                    ? "观察者不能修改谱面音频。"
                    : "选择谱面音频需要谱面信息权限。",
                error: true);
            return;
        }

        string? sourcePath;
        try
        {
            sourcePath = await PickLocalFileAsync(
                new FilePickerOpenOptions
                {
                    Title = "选择音乐",
                    AllowMultiple = false,
                    FileTypeFilter =
                    [
                        new FilePickerFileType("音频文件")
                        {
                            Patterns = ["*.mp3", "*.ogg", "*.wav", "*.flac", "*.m4a", "*.aac"],
                            MimeTypes = ["audio/*"]
                        }
                    ]
                },
                PickedFileRetention.Transient);
        }
        catch (Exception exception)
        {
            // The import itself reports its failures; the picker had no boundary.
            SetMetadataAudioStatus(AvaloniaLocalizationCatalog.Format("无法导入音频：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)), error: true);
            return;
        }
        if (string.IsNullOrWhiteSpace(sourcePath)) return;
        _ = await ImportChartAudioPathCoreAsync(tab, Path.GetFullPath(sourcePath));
    }

    private async Task<WindowsChartAudioImportStatus> ImportChartAudioPathCoreAsync(
        DesktopChartTab tab,
        string sourcePath)
    {
        if (tab.Session.IsReadOnly || !tab.Session.CanEditMetadata)
        {
            SetMetadataAudioStatus(
                tab.Session.IsReadOnly
                    ? "观察者不能修改谱面音频。"
                    : "选择谱面音频需要谱面信息权限。",
                error: true);
            return WindowsChartAudioImportStatus.Denied;
        }

        var mode = AudioImportMode.KeepOriginal;
        if (!Path.GetExtension(sourcePath).Equals(".ogg", StringComparison.OrdinalIgnoreCase))
        {
            mode = await new AudioImportModeDialog(
                    Path.GetFileName(sourcePath),
                    displayScaleSettings.UiScale,
                    displayScaleSettings.FontScale)
                .ShowDialog<AudioImportMode>(this);
            if (mode == AudioImportMode.Cancel)
                return WindowsChartAudioImportStatus.Canceled;
        }

        audioImportCancellation?.Cancel();
        audioImportCancellation?.Dispose();
        var cancellation = new CancellationTokenSource();
        audioImportCancellation = cancellation;
        audioImportInProgress = true;
        UpdateEditorAvailability();
        if (evidenceAudioPermissionRevokeDelayMilliseconds > 0)
        {
            DispatcherTimer.RunOnce(
                () =>
                {
                    if (viewModel.ActiveTab?.Id != tab.Id) return;
                    tab.Session.CanEditMetadata = false;
                    UpdateEditorAvailability();
                },
                TimeSpan.FromMilliseconds(
                    evidenceAudioPermissionRevokeDelayMilliseconds));
        }
        try
        {
            if (audioAnalysisInProgress)
            {
                audioAnalysisCancellation?.Cancel();
                try { await activeAudioAnalysisTask; }
                catch (OperationCanceledException) { }
            }

            IProgress<double>? progress = null;
            if (mode == AudioImportMode.ConvertToOgg)
            {
                progress = new Progress<double>(value =>
                    SetMetadataAudioStatus(AvaloniaLocalizationCatalog.Format("正在转换 OGG… {0:P0}", value)));
                SetMetadataAudioStatus("正在转换 OGG…");
            }
            else
                SetMetadataAudioStatus("正在复制音频到谱面编辑目录…");

            var result = await chartAudioImportWorkflow.RunAsync(
                tab.Session,
                tab.WorkingPath,
                tab.SourcePath,
                sourcePath,
                mode == AudioImportMode.ConvertToOgg,
                () => viewModel.ActiveTab?.Id == tab.Id,
                progress,
                cancellation.Token,
                TimeSpan.FromMilliseconds(
                    evidenceAudioPreCommitDelayMilliseconds));
            if (result.Status == WindowsChartAudioImportStatus.Canceled)
            {
                SetMetadataAudioStatus("音频导入已取消，未修改当前谱面。", error: true);
                return WindowsChartAudioImportStatus.Canceled;
            }
            if (result.Status == WindowsChartAudioImportStatus.Failed)
            {
                SetMetadataAudioStatus(
                    AvaloniaLocalizationCatalog.Format("无法导入音频：{0}", result.Error?.Message ?? AvaloniaLocalizationCatalog.Text("未知错误")),
                    error: true);
                return WindowsChartAudioImportStatus.Failed;
            }
            if (result.Status == WindowsChartAudioImportStatus.Denied)
            {
                SetMetadataAudioStatus(
                    result.MetadataApply?.Message ?? "当前权限不允许修改谱面音频。",
                    error: true);
                return WindowsChartAudioImportStatus.Denied;
            }

            var imported = result.Asset
                           ?? throw new InvalidOperationException("音频导入没有返回资源。");
            var apply = result.MetadataApply
                        ?? throw new InvalidOperationException("音频导入没有返回谱面修改结果。");
            metadataAudioFileBox.Text = imported.FileName;
            metadataEditorTabId = tab.Id;
            metadataEditorChangeSerial = tab.Session.ChangeSerial;
            SetMetadataAudioStatus(
                mode == AudioImportMode.ConvertToOgg
                    ? AvaloniaLocalizationCatalog.Format("音频已转换并导入：{0}", imported.FileName)
                    : AvaloniaLocalizationCatalog.Format("音频已导入：{0}", imported.FileName));
            viewModel.SetStatus(apply.Message);
            UpdateUi();
            await StartSingleTempoAnalysisAsync();
            return WindowsChartAudioImportStatus.Imported;
        }
        catch (Exception exception)
        {
            SetMetadataAudioStatus(AvaloniaLocalizationCatalog.Format("无法导入音频：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)), error: true);
            return WindowsChartAudioImportStatus.Failed;
        }
        finally
        {
            // Only the import that still owns the token may clear the shared
            // state; a newer import that replaced it is still running.
            if (ReferenceEquals(audioImportCancellation, cancellation))
            {
                audioImportCancellation = null;
                audioImportInProgress = false;
                UpdateEditorAvailability();
            }
            cancellation.Dispose();
        }
    }

    private Task StartSingleTempoAnalysisAsync()
    {
        if (audioAnalysisInProgress)
        {
            if (activeTempoAnalysisKind == TempoAnalysisKind.Single)
                RequestTempoAnalysisCancellation();
            return activeAudioAnalysisTask;
        }
        var operation = RunSingleTempoAnalysisAsync();
        activeAudioAnalysisTask = operation;
        return operation;
    }

    private async Task RunSingleTempoAnalysisAsync()
    {
        var tab = viewModel.ActiveTab;
        if (!TryBeginTempoAnalysis(
                tab,
                TempoAnalysisKind.Single,
                out var audioPath,
                out var cancellation))
            return;
        metadataAnalyzeSingleTempoButton.Content = "取消 BPM 分析";
        SetMetadataAudioStatus("正在读取波形并分析节拍，最长分析前 4 分钟；可点击按钮取消。");
        try
        {
            var result = await WindowsBeatAnalyzer.AnalyzeAsync(audioPath, cancellation.Token);
            if (!IsCurrentAudioAnalysisContext(tab))
            {
                SetMetadataAudioStatus("分析期间已切换谱面，本次结果已取消且不会写入当前谱面。", error: true);
                return;
            }

            SetMetadataAudioStatus(
                AvaloniaLocalizationCatalog.Format("BPM {0:0.###} · Offset {1:0.###} ms · 稳定度 {2:P0} · 置信度 {3:P0}", result.Bpm, result.OffsetMilliseconds, 1 - result.Instability, result.Confidence));
            var serialAtPreview = tab!.Session.ChangeSerial;
            var confirmed = await new SingleTempoResultDialog(
                    result,
                    tab.Session.CanEditMetadata,
                    displayScaleSettings.UiScale,
                    displayScaleSettings.FontScale)
                .ShowDialog<bool>(this);
            if (!confirmed) return;
            if (!IsCurrentAudioAnalysisContext(tab))
            {
                SetMetadataAudioStatus("确认前已切换谱面，检测结果未写入。", error: true);
                return;
            }

            var applied = TempoDetectionEditingService.ApplySingle(tab.Session, result, serialAtPreview);
            SetMetadataAudioStatus(
                applied.Message,
                applied.Status is TempoDetectionApplyStatus.Denied or TempoDetectionApplyStatus.Stale);
            viewModel.SetStatus(applied.Message);
            if (applied.Status == TempoDetectionApplyStatus.Denied &&
                WindowsRoomPermissionNoticePolicy.TempoAnalysisApplyDenied(
                    applied.PermissionCategory,
                    variableTempo: false) is { } denied)
                ShowRoomPermissionNotice(denied);
            if (applied.Status != TempoDetectionApplyStatus.Applied) return;
            UpdateTempoEditorFields(tab, result.Bpm, result.OffsetMilliseconds, applied.MetadataBpmUpdated);
        }
        catch (OperationCanceledException)
        {
            SetMetadataAudioStatus("BPM 分析已取消，未写入谱面。", error: true);
        }
        catch (Exception exception)
        {
            SetMetadataAudioStatus(AvaloniaLocalizationCatalog.Format("BPM 检测失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)), error: true);
        }
        finally
        {
            metadataAnalyzeSingleTempoButton.Content = "检测 BPM 与 Offset";
            CompleteTempoAnalysis(cancellation);
        }
    }

    private Task StartVariableTempoAnalysisAsync()
    {
        if (audioAnalysisInProgress)
        {
            if (activeTempoAnalysisKind == TempoAnalysisKind.Variable)
                RequestTempoAnalysisCancellation();
            return activeAudioAnalysisTask;
        }
        var operation = RunVariableTempoAnalysisAsync();
        activeAudioAnalysisTask = operation;
        return operation;
    }

    private Task StartManualTempoMeasurementAsync()
    {
        if (audioAnalysisInProgress) return activeAudioAnalysisTask;
        var operation = RunManualTempoMeasurementAsync();
        activeAudioAnalysisTask = operation;
        return operation;
    }

    private async Task RunManualTempoMeasurementAsync()
    {
        var tab = viewModel.ActiveTab;
        if (!TryBeginTempoAnalysis(
                tab,
                TempoAnalysisKind.Manual,
                out _,
                out var cancellation))
            return;

        metadataAnalyzeManualTempoButton.Content = "正在手动测量…";
        SetMetadataAudioStatus("手动测量会播放当前歌曲；请在弹窗内设置按键并跟随整拍连续打拍。");
        var originalRate = audioTransport.PlaybackRate;
        var wasPlaying = audioTransport.PlaybackSnapshot?.IsPlaying == true &&
                         audioTransport.ActiveTabId == tab!.Id;
        try
        {
            if (!await audioTransport.EnsureAudioReadyAsync(tab!))
                throw new InvalidOperationException(audioTransport.Status);
            if (!IsCurrentAudioAnalysisContext(tab))
                throw new OperationCanceledException();

            await audioTransport.SetPlaybackRateAsync(1);
            if (audioTransport.LastError != null)
                throw new InvalidOperationException(
                    audioTransport.LastError.Message,
                    audioTransport.LastError);

            var serialAtPreview = tab!.Session.ChangeSerial;
            var result = await new ManualTempoMeasurementDialog(
                    ToggleAudioPlaybackAsync,
                    () => audioTransport.ActiveTabId == tab.Id &&
                          audioTransport.PlaybackSnapshot?.IsPlaying == true,
                    () => audioTransport.ActiveTabId == tab.Id
                        ? audioTransport.PlaybackSnapshot?.Position.TotalMilliseconds
                        : null,
                    displayScaleSettings.UiScale,
                    displayScaleSettings.FontScale)
                .ShowDialog<BeatAnalysisResult?>(this);
            if (result is not { } measured) return;
            if (!IsCurrentAudioAnalysisContext(tab))
            {
                SetMetadataAudioStatus("确认前已切换谱面，手动测量结果未写入。", error: true);
                return;
            }

            var applied = TempoDetectionEditingService.ApplySingle(
                tab.Session,
                measured,
                serialAtPreview);
            SetMetadataAudioStatus(
                applied.Message,
                applied.Status is TempoDetectionApplyStatus.Denied or TempoDetectionApplyStatus.Stale);
            viewModel.SetStatus(applied.Message);
            if (applied.Status == TempoDetectionApplyStatus.Denied &&
                WindowsRoomPermissionNoticePolicy.TempoAnalysisApplyDenied(
                    applied.PermissionCategory,
                    variableTempo: false) is { } denied)
                ShowRoomPermissionNotice(denied);
            if (applied.Status == TempoDetectionApplyStatus.Applied)
                UpdateTempoEditorFields(
                    tab,
                    measured.Bpm,
                    measured.OffsetMilliseconds,
                    applied.MetadataBpmUpdated);
        }
        catch (OperationCanceledException)
        {
            SetMetadataAudioStatus("手动测量已取消，未写入谱面。", error: true);
        }
        catch (Exception exception)
        {
            SetMetadataAudioStatus(AvaloniaLocalizationCatalog.Format("手动测量失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)), error: true);
        }
        finally
        {
            if (audioTransport.ActiveTabId == tab!.Id)
            {
                var isPlaying = audioTransport.PlaybackSnapshot?.IsPlaying == true;
                if (isPlaying != wasPlaying)
                    await audioTransport.TogglePlayPauseAsync();
                await audioTransport.SetPlaybackRateAsync(originalRate);
            }
            metadataAnalyzeManualTempoButton.Content = "手动测量 BPM 与 Offset";
            CompleteTempoAnalysis(cancellation);
        }
    }

    private async Task RunVariableTempoAnalysisAsync()
    {
        var tab = viewModel.ActiveTab;
        if (!TryBeginTempoAnalysis(
                tab,
                TempoAnalysisKind.Variable,
                out var audioPath,
                out var cancellation))
            return;
        metadataAnalyzeVariableTempoButton.Content = "取消多 BPM 分析";
        SetMetadataAudioStatus("正在分窗估计局部节拍并合并稳定变速点，最长分析前 4 分钟；可点击按钮取消。");
        try
        {
            var result = await WindowsBeatAnalyzer.AnalyzeTimelineAsync(audioPath, cancellation.Token);
            if (!IsCurrentAudioAnalysisContext(tab))
            {
                SetMetadataAudioStatus("分析期间已切换谱面，本次结果已取消且不会写入当前谱面。", error: true);
                return;
            }

            var plan = TempoDetectionEditingService.CreateTimelinePlan(tab!.Session.Document, result.Timeline);
            var minimumConfidence = result.Timeline.Segments.Min(segment => segment.Confidence);
            SetMetadataAudioStatus(
                AvaloniaLocalizationCatalog.Format("预测到 {0} 个 BPM 段 · 首段 Offset {1:0.###} ms · 最低置信度 {2:P0}", plan.Candidates.Count, result.Timeline.InitialOffsetMilliseconds, minimumConfidence));
            var serialAtPreview = tab.Session.ChangeSerial;
            var choice = await new VariableTempoResultDialog(
                    result,
                    plan,
                    displayScaleSettings.UiScale,
                    displayScaleSettings.FontScale)
                .ShowDialog<VariableTempoDialogChoice>(this);
            if (choice == VariableTempoDialogChoice.Cancel) return;
            if (!IsCurrentAudioAnalysisContext(tab))
            {
                SetMetadataAudioStatus("确认前已切换谱面，预测结果未写入。", error: true);
                return;
            }

            var compensate = choice == VariableTempoDialogChoice.ApplyWithScrollCompensation;
            if (compensate &&
                (!TryParseMetadataNumber(metadataBpmBox.Text, out var displayedBpm) ||
                 !displayedBpm.Equals(plan.ReferenceBpm)))
            {
                SetMetadataAudioStatus(
                    AvaloniaLocalizationCatalog.Format("谱面 BPM 输入框中有尚未应用的内容。流速补正只使用已保存的基准 BPM {0:R}；请先应用谱面信息后重新预测。", plan.ReferenceBpm),
                    error: true);
                return;
            }

            var applied = TempoDetectionEditingService.ApplyTimeline(
                tab.Session,
                plan,
                result.Timeline.InitialOffsetMilliseconds,
                compensate,
                serialAtPreview);
            SetMetadataAudioStatus(
                applied.Message,
                applied.Status is TempoDetectionApplyStatus.Denied or TempoDetectionApplyStatus.Stale);
            viewModel.SetStatus(applied.Message);
            if (applied.Status == TempoDetectionApplyStatus.Denied &&
                WindowsRoomPermissionNoticePolicy.TempoAnalysisApplyDenied(
                    applied.PermissionCategory,
                    variableTempo: true) is { } denied)
                ShowRoomPermissionNotice(denied);
            if (applied.Status != TempoDetectionApplyStatus.Applied) return;
            UpdateTempoEditorFields(
                tab,
                plan.ReferenceBpm,
                result.Timeline.InitialOffsetMilliseconds,
                updateBpm: false);
        }
        catch (OperationCanceledException)
        {
            SetMetadataAudioStatus("多 BPM 分析已取消，未写入谱面。", error: true);
        }
        catch (Exception exception)
        {
            SetMetadataAudioStatus(AvaloniaLocalizationCatalog.Format("多 BPM 预测失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)), error: true);
        }
        finally
        {
            metadataAnalyzeVariableTempoButton.Content = "预测多个 BPM";
            CompleteTempoAnalysis(cancellation);
        }
    }

    private bool TryBeginTempoAnalysis(
        DesktopChartTab? tab,
        TempoAnalysisKind kind,
        out string audioPath,
        out CancellationTokenSource cancellation)
    {
        audioPath = string.Empty;
        cancellation = new CancellationTokenSource();
        if (tab == null)
        {
            cancellation.Dispose();
            return false;
        }
        if (tab.Session.IsReadOnly || !tab.Session.CanEditTiming)
        {
            cancellation.Dispose();
            SetMetadataAudioStatus(
                tab.Session.IsReadOnly
                    ? "观察者不能写入 BPM 或 Delay。"
                    : "BPM 与 Offset 属于 Timing，需要 Effect 权限。",
                error: true);
            ShowRoomPermissionNotice(
                WindowsRoomPermissionNoticePolicy.TempoAnalysisStartDenied());
            return false;
        }
        audioPath = WindowsAudioTransportViewModel.ResolveDocumentAudioPath(tab) ?? string.Empty;
        if (audioPath.Length == 0)
        {
            cancellation.Dispose();
            SetMetadataAudioStatus("请先选择一个存在的音频文件。", error: true);
            return false;
        }

        audioAnalysisCancellation?.Cancel();
        cancellation = new CancellationTokenSource();
        audioAnalysisCancellation = cancellation;
        audioAnalysisTabId = tab.Id;
        activeTempoAnalysisKind = kind;
        audioAnalysisInProgress = true;
        UpdateEditorAvailability();
        return true;
    }

    private void RequestTempoAnalysisCancellation()
    {
        if (!audioAnalysisInProgress || audioAnalysisCancellation == null) return;
        SetMetadataAudioStatus("正在取消 BPM 分析…");
        audioAnalysisCancellation.Cancel();
    }

    private void CompleteTempoAnalysis(CancellationTokenSource cancellation)
    {
        if (ReferenceEquals(audioAnalysisCancellation, cancellation))
        {
            audioAnalysisCancellation = null;
            audioAnalysisTabId = null;
        }
        cancellation.Dispose();
        audioAnalysisInProgress = false;
        activeTempoAnalysisKind = TempoAnalysisKind.None;
        UpdateEditorAvailability();
    }

    private bool IsCurrentAudioAnalysisContext(DesktopChartTab? tab) =>
        tab != null && viewModel.ActiveTab?.Id == tab.Id && audioAnalysisTabId == tab.Id;

    private void UpdateTempoEditorFields(
        DesktopChartTab tab,
        double bpm,
        double offset,
        bool updateBpm)
    {
        var previous = suppressMetadataEditorControls;
        suppressMetadataEditorControls = true;
        try
        {
            metadataOffsetBox.Text = offset.ToString("0.###", CultureInfo.InvariantCulture);
            if (updateBpm) metadataBpmBox.Text = bpm.ToString("R", CultureInfo.InvariantCulture);
        }
        finally
        {
            suppressMetadataEditorControls = previous;
        }
        metadataEditorTabId = tab.Id;
        metadataEditorChangeSerial = tab.Session.ChangeSerial;
    }

    private void SetMetadataAudioStatus(string message, bool error = false)
    {
        metadataAudioAnalysisText.Text = message;
        metadataAudioAnalysisText.Foreground = error ? Brushes.IndianRed : MutedBrush;
        viewModel.SetStatus(message);
    }

    private static bool TryParseMetadataNumber(string? text, out double value)
    {
        var parsed = double.TryParse(text, NumberStyles.Float, CultureInfo.InvariantCulture, out value) ||
                     double.TryParse(text, NumberStyles.Float, CultureInfo.CurrentCulture, out value);
        return parsed && double.IsFinite(value);
    }

    private static void TryDeleteImportedAsset(string path)
    {
        try { if (File.Exists(path)) File.Delete(path); }
        catch { }
    }

    private void UpdateNoteInspector(DesktopChartTab? tab)
    {
        if (tab == null)
        {
            noteSelectionHint.Text = "选择一个 Note 进行编辑";
            ClearNotePropertyFields();
            return;
        }

        var state = WindowsNotePropertyCommand.ReadInspectorState(
            tab.Session,
            tab.HiddenGroups);
        noteSelectionHint.Text = state.Hint;
        if (state.SelectedCount == 0)
        {
            ClearNotePropertyFields();
            return;
        }
        if (state.Fields is not { } fields)
        {
            noteInspectorNoteId = null;
            noteInspectorFields = null;
            return;
        }

        // UpdateUi runs on every status change and, in a room, on each presence
        // poll. Only rewrite a box when the selected note changed or that
        // field's stored value changed since the last fill; otherwise the box
        // holds the user's unapplied input, which must not be reverted.
        var previous = noteInspectorNoteId == state.NoteId
            ? noteInspectorFields
            : null;
        RefillNoteField(noteBeatBox, fields.Beat, previous?.Beat);
        RefillNoteField(noteEndBeatBox, fields.EndBeat, previous?.EndBeat);
        RefillNoteField(noteLaneBox, fields.Lane, previous?.Lane);
        RefillNoteField(noteVolumeBox, fields.Volume, previous?.Volume);
        RefillNoteField(noteSoundBox, fields.Sound, previous?.Sound);
        RefillNoteField(noteGroupBox, fields.Group, previous?.Group);
        noteInspectorNoteId = state.NoteId;
        noteInspectorFields = fields;
    }

    private static void RefillNoteField(
        TextBox box,
        string value,
        string? previouslyFilledValue)
    {
        if (previouslyFilledValue == null ||
            !string.Equals(value, previouslyFilledValue, StringComparison.Ordinal))
            box.Text = value;
    }

    /// <summary>
    /// Forces the next note-inspector refresh to rewrite every field, e.g.
    /// after an explicit Apply so the boxes show the canonical stored values.
    /// </summary>
    private void ResetNoteInspectorFill()
    {
        noteInspectorNoteId = null;
        noteInspectorFields = null;
    }

