    {
        ResetNoteInspectorFill();
        noteBeatBox.Text = string.Empty;
        noteEndBeatBox.Text = string.Empty;
        noteLaneBox.Text = string.Empty;
        noteVolumeBox.Text = string.Empty;
        noteSoundBox.Text = string.Empty;
        noteGroupBox.Text = string.Empty;
    }

    private void RefreshGroupPanel()
    {
        var tab = viewModel.ActiveTab;
        groupListPanel.Children.Clear();
        if (tab == null)
        {
            currentPlacementGroupText.Text = "未分组（0）";
            groupManagerHint.Text = "选择 Note 后可批量设置分组";
            return;
        }

        var snapshot = WindowsGroupManagerCommand.ReadSnapshot(tab);
        SyncKeySoundHiddenGroups(tab);
        timeline.PlacementGroup = snapshot.ActivePlacementGroup;
        timeline.SetHiddenGroups(tab.HiddenGroups);
        currentPlacementGroupText.Text = snapshot.ActivePlacementGroup == 0
            ? "未分组（0）"
            : $"Group {snapshot.ActivePlacementGroup}";
        currentPlacementGroupText.Foreground = snapshot.ActivePlacementGroup == 0
            ? MutedBrush
            : TimelineSurface.GetGroupBrush(snapshot.ActivePlacementGroup);
        groupManagerHint.Text = snapshot.VisibleEditableSelectionCount == 0
            ? "选择 Note 后可批量设置分组"
            : AvaloniaLocalizationCatalog.Format("已选择 {0} 个可见 Note，可批量分配", snapshot.VisibleEditableSelectionCount);

        var dynamicTabIndex =
            WindowsInspectorParityPolicy.GroupDynamicFocusStartIndex;
        foreach (var row in snapshot.Rows)
        {
            var color = row.Group == 0
                ? new SolidColorBrush(Color.Parse("#FF70787C"))
                : TimelineSurface.GetGroupBrush(row.Group);
            var visible = new CheckBox
            {
                Content = "显示",
                IsChecked = row.IsVisible,
                Foreground = color,
                VerticalAlignment = VerticalAlignment.Center,
                Margin = new Thickness(0, 0, 7, 0)
            };
            AutomationProperties.SetName(visible, AvaloniaLocalizationCatalog.Format("Group {0} 显示", row.Group));
            AutomationProperties.SetAutomationId(
                visible,
                $"Inspector.Group.Row.{row.Group}.Visible");
            KeyboardNavigation.SetTabIndex(visible, dynamicTabIndex++);
            visible.IsCheckedChanged += (_, _) =>
                SetGroupVisibility(row.Group, visible.IsChecked == true);

            var description = new StackPanel
            {
                Children =
                {
                    new TextBlock
                    {
                        Text = row.Group == 0 ? "未分组" : $"Group {row.Group}",
                        Foreground = color,
                        FontWeight = FontWeight.SemiBold
                    },
                    new TextBlock
                    {
                        Text = $"{row.NoteCount} Notes · {row.DominantSound ?? "未指定 Key 音"}",
                        Foreground = MutedBrush,
                        FontSize = 10,
                        TextTrimming = TextTrimming.CharacterEllipsis,
                        MaxWidth = 125
                    }
                }
            };

            var use = PrimaryButton(row.IsCurrent ? "当前" : "使用", (_, _) =>
            {
                WindowsGroupManagerCommand.SetPlacementGroup(tab, row.Group);
                groupIdBox.Text = row.Group.ToString(CultureInfo.InvariantCulture);
                viewModel.SetStatus(row.Group == 0
                    ? "新放置的 Note 将不分组"
                    : AvaloniaLocalizationCatalog.Format("新放置的 Note 将进入 Group {0}", row.Group));
                RefreshGroupPanel();
            });
            ApplyWpfToolButtonStyle(use);
            use.Padding = new Thickness(7, 5);
            use.Margin = new Thickness(2, 0);
            use.IsEnabled = !row.IsCurrent;
            AutomationProperties.SetName(use, AvaloniaLocalizationCatalog.Format("Group {0} 使用", row.Group));
            AutomationProperties.SetAutomationId(
                use,
                $"Inspector.Group.Row.{row.Group}.Use");
            KeyboardNavigation.SetTabIndex(use, dynamicTabIndex++);

            var rowGrid = new Grid { ColumnDefinitions = new ColumnDefinitions("Auto,*,Auto,Auto") };
            rowGrid.Children.Add(visible);
            Grid.SetColumn(description, 1);
            rowGrid.Children.Add(description);
            Grid.SetColumn(use, 2);
            rowGrid.Children.Add(use);
            if (row.Group != 0)
            {
                var dissolve = PrimaryButton("解散", (_, _) => DissolveGroup(row.Group));
                ApplyWpfToolButtonStyle(dissolve);
                dissolve.Padding = new Thickness(7, 5);
                dissolve.Margin = new Thickness(3, 0, 0, 0);
                dissolve.IsEnabled = row.IsVisible && !tab.Session.IsReadOnly && tab.Session.CanEditNotes;
                AutomationProperties.SetName(dissolve, AvaloniaLocalizationCatalog.Format("Group {0} 解散", row.Group));
                AutomationProperties.SetAutomationId(
                    dissolve,
                    $"Inspector.Group.Row.{row.Group}.Dissolve");
                KeyboardNavigation.SetTabIndex(dissolve, dynamicTabIndex++);
                Grid.SetColumn(dissolve, 3);
                rowGrid.Children.Add(dissolve);
            }

            groupListPanel.Children.Add(new Border
            {
                Background = row.IsCurrent ? PanelBrush : Brushes.Transparent,
                BorderBrush = row.IsCurrent ? AccentBrush : StrokeBrush,
                BorderThickness = new Thickness(1),
                CornerRadius = new CornerRadius(4),
                Padding = new Thickness(7, 6),
                Child = rowGrid
            });
        }
    }

    private void CreateAndUseGroup()
    {
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        var group = WindowsGroupManagerCommand.CreateAndUse(tab);
        groupIdBox.Text = group.ToString(CultureInfo.InvariantCulture);
        viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("已创建并使用 Group {0}；当前选择未改变", group));
        RefreshGroupPanel();
    }

    private void SetCurrentPlacementGroup()
    {
        var tab = viewModel.ActiveTab;
        if (tab == null || !TryReadGroupId(out var group)) return;
        SetPlacementGroup(group);
    }

    private void SetPlacementGroup(int group)
    {
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        WindowsGroupManagerCommand.SetPlacementGroup(tab, group);
        groupIdBox.Text = group.ToString(CultureInfo.InvariantCulture);
        if (quickGroupLabel != null) quickGroupLabel.Text = AvaloniaLocalizationCatalog.Format("分组 {0}", group);
        viewModel.SetStatus(group == 0
            ? "新放置的 Note 将不分组"
            : AvaloniaLocalizationCatalog.Format("新放置的 Note 将进入 Group {0}", group));
        RefreshGroupPanel();
    }

    private void AssignSelectionToGroup()
    {
        if (!TryReadGroupId(out var group)) return;
        AssignSelectionToGroup(group);
    }

    private void AssignSelectionToGroup(int group)
    {
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        try
        {
            var result = WindowsGroupManagerCommand.AssignSelection(tab, group);
            viewModel.SetStatus(result.CandidateCount == 0
                ? "请先选择一个或多个可见、未锁定的 Note"
                : result.Applied
                    ? AvaloniaLocalizationCatalog.Format("已将 {0} 个 Note 分配到 Group {1}（单次撤销）", result.ChangedCount, group)
                    : AvaloniaLocalizationCatalog.Format("选中 Note 已属于 Group {0}", group));
            groupIdBox.Text = group.ToString(CultureInfo.InvariantCulture);
            UpdateSelectionUi();
        }
        catch (InvalidOperationException exception)
        {
            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("分配 Group 失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
        }
    }

    private void ClearSelectedGroups() => AssignSelectionToGroup(0);

    private void ShowAllGroups()
    {
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        WindowsGroupManagerCommand.ShowAll(tab);
        viewModel.SetStatus("全部 Note 分组已显示");
        RefreshGroupPanel();
        UpdateSelectionUi();
    }

    private void HideNonzeroGroups()
    {
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        var removed = WindowsGroupManagerCommand.HideNonzero(tab);
        viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("已隐藏非零组；从选择中移除 {0} 个 Note", removed));
        RefreshGroupPanel();
        UpdateSelectionUi();
    }

    private void SetGroupVisibility(int group, bool visible)
    {
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        var removed = WindowsGroupManagerCommand.SetGroupVisible(tab, group, visible);
        viewModel.SetStatus(visible
            ? AvaloniaLocalizationCatalog.Format("Group {0} 已显示", group)
            : AvaloniaLocalizationCatalog.Format("Group {0} 已隐藏；从选择中移除 {1} 个 Note", group, removed));
        RefreshGroupPanel();
        UpdateSelectionUi();
    }

    private void DissolveGroup(int group)
    {
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        try
        {
            var result = WindowsGroupManagerCommand.Dissolve(tab, group);
            viewModel.SetStatus(result.Applied
                ? AvaloniaLocalizationCatalog.Format("已解散 Group {0} 的 {1} 个未锁定 Note（单次撤销）", group, result.ChangedCount)
                : AvaloniaLocalizationCatalog.Format("Group {0} 没有可解散的未锁定 Note", group));
            UpdateSelectionUi();
        }
        catch (InvalidOperationException exception)
        {
            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("解散 Group 失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
        }
    }

    private bool TryReadGroupId(out int group)
    {
        try
        {
            group = WindowsGroupManagerCommand.ParseGroupId(groupIdBox.Text);
            return true;
        }
        catch (FormatException exception)
        {
            group = 0;
            viewModel.SetStatus(exception.Message);
            return false;
        }
    }

    private void UpdateSelectionUi()
    {
        timeline.PruneNonInteractiveNoteSelection();
        UpdateInspector();
        UpdateEditorAvailability();
        timeline.InvalidateVisual();
    }

    private void OpenExistingNoteSounds()
    {
        var tab = viewModel.ActiveTab;
        if (!TryGetEditableSelectedNote(tab, out _)) return;
        var workingRoot = Path.GetDirectoryName(Path.GetFullPath(tab!.WorkingPath));
        if (string.IsNullOrWhiteSpace(workingRoot)) return;
        var onlineRoomChart = IsBoundOnlineRoomChart(tab);
        var sourceRoot = onlineRoomChart || string.IsNullOrWhiteSpace(tab.SourcePath)
            ? null
            : Path.GetDirectoryName(Path.GetFullPath(tab.SourcePath));
        var candidates = CoalesceNoteSoundCandidates(
                ChartAssetImportService.EnumerateNoteSoundCandidates([workingRoot, sourceRoot]),
                workingRoot)
            .Where(candidate => !onlineRoomChart || IsListedFrozenRoomNoteSound(tab, candidate.FullPath))
            .ToArray();

        noteSoundPickerItems.Children.Clear();
        noteSoundPickerFocusableButtons.Clear();
        noteSoundPickerFocusableButtons.Add(noteSoundPickerClearButton);
        noteSoundPickerCountText.Text = AvaloniaLocalizationCatalog.Format("{0} 个", candidates.Length);
        noteSoundPickerEmptyText.Text = onlineRoomChart
            ? "房间资源中没有可用的 Key 音。"
            : "谱面目录中没有可用的音频文件。";
        noteSoundPickerEmptyText.IsVisible = candidates.Length == 0;
        noteSoundPickerScrollViewer.IsVisible = candidates.Length > 0;

        if (candidates.Length == 0)
            noteSoundPickerLastNavigation = "opened-empty";
        else
        {
            var repeatedNames = candidates
                .GroupBy(candidate => candidate.FileName, StringComparer.OrdinalIgnoreCase)
                .Where(group => group.Count() > 1)
                .Select(group => group.Key)
                .ToHashSet(StringComparer.OrdinalIgnoreCase);
            foreach (var candidate in candidates)
            {
                var displayName = repeatedNames.Contains(candidate.FileName)
                    ? $"{candidate.FileName}  —  {Path.GetFileName(Path.GetDirectoryName(candidate.FullPath))}"
                    : candidate.FileName;
                var item = new Button();
                ConfigureNoteSoundPickerItemButton(
                    item,
                    "♪",
                    displayName,
                    WindowsNoteSoundPickerParityPolicy.SoundGlyph);
                ToolTip.SetTip(item, candidate.FullPath);
                AutomationProperties.SetName(item, displayName);
                AutomationProperties.SetAutomationId(
                    item,
                    $"Inspector.Note.SoundPicker.Item.{noteSoundPickerFocusableButtons.Count - 1}");
                KeyboardNavigation.SetTabIndex(
                    item,
                    noteSoundPickerFocusableButtons.Count);
                var sourcePath = candidate.FullPath;
                item.Click += async (_, _) =>
                {
                    noteSoundExistingPopup.IsOpen = false;
                    await AssignSelectedNoteSoundAsync(tab, sourcePath, import: false);
                };
                noteSoundPickerItems.Children.Add(item);
                noteSoundPickerFocusableButtons.Add(item);
            }
        }

        noteSoundPickerEscapeRestoredFocus = false;
        noteSoundPickerLastRawKey = "none";
        noteSoundPickerLastResolvedKey = "none";
        noteSoundPickerLastInputRoute = "none";
        noteSoundExistingPopup.IsOpen = true;
    }

    private static void ConfigureNoteSoundPickerItemButton(
        Button button,
        string glyph,
        string label,
        string glyphColor)
    {
        button.Foreground = new SolidColorBrush(
            Color.Parse(WindowsNoteSoundPickerParityPolicy.Item));
        button.Background = Brushes.Transparent;
        button.BorderBrush = Brushes.Transparent;
        button.BorderThickness = new Thickness(1);
        button.Padding = new Thickness(
            WindowsNoteSoundPickerParityPolicy.ItemHorizontalPadding,
            WindowsNoteSoundPickerParityPolicy.ItemVerticalPadding);
        button.Margin = new Thickness(0, 1);
        button.HorizontalContentAlignment = HorizontalAlignment.Stretch;
        button.CornerRadius = new CornerRadius(3);
        button.Cursor = new Cursor(StandardCursorType.Hand);

        var text = new TextBlock
        {
            Text = label,
            Foreground = button.Foreground,
            TextTrimming = TextTrimming.CharacterEllipsis,
            VerticalAlignment = VerticalAlignment.Center
        };
        var row = new Grid
        {
            ColumnDefinitions = new ColumnDefinitions("22,*"),
            Children =
            {
                new TextBlock
                {
                    Text = glyph,
                    Foreground = new SolidColorBrush(Color.Parse(glyphColor)),
                    FontSize = glyph == "×" ? 15 : 12,
                    HorizontalAlignment = HorizontalAlignment.Center,
                    VerticalAlignment = VerticalAlignment.Center
                },
                text
            }
        };
        Grid.SetColumn(text, 1);
        button.Content = row;

        button.PointerEntered += (_, _) =>
        {
            button.Background = new SolidColorBrush(Color.Parse("#263034"));
            button.BorderBrush = new SolidColorBrush(Color.Parse("#4B6267"));
            button.Foreground = Brushes.White;
            text.Foreground = Brushes.White;
        };
        button.PointerExited += (_, _) =>
        {
            button.Background = Brushes.Transparent;
            button.BorderBrush = button.IsFocused
                ? new SolidColorBrush(Color.Parse("#71999C"))
                : Brushes.Transparent;
            button.Foreground = new SolidColorBrush(
                Color.Parse(WindowsNoteSoundPickerParityPolicy.Item));
            text.Foreground = button.Foreground;
        };
        button.GotFocus += (_, _) =>
            button.BorderBrush = new SolidColorBrush(Color.Parse("#71999C"));
        button.LostFocus += (_, _) =>
        {
            if (!button.IsPointerOver) button.BorderBrush = Brushes.Transparent;
        };
    }

    private void NoteSoundPicker_Opened()
    {
        var settings = displayScaleController.CurrentSettings.Normalize();
        var plan = AvaloniaPopupScaleController.Resolve(
            WindowsNoteSoundPickerParityPolicy.ItemFontSize,
            settings);
        if (TopLevel.GetTopLevel(noteSoundPickerSurface) is PopupRoot popupRoot)
            popupRoot.Transform = new ScaleTransform(plan.UiScale, plan.UiScale);

        noteSoundPickerTitleText.FontSize =
            WindowsNoteSoundPickerParityPolicy.HeaderFontSize * plan.FontScale;
        noteSoundPickerSubtitleText.FontSize =
            WindowsNoteSoundPickerParityPolicy.SubtitleFontSize * plan.FontScale;
        noteSoundPickerCountText.FontSize =
            WindowsNoteSoundPickerParityPolicy.CountFontSize * plan.FontScale;
        noteSoundPickerEmptyText.FontSize =
            WindowsNoteSoundPickerParityPolicy.ItemFontSize * plan.FontScale;
        foreach (var button in noteSoundPickerFocusableButtons)
            button.FontSize =
                WindowsNoteSoundPickerParityPolicy.ItemFontSize * plan.FontScale;

        noteSoundPickerScrollViewer.ScrollToHome();
        noteSoundPickerLastNavigation = "opened-clear";
        UpdateNoteSoundPickerAutomation();
        Dispatcher.UIThread.Post(
            () =>
            {
                noteSoundPickerClearButton.Focus();
                UpdateNoteSoundPickerAutomation();
            },
            DispatcherPriority.Input);
    }

    private void NoteSoundPicker_KeyDown(object? sender, KeyEventArgs eventArgs)
    {
        var key = WindowsEditorShortcutGesture.ResolveReportedKey(
            eventArgs.Key,
            eventArgs.PhysicalKey,
            eventArgs.KeySymbol,
            eventArgs.Key is Key.System or Key.ImeProcessed or Key.DeadCharProcessed
                ? WindowsShortcutPhysicalKeyState.TryResolvePressedKey()
                : null);
        noteSoundPickerLastRawKey = eventArgs.Key.ToString();
        noteSoundPickerLastResolvedKey = key.ToString();
        noteSoundPickerLastInputRoute = sender?.GetType().Name ?? "null";
        var focused = FocusManager?.GetFocusedElement() as Button;
        var focusedIndex = focused == null
            ? -1
            : noteSoundPickerFocusableButtons.IndexOf(focused);
        var navigation = WindowsNoteSoundPickerParityPolicy.ResolveNavigation(
            key,
            eventArgs.KeyModifiers,
            focusedIndex,
            noteSoundPickerFocusableButtons.Count);
        if (navigation.Action == WindowsNoteSoundPickerNavigationAction.None)
        {
            UpdateNoteSoundPickerAutomation();
            return;
        }

        eventArgs.Handled = true;
        if (navigation.Action == WindowsNoteSoundPickerNavigationAction.Focus)
        {
            var target = noteSoundPickerFocusableButtons[navigation.TargetIndex];
            target.Focus();
            target.BringIntoView();
            noteSoundPickerLastNavigation =
                $"{key}:{focusedIndex}->{navigation.TargetIndex}";
            UpdateNoteSoundPickerAutomation();
            return;
        }

        noteSoundPickerLastNavigation = "Escape:close-restore";
        noteSoundExistingPopup.IsOpen = false;
        Dispatcher.UIThread.Post(
            () =>
            {
                noteSoundExistingButton.Focus();
                noteSoundPickerEscapeRestoredFocus =
                    ReferenceEquals(FocusManager?.GetFocusedElement(), noteSoundExistingButton);
                UpdateNoteSoundPickerAutomation();
            },
            DispatcherPriority.Input);
    }

    private void UpdateNoteSoundPickerAutomation()
    {
        var focused = FocusManager?.GetFocusedElement() as Button;
        var focusedIndex = focused == null
            ? -1
            : noteSoundPickerFocusableButtons.IndexOf(focused);
        AutomationProperties.SetHelpText(
            noteSoundPickerSurface,
            $"Open={noteSoundExistingPopup.IsOpen}; " +
            $"FocusableCount={noteSoundPickerFocusableButtons.Count}; " +
            $"FocusedIndex={focusedIndex}; " +
            $"LastNavigation={noteSoundPickerLastNavigation}; " +
            $"LastRawKey={noteSoundPickerLastRawKey}; " +
            $"LastResolvedKey={noteSoundPickerLastResolvedKey}; " +
            $"LastInputRoute={noteSoundPickerLastInputRoute}; " +
            $"EscapeRestoredFocus={noteSoundPickerEscapeRestoredFocus}; " +
            $"Width={WindowsNoteSoundPickerParityPolicy.Width:R}; " +
            $"MaxHeight={WindowsNoteSoundPickerParityPolicy.MaxHeight:R}; " +
            $"ScrollMaxHeight={WindowsNoteSoundPickerParityPolicy.ScrollMaxHeight:R}");
        AutomationProperties.SetHelpText(
            noteSoundExistingButton,
            $"PickerOpen={noteSoundExistingPopup.IsOpen}; " +
            $"FocusableCount={noteSoundPickerFocusableButtons.Count}; " +
            $"CandidateCount={Math.Max(0, noteSoundPickerFocusableButtons.Count - 1)}; " +
            $"FocusedIndex={focusedIndex}; " +
            $"EscapeRestoredFocus={noteSoundPickerEscapeRestoredFocus}; " +
            $"LastNavigation={noteSoundPickerLastNavigation}; " +
            $"LastRawKey={noteSoundPickerLastRawKey}; " +
            $"LastResolvedKey={noteSoundPickerLastResolvedKey}; " +
            $"LastInputRoute={noteSoundPickerLastInputRoute}; " +
            $"Width={WindowsNoteSoundPickerParityPolicy.Width:R}; " +
            $"MaxHeight={WindowsNoteSoundPickerParityPolicy.MaxHeight:R}; " +
            $"ScrollMaxHeight={WindowsNoteSoundPickerParityPolicy.ScrollMaxHeight:R}; " +
            $"VerticalOffset={WindowsNoteSoundPickerParityPolicy.VerticalOffset:R}");
    }

    private async Task ImportSelectedNoteSoundAsync()
    {
        var tab = viewModel.ActiveTab;
        if (!TryGetEditableSelectedNote(tab, out _)) return;
        if (IsBoundOnlineRoomChart(tab!))
        {
            await ShowSettingsMessageAsync(
                "联机中不能新增本地 Key 音",
                ChartWorkspaceSafetyPolicy.OnlineNoteSoundImportBlockedMessage);
            return;
        }

        string? sourcePath;
        try
        {
            sourcePath = await PickLocalFileAsync(
                new FilePickerOpenOptions
                {
                    Title = "选择 Note Key 音",
                    AllowMultiple = false,
                    FileTypeFilter =
                    [
                        new FilePickerFileType("音频文件")
                        {
                            Patterns = ["*.wav", "*.ogg", "*.mp3", "*.flac", "*.m4a", "*.aac"],
                            MimeTypes = ["audio/*"]
                        }
                    ]
                },
                PickedFileRetention.Transient);
        }
        catch (Exception exception)
        {
            // Button handler boundary for the picker; the assignment below
            // reports its own failures.
            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("设置 Note Key 音失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
            return;
        }
        if (string.IsNullOrWhiteSpace(sourcePath)) return;
        await AssignSelectedNoteSoundAsync(tab!, Path.GetFullPath(sourcePath), import: true);
    }

    private async Task AssignSelectedNoteSoundAsync(
        DesktopChartTab tab,
        string? sourcePath,
        bool import)
    {
        ChartAssetImportResult? imported = null;
        try
        {
            var sound = sourcePath;
            if (import && !string.IsNullOrWhiteSpace(sourcePath))
            {
                imported = await Task.Run(() => ChartAssetImportService.ImportNoteSound(
                    tab.WorkingPath,
                    sourcePath,
                    tab.SourcePath));
                sound = imported.FileName;
            }
            else if (!string.IsNullOrWhiteSpace(sound))
            {
                sound = Path.GetFileName(sound);
            }

            if (viewModel.ActiveTab?.Id != tab.Id)
                throw new OperationCanceledException("选择 Key 音期间已切换谱面。");
            var soundPolicy = await CreateNoteSoundAssignmentPolicyAsync(tab, sound);
            if (viewModel.ActiveTab?.Id != tab.Id)
                throw new OperationCanceledException("校验 Key 音期间已切换谱面。");
            var result = WindowsNotePropertyCommand.AssignSound(
                tab.Session,
                sound,
                soundPolicy,
                tab.HiddenGroups);
            noteSoundBox.Text = result.Sound ?? string.Empty;
            viewModel.SetStatus(result.Sound == null
                ? "已清除当前 Note 的 Key 音引用；音频文件本身未删除"
                : import
                    ? AvaloniaLocalizationCatalog.Format("Key 音已复制为 {0}；保存谱面时写回曲库目录", result.Sound)
                    : IsBoundOnlineRoomChart(tab)
                        ? AvaloniaLocalizationCatalog.Format("已使用房间冻结资源 {0}；不会产生资源上传请求", result.Sound)
                        : AvaloniaLocalizationCatalog.Format("已使用谱面资源 {0}", result.Sound));
            UpdateSelectionUi();
        }
        catch (OperationCanceledException exception)
        {
            if (imported?.Created == true) TryDeleteImportedAsset(imported.DestinationPath);
            viewModel.SetStatus(exception.Message);
        }
        catch (Exception exception) when (
            exception is InvalidOperationException or ArgumentException or IOException or
            UnauthorizedAccessException or NotSupportedException)
        {
            if (imported?.Created == true) TryDeleteImportedAsset(imported.DestinationPath);
            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("设置 Note Key 音失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
        }
    }

    private bool TryGetEditableSelectedNote(DesktopChartTab? tab, out ChartNote? note)
    {
        note = null;
        if (tab == null) return false;
        var selected = tab.Session.Document.Notes
            .Where(candidate => tab.Session.Selection.Contains(candidate.Id) &&
                                !tab.HiddenGroups.Contains(candidate.Group))
            .ToArray();
        if (selected.Length != 1)
        {
            viewModel.SetStatus("请先只选择一个 Note。");
            return false;
        }
        if (tab.Session.IsReadOnly || !tab.Session.CanEditNotes ||
            (!tab.Session.AllowOwnerProtectedEdits && tab.Session.IsOwnerProtected(selected[0])))
        {
            viewModel.SetStatus("当前 Note 没有可用的编辑权限。");
            return false;
        }
        note = selected[0];
        return true;
    }

    private bool IsBoundOnlineRoomChart(DesktopChartTab tab) =>
        roomChartSyncRoomId != null && ReferenceEquals(roomChartSyncTab, tab);

    private bool IsListedFrozenRoomNoteSound(DesktopChartTab tab, string fullPath)
    {
        return IsBoundOnlineRoomChart(tab) &&
               ChartAssetImportService.IsSupportedNoteSoundFile(fullPath) &&
               roomChartFrozenResources?.ContainsListedFile(fullPath) == true;
    }

    private async Task<WindowsNoteSoundAssignmentPolicy> CreateNoteSoundAssignmentPolicyAsync(
        DesktopChartTab tab,
        string? sound)
    {
        if (!IsBoundOnlineRoomChart(tab))
            return new WindowsNoteSoundAssignmentPolicy(false, null);

        var requested = sound?.Trim();
        if (string.IsNullOrWhiteSpace(requested))
            return new WindowsNoteSoundAssignmentPolicy(true, _ => false);
        var safeName = Path.GetFileName(requested);
        if (string.IsNullOrWhiteSpace(safeName) ||
            !string.Equals(requested, safeName, StringComparison.Ordinal))
            return new WindowsNoteSoundAssignmentPolicy(true, _ => false);

        string fullPath;
        try
        {
            var root = Path.GetDirectoryName(Path.GetFullPath(tab.WorkingPath));
            if (string.IsNullOrWhiteSpace(root))
                return new WindowsNoteSoundAssignmentPolicy(true, _ => false);
            fullPath = Path.GetFullPath(Path.Combine(root, safeName));
        }
        catch (Exception exception) when (
            exception is ArgumentException or IOException or NotSupportedException)
        {
            return new WindowsNoteSoundAssignmentPolicy(true, _ => false);
        }

        var registry = roomChartFrozenResources;
        var verified = registry != null &&
                       await registry.VerifyAsync(fullPath).ConfigureAwait(true);
        return new WindowsNoteSoundAssignmentPolicy(
            true,
            candidate => verified && ReferenceEquals(roomChartFrozenResources, registry) &&
                         IsBoundOnlineRoomChart(tab) && PathsEqual(candidate, fullPath));
    }

    private static IReadOnlyList<ChartNoteSoundCandidate> CoalesceNoteSoundCandidates(
        IReadOnlyList<ChartNoteSoundCandidate> candidates,
        string workingRoot)
    {
        var result = new List<ChartNoteSoundCandidate>();
        foreach (var group in candidates.GroupBy(
                     candidate => candidate.FileName,
                     StringComparer.OrdinalIgnoreCase))
        {
            var working = group.FirstOrDefault(candidate => string.Equals(
                Path.GetDirectoryName(candidate.FullPath)?.TrimEnd(Path.DirectorySeparatorChar),
                workingRoot.TrimEnd(Path.DirectorySeparatorChar),
                StringComparison.OrdinalIgnoreCase));
            if (working == null)
            {
                result.AddRange(group);
                continue;
            }
            result.Add(working);
            result.AddRange(group.Where(candidate =>
                !ReferenceEquals(candidate, working) &&
                !NoteSoundCandidateFilesEqual(candidate.FullPath, working.FullPath)));
        }
        return result
            .OrderBy(candidate => candidate.FileName, StringComparer.OrdinalIgnoreCase)
            .ThenBy(candidate => candidate.FullPath, StringComparer.OrdinalIgnoreCase)
            .ToArray();
    }

    private static bool NoteSoundCandidateFilesEqual(string left, string right)
    {
        try
        {
            var leftInfo = new FileInfo(left);
            var rightInfo = new FileInfo(right);
            if (leftInfo.Length != rightInfo.Length) return false;
            using var leftStream = File.OpenRead(left);
            using var rightStream = File.OpenRead(right);
            return System.Security.Cryptography.SHA256.HashData(leftStream).AsSpan()
                .SequenceEqual(System.Security.Cryptography.SHA256.HashData(rightStream));
        }
        catch (Exception exception) when (exception is IOException or UnauthorizedAccessException)
        {
            return false;
        }
    }

    private async Task ApplyNotePropertiesAsync()
    {
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        var session = tab.Session;
        try
        {
            var sound = noteSoundBox.Text ?? string.Empty;
            var soundPolicy = await CreateNoteSoundAssignmentPolicyAsync(tab, sound);
            if (viewModel.ActiveTab?.Id != tab.Id)
                throw new InvalidOperationException("校验 Key 音期间已切换谱面。");
            var result = WindowsNotePropertyCommand.Apply(
                session,
                new WindowsNotePropertyFields(
                    noteBeatBox.Text ?? string.Empty,
                    noteEndBeatBox.Text ?? string.Empty,
                    noteLaneBox.Text ?? string.Empty,
                    noteVolumeBox.Text ?? string.Empty,
                    sound,
                    noteGroupBox.Text ?? string.Empty),
                soundPolicy,
                hiddenGroups: tab.HiddenGroups);
            var lane = result.IsDraft
                ? $"D:{result.Column}"
                : result.Column.ToString(CultureInfo.InvariantCulture);
            // Explicit apply: show the canonical stored values in every box.
            ResetNoteInspectorFill();
            viewModel.SetStatus(
                AvaloniaLocalizationCatalog.Format("已应用 Note 属性 · Beat {0} · 轨道 {1}{2}", result.Beat, lane, (result.EndBeat.HasValue ? $" · End {result.EndBeat.Value}" : " · Tap")));
            UpdateSelectionUi();
        }
        catch (Exception exception)
        {
            // Button handler: beyond the command's own validation errors, the
            // edit and the room sound-policy lookup can fault on odd input.
            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("应用 Note 属性失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
        }
    }

    private HashSet<Guid> SelectedTimingListIds() =>
        timingList.SelectedItems?.OfType<TimingListItem>().Select(item => item.Id).ToHashSet() ?? [];

    private void SyncTimingListSelection(
        IReadOnlyCollection<Guid> timingIds,
        Guid? primaryId = null)
    {
        var ids = timingIds.ToHashSet();
        var items = timingList.Items.OfType<TimingListItem>().ToArray();
        var primary = primaryId.HasValue
            ? items.FirstOrDefault(item => item.Id == primaryId.Value)
            : items.FirstOrDefault(item => ids.Contains(item.Id));
        var previous = suppressTimingSelection;
        suppressTimingSelection = true;
        try
        {
            timingList.SelectedItems?.Clear();
            timingList.SelectedItem = primary;
            if (timingList.SelectedItems != null)
            {
                foreach (var item in items.Where(item => ids.Contains(item.Id)))
                    if (!timingList.SelectedItems.Contains(item))
                        timingList.SelectedItems.Add(item);
            }
        }
        finally
        {
            suppressTimingSelection = previous;
        }

        if (primary != null) PopulateTimingFields(primary.Id);
    }

