        RefreshOwnerLockUi();
    }

    private void RefreshOwnerLockUi()
    {
        if (ownerLockButton == null || quickOwnerLockButton == null) return;
        var tab = viewModel.ActiveTab;
        var session = tab?.Session;
        var inOnlineEditor = tab != null &&
                             ReferenceEquals(tab, roomChartSyncTab) &&
                             roomChartSyncCoordinator != null &&
                             roomChartSyncRoomId != null;
        ownerLockButton.IsVisible = inOnlineEditor;
        quickOwnerLockButton.IsVisible = inOnlineEditor;
        if (!inOnlineEditor || session == null)
        {
            ownerLockButton.IsEnabled = false;
            ownerLockButton.Content = "锁定选区";
            quickOwnerLockButton.IsEnabled = false;
            if (quickOwnerLockLabel != null) quickOwnerLockLabel.Text = "锁定选区";
            AutomationProperties.SetName(quickOwnerLockButton, "锁定选区");
            return;
        }

        var ranges = SelectedOwnerLockRanges(
            tab ?? throw new InvalidOperationException("The online editor tab is unavailable."));
        var selectionIsLocked = OwnerLockSelectionPlanner.IsFullyCovered(
            ranges,
            session.OwnerProtectedRegions.Select(region =>
                new OwnerLockSelectionRange(region.StartBeat, region.EndBeat)));
        ownerLockButton.IsEnabled = session.AllowOwnerProtectedEdits && ranges.Count > 0;
        quickOwnerLockButton.IsEnabled = ownerLockButton.IsEnabled;
        var label = !session.AllowOwnerProtectedEdits
            ? "仅房主可锁定"
            : selectionIsLocked
                ? "解除选区"
                : "锁定选区";
        ownerLockButton.Content = label;
        if (quickOwnerLockLabel != null) quickOwnerLockLabel.Text = label;
        AutomationProperties.SetName(quickOwnerLockButton, label);
    }

    private async Task ToggleOwnerLockSelectionAsync()
    {
        var account = onlineAccountHost?.Session;
        var tab = roomChartSyncTab;
        var roomId = roomChartSyncRoomId;
        if (account == null || tab == null || roomId == null ||
            !ReferenceEquals(viewModel.ActiveTab, tab) ||
            !tab.Session.AllowOwnerProtectedEdits)
            return;
        var ranges = SelectedOwnerLockRanges(tab);
        if (ranges.Count == 0) return;

        if (ownerLockButton != null) ownerLockButton.IsEnabled = false;
        if (quickOwnerLockButton != null) quickOwnerLockButton.IsEnabled = false;
        try
        {
            using var timeout = new CancellationTokenSource(TimeSpan.FromSeconds(30));
            var result = await account.ToggleRoomChartLockSelectionAsync(
                roomId.Value,
                ranges.Select(range => new OnlineChartLockRange(
                    new OnlineSyncBeat(
                        range.StartBeat.Bar,
                        range.StartBeat.Numerator,
                        range.StartBeat.Denominator),
                    new OnlineSyncBeat(
                        range.EndBeat.Bar,
                        range.EndBeat.Numerator,
                        range.EndBeat.Denominator)))
                    .ToArray(),
                timeout.Token);
            if (roomChartSyncRoomId != roomId || !ReferenceEquals(roomChartSyncTab, tab)) return;

            applyingRemoteChartSync = true;
            try
            {
                tab.Session.ReplaceOwnerProtectedRegions(
                    OnlineChartSyncCodec.ToOwnerRegions(result.Locks));
            }
            finally
            {
                applyingRemoteChartSync = false;
            }
            viewModel.SetStatus(result.IsUnlock
                ? "房主已解除当前连续选区；选区外两侧的锁定保持不变"
                : "已锁定当前选区；单对象保持精确行 / LN 区间，多选保持一个连续区间");
            timeline.InvalidateVisual();
        }
        catch (Exception exception) when (
            exception is OnlineApiException or HttpRequestException or System.Net.WebException or OperationCanceledException or
                JsonException or InvalidOperationException)
        {
            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("选区锁同步失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
        }
        finally
        {
            RefreshOwnerLockUi();
        }
    }

    private IReadOnlyList<OwnerLockSelectionRange> SelectedOwnerLockRanges(DesktopChartTab tab)
    {
        var session = tab.Session;
        var selectedTimingIds = timeline.SelectedTimingIds.ToHashSet();
        var notes = session.Document.Notes
            .Where(note => session.Selection.Contains(note.Id) && !tab.HiddenGroups.Contains(note.Group))
            .ToArray();
        var timing = session.Document.Timing
            .Where(item => selectedTimingIds.Contains(item.Id))
            .ToArray();
        if (notes.Length == 0 && timing.Length == 0) return [];

        var ranges = notes.Select(note => new OwnerLockSelectionRange(
                note.Beat,
                note.EndBeat is { } end && end.CompareTo(note.Beat) > 0
                    ? end
                    : OwnerLockSelectionPlanner.BuildPointRange(
                        note.Beat,
                        session.SnapDivision).EndBeat))
            .Concat(timing.Select(item => new OwnerLockSelectionRange(
                item.Beat,
                OwnerLockSelectionPlanner.BuildPointRange(
                    item.Beat,
                    session.SnapDivision).EndBeat)));
        return OwnerLockSelectionPlanner.BuildSelectedObjectRanges(ranges);
    }

    private void CopyMixedSelection()
    {
        if (TryExecuteTrackCommand("Copy")) return;
        if (viewModel.ActiveTab == null) return;
        try
        {
            _ = viewModel.CopyMixedSelection(timeline.SelectedTimingIds);
            UpdateEditorAvailability();
        }
        catch (InvalidOperationException exception)
        {
            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("复制失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
        }
    }

    private void CutMixedSelection()
    {
        if (TryExecuteTrackCommand("Cut")) return;
        if (viewModel.ActiveTab == null) return;
        try
        {
            var clipboard = viewModel.CopyMixedSelection(timeline.SelectedTimingIds);
            if (clipboard.IsEmpty) return;
            var result = viewModel.DeleteMixedSelection(timeline.SelectedTimingIds);
            if (!result.Applied) return;
            timeline.SetSelectedTiming(null);
            RefreshTimingList([], force: true);
            UpdateSelectionUi();
            viewModel.SetStatus(
                AvaloniaLocalizationCatalog.Format("已剪切 {0:N0} 个 Note、{1:N0} 个 Effect", clipboard.NoteCount, clipboard.EffectCount));
        }
        catch (InvalidOperationException exception)
        {
            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("剪切失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
        }
    }

    private void SelectAllVisibleObjects()
    {
        if (TryExecuteTrackCommand("SelectAll")) return;
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        tab.Session.Selection.Clear();
        tab.Session.Selection.UnionWith(tab.Session.Document.Notes
            .Where(note => !tab.HiddenGroups.Contains(note.Group) &&
                           (timeline.ProEditorEnabled || !note.IsDraft))
            .Select(note => note.Id));
        var timingIds = tab.Session.Document.Timing
            .Where(timing => timing.Effect.HasValue)
            .Select(timing => timing.Id)
            .ToArray();
        timeline.SetSelectedTimings(timingIds);
        SyncTimingListSelection(timingIds);
        viewModel.SetStatus(
            AvaloniaLocalizationCatalog.Format("已全选 {0:N0} 个可见 Note、{1:N0} 个 Effect", tab.Session.Selection.Count, timingIds.Length));
        UpdateSelectionUi();
    }

    private void ExecuteHistoryCommand(bool redo)
    {
        if (TryExecuteTrackCommand(redo ? "Redo" : "Undo")) return;
        var tab = viewModel.ActiveTab;
        if (tab == null)
        {
            viewModel.SetStatus(redo ? "没有可重做操作" : "没有可撤销操作");
            return;
        }

        var outcome = WindowsEditorHistoryCommand.Execute(
            tab.Session,
            IsBoundOnlineRoomChart(tab),
            redo);
        viewModel.SetStatus(outcome.Status);
    }

    private void MirrorVisibleSelection()
    {
        if (TryExecuteTrackCommand("Mirror")) return;
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        // Match WPF: a mixed source selection mirrors only visible, unlocked
        // Notes. Destination-lock validation remains atomic in the shared
        // service; one locked source must not cancel unrelated unlocked Notes.
        var ids = WindowsGroupManagerCommand.VisibleEditableSelectionIds(tab);
        if (ids.Count == 0)
        {
            viewModel.SetStatus("请先选择一个或多个可见 Note");
            return;
        }
        try
        {
            var changed = NoteMirrorEditingService.MirrorSelection(tab.Session, ids);
            viewModel.SetStatus(changed > 0
                ? AvaloniaLocalizationCatalog.Format("已水平镜像 {0} 个可见 Note（单次撤销）", changed)
                : "选中的 Note 位于镜像轴上，无需移动");
            UpdateSelectionUi();
        }
        catch (InvalidOperationException exception)
        {
            viewModel.SetStatus(exception.Message);
            timeline.InvalidateVisual();
        }
    }

    private void RandomizeVisibleSelection(bool perBeat)
    {
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        var ids = WindowsGroupManagerCommand.VisibleEditableSelectionIds(tab);
        if (ids.Count == 0)
        {
            viewModel.SetStatus("请先选择一个或多个可见 Note");
            return;
        }
        try
        {
            var mode = perBeat
                ? NoteLaneRandomizationMode.PerBeatPermutation
                : NoteLaneRandomizationMode.FixedPermutation;
            var result = NoteLaneRandomizationService.RandomizeSelection(
                tab.Session,
                ids,
                mode);
            viewModel.SetStatus(result.ChangedCount > 0
                ? perBeat
                    ? AvaloniaLocalizationCatalog.Format("已完全随机 {0} 个 Note（{1} 排分别打乱 · 单次撤销）", result.ChangedCount, result.RowCount)
                    : AvaloniaLocalizationCatalog.Format("已随机排列 {0} 个 Note（固定轨道映射 · 单次撤销）", result.ChangedCount)
                : result.CollisionBlocked
                    ? "没有找到不与未选中 Note / LN 重叠的安全排列，谱面未修改"
                : result.SelectedCount == 0
                    ? "选区中没有可随机的正式轨道 Note"
                    : "当前轨道数无法产生不同的随机排列");
            UpdateSelectionUi();
        }
        catch (InvalidOperationException exception)
        {
            viewModel.SetStatus(exception.Message);
            timeline.InvalidateVisual();
        }
    }

    private void BeginQuickEffectEdit()
    {
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        if (tab.Session.IsReadOnly || !tab.Session.CanEditTiming)
        {
            viewModel.SetStatus("当前没有编辑 Timing / Effect 的权限");
            return;
        }
        if (!inspectorPanel.IsVisible)
        {
            inspectorPanel.IsVisible = true;
            editorWorkbench.ColumnDefinitions[4].Width = new GridLength(350);
            inspectorToggleButton.Content = "−";
            ToolTip.SetTip(inspectorToggleButton, "收起右侧面板");
        }
        editorInspectorTabs.SelectedItem = timingInspectorTab;
        timeline.SetSelectedTiming(null);
        SyncTimingListSelection([]);
        var rememberedEffect = timingEffectMemory.Current;
        timingBeatBox.Text = BeatPosition.FromDouble(timeline.CurrentBeat)
            .Snap(tab.Session.SnapDivision)
            .ToString();
        timingBpmBox.Text = string.Empty;
        timingDelayBox.Text = "0";
        // The box is bound to option records, so select the matching record;
        // assigning the enum name string never matched and left the previous
        // selection (often "None") in place.
        var rememberedEffectValue = rememberedEffect.Effect.ToString();
        timingEffectBox.SelectedItem =
            WindowsInspectorParityPolicy.Wpf110TimingEffectOptions.FirstOrDefault(
                option => option.Value.Equals(
                    rememberedEffectValue,
                    StringComparison.Ordinal)) ??
            timingEffectBox.SelectedItem;
        timingValueBox.Text = rememberedEffect.ValueText;
        timingCustomFieldBox.Text = rememberedEffect.CustomFieldName;
        timingValueBox.Focus();
        timingValueBox.SelectAll();
        viewModel.SetStatus(
            AvaloniaLocalizationCatalog.Format("添加 {0} Effect · Beat {1} · 继承值 {2}", EffectNumberText.CanonicalName(
                rememberedEffect.Effect,
                rememberedEffect.CustomFieldName), timingBeatBox.Text, rememberedEffect.ValueText));
    }

