    private void DeleteTimingBatch(IEnumerable<Guid> timingIds)
    {
        if (viewModel.ActiveTab == null) return;
        try
        {
            var result = viewModel.DeleteTimings(timingIds);
            if (!result.Applied) return;
            var remaining = timeline.SelectedTimingIds
                .Except(result.DeletedTimingIds)
                .ToArray();
            timeline.SetSelectedTimings(remaining);
            RefreshTimingList(remaining, force: true);
            UpdateSelectionUi();
