    private void RefreshTimingList(Guid? selectTimingId = null, bool force = false) =>
        RefreshTimingList(selectTimingId.HasValue ? [selectTimingId.Value] : null, force);

    private void RefreshTimingList(IEnumerable<Guid>? selectTimingIds, bool force = false)
    {
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        var selectedIds = selectTimingIds?.ToHashSet() ?? timeline.SelectedTimingIds.ToHashSet();
        if (!force && timingListTabId == tab.Id && timingListChangeSerial == tab.Session.ChangeSerial)
            return;

        var items = tab.Session.Document.Timing
            .Select((timing, index) => new { Timing = timing, Index = index })
            .OrderBy(entry => entry.Timing.Beat)
            .ThenBy(entry => entry.Timing.Bpm.HasValue ? 0 : 1)
            .ThenBy(entry => entry.Index)
            .Select(entry => CreateTimingListItem(entry.Timing))
            .ToArray();
        suppressTimingSelection = true;
        try
        {
            timingList.ItemsSource = items;
            AutomationProperties.SetName(timingList, AvaloniaLocalizationCatalog.Format("Timing 列表 · {0:N0} 项", items.Length));
            SyncTimingListSelection(
                selectedIds,
                items.FirstOrDefault(item => selectedIds.Contains(item.Id))?.Id);
        }
        finally
        {
            suppressTimingSelection = false;
        }
        timingListTabId = tab.Id;
        timingListChangeSerial = tab.Session.ChangeSerial;
        timeline.SetSelectedTimings(
            items.Where(item => selectedIds.Contains(item.Id)).Select(item => item.Id),
            timingList.SelectedItem is TimingListItem primary ? primary.Id : null);
        if (timingList.SelectedItem is TimingListItem selected) PopulateTimingFields(selected.Id, force);
    }

    private static TimingListItem CreateTimingListItem(TimingEvent timing)
    {
        var delay = timing.Delay.ToString("0.###", CultureInfo.InvariantCulture);
        var main = timing.Bpm.HasValue
            ? $"{timing.Bpm.Value.ToString("0.###", CultureInfo.InvariantCulture)} BPM  ·  {delay} ms"
            : $"Delay {delay} ms";
        var effect = "—";
        if (timing.Effect.HasValue)
        {
            var name = EffectNumberText.CanonicalName(
                timing.Effect.Value,
                timing.EffectFieldName);
            var value = string.IsNullOrWhiteSpace(timing.EffectValueText)
                ? timing.EffectValue.ToString("R", CultureInfo.InvariantCulture)
                : timing.EffectValueText;
            effect = $"{name}  {value}";
        }
        return new TimingListItem(timing.Id, timing.Beat.ToString(), main, effect);
    }

    private void MarkTimingEditorDirty()
    {
        if (!suppressTimingEditorControls) timingEditorDirty = true;
    }

    private void PopulateTimingFields(Guid timingId, bool force = false)
    {
        if (!WindowsInspectorParityPolicy.ShouldPopulateTimingFields(
                force,
                timingEditorDirty,
                timingEditorTimingId,
                timingId))
            return;
        var timing = viewModel.ActiveTab?.Session.Document.Timing
            .FirstOrDefault(candidate => candidate.Id == timingId);
        if (timing == null) return;
        suppressTimingEditorControls = true;
        try
        {
            timingBeatBox.Text = timing.Beat.ToString();
            timingBpmBox.Text = timing.Bpm?.ToString("0.###", System.Globalization.CultureInfo.InvariantCulture) ?? string.Empty;
            timingDelayBox.Text = timing.Delay.ToString("0.###", System.Globalization.CultureInfo.InvariantCulture);
            var effectValue = timing.Effect?.ToString() ?? "None";
            timingEffectBox.SelectedItem =
                WindowsInspectorParityPolicy.Wpf110TimingEffectOptions.First(
                    option => option.Value.Equals(
                        effectValue,
                        StringComparison.Ordinal));
            timingValueBox.Text = string.IsNullOrWhiteSpace(timing.EffectValueText)
                ? timing.EffectValue.ToString("R", System.Globalization.CultureInfo.InvariantCulture)
                : timing.EffectValueText;
            timingCustomFieldBox.Text = timing.EffectFieldName;
        }
        finally
        {
            suppressTimingEditorControls = false;
        }
        timingEditorTimingId = timingId;
        timingEditorDirty = false;
    }

    private CompleteTimingEdit ReadTimingFields()
    {
        if (!BeatPosition.TryParse(timingBeatBox.Text, out var beat) || beat.CompareTo(BeatPosition.Zero) < 0)
            throw new FormatException("Beat 格式应为 1:0/1 或十进制数，且不能为负数。");
        if (!TryTimingNumber(timingDelayBox.Text, out var delay) || !double.IsFinite(delay))
            throw new FormatException("Delay 必须是有限毫秒数。");

        double? bpm = null;
        if (!string.IsNullOrWhiteSpace(timingBpmBox.Text))
        {
            if (!TryTimingNumber(timingBpmBox.Text, out var parsedBpm))
                throw new FormatException("BPM 必须是有效数字。");
            bpm = parsedBpm;
        }

        TimingEffectKind? effect = null;
        var effectName =
            (timingEffectBox.SelectedItem as WindowsTimingEffectOption)?.Value;
        if (!string.Equals(effectName, "None", StringComparison.Ordinal) &&
            Enum.TryParse<TimingEffectKind>(effectName, out var parsedEffect))
            effect = parsedEffect;
        return new CompleteTimingEdit(
            beat,
            bpm,
            delay,
            effect,
            timingValueBox.Text ?? string.Empty,
            timingCustomFieldBox.Text ?? string.Empty);
    }

    private static bool TryTimingNumber(string? text, out double value) =>
        double.TryParse(
            text,
            System.Globalization.NumberStyles.Float,
            System.Globalization.CultureInfo.InvariantCulture,
            out value) ||
        double.TryParse(
            text,
            System.Globalization.NumberStyles.Float,
            System.Globalization.CultureInfo.CurrentCulture,
            out value);

    private void AddTimingFromFields()
    {
        var tab = viewModel.ActiveTab;
        if (tab == null) return;
        timingBeatBox.Text = BeatPosition.FromDouble(timeline.CurrentBeat).Snap(tab.Session.SnapDivision).ToString();
        try
        {
            var edit = ReadTimingFields();
            var id = viewModel.AddTiming(edit);
            if (id != Guid.Empty)
            {
                timingEffectMemory.Remember(edit);
                RefreshTimingList(id, force: true);
                UpdateSelectionUi();
            }
        }
        catch (Exception exception) when (exception is FormatException or ArgumentException or InvalidOperationException)
        {
            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("新增 Timing / Effect 失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
        }
    }

    private void ApplyTimingFromFields()
    {
        if (timingList.SelectedItem is not TimingListItem selected)
        {
            viewModel.SetStatus("请先选择一个 Timing / Effect 条目");
            return;
        }
        try
        {
            var edit = ReadTimingFields();
            if (viewModel.UpdateTiming(selected.Id, edit))
            {
                timingEffectMemory.Remember(edit);
                RefreshTimingList(selected.Id, force: true);
            }
        }
        catch (Exception exception) when (exception is FormatException or ArgumentException or InvalidOperationException)
        {
            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("应用 Timing / Effect 失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
        }
    }

    private void DeleteSelectedTiming()
    {
        var ids = SelectedTimingListIds();
        if (ids.Count == 0 && timingList.SelectedItem is TimingListItem selected)
            ids.Add(selected.Id);
        DeleteTimingBatch(ids);
    }

    private void JumpToSelectedTiming()
    {
        if (timingList.SelectedItem is not TimingListItem selected) return;
        var timing = viewModel.ActiveTab?.Session.Document.Timing
            .FirstOrDefault(candidate => candidate.Id == selected.Id);
        if (timing == null) return;
        timeline.SetCurrentBeat(timing.Beat.Value);
        viewModel.UpdateCurrentBeat(timing.Beat.Value);
        viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("已跳转到 {0}", timing.Beat));
    }

    private void RebuildTabs()
    {
        tabBar.Children.Clear();
        onlineLatencyVisuals.Clear();
        foreach (var tab in viewModel.Tabs)
        {
            var isLiveRoomTab = ReferenceEquals(tab, roomChartSyncTab);
            var isRetainedRoomTab = retainedOnlineRoomTabIds.Contains(tab.Id);
            var isObserverRoomTab = isLiveRoomTab &&
                                    onlineAccountHost?.Session.CurrentMemberRole.Equals(
                                        "viewer",
                                        StringComparison.OrdinalIgnoreCase) == true;
            var roomStateSuffix = isLiveRoomTab
                ? isObserverRoomTab ? " · 观看" : " · 联机"
                : isRetainedRoomTab
                    ? " · 房间留存"
                    : string.Empty;
            var presentation = WindowsTitleBarParityPolicy.ResolveDocumentTab(
                tab.Format,
                tab.DisplayTitle,
                tab.Session.IsDirty,
                ReferenceEquals(tab, viewModel.ActiveTab),
                isLiveRoomTab,
                isRetainedRoomTab,
                isObserverRoomTab,
                isLiveRoomTab
                    ? onlineAccountHost?.Session.CurrentRoom?.RoomNumber
                    : null);
            var formatBadge = new AutomationBorder
            {
                Margin = WindowsTitleBarParityPolicy.FormatBadgeMargin,
                Padding = WindowsTitleBarParityPolicy.FormatBadgePadding,
                CornerRadius = new CornerRadius(2),
                Background = new SolidColorBrush(presentation.FormatBackground),
                BorderBrush = new SolidColorBrush(presentation.FormatBorder),
                BorderThickness = new Thickness(1),
                Child = new TextBlock
                {
                    Text = presentation.FormatBadge,
                    FontSize = 8,
                    FontWeight = FontWeight.Bold,
                    Foreground = new SolidColorBrush(presentation.FormatForeground),
                    VerticalAlignment = VerticalAlignment.Center
                }
            };
            AutomationProperties.SetAutomationId(formatBadge, "Editor.ChartTab.FormatBadge");
            AutomationProperties.SetName(formatBadge, presentation.FormatBadge);

            AutomationBorder? liveBadge = null;
            if (presentation.LiveBadgeText != null)
            {
                var latency = WindowsTitleBarParityPolicy.ResolveOnlineLatency(
                    onlineRoundTripLatencyMs);
                var latencyLabel = new TextBlock
                {
                    Text = latency.Text,
                    FontSize = 8,
                    FontFamily = new FontFamily("Cascadia Mono,Consolas"),
                    Foreground = new SolidColorBrush(latency.Foreground),
                    VerticalAlignment = VerticalAlignment.Center,
                    Margin = new Thickness(5, 0, 0, 0)
                };
                AutomationProperties.SetAutomationId(
                    latencyLabel,
                    "Editor.ChartTab.LiveLatency");
                AutomationProperties.SetName(latencyLabel, latency.Text);
                liveBadge = new AutomationBorder
                {
                    Margin = WindowsTitleBarParityPolicy.LiveBadgeMargin,
                    Padding = WindowsTitleBarParityPolicy.LiveBadgePadding,
                    CornerRadius = new CornerRadius(2),
                    Background = new SolidColorBrush(Color.Parse("#314B4E")),
                    BorderBrush = new SolidColorBrush(Color.Parse("#65979A")),
                    BorderThickness = new Thickness(1),
                    Child = new StackPanel
                    {
                        Orientation = Orientation.Horizontal,
                        Children =
                        {
                            new TextBlock
                            {
                                Text = presentation.LiveBadgeText,
                                FontSize = 8,
                                FontWeight = FontWeight.Bold,
                                Foreground = new SolidColorBrush(Color.Parse("#DCEFEF")),
                                VerticalAlignment = VerticalAlignment.Center
                            },
                            new TextBlock
                            {
                                Text = presentation.LiveRoomNumberText,
                                FontSize = 8,
                                FontFamily = new FontFamily("Cascadia Mono,Consolas"),
                                FontWeight = FontWeight.SemiBold,
                                Foreground = new SolidColorBrush(Color.Parse("#A5CDCF")),
                                VerticalAlignment = VerticalAlignment.Center
