                AutomationProperties.SetName(
                    liveBadge,
                    $"{presentation.LiveBadgeText}{presentation.LiveRoomNumberText} {latency.Text}");
                AutomationProperties.SetHelpText(
                    liveBadge,
                    $"{presentation.LiveDescription}；{latency.ToolTip}");
