                AvaloniaLocalizationCatalog.Format("谱面标签 {0} · {1}{2}", tab.DisplayTitle, Path.GetFileName(tab.SourcePath), roomStateSuffix));
            AutomationProperties.SetHelpText(
                button,
                AvaloniaLocalizationCatalog.Format("{0}\n未保存：{1}\n联机状态：{2}", Path.GetFullPath(tab.SourcePath), (tab.Session.IsDirty ? AvaloniaLocalizationCatalog.Text("是") : AvaloniaLocalizationCatalog.Text("否")), presentation.RoomStateDescription));
            button.Click += (_, _) =>
            {
                // Switching repopulates the metadata panel for the new tab and
                // used to drop the current tab's unapplied input silently.
                if (viewModel.ActiveTab is { } currentTab &&
                    !ReferenceEquals(currentTab, tab) &&
                    !TryApplyPendingMetadataEditor(
                        currentTab,
                        enforceCommunityRules: false))
                    return;
                viewModel.Activate(tab.Id);
                ShowEditorSurface();
            };
            var close = new Button
            {
                Content = new AvaloniaPath
                {
                    Width = 13,
                    Height = 13,
                    Data = Geometry.Parse("M2,2 L11,11 M11,2 L2,11"),
                    Stroke = new SolidColorBrush(Color.Parse("#D8DEDF")),
                    StrokeThickness = 1.6,
                    StrokeLineCap = PenLineCap.Round,
                    Stretch = Stretch.None,
                    HorizontalAlignment = HorizontalAlignment.Center,
                    VerticalAlignment = VerticalAlignment.Center
                },
                Width = WindowsTitleBarParityPolicy.DocumentTabCloseWidth,
                Height = 24,
                Padding = new Thickness(5),
                HorizontalContentAlignment = HorizontalAlignment.Center,
                VerticalContentAlignment = VerticalAlignment.Center,
                Background = Brushes.Transparent,
                BorderThickness = new Thickness(0)
            };
            AutomationProperties.SetAutomationId(close, "Editor.ChartTab.Close");
            AutomationProperties.SetName(close, AvaloniaLocalizationCatalog.Format("关闭谱面标签 {0}", tab.DisplayTitle));
            ToolTip.SetTip(close, AvaloniaLocalizationCatalog.Format("关闭 {0}", tab.DisplayTitle));
            close.Click += async (_, _) => await CloseTabAsync(tab);
            var tabContent = new StackPanel { Orientation = Orientation.Horizontal };
            tabContent.Children.Add(formatBadge);
            if (liveBadge != null) tabContent.Children.Add(liveBadge);
            if (retainedBadge != null) tabContent.Children.Add(retainedBadge);
            tabContent.Children.Add(button);
            tabContent.Children.Add(close);
            tabBar.Children.Add(new Border
            {
                Height = WindowsTitleBarParityPolicy.DocumentTabHeight,
                Margin = WindowsTitleBarParityPolicy.DocumentTabMargin,
                Padding = WindowsTitleBarParityPolicy.DocumentTabPadding,
                Background = new SolidColorBrush(presentation.TabBackground),
                BorderBrush = new SolidColorBrush(presentation.TabBorder),
                BorderThickness = new Thickness(1),
                CornerRadius = new CornerRadius(3),
                Child = tabContent
            });
        }
        UpdateOnlineLatencyLabels();
    }

    private void UpdateOnlineLatencyLabels()
    {
        var latency = WindowsTitleBarParityPolicy.ResolveOnlineLatency(
            onlineRoundTripLatencyMs);
        foreach (var visual in onlineLatencyVisuals)
        {
            visual.Label.Text = latency.Text;
            visual.Label.Foreground = new SolidColorBrush(latency.Foreground);
            AutomationProperties.SetName(visual.Label, latency.Text);
            AutomationProperties.SetName(
                visual.Badge,
                $"{visual.BadgePrefix} {latency.Text}");
        }
    }

    private async Task CheckActiveChartAsync()
    {
        var tab = viewModel.ActiveTab;
        if (tab == null) return;

        var presentation = PresentChartValidation(tab);
        if (presentation.Navigation is { } navigation)
            ApplyChartIssueNavigation(tab, navigation);
        await ShowChartValidationDialogAsync(
            presentation.ManualCheckMessage,
            presentation.CanSave
                ? ChartValidationDialogTone.Information
                : ChartValidationDialogTone.Warning,
            manual: true);
    }

    private async Task<SaveRoundTripResult?> SaveAndVerifyWithPreflightAsync(Guid? tabId = null)
    {
        try { await SaveTrackWorkspacesAsync(); }
        catch (Exception exception) { viewModel.SetStatus($"轨道保存失败：{exception.Message}"); return null; }
        var tab = tabId.HasValue
            ? viewModel.Tabs.FirstOrDefault(candidate => candidate.Id == tabId.Value)
            : viewModel.ActiveTab;
        if (tab == null) return null;
        if (saveInProgress)
        {
            // A save is still writing or read-back verifying outside the
            // workspace gate; a second concurrent save failed its File.Move.
            // Repeated requests (Ctrl+S held or pressed twice) share one
            // follow-up save per tab that runs after the current one.
            if (!pendingFollowUpSaves.TryGetValue(tab.Id, out var followUp))
            {
                followUp = new TaskCompletionSource<SaveRoundTripResult?>(
                    TaskCreationOptions.RunContinuationsAsynchronously);
                pendingFollowUpSaves[tab.Id] = followUp;
            }
            return await followUp.Task;
        }

        var tabIdToSave = tab.Id;
        return await RunExclusiveSaveAsync(
            () => SaveAndVerifyWithPreflightCoreAsync(tabIdToSave));
    }

    /// <summary>
    /// Runs one Save or Save As while holding the single save slot, then the
    /// Save requests that were coalesced meanwhile. Save As waits here for a
    /// running save (it used to race Ctrl+S on the same tab's files); a Save
    /// requested while the slot is held joins the follow-up queue instead.
    /// </summary>
    private async Task<SaveRoundTripResult?> RunExclusiveSaveAsync(
        Func<Task<SaveRoundTripResult?>> operation)
    {
        while (saveInProgress)
            await saveSlotReleased.Task;
        saveInProgress = true;
        try
        {
            try
            {
                return await operation();
            }
            finally
            {
                while (pendingFollowUpSaves.Count > 0)
                {
                    var (followUpTabId, followUp) = pendingFollowUpSaves.First();
                    pendingFollowUpSaves.Remove(followUpTabId);
                    try
                    {
                        followUp.TrySetResult(
                            await SaveAndVerifyWithPreflightCoreAsync(followUpTabId));
                    }
                    catch (Exception exception)
                    {
                        followUp.TrySetException(exception);
                    }
                }
            }
        }
        finally
        {
            saveInProgress = false;
            var released = saveSlotReleased;
            saveSlotReleased = new TaskCompletionSource(
                TaskCreationOptions.RunContinuationsAsynchronously);
            released.TrySetResult();
        }
    }

    private async Task<SaveRoundTripResult?> SaveAndVerifyWithPreflightCoreAsync(Guid tabId)
    {
        var tab = viewModel.Tabs.FirstOrDefault(candidate => candidate.Id == tabId);
        if (tab == null) return null;
        if (!ReferenceEquals(viewModel.ActiveTab, tab))
            viewModel.Activate(tab.Id);
        if (!ApplyMetadataEditor(enforceCommunityRules: true))
        {
            // Saving keeps the community metadata rules on purpose (only the
            // local-preservation paths — backup, export, close preflight — relax
            // them), but the reason used to reach only the status bar, so Ctrl+S
            // and the close dialog's "Save" looked as if nothing happened.
            if (lastMetadataApplyError is { Length: > 0 } metadataError)
                await ShowSettingsMessageAsync(
                    "保存失败",
                    AvaloniaLocalizationCatalog.Format("谱面信息未应用：{0}", AvaloniaLocalizationCatalog.Text(metadataError)));
            return null;
        }
        if (!await EnsureChartCanSaveAsync(tab))
            return null;
        if (retainedOnlineRoomTabIds.Contains(tab.Id))
            // Already inside the save slot: call the core, not the queued entry.
            return await PickAndSaveAsCoreAsync(tab.Id, preflightComplete: true);
        try
        {
            return await viewModel.SaveAndVerifyAsync(tab.Id);
        }
        catch (Exception exception)
        {
            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("保存谱面失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
            WindowsNativeMessageBox.Show(
                this,
                WindowsLibraryLauncherParityPolicy.CreateOperationError(
                    "无法保存原谱面；软件旁缓存已保留",
                    exception));
            return null;
        }
    }

    private async Task<bool> EnsureChartCanSaveAsync(DesktopChartTab tab)
    {
        var presentation = PresentChartValidation(tab, tab.Session.CaptureCommittedDocument());
        if (presentation.CanSave) return true;

        if (presentation.Navigation is { } navigation)
            ApplyChartIssueNavigation(tab, navigation);
        await ShowChartValidationDialogAsync(
            presentation.SaveBlockingMessage ?? string.Empty,
            ChartValidationDialogTone.Warning,
            manual: false);
        return false;
    }

    private DesktopChartValidationPresentation PresentChartValidation(
        DesktopChartTab tab,
        ChartDocument? document = null)
    {
        var presentation = DesktopChartValidationPresenter.Create(
            document ?? tab.Session.Document,
            tab.HiddenGroups);
        lastChartValidationPresentation = presentation;
        timeline.InvalidateVisual();
        return presentation;
    }

    private void ApplyChartIssueNavigation(
        DesktopChartTab tab,
        DesktopChartIssueNavigationPlan navigation)
    {
        if (!ReferenceEquals(viewModel.ActiveTab, tab)) viewModel.Activate(tab.Id);

        foreach (var group in navigation.HiddenGroupsToReveal)
            tab.HiddenGroups.Remove(group);
        timeline.SetHiddenGroups(tab.HiddenGroups);

        tab.Session.Selection.Clear();
        timeline.SetSelectedTiming(null);
        var existingNoteIds = tab.Session.Document.Notes.Select(note => note.Id).ToHashSet();
        tab.Session.Selection.UnionWith(navigation.NoteIds.Where(existingNoteIds.Contains));

        timeline.SetCurrentBeat(navigation.ExactBeat.Value);
        viewModel.UpdateCurrentBeat(navigation.ExactBeat.Value);
        RefreshGroupPanel();
        UpdateNoteInspector(tab);
        editorInspectorTabs.SelectedItem = noteInspectorTab;
        UpdateSelectionUi();
        viewModel.SetStatus(navigation.HoverStatusText);
        timeline.InvalidateVisual();
        lastChartValidationNavigation = navigation;
    }

    private async Task ShowChartValidationDialogAsync(
        string message,
        ChartValidationDialogTone tone,
        bool manual)
    {
        var dialog = new ChartValidationDialog(
            message,
            tone,
            displayScaleSettings.UiScale,
            displayScaleSettings.FontScale);
        if (manual)
        {
            chartValidationManualCheckShown = true;
            chartValidationManualDialogScale = dialog.ScaleDiagnostics;
            lastChartValidationDialogMode = tone == ChartValidationDialogTone.Information
                ? "manual-information"
                : "manual-warning";
        }
        else
        {
            chartValidationSaveBlockedShown = true;
            chartValidationSaveDialogScale = dialog.ScaleDiagnostics;
            lastChartValidationDialogMode = "save-warning";
        }
        await dialog.ShowDialog<bool>(this);
    }

    private async Task CloseTabAsync(DesktopChartTab tab)
    {
        // A second click while the first close is still persisting or waiting
        // on the room-exit confirmation must not start a parallel close.
        if (!closingTabIds.Add(tab.Id)) return;
        try
        {
            await CloseTabWithPromptsAsync(tab);
        }
        catch (Exception exception)
        {
            // The close button is an async handler with no other boundary. A
            // persistence failure (disk full, file locked by antivirus) must
            // leave the tab open with its edits instead of ending the process.
            Debug.WriteLine($"Closing chart tab failed: {exception}");
            if (windowCloseTeardownStarted) return;
            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("关闭谱面标签失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
            WindowsNativeMessageBox.Show(
                this,
                WindowsLibraryLauncherParityPolicy.CreateOperationError(
                    "无法关闭谱面标签",
                    exception));
        }
        finally
        {
            closingTabIds.Remove(tab.Id);
        }
    }

    private async Task CloseTabWithPromptsAsync(DesktopChartTab tab)
    {
        if (!TryApplyPendingMetadataEditor(
                tab,
                enforceCommunityRules: false))
            return;
        if (retainedOnlineRoomTabIds.Contains(tab.Id))
        {
            var retainedChoice = await new PreservedRoomDraftCloseDialog(
                    tab.DisplayTitle,
                    displayScaleSettings.UiScale,
                    displayScaleSettings.FontScale)
                .ShowDialog<PreservedRoomDraftCloseChoice>(this);
            switch (retainedChoice)
            {
                case PreservedRoomDraftCloseChoice.SaveAs:
                    var retainedSaved = await PickAndSaveAsAsync(tab.Id);
                    if (retainedSaved?.StructurallyEqual == true &&
                        !tab.Session.IsDirty)
                        await CloseTabCoreAsync(tab, discardUnsavedChanges: false);
                    break;
                case PreservedRoomDraftCloseChoice.Discard:
                    await CloseTabCoreAsync(tab, discardUnsavedChanges: true);
                    break;
            }
            return;
        }

        if (!tab.Session.IsDirty)
        {
            await CloseTabCoreAsync(tab, discardUnsavedChanges: false);
            return;
        }

        var choice = await new UnsavedChangesDialog(
                tab.DisplayTitle,
                applicationClosing: false,
                displayScaleSettings.UiScale,
                displayScaleSettings.FontScale)
            .ShowDialog<UnsavedChangesChoice>(this);
        switch (choice)
        {
            case UnsavedChangesChoice.Save:
                var saved = await SaveAndVerifyWithPreflightAsync(tab.Id);
                if (saved?.StructurallyEqual == true && !tab.Session.IsDirty)
                    await CloseTabCoreAsync(tab, discardUnsavedChanges: false);
                break;
            case UnsavedChangesChoice.Discard:
                await CloseTabCoreAsync(tab, discardUnsavedChanges: true);
                break;
        }
    }

    private async Task<bool> CloseTabCoreAsync(
        DesktopChartTab tab,
        bool discardUnsavedChanges)
    {
        if (!await ConfirmOnlineRoomExitAsync(tab)) return false;
        var result = await viewModel.CloseTabAsync(tab.Id, discardUnsavedChanges);
        if (result.Status == DesktopChartCloseStatus.PersistFailed)
        {
            // The workspace rolled the close back, so the tab and its edits are
            // still open; say why instead of leaving only a status-bar line.
            WindowsNativeMessageBox.Show(
                this,
                WindowsLibraryLauncherParityPolicy.CreateOperationError(
                    "无法关闭谱面标签",
                    result.Error ?? new IOException(viewModel.Status)));
            return false;
        }
        if (!result.Closed) return false;
        await OnChartTabClosedAsync(tab);
        return true;
    }

    private async Task<bool> ConfirmOnlineRoomExitAsync(
        DesktopChartTab? closingTab = null)
    {
        if (closingTab != null &&
            !ReferenceEquals(roomChartSyncTab, closingTab))
            return true;

        var account = onlineAccountHost?.Session;
        var room = account?.CurrentRoom;
        if (room == null) return true;
        var isOwner =
            account?.CurrentUser != null &&
            room.OwnerUserId == account.CurrentUser.Id;
        var choice = await new OnlineRoomExitConfirmationDialog(
                room.Name,
                isOwner,
                displayScaleSettings.UiScale,
                displayScaleSettings.FontScale)
            .ShowDialog<OnlineRoomExitChoice>(this);
        return choice == OnlineRoomExitChoice.Confirm;
    }

    private async Task OnChartTabClosedAsync(DesktopChartTab tab)
    {
        difficultyStates.Remove(tab.Id);
        retainedOnlineRoomTabIds.Remove(tab.Id);
        difficultyAnalysisCancellation?.Cancel();
        if (!ReferenceEquals(roomChartSyncTab, tab)) return;
        await StopRoomChartSyncAsync(
            resetRetainedTab:
            WindowsOnlineRoomRetentionPolicy.ShouldPreserveDraftOnConfirmedExit(
                WindowsOnlineRoomExitContext.ExplicitTabClose));
        if (onlineAccountHost?.Session.CurrentRoom != null)
        {
            try
            {
                using var timeout = new CancellationTokenSource(TimeSpan.FromSeconds(15));
                await onlineAccountHost.Session.LeaveCurrentRoomAsync(timeout.Token);
            }
            catch (Exception exception) when (
                exception is OnlineApiException or HttpRequestException or System.Net.WebException or OperationCanceledException or
                    JsonException)
            {
                viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("联机标签已关闭；退出房间请求未确认：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
            }
        }
    }

    private async Task CreateChartAsync()
    {
        var creator = onlineAccountHost?.Session.IsAuthenticated == true
            ? onlineAccountHost.Session.CurrentUser?.Username
            : null;
        try
        {
            await viewModel.CreateAsync(creator: creator);
            if (viewModel.ActiveTab is { } tab)
                viewModel.SetStatus(
                    AvaloniaLocalizationCatalog.Format("已在工作目录创建 {0}，可直接开始编辑", tab.DisplayTitle));
            ShowEditorSurface();
        }
        catch (Exception exception)
        {
            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("新建谱面失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
            WindowsNativeMessageBox.Show(
                this,
                WindowsLibraryLauncherParityPolicy.CreateOperationError(
                    "无法创建新项目",
                    exception));
        }
    }

    private async Task CreateChartFromAudioAsync()
    {
        string? selectedPath;
        try
        {
            selectedPath = await PickLocalFileAsync(
                new FilePickerOpenOptions
                {
                    Title = "选择要导入曲库的音频",
                    AllowMultiple = false,
                    FileTypeFilter =
                    [
                        new FilePickerFileType("音频文件")
                        {
                            Patterns = ["*.mp3", "*.ogg", "*.wav", "*.flac", "*.m4a", "*.aac"],
                            MimeTypes = ["audio/*"]
                        }
                    ]
                },
                PickedFileRetention.Transient);
        }
        catch (Exception exception)
        {
            // The picker (and Android's staging copy) can fault; this is a
            // button handler with no other boundary.
            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("无法从音频创建谱面：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
            return;
        }
        if (string.IsNullOrWhiteSpace(selectedPath)) return;
        await CreateChartFromAudioPathAsync(Path.GetFullPath(selectedPath));
    }

    private async Task CreateChartFromAudioPathAsync(string selectedPath)
    {
        // The name prompt is a single shared overlay. A second creation (drop
        // while the prompt is open, or the library button) used to replace the
        // first flow's completion source and leave that flow waiting forever.
        if (audioChartCreationInProgress)
        {
            viewModel.SetStatus("音频导入进行中，请稍后再试。");
            return;
        }
        audioChartCreationInProgress = true;
        try
        {
            await CreateChartFromAudioPathCoreAsync(selectedPath);
        }
        finally
        {
            audioChartCreationInProgress = false;
        }
    }

    private async Task CreateChartFromAudioPathCoreAsync(string selectedPath)
    {
        if (!File.Exists(selectedPath) || !WindowsFileDropPolicy.IsAudioPath(selectedPath))
        {
            WindowsNativeMessageBox.Show(
                this,
                new WindowsNativeMessageBoxRequest(
                    "请选择受支持的音频文件。",
                    "导入音频",
                    WindowsNativeMessageBoxIcon.Warning));
            return;
        }

        var firstPrompt = true;
        DesktopNamedAudioChartCreation creation;
        while (true)
        {
            var requestedName = await ShowAudioImportNamePromptAsync(
                selectedPath,
                resetState: firstPrompt);
            firstPrompt = false;
            if (requestedName == null) return;
            if (!File.Exists(selectedPath))
            {
                audioImportNameStatusText.Text = "音频文件已不存在，请重新选择。";
                audioImportNameStatusText.Foreground = Brushes.OrangeRed;
                if (audioImportNameConfirmButton != null)
                    audioImportNameConfirmButton.IsEnabled = true;
                continue;
            }
            try
            {
                var creator = onlineAccountHost?.Session.IsAuthenticated == true
                    ? onlineAccountHost.Session.CurrentUser?.Username
                    : null;
                creation = await viewModel.CreateNamedAudioChartAsync(
                    requestedName,
                    creator);
                HideAudioImportNamePrompt();
                ShowEditorSurface();
                break;
            }
            catch (Exception exception)
            {
                audioImportNameStatusText.Text = exception.Message;
                audioImportNameStatusText.Foreground = Brushes.OrangeRed;
                viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("无法从音频创建谱面：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
            }
        }

        if (!activeAudioImportTask.IsCompleted)
            await activeAudioImportTask;
        var importOperation = ImportChartAudioPathCoreAsync(creation.Tab, selectedPath);
        activeAudioImportTask = importOperation;
        var importStatus = await importOperation;
        viewModel.SetStatus(
            WindowsAudioLibraryCreationPolicy.CompletionStatus(
                creation.Name,
                importStatus));
    }

    private Task<string?> ShowAudioImportNamePromptAsync(
        string sourcePath,
        bool resetState)
    {
        if (resetState)
        {
            audioImportSourceText.Text = Path.GetFileName(sourcePath);
            audioImportNameBox.Text = Path.GetFileNameWithoutExtension(sourcePath);
            audioImportNameStatusText.Text = string.Empty;
            audioImportNameStatusText.Foreground =
                new SolidColorBrush(Color.Parse("#C58C79"));
        }
        audioImportNameConfirmButton?.SetCurrentValue(IsEnabledProperty, true);
        // Never orphan an earlier prompt: end it as canceled so its flow
        // returns instead of awaiting a completion source nobody will set.
        audioImportNameCompletion?.TrySetResult(null);
        audioImportNameCompletion = new TaskCompletionSource<string?>(
            TaskCreationOptions.RunContinuationsAsynchronously);
        audioImportNameLayer.IsVisible = true;
        Dispatcher.UIThread.Post(() =>
        {
            audioImportNameBox.Focus();
            audioImportNameBox.SelectAll();
        }, DispatcherPriority.Input);
        return audioImportNameCompletion.Task;
    }

    private void CompleteAudioImportNamePrompt(bool confirm)
    {
        var completion = audioImportNameCompletion;
        if (completion == null) return;
        audioImportNameCompletion = null;
        if (!confirm)
        {
            audioImportNameLayer.IsVisible = false;
            completion.TrySetResult(null);
            return;
        }
        if (audioImportNameConfirmButton != null)
            audioImportNameConfirmButton.IsEnabled = false;
        audioImportNameStatusText.Text = "正在创建谱面与编辑缓存…";
        audioImportNameStatusText.Foreground =
            new SolidColorBrush(Color.Parse("#C58C79"));
        completion.TrySetResult(audioImportNameBox.Text);
    }

    private void HideAudioImportNamePrompt()
    {
        audioImportNameLayer.IsVisible = false;
        audioImportNameCompletion = null;
    }

    private async Task<OnlineRoomUploadPreparation> PrepareCurrentOnlineRoomUploadAsync(
        CancellationToken cancellationToken)
    {
        if (onlineAccountHost?.Session.CurrentRoom != null)
            throw new InvalidOperationException(
                "请先退出当前联机房间，再创建新房间。");
        var tab = viewModel.ActiveTab ??
                  throw new InvalidOperationException(
                      "请先打开要绑定到房间的谱面；一个房间只编辑一张谱。");
        if (roomChartSyncRoomId != null)
            throw new InvalidOperationException(
                "请先退出当前联机谱面，再创建新房间。");

        viewModel.SetStatus("正在刷新谱面工作缓存…");
        if (!await viewModel.PersistAsync())
            throw new IOException(viewModel.Status);
        cancellationToken.ThrowIfCancellationRequested();
        var package = await onlineRoomResourceService.BuildUploadPackageAsync(
            tab,
            cancellationToken);
        preparedOnlineRoomUpload = new PreparedOnlineRoomUpload(
            tab.Id,
            tab.Session.ChangeSerial,
            package);
        return new OnlineRoomUploadPreparation(
            package.Files.Count,
            package.TotalBytes,
            package.Files
                .Select(file => new OnlineRoomUploadPreviewFile(
                    file.Path,
                    file.Length))
                .ToArray());
    }

    private async Task<OnlineRoomResourcePreparation> PrepareCurrentOnlineRoomDownloadAsync(
        OnlineRoomSummaryDto room,
        CancellationToken cancellationToken)
    {
        var account = onlineAccountHost?.Session ??
                      throw new InvalidOperationException("联机账号会话不可用。");
        if (account.CurrentRoom?.Id != room.Id)
            throw new InvalidOperationException("当前房间已经变化，请重新进入。");
        var manifest = await account.GetRoomResourceManifestAsync(
            room.Id,
            cancellationToken);
        var cacheStatus = await onlineRoomResourceService.InspectAsync(
            manifest,
            cancellationToken);
        return new OnlineRoomResourcePreparation(
            cacheStatus.TotalBytes,
            cacheStatus.MissingBytes,
            cacheStatus.ReusedCount,
            manifest.Entries is { Count: > 0 });
    }

    private async Task OpenCurrentOnlineRoomChartAsync(
        OnlineRoomSummaryDto room,
        bool lockExistingNotes,
        bool usePreparedUpload,
        CancellationToken cancellationToken)
    {
        var account = onlineAccountHost?.Session ??
                      throw new InvalidOperationException("联机账号会话不可用。");
        if (account.CurrentRoom?.Id != room.Id)
            throw new InvalidOperationException("当前房间已经变化，请重新进入。");
        await StopRoomChartSyncAsync(resetRetainedTab: true);

        if (room.OwnerUserId == account.CurrentUser?.Id && !room.ResourcesReady)
        {
            await InitializeOwnedRoomChartAsync(
                account,
                room,
                lockExistingNotes,
                usePreparedUpload,
                cancellationToken);
            return;
        }

        viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("正在检查房间“{0}”的本地资源缓存…", room.Name));
        var manifest = await account.GetRoomResourceManifestAsync(room.Id, cancellationToken);
        var cacheStatus = await onlineRoomResourceService.InspectAsync(manifest, cancellationToken);
        ShowRoomDownloadProgress(room.Id, room.Name, cacheStatus);
        var enteredRoom = false;
        try
        {
            viewModel.SetStatus(cacheStatus.MissingBytes == 0
                ? "房间资源 SHA-256 校验通过，正在复用本地缓存…"
                : AvaloniaLocalizationCatalog.Format("正在下载房间资源：{0}", FormatTransferBytes(cacheStatus.MissingBytes)));
            var progress = new Progress<WindowsOnlineRoomTransferProgress>(value =>
            {
                UpdateRoomDownloadProgress(room.Id, value);
                viewModel.SetStatus(
                    AvaloniaLocalizationCatalog.Format("房间资源 {0:P0} · {1} / {2} · {3}", value.Fraction, FormatTransferBytes(value.TransferredBytes), FormatTransferBytes(value.TotalBytes), value.CurrentPath));
            });
            var materialized = await onlineRoomResourceService.DownloadAndMaterializeAsync(
                account,
                room.Id,
                manifest,
                progress,
                cancellationToken);
            cancellationToken.ThrowIfCancellationRequested();

            SetRoomDownloadProgressStage(
                room.Id,
                "资源下载与校验完成，正在打开真实谱面",
                "100%  ·  正在进入编辑器");
            await PreserveRetainedRoomTabBeforeRebindAsync(
                materialized.ChartPath,
                room.Id,
                cancellationToken);
            viewModel.SetStatus("房间资源已校验，正在打开真实 MC 编辑器标签…");
            await viewModel.OpenAsync(materialized.ChartPath);
            var tab = viewModel.ActiveTab ?? throw new InvalidDataException("房间谱面无法打开。");
            var snapshot = await account.GetRoomChartAsync(room.Id, cancellationToken);
            var canonical = OnlineChartSyncCodec.CreateCanonicalDocument(
                tab.Session.CaptureCommittedDocument(),
                snapshot);
            ApplyInitialRoomSnapshot(tab, canonical, snapshot.Locks);
            var frozenResources = await WindowsFrozenRoomResourceRegistry.CreateAsync(
                tab.WorkingPath,
                manifest,
                cancellationToken);
            await BindRoomChartAsync(
                account,
                room.Id,
                room.RoomNumber,
                room.Name,
                tab,
                RoomChartSyncState.Create(snapshot.Revision, canonical),
                frozenResources);
            var observer = account.CurrentMemberRole.Equals("viewer", StringComparison.OrdinalIgnoreCase);
            viewModel.SetStatus(observer
                ? AvaloniaLocalizationCatalog.Format("已进入房间“{0}” · 观察者只读 · revision {1:N0} · {2:N0} Note", room.Name, snapshot.Revision, tab.Session.Document.Notes.Count)
                : AvaloniaLocalizationCatalog.Format("已进入联机房间“{0}” · revision {1:N0} · {2:N0} Note", room.Name, snapshot.Revision, tab.Session.Document.Notes.Count));
            enteredRoom = true;
        }
        catch (Exception exception)
        {
            if (roomDownloadProgressRoomId == room.Id)
            {
                roomDownloadProgressBar.IsIndeterminate = false;
                roomDownloadProgressDetailText.Text = AvaloniaLocalizationCatalog.Format("下载或打开失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message));
                roomDownloadProgressValueText.Text = "未完成";
            }
            throw;
        }
        finally
        {
            await HideRoomDownloadProgressAsync(room.Id, enteredRoom);
        }
    }

    private async Task InitializeOwnedRoomChartAsync(
        OnlineAccountSession account,
        OnlineRoomSummaryDto room,
        bool lockExistingNotes,
        bool usePreparedUpload,
        CancellationToken cancellationToken)
    {
        var tab = viewModel.ActiveTab ??
                  throw new InvalidOperationException("请先打开要绑定到房间的谱面。");
        if (roomChartSyncRoomId is { } boundRoomId && boundRoomId != room.Id)
            throw new InvalidOperationException("请先退出当前联机谱面，再创建新房间。");
        await StopRoomChartSyncAsync(resetRetainedTab: true);

        viewModel.SetStatus("正在刷新谱面工作缓存…");
        WindowsOnlineRoomUploadPackage package;
        if (usePreparedUpload &&
            preparedOnlineRoomUpload is { } prepared &&
            prepared.TabId == tab.Id &&
            prepared.ChangeSerial == tab.Session.ChangeSerial)
        {
            package = prepared.Package;
        }
        else
        {
            if (!await viewModel.PersistAsync())
                throw new IOException(viewModel.Status);
            package = await onlineRoomResourceService.BuildUploadPackageAsync(
                tab,
                cancellationToken);
        }
        preparedOnlineRoomUpload = null;
        viewModel.SetStatus(
            AvaloniaLocalizationCatalog.Format("正在建立联机谱面状态并上传 {0:N0} 个资源…", package.Files.Count));
        ShowRoomUploadProgress(room.Id, room.Name, package);
        var uploadSucceeded = false;
        var committedDocument = tab.Session.CaptureCommittedDocument();
        var previousOwnerRegions = tab.Session.OwnerProtectedRegions.ToArray();
        var previousAllowOwnerProtectedEdits = tab.Session.AllowOwnerProtectedEdits;
        var appliedServerInitialization = false;
        var initialLocks = lockExistingNotes
            ? OwnerLockSelectionPlanner.BuildAutomaticNoteRanges(
                    committedDocument.Notes,
                    tab.Session.SnapDivision)
                .Select(range => OnlineChartSyncCodec.CreateLockRange(
                    range.StartBeat,
                    range.EndBeat))
                .ToArray()
            : [];
        try
        {
            var snapshot = await account.InitializeRoomChartAsync(
                room.Id,
                OnlineChartSyncCodec.CreateInitializeRequest(committedDocument, initialLocks),
                cancellationToken);
            var canonical = OnlineChartSyncCodec.CreateCanonicalDocument(
                committedDocument,
                snapshot);
            ApplyInitialRoomSnapshot(tab, canonical, snapshot.Locks);
            appliedServerInitialization = true;
            var progress = new Progress<WindowsOnlineRoomTransferProgress>(value =>
            {
                UpdateRoomUploadProgress(room.Id, value);
                viewModel.SetStatus(
                    AvaloniaLocalizationCatalog.Format("上传房间资源 {0:P0} · {1} / {2} · {3}", value.Fraction, FormatTransferBytes(value.TransferredBytes), FormatTransferBytes(value.TotalBytes), value.CurrentPath));
            });
            var manifest = await onlineRoomResourceService.UploadAsync(
                account,
                room.Id,
                package,
                progress,
                cancellationToken);
            var frozenResources = await WindowsFrozenRoomResourceRegistry.CreateAsync(
                tab.WorkingPath,
                manifest,
                cancellationToken);
            await BindRoomChartAsync(
                account,
                room.Id,
                room.RoomNumber,
                room.Name,
                tab,
                RoomChartSyncState.Create(snapshot.Revision, canonical),
                frozenResources);
            viewModel.SetStatus(
                AvaloniaLocalizationCatalog.Format("房间“{0}”已创建并绑定当前编辑器 · revision {1:N0}", room.Name, snapshot.Revision));
            uploadSucceeded = true;
        }
        catch (Exception exception)
        {
            if (roomUploadProgressRoomId == room.Id)
            {
                roomUploadProgressDetailText.Text = AvaloniaLocalizationCatalog.Format("上传失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message));
                roomUploadProgressValueText.Text = "未完成";
            }
            if (roomChartSyncRoomId == room.Id)
                await StopRoomChartSyncAsync(resetRetainedTab: false);
            if (appliedServerInitialization && viewModel.Tabs.Contains(tab))
            {
                applyingRemoteChartSync = true;
                try
                {
                    tab.Session.ApplyRemoteMutation(
                        document => ReplaceOnlineChartContent(document, committedDocument));
                    tab.Session.ReplaceOwnerProtectedRegions(previousOwnerRegions);
                    tab.Session.AllowOwnerProtectedEdits = previousAllowOwnerProtectedEdits;
                }
                finally
                {
                    applyingRemoteChartSync = false;
                }
            }
            throw;
        }
        finally
        {
            await HideRoomUploadProgressAsync(room.Id, uploadSucceeded);
        }
    }

    private void ApplyInitialRoomSnapshot(
        DesktopChartTab tab,
        ChartDocument canonical,
        IReadOnlyList<OnlineChartLock> locks)
    {
        applyingRemoteChartSync = true;
        try
        {
            tab.Session.ApplyRemoteMutation(document => ReplaceOnlineChartContent(document, canonical));
            tab.Session.ReplaceOwnerProtectedRegions(OnlineChartSyncCodec.ToOwnerRegions(locks));
        }
        finally
        {
            applyingRemoteChartSync = false;
        }
    }

    private async Task BindRoomChartAsync(
        OnlineAccountSession account,
        Guid roomId,
        long roomNumber,
        string roomName,
        DesktopChartTab tab,
        RoomChartSyncState initialState,
        WindowsFrozenRoomResourceRegistry frozenResources)
    {
        await StopRoomChartSyncAsync(resetRetainedTab: true);
        if (account.CurrentRoom?.Id != roomId || !viewModel.Tabs.Contains(tab))
            throw new OperationCanceledException("联机谱面绑定已取消。");

        roomChartSyncRoomId = roomId;
        roomChartSyncRoomNumber = Math.Max(0, roomNumber);
        roomChartSyncRoomName = roomName?.Trim() ?? string.Empty;
        roomChartSyncTab = tab;
        onlineCreatorMembers = [];
        ResetRoomChatUi(reveal: true);
        RefreshTimelineOnlineCreators();
        onlineRoundTripLatencyMs = null;
        retainedOnlineRoomTabIds.Remove(tab.Id);
        roomChartFrozenResources = frozenResources;
        roomChartLocalChangeSerial = 0;
        roomChartObservedSessionSerial = tab.Session.ChangeSerial;
        tab.Session.Changed += RoomChartSession_Changed;
        roomAccessSnapshot = CaptureRoomAccess(account);
        ApplyOnlineRoomPermissions();

        RoomChartSyncCoordinator? coordinator = null;
        var host = new AvaloniaRoomChartSyncDocumentHost(
            () => new RoomChartLocalSnapshot(
                tab.Session.CaptureCommittedDocument(),
                roomChartLocalChangeSerial),
            plan =>
            {
                if (ReferenceEquals(roomChartSyncCoordinator, coordinator))
                    ApplyRoomChartPlan(tab, plan);
            },
            state =>
            {
                if (ReferenceEquals(roomChartSyncCoordinator, coordinator))
                    PublishRoomChartSyncViewState(tab, state);
            },
            // The same serial the capture above reports, so the host can refuse
            // a plan merged before a local edit made during the re-merge window.
            currentChangeSerial: () => roomChartLocalChangeSerial,
            // Not gated on the current coordinator: whatever is being discarded
            // is the user's work and is kept either way.
            preserveRejectedLocalChanges: rejected =>
                PreserveRejectedRoomChartChanges(tab, rejected));
        coordinator = new RoomChartSyncCoordinator(
            initialState,
            new AvaloniaRoomChartSyncTransport(account, roomId),
            host);
        roomChartSyncCoordinator = coordinator;
        coordinator.Start();
        await EnsureOnlineRoomPresenceLoopAsync(roomId);
        viewModel.Activate(tab.Id);
        ShowEditorSurface();
    }

    /// <summary>
    /// A deterministic server rejection (locked region, permission, size) is
    /// about to replace the local room document with the authoritative one.
    /// Keep the local document as an ordinary chart backup, where "恢复备份"
    /// finds it. Runs on the UI thread from the sync host and never throws: a
    /// failed write is logged and reported, and synchronization continues.
    /// </summary>
    private void PreserveRejectedRoomChartChanges(
        DesktopChartTab tab,
        RoomChartRejectedLocalChanges rejected)
    {
        try
        {
            var backupPath = ChartBackupArchiveService.CreateBackup(
                AvaloniaAppPaths.EditorBackupRoot,
                rejected.LocalDocument,
                tab.SourcePath);
            Debug.WriteLine(
                $"Rejected room changes ({rejected.StatusCode} {rejected.ErrorCode}, " +
                $"revision {rejected.Revision}) preserved as {backupPath}");
            if (windowCloseTeardownStarted) return;
            var message = AvaloniaLocalizationCatalog.Format("部分协作修改被服务器拒绝，已保存为备份，可通过恢复备份找回：{0}", Path.GetFileName(backupPath));
            backupCacheStatusText.Text = message;
            ShowEditorToast(message);
            viewModel.SetStatus(message);
        }
        catch (Exception exception)
        {
            Debug.WriteLine($"Preserving rejected room changes failed: {exception}");
            try
            {
                if (!windowCloseTeardownStarted)
                    viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("部分协作修改被服务器拒绝，保存备份失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
            }
            catch (Exception statusException)
            {
                Debug.WriteLine($"Reporting the preservation failure failed: {statusException}");
            }
        }
    }

    private void RoomChartSession_Changed(object? sender, EventArgs eventArgs)
    {
        var tab = roomChartSyncTab;
        if (tab == null || !ReferenceEquals(sender, tab.Session)) return;
        var currentSerial = tab.Session.ChangeSerial;
        if (currentSerial == roomChartObservedSessionSerial) return;
        roomChartObservedSessionSerial = currentSerial;
        if (applyingRemoteChartSync) return;
        roomChartLocalChangeSerial = checked(roomChartLocalChangeSerial + 1);
        roomChartSyncCoordinator?.NotifyLocalChange();
    }

    private void ApplyRoomChartPlan(DesktopChartTab tab, RoomChartApplyPlan plan)
    {
        applyingRemoteChartSync = true;
        try
        {
            if (plan.ApplyDocument)
            {
                var next = plan.Document;
                if (plan.ClearHistory)
                    tab.Session.ReplaceDocument(next, markDirty: true);
                else if (!tab.Session.TryMergeRemoteAttributionDuringInteractiveMutation(next))
                    tab.Session.ApplyRemoteMutation(
                        document => ReplaceOnlineChartContent(document, next));
            }
            tab.Session.ReplaceOwnerProtectedRegions(plan.OwnerProtectedRegions);
        }
        finally
        {
            applyingRemoteChartSync = false;
        }
        if (ReferenceEquals(viewModel.ActiveTab, tab)) UpdateUi();
    }

    private void PublishRoomChartSyncViewState(
        DesktopChartTab tab,
        RoomChartSyncViewState state)
    {
        if (!ReferenceEquals(roomChartSyncTab, tab)) return;
        timeline.SetRoomSyncDiagnostics(
            state.WorkStatus.ToString(),
            state.FeedStatus.ToString(),
            state.Revision,
            state.PendingOperationId,
            state.ConsecutiveWorkFailures,
            state.ConsecutiveFeedFailures);
        var retry = FormatRoomChartRetryDelay(state.RetryAt);
        var message = state.WorkStatus switch
        {
            RoomChartSyncWorkStatus.Throttled => "正在汇集本地谱面修改…",
            RoomChartSyncWorkStatus.Synchronizing => "正在同步房间谱面…",
            RoomChartSyncWorkStatus.RollingBack => "正在原子回滚房间谱面…",
            RoomChartSyncWorkStatus.BackingOff =>
                AvaloniaLocalizationCatalog.Format("谱面同步暂时中断，{0}后重试；本地修改会保留。", retry),
            RoomChartSyncWorkStatus.WriteBudgetThrottled =>
                AvaloniaLocalizationCatalog.Format("谱面写入额度暂满，{0}后用同一 OperationId 重试。", retry),
            RoomChartSyncWorkStatus.PermanentlyBlocked =>
                "房间已达到联机操作上限；本地修改仍可保存。",
            RoomChartSyncWorkStatus.Faulted =>
                AvaloniaLocalizationCatalog.Format("谱面同步：{0}", state.WorkErrorMessage ?? AvaloniaLocalizationCatalog.Text("发生未知错误。")),
            RoomChartSyncWorkStatus.Idle when state.WorkErrorMessage != null =>
                AvaloniaLocalizationCatalog.Format("谱面同步：{0}", AvaloniaLocalizationCatalog.Text(state.WorkErrorMessage)),
            RoomChartSyncWorkStatus.Idle when state.StatusHoldUntil > DateTimeOffset.UtcNow =>
                AvaloniaLocalizationCatalog.Format("房间谱面已同步 · revision {0:N0}", state.Revision),
            _ => string.Empty
        };
        if (message.Length == 0)
        {
            message = state.FeedStatus switch
            {
                RoomChartSyncFeedStatus.Connecting => "正在连接实时谱面通知…",
                RoomChartSyncFeedStatus.Reconnecting => "实时谱面通知中断，正在重连…",
                RoomChartSyncFeedStatus.Faulted =>
                    AvaloniaLocalizationCatalog.Format("实时谱面通知：{0}", state.FeedErrorMessage ?? AvaloniaLocalizationCatalog.Text("连接已停止。")),
                _ => string.Empty
            };
        }
        if (message.Length == 0 &&
            state.WorkStatus == RoomChartSyncWorkStatus.Idle &&
            state.FeedStatus == RoomChartSyncFeedStatus.Connected)
            message = AvaloniaLocalizationCatalog.Format("房间谱面已同步 · revision {0:N0}", state.Revision);
        if (message.Length > 0) viewModel.SetStatus(message);

        var deniedCategory = CollaborationRevisionPolicy.GetPermissionDeniedCategory(
            state.WorkErrorCode);
        if (deniedCategory != null &&
            !string.Equals(lastRoomChartPermissionErrorCode, state.WorkErrorCode, StringComparison.Ordinal))
        {
            lastRoomChartPermissionErrorCode = state.WorkErrorCode;
            var presentation = WindowsRoomPermissionNoticePolicy.Denied(deniedCategory);
            viewModel.SetStatus(presentation.Message);
            ShowRoomPermissionNotice(presentation);
        }
        else if (deniedCategory == null)
        {
            lastRoomChartPermissionErrorCode = null;
        }
    }

    private void ApplyOnlineRoomPermissions()
    {
        var tab = roomChartSyncTab;
        var account = onlineAccountHost?.Session;
        var room = account?.CurrentRoom;
        if (tab == null || account == null || room == null || room.Id != roomChartSyncRoomId) return;
        var owner = room.OwnerUserId == account.CurrentUser?.Id ||
                    account.CurrentMemberRole.Equals("owner", StringComparison.OrdinalIgnoreCase);
        var access = WindowsOnlineRoomPermissionPolicy.Resolve(
            owner,
            account.CurrentMemberRole,
            account.CanEditMetadata,
            account.CanEditTiming,
            account.CanEditNotes);
        tab.Session.AllowOwnerProtectedEdits = owner;
        tab.Session.IsReadOnly = access.IsReadOnly;
        tab.Session.CanEditMetadata = access.CanEditMetadata;
        tab.Session.CanEditTiming = access.CanEditTiming;
        tab.Session.CanEditNotes = access.CanEditNotes;
        if (ReferenceEquals(viewModel.ActiveTab, tab)) UpdateSelectionUi();
    }

    private void UpdateOnlineCreatorMembers(
        OnlineAccountSession account,
        IReadOnlyList<OnlineRoomMemberDto> members)
    {
        ArgumentNullException.ThrowIfNull(account);
        ArgumentNullException.ThrowIfNull(members);
        onlineCreatorMembers = members.Where(member => member.IsOnline).ToArray();
        roomMemberList.ItemsSource = onlineCreatorMembers;
        var room = account.CurrentRoom;
        roomCollaborationTitle.Text =
            room?.Name ?? roomChartSyncRoomName ?? "联机房间";
        roomMemberCountText.Text =
            $"{room?.MemberCount ?? 0:N0} / {room?.MaximumMembers ?? 8:N0}";
        RefreshTimelineOnlineCreators();
        foreach (var avatarKey in onlineCreatorMembers
                     .Select(member => member.AvatarKey)
                     .Where(avatarKey =>
                         !string.IsNullOrWhiteSpace(avatarKey) &&
                         !avatarKey.Equals("default", StringComparison.OrdinalIgnoreCase))
                     .Distinct(StringComparer.Ordinal))
        {
            if (onlineCreatorAvatarCache.ContainsKey(avatarKey) ||
                onlineCreatorAvatarLoads.ContainsKey(avatarKey))
                continue;
            var load = DownloadOnlineCreatorAvatarAsync(account, avatarKey);
            onlineCreatorAvatarLoads.Add(avatarKey, load);
            _ = InstallOnlineCreatorAvatarAsync(avatarKey, load);
        }
    }

    private void RefreshTimelineOnlineCreators()
    {
        if (roomChartSyncRoomId == null ||
            roomChartSyncTab == null ||
            !ReferenceEquals(viewModel.ActiveTab, roomChartSyncTab))
        {
            timeline.SetOnlineCreators(
                new Dictionary<long, OnlineCreatorAppearance>());
            return;
        }

        var appearances = new Dictionary<long, OnlineCreatorAppearance>();
        foreach (var member in onlineCreatorMembers)
        {
            var avatar = !string.IsNullOrWhiteSpace(member.AvatarKey) &&
                         onlineCreatorAvatarCache.TryGetValue(
                             member.AvatarKey,
                             out var cached)
                ? cached
                : null;
            appearances[member.UserId] = new OnlineCreatorAppearance(
                member.DisplayName,
                avatar);
        }
        timeline.SetOnlineCreators(appearances);
    }

    private async Task<Bitmap?> DownloadOnlineCreatorAvatarAsync(
        OnlineAccountSession account,
        string avatarKey)
    {
        using var stream = new MemoryStream();
        await account.DownloadAvatarAsync(
            avatarKey,
            stream,
            cancellationToken: onlineCreatorAvatarLifetime.Token);
        stream.Position = 0;
        return new Bitmap(stream);
    }

    private void BindRemoteAvatar(
        WindowsDefaultUserAvatar avatar,
        string? avatarKey,
        string displayName)
    {
        ArgumentNullException.ThrowIfNull(avatar);
        var normalizedKey = avatarKey?.Trim() ?? string.Empty;
        avatar.RemoteImage.Tag = normalizedKey;
        if (string.IsNullOrWhiteSpace(normalizedKey) ||
            normalizedKey.Equals("default", StringComparison.OrdinalIgnoreCase))
        {
            avatar.RemoteImage.Source = null;
            AutomationProperties.SetName(avatar, AvaloniaLocalizationCatalog.Format("默认头像 · {0}", displayName));
            return;
        }

        if (onlineCreatorAvatarCache.TryGetValue(normalizedKey, out var cached))
        {
            avatar.RemoteImage.Source = cached;
            AutomationProperties.SetName(avatar, AvaloniaLocalizationCatalog.Format("用户头像 · {0}", displayName));
            return;
        }

        avatar.RemoteImage.Source = null;
        AutomationProperties.SetName(avatar, AvaloniaLocalizationCatalog.Format("正在载入头像 · {0}", displayName));
        _ = LoadRemoteAvatarIntoAsync(
            avatar,
            normalizedKey,
            displayName);
    }

    private async Task LoadRemoteAvatarIntoAsync(
        WindowsDefaultUserAvatar avatar,
        string avatarKey,
        string displayName)
    {
        var account = onlineAccountHost?.Session;
        if (account == null || onlineCreatorAvatarLifetime.IsCancellationRequested)
            return;
        try
        {
            if (!onlineCreatorAvatarLoads.TryGetValue(avatarKey, out var load))
            {
                load = DownloadOnlineCreatorAvatarAsync(account, avatarKey);
                onlineCreatorAvatarLoads.Add(avatarKey, load);
                _ = InstallOnlineCreatorAvatarAsync(avatarKey, load);
            }

            var bitmap = await load;
            if (bitmap == null ||
                onlineCreatorAvatarLifetime.IsCancellationRequested ||
                !string.Equals(
                    avatar.RemoteImage.Tag as string,
                    avatarKey,
                    StringComparison.Ordinal))
                return;
            avatar.RemoteImage.Source = bitmap;
            AutomationProperties.SetName(avatar, AvaloniaLocalizationCatalog.Format("用户头像 · {0}", displayName));
        }
        catch (Exception exception) when (
            exception is OnlineApiException or HttpRequestException or
                OperationCanceledException or JsonException or IOException or
                InvalidDataException or ArgumentException)
        {
            if (string.Equals(
                    avatar.RemoteImage.Tag as string,
                    avatarKey,
                    StringComparison.Ordinal))
            {
                avatar.RemoteImage.Source = null;
                AutomationProperties.SetName(avatar, AvaloniaLocalizationCatalog.Format("默认头像 · {0}", displayName));
            }
        }
    }

    private async Task InstallOnlineCreatorAvatarAsync(
        string avatarKey,
        Task<Bitmap?> load)
    {
        Bitmap? bitmap = null;
        try
        {
            bitmap = await load;
            if (bitmap == null || onlineCreatorAvatarLifetime.IsCancellationRequested)
            {
                bitmap?.Dispose();
                return;
            }
            onlineCreatorAvatarCache[avatarKey] = bitmap;
            RefreshTimelineOnlineCreators();
        }
        catch (Exception exception) when (
            exception is OnlineApiException or HttpRequestException or
                OperationCanceledException or JsonException or IOException or
                InvalidDataException or ArgumentException)
        {
            bitmap?.Dispose();
            onlineCreatorAvatarLoads.Remove(avatarKey);
        }
    }

    private async Task EnsureOnlineRoomPresenceLoopAsync(Guid roomId)
    {
        await roomPresenceLifecycleGate.WaitAsync();
        try
        {
            if (roomPresenceRoomId == roomId &&
                roomPresenceLifetime is { IsCancellationRequested: false } &&
                !roomPresenceTask.IsCompleted)
                return;

            await StopOnlineRoomPresenceLoopCoreAsync();
            var lifetime = new CancellationTokenSource();
            var generation = checked(roomPresenceGeneration + 1);
            roomPresenceGeneration = generation;
            roomPresenceRoomId = roomId;
            roomPresenceLifetime = lifetime;
            roomPresenceTask = Task.Run(
                () => RunOnlineRoomPresenceLoopAsync(
                    roomId,
                    generation,
                    lifetime.Token),
                CancellationToken.None);
        }
        finally
        {
            roomPresenceLifecycleGate.Release();
        }
    }

    private async Task StopOnlineRoomPresenceLoopAsync()
    {
        await roomPresenceLifecycleGate.WaitAsync();
        try
        {
            await StopOnlineRoomPresenceLoopCoreAsync();
        }
        finally
        {
            roomPresenceLifecycleGate.Release();
        }
    }

    private async Task StopOnlineRoomPresenceLoopCoreAsync()
    {
        var lifetime = roomPresenceLifetime;
        var task = roomPresenceTask;
        roomPresenceLifetime = null;
        roomPresenceTask = Task.CompletedTask;
        roomPresenceRoomId = null;
        roomPresenceGeneration = checked(roomPresenceGeneration + 1);
        if (lifetime == null) return;

        try
        {
            lifetime.Cancel();
            await task.ConfigureAwait(false);
        }
        catch (OperationCanceledException) when (lifetime.IsCancellationRequested)
        {
        }
        finally
        {
            lifetime.Dispose();
        }
    }

    private async Task RunOnlineRoomPresenceLoopAsync(
        Guid roomId,
        long generation,
        CancellationToken cancellationToken)
    {
        var failures = 0;
        while (!cancellationToken.IsCancellationRequested)
        {
            var account = onlineAccountHost?.Session;
            if (account?.CurrentRoom?.Id != roomId) return;

            try
            {
                using var timeout = CancellationTokenSource.CreateLinkedTokenSource(
                    cancellationToken);
                timeout.CancelAfter(TimeSpan.FromSeconds(15));
                var requestClock = Stopwatch.StartNew();
                var live = await account.GetRoomLiveStateAsync(
                        roomChartSyncRoomId == roomId ? latestRoomMessageId : 0,
                        timeout.Token)
                    .ConfigureAwait(false);
                requestClock.Stop();
                if (live.Outcome != OnlineRoomLifecycleOutcome.Success ||
                    live.Value == null ||
                    account.CurrentRoom?.Id != roomId)
                    return;

                failures = 0;
                await Dispatcher.UIThread.InvokeAsync(
                    () => ApplyOnlineRoomLiveState(
                        roomId,
                        generation,
                        live.Value,
                        requestClock.ElapsedMilliseconds),
                    DispatcherPriority.Background,
                    cancellationToken);
                await Task.Delay(
                        TimeSpan.FromSeconds(3),
                        cancellationToken)
                    .ConfigureAwait(false);
            }
            catch (OperationCanceledException) when (
                cancellationToken.IsCancellationRequested)
            {
                return;
            }
            catch (Exception exception)
            {
                if (account.CurrentRoom?.Id != roomId) return;
                failures = Math.Min(failures + 1, 8);
                var retry = ComputeRoomPresenceRetryDelay(failures);
                await Dispatcher.UIThread.InvokeAsync(
                    () => PublishRoomPresenceRetry(
                        roomId,
                        generation,
                        exception,
                        retry),
                    DispatcherPriority.Background,
                    cancellationToken);
                await Task.Delay(retry, cancellationToken).ConfigureAwait(false);
            }
        }
    }

    private void ApplyOnlineRoomLiveState(
        Guid roomId,
        long generation,
        OnlineRoomLiveStateDto liveState,
        long elapsedMilliseconds)
    {
        if (roomPresenceRoomId != roomId ||
            roomPresenceGeneration != generation ||
            onlineAccountHost?.Session.CurrentRoom?.Id != roomId)
            return;

        if (roomChartSyncRoomId == roomId)
        {
            UpdateOnlineCreatorMembers(
                onlineAccountHost.Session,
                liveState.Members);
            AppendRoomChatMessages(
                liveState.Messages,
                liveState.LatestMessageId);
            roomCollaborationTitle.Text = liveState.Room.Name;
            roomMemberCountText.Text =
                $"{liveState.Room.MemberCount:N0} / " +
                $"{liveState.Room.MaximumMembers:N0}";
            roomChatStatusText.Text = string.Empty;
            onlineRoundTripLatencyMs = (int)Math.Clamp(
                elapsedMilliseconds,
                0,
                99_999);
            UpdateOnlineLatencyLabels();
            var previousAccess = roomAccessSnapshot;
            var currentAccess = CaptureRoomAccess(onlineAccountHost.Session);
            ApplyOnlineRoomPermissions();
            roomAccessSnapshot = currentAccess;
            if (previousAccess != null &&
                WindowsRoomPermissionNoticePolicy.Updated(
                    previousAccess,
                    currentAccess) is { } presentation)
                ShowRoomPermissionNotice(presentation);
        }
    }

    private void PublishRoomPresenceRetry(
        Guid roomId,
        long generation,
        Exception exception,
        TimeSpan retry)
    {
        if (roomPresenceRoomId != roomId ||
            roomPresenceGeneration != generation)
            return;

        onlineRoundTripLatencyMs = null;
        UpdateOnlineLatencyLabels();
        if (roomChartSyncRoomId == roomId)
        {
            roomChatStatusText.Text =
                AvaloniaLocalizationCatalog.Format("连接暂时中断，{0} 秒后重试…", Math.Max(1, (int)Math.Ceiling(retry.TotalSeconds)));
        }
        Debug.WriteLine(
            $"Room live polling failed and will retry: {exception.Message}");
    }

    private static TimeSpan ComputeRoomPresenceRetryDelay(int failureCount)
    {
        var exponent = Math.Min(5, Math.Max(0, failureCount - 1));
        var milliseconds = Math.Min(8_000, 400 * (1 << exponent));
        return TimeSpan.FromMilliseconds(
            milliseconds + Random.Shared.Next(80, 280));
    }

    private async void ChartingHeartbeatTimer_Tick(object? sender, EventArgs eventArgs)
    {
        if (chartingHeartbeatInProgress ||
            onlineAccountHost?.Session.IsAuthenticated != true ||
            chartingHeartbeatLifetime.IsCancellationRequested)
            return;

        chartingHeartbeatInProgress = true;
        activeChartingHeartbeatTask = RunChartingHeartbeatAsync();
        try
        {
            await activeChartingHeartbeatTask;
        }
        catch (OperationCanceledException) when (chartingHeartbeatLifetime.IsCancellationRequested)
        {
        }
        finally
        {
            chartingHeartbeatInProgress = false;
        }
    }

    private async Task RunChartingHeartbeatAsync()
    {
        var account = onlineAccountHost?.Session;
        if (account?.IsAuthenticated != true) return;

        using var timeout = CancellationTokenSource.CreateLinkedTokenSource(
            chartingHeartbeatLifetime.Token);
        timeout.CancelAfter(TimeSpan.FromSeconds(15));
        try
        {
            var tab = viewModel.ActiveTab;
            if (tab == null)
            {
                chartingHeartbeatStatus = "等待打开谱面";
                UpdateOnlineAccountUi();
                return;
            }

            var liveTabIds = viewModel.Tabs.Select(item => item.Id).ToHashSet();
            foreach (var staleId in chartingHeartbeatSessionIds.Keys
                         .Where(id => !liveTabIds.Contains(id))
                         .ToArray())
                chartingHeartbeatSessionIds.Remove(staleId);

            if (!chartingHeartbeatSessionIds.TryGetValue(tab.Id, out var editorSessionId))
            {
                editorSessionId = Guid.NewGuid();
                chartingHeartbeatSessionIds.Add(tab.Id, editorSessionId);
            }

            var isEditing =
                !libraryVisible &&
                !onlineSurfaceLayer.IsVisible &&
                !windowCloseTeardownStarted &&
                !windowClosePreflightComplete;
            var result = await account.SendChartingHeartbeatAsync(
                editorSessionId,
                tab.Session.ChangeSerial,
                isEditing,
                timeout.Token);
            if (result != null)
                chartingHeartbeatStatus = result.IsCounting
                    ? "正在累计有效制谱时长"
                    : "等待有效谱面操作";
        }
        catch (Exception exception) when (
            exception is OnlineApiException or HttpRequestException or System.Net.WebException or OperationCanceledException or
                JsonException)
        {
            if (exception is OperationCanceledException &&
                chartingHeartbeatLifetime.IsCancellationRequested)
                throw;
            chartingHeartbeatStatus = "计时同步暂时中断，将自动重试";
        }

        if (!windowCloseTeardownStarted && !windowClosePreflightComplete)
            UpdateOnlineAccountUi();
    }

    private void ReconcileChartingHeartbeatTimer()
    {
        if (windowCloseTeardownStarted ||
            windowClosePreflightComplete ||
            onlineAccountHost?.Session.IsAuthenticated != true)
        {
            chartingHeartbeatTimer.Stop();
            chartingHeartbeatStatus = "等待登录";
            return;
        }

        if (chartingHeartbeatStatus.Equals("等待登录", StringComparison.Ordinal))
            chartingHeartbeatStatus = "等待有效谱面操作";
        if (!chartingHeartbeatTimer.IsEnabled)
            chartingHeartbeatTimer.Start();
    }

    private async Task<RoomChartRollbackOutcome> RollbackCurrentRoomChartAsync(
        Guid snapshotId,
        CancellationToken cancellationToken)
    {
        var coordinator = roomChartSyncCoordinator ??
                          throw new InvalidOperationException("当前房间谱面尚未绑定编辑器。");
        var outcome = await coordinator.RollbackAsync(snapshotId, cancellationToken);
        if (!outcome.IgnoredStaleResponse)
            viewModel.SetStatus(
                AvaloniaLocalizationCatalog.Format("已回滚到快照“{0}”；安全快照 {1:D}", outcome.RestoredSnapshot?.Name, outcome.SafetySnapshotId));
        return outcome;
    }

    private async Task StopRoomChartSyncAsync(bool resetRetainedTab)
    {
        // Every caller must observe complete coordinator shutdown before a new
        // binding can be installed. Returning early here used to let a new room
        // race the old SSE/work loops while they were still draining.
        await roomChartSyncStopGate.WaitAsync();
        try
        {
            var coordinator = roomChartSyncCoordinator;
            roomChartSyncCoordinator = null;
            var tab = roomChartSyncTab;
            roomChartSyncTab = null;
            var retainedRoomNumber = roomChartSyncRoomNumber;
            var retainedRoomName = roomChartSyncRoomName;
            roomChartSyncRoomId = null;
            roomChartSyncRoomNumber = 0;
            roomChartSyncRoomName = string.Empty;
            onlineCreatorMembers = [];
            ResetRoomChatUi(reveal: false);
            timeline.SetOnlineCreators(
                new Dictionary<long, OnlineCreatorAppearance>());
            timeline.ResetRoomSyncDiagnostics();
            onlineRoundTripLatencyMs = null;
            roomChartFrozenResources = null;
            lastRoomChartPermissionErrorCode = null;
            roomAccessSnapshot = null;
            if (tab != null) tab.Session.Changed -= RoomChartSession_Changed;
            if (coordinator != null)
            {
                try
                {
                    await coordinator.StopAsync();
                }
                finally
                {
                    await coordinator.DisposeAsync();
                }
            }

            if (resetRetainedTab && tab != null && viewModel.Tabs.Contains(tab))
            {
                retainedOnlineRoomTabIds.Add(tab.Id);
                applyingRemoteChartSync = true;
                try
                {
                    WindowsOnlineRoomRetentionPolicy.PrepareForLocalEditing(tab);
                }
                finally
                {
                    applyingRemoteChartSync = false;
                }
                try
                {
                    _ = await viewModel.PreserveRoomDraftAsync(
                        tab.Id,
                        retainedRoomNumber,
                        retainedRoomName,
                        DateTimeOffset.UtcNow);
                }
                catch (Exception exception) when (
                    exception is IOException or UnauthorizedAccessException or
                        InvalidDataException)
                {
                    viewModel.SetStatus(
                        AvaloniaLocalizationCatalog.Format("房间留存仍在当前标签中，但持久缓存写入失败；请立即另存为：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
                }
            }
            UpdateUi();
        }
        finally
        {
            roomChartSyncStopGate.Release();
        }
    }

    private async Task RestoreRetainedOnlineRoomTabsAsync()
    {
        foreach (var tab in viewModel.Tabs.Where(tab =>
                     tab.IsPreservedRoomDraft ||
                     WindowsOnlineRoomRetentionPolicy.IsMaterializedRoomSource(
                         tab.SourcePath,
                         AvaloniaAppPaths.OnlineRoomDocumentRoot)))
        {
            retainedOnlineRoomTabIds.Add(tab.Id);
            var clearedAttribution =
                WindowsOnlineRoomRetentionPolicy.PrepareForLocalEditing(tab);
            if (tab.IsPreservedRoomDraft && clearedAttribution == 0) continue;

            try
            {
                _ = await viewModel.PreserveRoomDraftAsync(
                    tab.Id,
                    tab.IsPreservedRoomDraft ? tab.PreservedRoomNumber : 0,
                    tab.IsPreservedRoomDraft ? tab.PreservedRoomName : string.Empty,
                    tab.PreservedRoomEndedUtc is { } endedUtc
                        ? new DateTimeOffset(DateTime.SpecifyKind(endedUtc, DateTimeKind.Utc))
                        : DateTimeOffset.UtcNow);
            }
            catch (Exception exception) when (
                exception is IOException or UnauthorizedAccessException or
                    InvalidDataException)
            {
                viewModel.SetStatus(
                    AvaloniaLocalizationCatalog.Format("已恢复房间留存标签，但缓存清单升级失败；请另存为：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
            }
        }
    }

    private async Task PreserveRetainedRoomTabBeforeRebindAsync(
        string materializedChartPath,
        Guid roomId,
        CancellationToken cancellationToken)
    {
        var retainedTab = viewModel.Tabs.FirstOrDefault(tab =>
            retainedOnlineRoomTabIds.Contains(tab.Id) &&
            PathsEqual(tab.SourcePath, materializedChartPath));
        if (retainedTab == null) return;

        cancellationToken.ThrowIfCancellationRequested();
        var preservedPath = WindowsOnlineRoomRetentionPolicy.CreatePreservedSourcePath(
            AvaloniaAppPaths.OnlineRoomDocumentRoot,
            roomId,
            retainedTab.Id,
            DateTimeOffset.UtcNow,
            Path.GetExtension(retainedTab.SourcePath));
        Directory.CreateDirectory(Path.GetDirectoryName(preservedPath)!);
        var saved = await viewModel.SaveAsAndVerifyAsync(retainedTab.Id, preservedPath);
        if (saved?.StructurallyEqual != true || retainedTab.Session.IsDirty)
            throw new IOException("房间留存标签无法安全另存，已取消重新加入以避免覆盖本地成果。");
    }

    private async Task LeaveCurrentRoomBeforeShutdownAsync()
    {
        var account = onlineAccountHost?.Session;
        if (account?.CurrentRoom == null) return;

        try
        {
            using var timeout = new CancellationTokenSource(TimeSpan.FromSeconds(4));
            await account.LeaveCurrentRoomAsync(timeout.Token);
        }
        catch (Exception exception) when (
            exception is OnlineApiException or HttpRequestException or System.Net.WebException or OperationCanceledException or
                JsonException)
        {
            // WPF also treats room departure as best effort during shutdown.
            // The server lease/heartbeat path remains the final cleanup fallback.
        }
    }

    private static void ReplaceOnlineChartContent(ChartDocument target, ChartDocument source)
    {
        target.Metadata = source.Metadata.Clone();
        target.KeyCount = source.KeyCount;
        target.Notes.Clear();
        target.Notes.AddRange(source.Notes.Select(note => note.Clone()));
        target.Timing.Clear();
        target.Timing.AddRange(source.Timing.Select(timing => timing.Clone()));
    }

    private static WindowsRoomAccessSnapshot CaptureRoomAccess(
        OnlineAccountSession account) =>
        WindowsRoomPermissionNoticePolicy.Capture(
            account.CurrentMemberRole,
            account.CanEditMetadata,
            account.CanEditTiming,
            account.CanEditNotes);

    private static string FormatRoomChartRetryDelay(DateTimeOffset? retryAt)
    {
        var delay = retryAt is { } value ? value - DateTimeOffset.UtcNow : TimeSpan.Zero;
        if (delay < TimeSpan.Zero) delay = TimeSpan.Zero;
        return delay.TotalMinutes >= 1
            ? AvaloniaLocalizationCatalog.Format("{0:0} 分钟", Math.Ceiling(delay.TotalMinutes))
            : AvaloniaLocalizationCatalog.Format("{0:0} 秒", Math.Max(1, Math.Ceiling(delay.TotalSeconds)));
    }

    private static string FormatTransferBytes(long bytes) => bytes switch
    {
        >= 1024L * 1024 * 1024 => $"{bytes / (1024d * 1024 * 1024):0.##} GB",
        >= 1024L * 1024 => $"{bytes / (1024d * 1024):0.##} MB",
        >= 1024L => $"{bytes / 1024d:0.##} KB",
        _ => $"{bytes} B"
    };

    private async Task PollRoomInvitationsAsync()
    {
        var account = onlineAccountHost?.Session;
        if (roomInvitationPollInProgress || roomInvitationResponseInProgress ||
            pendingRoomInvitation != null || account?.IsAuthenticated != true ||
            windowClosePreflightInProgress || windowClosePreflightComplete)
            return;

        roomInvitationPollInProgress = true;
        try
        {
            using var timeout = new CancellationTokenSource(TimeSpan.FromSeconds(12));
            var invitation = (await account.GetRoomInvitationsAsync(timeout.Token))
                .OrderByDescending(item => item.ExpiresAt)
                .FirstOrDefault();
            if (invitation == null) return;

            if (account.CurrentRoom?.Id == invitation.RoomId)
            {
                // A previous accept may already have installed the one-shot room
                // while resource materialization was still finishing.
                return;
            }

            pendingRoomInvitation = invitation;
            roomInvitationTitleText.Text =
                AvaloniaLocalizationCatalog.Format("{0} 邀请你加入 {1}", invitation.InviterDisplayName, invitation.RoomName);
            roomInvitationDetailText.Text = "请选择同意或拒绝。";
            AutomationProperties.SetName(
                roomInvitationToast,
                AvaloniaLocalizationCatalog.Format("{0} 邀请你加入 {1}", invitation.InviterDisplayName, invitation.RoomName));
            AutomationProperties.SetHelpText(
                roomInvitationToast,
                AvaloniaLocalizationCatalog.Format("隐藏密码房可凭服务器邀请直接进入，不会显示或再次要求房间密码；contract={0}; width={1:0}; top={2:0}; right={3:0}; buttons={4:0}/{5:0}。", WindowsOnlineSurfaceParityPolicy.ContractVersion, WindowsOnlineSurfaceParityPolicy.InvitationToastWidth, WindowsOnlineSurfaceParityPolicy.InvitationToastTopMargin, WindowsOnlineSurfaceParityPolicy.InvitationToastRightMargin, WindowsOnlineSurfaceParityPolicy.InvitationToastButtonHeight, WindowsOnlineSurfaceParityPolicy.InvitationToastButtonGap));
            SetRoomInvitationActionsEnabled(true);
            roomInvitationToast.IsVisible = true;
        }
        catch (Exception exception) when (
            exception is OnlineApiException or HttpRequestException or System.Net.WebException or OperationCanceledException or
                JsonException)
        {
            // Invitation polling is background-only; the next two-second tick retries.
        }
        finally
        {
            roomInvitationPollInProgress = false;
        }
    }

    private async Task RespondToPendingRoomInvitationAsync(string action)
    {
        var invitation = pendingRoomInvitation;
        var account = onlineAccountHost?.Session;
        if (invitation == null || account?.IsAuthenticated != true ||
            roomInvitationResponseInProgress)
            return;

        if (account.CurrentRoom is { } currentRoom && currentRoom.Id != invitation.RoomId)
        {
            roomInvitationDetailText.Text = "请先退出当前联机房间，再接受新邀请。";
            return;
        }
        var entersRoom = action is "join" or "watch";
        if (!entersRoom && account.CurrentRoom?.Id == invitation.RoomId)
        {
            DismissPendingRoomInvitation();
            return;
        }

        roomInvitationResponseInProgress = true;
        SetRoomInvitationActionsEnabled(false);
        roomInvitationDetailText.Text = entersRoom
            ? "正在验证邀请并准备房间资源…"
            : "正在取消邀请…";
        try
        {
            using var timeout = new CancellationTokenSource(
                entersRoom ? TimeSpan.FromMinutes(10) : TimeSpan.FromSeconds(20));
            if (entersRoom && account.CurrentRoom is { } acceptedRoom)
            {
                // The invitation response may already have reached the server while
                // local resource preparation failed, or its HTTP response was lost.
                // Resume the accepted room directly; never consume the one-shot
                // invitation again or ask for a hidden-room password.
                DismissPendingRoomInvitation();
                await OpenConsumedRoomInvitationAsync(acceptedRoom, timeout.Token);
                return;
            }

            var response = await account.RespondToRoomInvitationAsync(
                invitation.Id,
                action,
                timeout.Token);
            if (!entersRoom || response.Kind == OnlineRoomInvitationResponseKind.Canceled)
            {
                DismissPendingRoomInvitation();
                return;
            }

            var room = response.Room ?? account.CurrentRoom ??
                       throw new OnlineApiException("服务器没有返回受邀房间资料。");
            DismissPendingRoomInvitation();
            await OpenConsumedRoomInvitationAsync(room, timeout.Token);
        }
        catch (Exception exception) when (
            exception is OnlineApiException or HttpRequestException or System.Net.WebException or OperationCanceledException or
                JsonException)
        {
            if (entersRoom &&
                account.CurrentRoom is { } joinedRoom &&
                joinedRoom.Id == invitation.RoomId)
            {
                DismissPendingRoomInvitation();
                using var recoveryTimeout = new CancellationTokenSource(TimeSpan.FromMinutes(10));
                await OpenConsumedRoomInvitationAsync(joinedRoom, recoveryTimeout.Token);
                return;
            }

            roomInvitationDetailText.Text = exception is OperationCanceledException
                ? "处理邀请超时，请重试。"
                : exception.Message;
        }
        finally
        {
            roomInvitationResponseInProgress = false;
            if (pendingRoomInvitation != null) SetRoomInvitationActionsEnabled(true);
        }
    }

    private async Task OpenConsumedRoomInvitationAsync(
        OnlineRoomSummaryDto room,
        CancellationToken cancellationToken)
    {
        try
        {
            var account = onlineAccountHost?.Session ??
                          throw new InvalidOperationException("联机账号会话不可用。");
            if (account.CurrentRoom?.Id != room.Id)
                throw new InvalidOperationException("当前房间已经变化，请重新进入。");
            cancellationToken.ThrowIfCancellationRequested();
            viewModel.SetStatus(
                AvaloniaLocalizationCatalog.Format("已接受“{0}”邀请；无需房间密码，正在检查资源缓存。", room.Name));
            await ShowHostedOnlineCommunityAsync(
                account,
                openCurrentRoom: true);
        }
        catch (Exception exception) when (
            exception is OnlineApiException or HttpRequestException or System.Net.WebException or JsonException or IOException or
                UnauthorizedAccessException or InvalidDataException or InvalidOperationException or
                OperationCanceledException)
        {
            viewModel.SetStatus(
                AvaloniaLocalizationCatalog.Format("已经加入“{0}”，但资源准备暂时失败：{1}。邀请已安全消费，不会再次要求密码。", room.Name, AvaloniaLocalizationCatalog.Text(exception.Message)));
        }
    }

    private void DismissPendingRoomInvitation()
    {
        pendingRoomInvitation = null;
        roomInvitationToast.IsVisible = false;
        roomInvitationTitleText.Text = string.Empty;
        roomInvitationDetailText.Text = string.Empty;
    }

    private void SetRoomInvitationActionsEnabled(bool enabled)
    {
        if (roomInvitationCancelButton != null) roomInvitationCancelButton.IsEnabled = enabled;
        if (roomInvitationJoinButton != null) roomInvitationJoinButton.IsEnabled = enabled;
    }

    private async Task<WindowsAppUpdateSnapshot> RefreshAppUpdateSnapshotAsync(
        CancellationToken cancellationToken)
    {
        if (onlineAccountHost == null)
            throw new InvalidOperationException(
                onlineHostError ?? "联机配置无效，无法检查客户端版本。");
        var configuration = await onlineAccountHost.Session.GetAppConfigurationAsync(
            cancellationToken);
        appConfiguration = configuration;
        appUpdateSnapshot = WindowsAppUpdatePolicy.Evaluate(
            configuration,
            WindowsOnlineAccountHost.ClientVersion);
        ApplyAppConfiguration(appUpdateSnapshot);
        return appUpdateSnapshot;
    }

    private void ApplyAppConfiguration(WindowsAppUpdateSnapshot snapshot)
    {
        aboutContentText.Text = string.IsNullOrEmpty(snapshot.Configuration.AboutContent)
            ? "LumaChart Studio"
            : snapshot.Configuration.AboutContent;
        aboutVersionText.Text = AvaloniaLocalizationCatalog.Format("版本 {0}", AvaloniaClientBuildInfo.DisplayVersion);
        settingsVersionText.Text = WindowsAppUpdatePolicy.SettingsVersionText(
            WindowsOnlineAccountHost.ClientVersion,
            snapshot);
    }

    private async Task RefreshUpdatePolicyAndShowAsync(
        bool blocksLogin,
        bool showWhenCurrent = true)
    {
        try
        {
            using var timeout = new CancellationTokenSource(
                TimeSpan.FromSeconds(WindowsAppUpdatePolicy.RequestTimeoutSeconds));
            var snapshot = await RefreshAppUpdateSnapshotAsync(timeout.Token);
            var presentation = WindowsAppUpdatePolicy.Present(
                snapshot,
                blocksLogin,
                showWhenCurrent);
            if (presentation != null)
                await ShowUpdatePromptAsync(presentation, snapshot.DownloadUri);
        }
        catch (Exception exception) when (
            exception is OnlineApiException or HttpRequestException or
                OperationCanceledException or JsonException or InvalidOperationException)
        {
            await ShowUpdatePromptAsync(
                WindowsAppUpdatePolicy.Failure(
                    WindowsOnlineAccountHost.ClientVersion,
                    blocksLogin),
                downloadUri: null);
        }
    }

    private Task ShowUpdatePromptAsync(
        WindowsAppUpdatePresentation presentation,
        Uri? downloadUri)
    {
        ArgumentNullException.ThrowIfNull(presentation);
        updateTitleText.Text = presentation.Title;
        updateVersionText.Text = presentation.VersionText;
        updateNoticeText.Text = presentation.Notice;
        updatePromptBlocksLogin = presentation.BlocksLogin;
        if (updateLaterButton != null)
            updateLaterButton.Content = presentation.LaterButtonText;
        if (updateDownloadButton != null)
        {
            updateDownloadButton.Content = presentation.DownloadButtonText;
            updateDownloadButton.IsEnabled = presentation.DownloadEnabled;
            updateDownloadButton.Tag = presentation.DownloadEnabled ? downloadUri : null;
        }
        AutomationProperties.SetName(
            updateLayer,
            $"{presentation.Title}：{presentation.VersionText}：{presentation.Notice}");
        AutomationProperties.SetHelpText(
            updateLayer,
            $"BlocksLogin={presentation.BlocksLogin}; " +
            $"DownloadEnabled={presentation.DownloadEnabled}");
        updatePromptCompletion ??= new TaskCompletionSource<bool>(
            TaskCreationOptions.RunContinuationsAsynchronously);
        updateLayer.IsVisible = true;
        updateLaterButton?.Focus();
        return updatePromptCompletion.Task;
    }

    private void CloseUpdatePrompt()
    {
        updateLayer.IsVisible = false;
        if (updateDownloadButton != null) updateDownloadButton.Tag = null;
        var completion = updatePromptCompletion;
        updatePromptCompletion = null;
        completion?.TrySetResult(true);
        if (!updatePromptBlocksLogin) timeline.Focus();
    }

    private void OpenCurrentUpdateDownload()
    {
        if (updateDownloadButton?.Tag is Uri uri) OpenExternalUrl(uri.AbsoluteUri);
    }

    private async Task ShowAboutAsync()
    {
        aboutVersionText.Text = AvaloniaLocalizationCatalog.Format("版本 {0}", AvaloniaClientBuildInfo.DisplayVersion);
        aboutContentText.Text = appConfiguration?.AboutContent is { Length: > 0 } content
            ? content
            : "LumaChart Studio";
        if (aboutAdminButton != null)
            aboutAdminButton.IsVisible =
                onlineAccountHost?.Session.IsAuthenticated == true &&
                onlineAccountHost.Session.CanUseAdminApi;
        aboutLayer.IsVisible = true;
        if (onlineAccountHost == null) return;
        try
        {
            using var timeout = new CancellationTokenSource(TimeSpan.FromSeconds(6));
            await RefreshAppUpdateSnapshotAsync(timeout.Token);
            if (aboutAdminButton != null)
                aboutAdminButton.IsVisible =
                    onlineAccountHost.Session.IsAuthenticated &&
                    onlineAccountHost.Session.CanUseAdminApi;
        }
        catch (Exception exception) when (
            exception is OnlineApiException or HttpRequestException or
                OperationCanceledException or JsonException)
        {
            // The WPF 1.1.0 About surface remains available offline with the
            // last configuration fetched during this process.
        }
    }

    private async Task ShowIssueReportAsync()
    {
        var settings = displayScaleController.CurrentSettings;
        var environment = WindowsIssueReportPolicy.BuildEnvironment(
            WindowsOnlineAccountHost.ClientVersion,
            RenderScaling,
            settings.UiScale,
            settings.FontScale,
            ClientSize.Width,
            ClientSize.Height,
            onlineAccountHost?.Session.IsAuthenticated == true,
            onlineAccountHost?.Session.CurrentRoom != null);
        var dialog = new WindowsIssueReportDialog(
            onlineAccountHost?.Session,
            environment,
            settings.UiScale,
            settings.FontScale);
        await dialog.ShowDialog<OnlineIssueReportDto?>(this);
        timeline.Focus();
    }

    private void CloseAbout()
    {
        aboutLayer.IsVisible = false;
        timeline.Focus();
    }

    private async Task OpenOwnerAppConfigurationAsync()
    {
        if (onlineAccountHost?.Session.IsAuthenticated != true ||
            !onlineAccountHost.Session.CanUseAdminApi)
            return;
        aboutLayer.IsVisible = false;
        try
        {
            await ShowHostedOnlineCommunityAsync(
                onlineAccountHost.Session,
                openAdminConfiguration: true);
        }
        catch (Exception exception)
        {
            // Button handler boundary, as for the account entry: a failing
            // hosted surface must not take the editor down with it.
            Debug.WriteLine($"Owner app configuration failed: {exception}");
            if (windowCloseTeardownStarted) return;
            UpdateOnlineAccountUi();
            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("账号功能不可用：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
        }
    }

    private void OpenExternalUrl(string value)
    {
        var uri = WindowsExternalUriPolicy.Resolve(value);
        if (uri == null) return;
        _ = OpenExternalUrlAsync(uri);
    }

    private async Task OpenExternalUrlAsync(Uri uri)
    {
        try
        {
            await PlatformExternalUriServices.OpenAsync(uri);
        }
        catch (Exception exception) when (
            exception is InvalidOperationException or System.ComponentModel.Win32Exception)
        {
            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("无法打开链接：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
        }
    }

    private async Task<bool> EnsureLoginVersionAllowedAsync()
    {
        if (onlineAccountHost == null) return false;
        try
        {
            using var timeout = new CancellationTokenSource(
                TimeSpan.FromSeconds(WindowsAppUpdatePolicy.RequestTimeoutSeconds));
            var snapshot = await RefreshAppUpdateSnapshotAsync(timeout.Token);
            if (!snapshot.BlocksLogin) return true;
            var presentation = WindowsAppUpdatePolicy.Present(
                snapshot,
                blocksLogin: true,
                showWhenCurrent: true);
            if (presentation != null)
                await ShowUpdatePromptAsync(presentation, snapshot.DownloadUri);
            return false;
        }
        catch (Exception exception) when (
            exception is OnlineApiException or HttpRequestException or
                OperationCanceledException or JsonException)
        {
            // A transient public-config failure does not invent a local block.
            // The authoritative login route still returns client_update_required
            // and its handler below converts that response to the blocking prompt.
            return true;
        }
    }

    private async Task RestoreOnlineAccountAsync()
    {
        if (onlineAccountHost == null)
        {
            UpdateOnlineAccountUi();
            return;
        }

        onlineRestoreCancellation?.Cancel();
        onlineRestoreCancellation?.Dispose();
        var restoreCancellation = new CancellationTokenSource(
            TimeSpan.FromSeconds(
                WindowsOnlineSurfaceParityPolicy.StartupRestoreTimeoutSeconds));
        onlineRestoreCancellation = restoreCancellation;
        titleUserNameText.Text = "账号";
        titleUserStateText.Text = "恢复中";
        try
        {
            await onlineAccountHost.Session.TryRestoreAsync(restoreCancellation.Token);
        }
        catch (Exception exception) when (
            exception is OnlineApiException or HttpRequestException or System.Net.WebException or OperationCanceledException or
                JsonException)
        {
            if (exception is not OperationCanceledException ||
                !restoreCancellation.IsCancellationRequested)
                viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("账号会话暂时无法恢复：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
        }
        finally
        {
            UpdateOnlineAccountUi();
        }
    }

    private async Task RestoreStartupOnlineAccountAsync(bool showStartupChoice)
    {
        if (onlineAccountHost == null)
        {
            UpdateOnlineAccountUi();
            return;
        }

        WindowsAppUpdateSnapshot? startupSnapshot = null;
        try
        {
            titleUserNameText.Text = "账号";
            titleUserStateText.Text = "检查版本";
            using var timeout = new CancellationTokenSource(
                TimeSpan.FromSeconds(WindowsAppUpdatePolicy.RequestTimeoutSeconds));
            startupSnapshot = await RefreshAppUpdateSnapshotAsync(timeout.Token);
        }
        catch (Exception exception) when (
            exception is OnlineApiException or HttpRequestException or
                OperationCanceledException or JsonException)
        {
            viewModel.SetStatus("暂时无法检查客户端版本，可重试登录或离线使用。");
        }

        if (startupSnapshot?.BlocksLogin == true)
        {
            startupAccountChoiceHandled = true;
            titleUserNameText.Text = "Guest";
            titleUserStateText.Text = "需要更新";
            viewModel.SetStatus(
                AvaloniaLocalizationCatalog.Format("需要更新到 {0} 才能登录，也可离线使用。", startupSnapshot.Configuration.MinimumLoginVersion));
            var blocked = WindowsAppUpdatePolicy.Present(
                startupSnapshot,
                blocksLogin: true,
                showWhenCurrent: true);
            if (blocked != null)
                await ShowUpdatePromptAsync(blocked, startupSnapshot.DownloadUri);
            UpdateOnlineAccountUi();
            return;
        }

        await RestoreOnlineAccountAsync();
        if (startupSnapshot?.IsUpdateAvailable == true)
        {
            var available = WindowsAppUpdatePolicy.Present(
                startupSnapshot,
                blocksLogin: false,
                showWhenCurrent: false);
            if (available != null)
                await ShowUpdatePromptAsync(available, startupSnapshot.DownloadUri);
        }

        if (startupAccountChoiceHandled ||
            !showStartupChoice ||
            !WindowsOnlineSurfaceParityPolicy.RequiresStartupAccountChoice(
                evidenceChartMode,
                onlineAccountHost.Session.IsAuthenticated))
            return;

        startupAccountChoiceHandled = true;
        var accepted = await ShowHostedOnlineAccountAsync(
            onlineAccountHost.Session);
        UpdateOnlineAccountUi();
        if (accepted && onlineAccountHost.Session.IsAuthenticated)
        {
            var user = onlineAccountHost.Session.CurrentUser;
            viewModel.SetStatus(
                AvaloniaLocalizationCatalog.Format("已登录 {0}", user?.DisplayName ?? user?.Username ?? AvaloniaLocalizationCatalog.Text("账号")));
        }
        else
        {
            viewModel.SetStatus("已选择离线使用");
        }
    }

    private async Task ShowOnlineAccountAsync(
        OnlineCommunityHostedSection requestedSection =
            OnlineCommunityHostedSection.Profile)
    {
        HideFriendsPanel();
        startupAccountChoiceHandled = true;
        pendingOnlineCommunitySection = requestedSection;
        if (activeHostedOnlineCommunitySurface?.NavigateHosted(
                requestedSection) == true)
            return;
        if (onlineSurfaceCompletion != null || onlineAccountEntryInProgress)
            return;
        if (onlineAccountHost == null)
        {
            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("账号功能不可用：{0}", onlineHostError ?? AvaloniaLocalizationCatalog.Text("联机配置无效")));
            return;
        }

        // Claimed synchronously before the first await: the login version check
        // can take several seconds, and a second click during it used to reach
        // BeginOnlineSurface while the first surface was already active.
        onlineAccountEntryInProgress = true;
        try
        {
            var wasAuthenticated = onlineAccountHost.Session.IsAuthenticated;
            if (!wasAuthenticated)
            {
                var accepted = await ShowHostedOnlineAccountAsync(
                    onlineAccountHost.Session);
                UpdateOnlineAccountUi();
                if (!accepted || !onlineAccountHost.Session.IsAuthenticated) return;
                var loggedInUser = onlineAccountHost.Session.CurrentUser;
                viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("已登录 {0}", loggedInUser?.DisplayName ?? loggedInUser?.Username ?? AvaloniaLocalizationCatalog.Text("账号")));
            }

            if (onlineAccountHost.Session.IsAuthenticated)
                await ShowHostedOnlineCommunityAsync(
                    onlineAccountHost.Session,
                    initialSection: pendingOnlineCommunitySection);
            UpdateOnlineAccountUi();
            if (onlineAccountHost.Session.IsAuthenticated)
            {
                var user = onlineAccountHost.Session.CurrentUser;
                viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("账号资料已同步：{0}", user?.DisplayName ?? user?.Username ?? AvaloniaLocalizationCatalog.Text("账号")));
            }
            else if (!onlineAccountHost.Session.IsAuthenticated)
            {
                viewModel.SetStatus("已退出登录");
            }
        }
        catch (Exception exception)
        {
            // Button handlers are async lambdas; a fault escaping here would reach
            // the dispatcher's fatal handler and end the process without the
            // unsaved-work preflight. The editor itself is unaffected.
            Debug.WriteLine($"Online account entry failed: {exception}");
            if (windowCloseTeardownStarted) return;
            UpdateOnlineAccountUi();
            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("账号功能不可用：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
        }
        finally
        {
            onlineAccountEntryInProgress = false;
        }
    }

    private async Task<bool> ShowHostedOnlineAccountAsync(
        OnlineAccountSession session)
    {
        // Reserve the single hosted-surface slot before the version check awaits,
        // so a concurrent entry is rejected instead of throwing afterwards.
        var completion = BeginOnlineSurface();
        if (completion == null) return false;
        OnlineAccountDialog? surface = null;
        try
        {
            if (!await EnsureLoginVersionAllowedAsync()) return false;
            // Window closing completes the reserved slot while the check awaited.
            if (completion.Task.IsCompleted) return false;
            surface = new OnlineAccountDialog(
                session,
                result => completion.TrySetResult(result),
                async _ =>
                {
                    await RefreshUpdatePolicyAndShowAsync(
                        blocksLogin: true,
                        showWhenCurrent: true);
                    completion.TrySetResult(false);
                });
            var content = surface.DetachHostedContent();
            var host = new Grid();
            host.Children.Add(content);

            var offline = PrimaryButton(
                "不登录，离线使用  →",
                (_, _) => completion.TrySetResult(false));
            ApplyWpfPrimaryButtonStyle(offline);
            offline.Width = WindowsOnlineSurfaceParityPolicy.OfflineButtonWidth;
            offline.Height = WindowsOnlineSurfaceParityPolicy.OfflineButtonHeight;
            offline.FontSize = 13;
            offline.FontWeight = FontWeight.SemiBold;
            offline.Background = new SolidColorBrush(Color.Parse("#38676C"));
            offline.BorderBrush = new SolidColorBrush(Color.Parse("#79B8BD"));
            offline.BorderThickness = new Thickness(1.5);
            offline.HorizontalAlignment = HorizontalAlignment.Right;
            offline.VerticalAlignment = VerticalAlignment.Bottom;
            offline.Padding = new Thickness(14, 7);
            AutomationProperties.SetAutomationId(
                offline,
                "OnlineAccount.ContinueOffline");
            var offlineHost = new Border
            {
                HorizontalAlignment = HorizontalAlignment.Right,
                VerticalAlignment = VerticalAlignment.Bottom,
                Margin = new Thickness(
                0,
                0,
                WindowsOnlineSurfaceParityPolicy.OfflineButtonRightMargin,
                    WindowsOnlineSurfaceParityPolicy.OfflineButtonBottomMargin),
                Padding = new Thickness(5),
                Background = new SolidColorBrush(Color.Parse("#E6111315")),
                BorderBrush = new SolidColorBrush(Color.Parse("#475B60")),
                BorderThickness = new Thickness(1),
                CornerRadius = new CornerRadius(7),
                Child = offline
            };
            host.Children.Add(offlineHost);
            ShowOnlineSurface(host, "OnlineAccount.Layer");
            var activation = surface.ActivateHostedAsync();
            var firstCompleted = await Task.WhenAny(activation, completion.Task);
            if (ReferenceEquals(firstCompleted, completion.Task))
            {
                // Offline use must win immediately even while an unreachable
                // endpoint is still loading the login captcha. The finally
                // block cancels the hosted surface lifetime; observe a late
                // fault so it cannot become an unobserved task exception.
                _ = activation.ContinueWith(
                    static task => _ = task.Exception,
                    CancellationToken.None,
                    TaskContinuationOptions.OnlyOnFaulted |
                    TaskContinuationOptions.ExecuteSynchronously,
                    TaskScheduler.Default);
                return await completion.Task;
            }
            await activation;
            return await completion.Task;
        }
        finally
        {
            surface?.DisposeHostedSurface();
            EndOnlineSurface(completion);
        }
    }

    private async Task<bool> ShowHostedOnlineCommunityAsync(
        OnlineAccountSession session,
        bool openAdminConfiguration = false,
        bool openCurrentRoom = false,
        OnlineCommunityHostedSection initialSection =
            OnlineCommunityHostedSection.Profile)
    {
        var completion = BeginOnlineSurface();
        if (completion == null) return false;
        OnlineCommunityDialog? surface = null;
        try
        {
            surface = new OnlineCommunityDialog(
                session,
                PrepareCurrentOnlineRoomUploadAsync,
                PrepareCurrentOnlineRoomDownloadAsync,
                OpenCurrentOnlineRoomChartAsync,
                RollbackCurrentRoomChartAsync,
                result => completion.TrySetResult(result),
                this,
                openAdminConfiguration);
            activeHostedOnlineCommunitySurface = surface;
            var content = surface.DetachHostedContent();
            var host = new Grid
            {
                RowDefinitions = new RowDefinitions(
                    $"{WindowsOnlineSurfaceParityPolicy.CommunityHeaderHeight},*"),
                Background = new SolidColorBrush(Color.Parse("#111315"))
            };
            var header = new Border
            {
                Background = new SolidColorBrush(Color.Parse("#171A1D")),
                BorderBrush = new SolidColorBrush(Color.Parse("#30363A")),
                BorderThickness = new Thickness(0, 0, 0, 1),
                Padding = new Thickness(20, 0)
            };
            var headerGrid = new Grid
            {
                ColumnDefinitions = new ColumnDefinitions("*,Auto")
            };
            var title = new StackPanel
            {
                Orientation = Orientation.Horizontal,
                VerticalAlignment = VerticalAlignment.Center
            };
            title.Children.Add(new TextBlock
            {
                Text = "联机写谱",
                FontSize = 22,
                FontWeight = FontWeight.SemiBold,
                Foreground = new SolidColorBrush(Color.Parse("#E2E6E7"))
            });
            headerGrid.Children.Add(title);
            var close = PrimaryButton(
                "返回编辑器",
                (_, _) => completion.TrySetResult(true));
            close.Padding = new Thickness(14, 7);
            ApplyWpfToolButtonStyle(close);
            AutomationProperties.SetAutomationId(
                close,
                "OnlineCommunity.Header.Close");
            Grid.SetColumn(close, 1);
            headerGrid.Children.Add(close);
            header.Child = headerGrid;
            host.Children.Add(header);
            Grid.SetRow(content, 1);
            host.Children.Add(content);
            ShowOnlineSurface(host, "OnlineCommunity.Layer");
            await surface.ActivateHostedAsync(openCurrentRoom, initialSection);
            return await completion.Task;
        }
        finally
        {
            surface?.DisposeHostedSurface();
            if (ReferenceEquals(activeHostedOnlineCommunitySurface, surface))
                activeHostedOnlineCommunitySurface = null;
            EndOnlineSurface(completion);
        }
    }

    private TaskCompletionSource<bool>? BeginOnlineSurface()
    {
        // Only one hosted account/community surface can own the layer. A second
        // entry (double click, startup restore racing a click) is ignored rather
        // than thrown, because every caller is an async UI handler.
        if (onlineSurfaceCompletion != null)
            return null;
        if (spacePanGestureState.Cancel())
            timeline.EndSpacePanModifier();
        oneShotShortcutState.Clear();
        var completion = new TaskCompletionSource<bool>(
            TaskCreationOptions.RunContinuationsAsynchronously);
        onlineSurfaceCompletion = completion;
        return completion;
    }

    private void ShowOnlineSurface(Control content, string automationId)
    {
        onlineSurfaceContent.Children.Clear();
        var hosted = new AutomationBorder { Child = content };
        AutomationProperties.SetAutomationId(hosted, automationId);
        onlineSurfaceContent.Children.Add(hosted);
        onlineSurfaceLayer.IsVisible = true;
    }

    private void EndOnlineSurface(TaskCompletionSource<bool> completion)
    {
        if (!ReferenceEquals(onlineSurfaceCompletion, completion)) return;
        onlineSurfaceLayer.IsVisible = false;
        onlineSurfaceContent.Children.Clear();
        onlineSurfaceCompletion = null;
        UpdateOnlineAccountUi();
    }

    private void ReconcileFollowNotificationSession()
    {
        var currentUserId = onlineAccountHost?.Session.IsAuthenticated == true
            ? onlineAccountHost.Session.CurrentUser?.Id ?? 0
            : 0;
        if (followNotificationUserId == currentUserId) return;
        followNotificationUserId = currentUserId;
        followNotificationRetryNotBefore = DateTimeOffset.MinValue;
        ResetFollowNotificationToastUi();
        if (currentUserId > 0) _ = PollFollowNotificationsAsync();
    }

    private async Task PollFollowNotificationsAsync()
    {
        var session = onlineAccountHost?.Session;
        if (session?.IsAuthenticated != true ||
            followNotificationPollInProgress ||
            windowCloseTeardownStarted ||
            DateTimeOffset.UtcNow < followNotificationRetryNotBefore)
            return;
        followNotificationPollInProgress = true;
        try
        {
            using var timeout = CancellationTokenSource.CreateLinkedTokenSource(
                followNotificationPollingCancellation.Token);
            timeout.CancelAfter(TimeSpan.FromSeconds(5));
            _ = await session.PollNotificationsAsync(timeout.Token);
        }
        catch (OnlineApiException exception) when (
            exception.StatusCode == System.Net.HttpStatusCode.TooManyRequests)
        {
            var retryAfter = exception.RetryAfter.GetValueOrDefault(
                TimeSpan.FromMilliseconds(
                    WindowsTransientToastParityPolicy.FollowPollIntervalMilliseconds));
            followNotificationRetryNotBefore = DateTimeOffset.UtcNow +
                                               (retryAfter > TimeSpan.Zero
                                                   ? retryAfter
                                                   : TimeSpan.FromMilliseconds(
                                                       WindowsTransientToastParityPolicy
                                                           .FollowPollIntervalMilliseconds));
        }
        catch (Exception exception) when (
            exception is OnlineApiException or HttpRequestException or
                OperationCanceledException or JsonException)
        {
            Debug.WriteLine(
                $"Follow notification refresh failed: {exception.Message}");
        }
        finally
        {
            followNotificationPollInProgress = false;
        }
    }

    private void OnlineAccountSession_Changed(object? sender, EventArgs eventArgs)
    {
        if (Dispatcher.UIThread.CheckAccess())
        {
            ReconcileFollowNotificationSession();
            ReconcileChartingHeartbeatTimer();
            UpdateOnlineAccountUi();
            _ = ReconcileOnlineRoomBindingAsync();
            _ = PollRoomInvitationsAsync();
        }
        else
        {
            Dispatcher.UIThread.Post(() =>
            {
                ReconcileFollowNotificationSession();
                ReconcileChartingHeartbeatTimer();
                UpdateOnlineAccountUi();
                _ = ReconcileOnlineRoomBindingAsync();
                _ = PollRoomInvitationsAsync();
            });
        }
    }

    private async Task ReconcileOnlineRoomBindingAsync()
    {
        var generation = ++onlineRoomBindingReconcileGeneration;
        var currentRoomId = onlineAccountHost?.Session.CurrentRoom?.Id;
        if (currentRoomId is { } activeRoomId)
            await EnsureOnlineRoomPresenceLoopAsync(activeRoomId);
        else
            await StopOnlineRoomPresenceLoopAsync();

        // Session changes arrive in bursts and each starts a reconcile. One that
        // was overtaken while awaiting must not act on the room id it read
        // before the await; the newest reconcile owns the decision.
        if (generation != onlineRoomBindingReconcileGeneration) return;
        currentRoomId = onlineAccountHost?.Session.CurrentRoom?.Id;
        if (roomChartSyncRoomId == null) return;
        if (currentRoomId == roomChartSyncRoomId)
        {
            ApplyOnlineRoomPermissions();
            return;
        }
        await StopRoomChartSyncAsync(resetRetainedTab: true);
        viewModel.SetStatus("房间已关闭或成员资格已结束；保留标签仍可本地编辑和保存。");
    }

    private void UpdateOnlineAccountUi()
    {
        if (onlineAccountButton == null) return;
        if (!SimpleManiaProduct.OnlineEnabled)
        {
            titleUserNameText.Text = "本地创作";
            titleUserStateText.Text = "离线可用";
            onlineAccountButton.IsEnabled = false;
            ToolTip.SetTip(onlineAccountButton, "本地谱面编辑，无需账号");
            return;
        }
        ReconcileChartingHeartbeatTimer();
        if (onlineAccountHost == null)
        {
            titleUserNameText.Text = "配置错误";
            titleUserStateText.Text = "联机不可用";
            BindRemoteAvatar(titleUserAvatar, null, "Guest");
            ToolTip.SetTip(onlineAccountButton, onlineHostError);
            return;
        }

        var user = onlineAccountHost.Session.CurrentUser;
        if (!onlineAccountHost.Session.IsAuthenticated)
        {
            DismissPendingRoomInvitation();
            HideFriendsPanel();
        }
        else if (friendsPanel.IsVisible &&
                 friendsList.ItemsSource is IEnumerable<OnlinePlayerProfileDto>
                     currentFriends)
        {
            var snapshot = currentFriends.ToArray();
            friendsList.ItemsSource = null;
            friendsList.ItemsSource = snapshot;
        }
        titleUserNameText.Text = onlineAccountHost.Session.IsAuthenticated
            ? user?.DisplayName ?? user?.Username ?? "账号"
            : "Guest";
        titleUserStateText.Text = onlineAccountHost.Session.IsAuthenticated
            ? "在线"
            : "离线";
        BindRemoteAvatar(
            titleUserAvatar,
            onlineAccountHost.Session.IsAuthenticated ? user?.AvatarKey : null,
            titleUserNameText.Text);
        AutomationProperties.SetName(
            onlineAccountButton,
            onlineAccountHost.Session.IsAuthenticated
                ? AvaloniaLocalizationCatalog.Format("账号 · {0}", titleUserNameText.Text)
                : "账号 · 登录");
        ToolTip.SetTip(
            onlineAccountButton,
            onlineAccountHost.Session.IsAuthenticated
                ? $"{user?.Username} · {user?.Role} · {chartingHeartbeatStatus}"
                : "登录 LumaChart 账号");
    }

    private async Task PickAndOpenChartAsync()
    {
        // Reached from buttons and Ctrl+O. The platform picker and the Android
        // import staging can fault (activity recreation, storage full); the
        // per-file open below already reports its own failures.
        try
        {
            await PickAndOpenChartCoreAsync();
        }
        catch (Exception exception)
        {
            Debug.WriteLine($"Picking a chart failed: {exception}");
            if (windowCloseTeardownStarted) return;
            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("打开谱面失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
        }
    }

    private async Task PickAndOpenChartCoreAsync()
    {
        if (PlatformFileImportServices.Current is { } platform)
        {
            var importedPath = await platform.PickChartFileAsync();
            if (!string.IsNullOrWhiteSpace(importedPath))
                await OpenChartOrArchiveAsync(importedPath);
            return;
        }

        var evidenceStartLocation = await ResolveEvidenceFilePickerStartLocationAsync();
        var files = await StorageProvider.OpenFilePickerAsync(new FilePickerOpenOptions
        {
            Title = "打开 Malody / osu! 谱面或谱包",
            AllowMultiple = true,
            SuggestedStartLocation = evidenceStartLocation,
            FileTypeFilter =
            [
                new FilePickerFileType("LumaChart 支持的谱面与谱包")
                    { Patterns = ["*.mc", "*.osu", "*.mcz", "*.osz"] },
                new FilePickerFileType("Malody MC") { Patterns = ["*.mc"] },
                new FilePickerFileType("osu!mania") { Patterns = ["*.osu"] },
                new FilePickerFileType("Malody / osu! 谱包") { Patterns = ["*.mcz", "*.osz"] }
            ]
        });
        foreach (var file in files)
        {
            var path = file.TryGetLocalPath();
            if (!string.IsNullOrWhiteSpace(path)) await OpenChartOrArchiveAsync(path);
        }
    }

    /// <summary>
    /// Shows a single-file picker and returns a path the shared import
    /// pipelines can read. Windows pickers already return real paths and are
    /// unaffected; Android's Storage Access Framework returns a content
    /// document with no path, which is staged into an app-private root first.
    /// </summary>
    private async Task<string?> PickLocalFileAsync(
        FilePickerOpenOptions options,
        PickedFileRetention retention,
        CancellationToken cancellationToken = default)
    {
        var files = await StorageProvider.OpenFilePickerAsync(options);
        return await PlatformPickedFiles.ResolveLocalPathAsync(
            files.FirstOrDefault(),
            retention,
            cancellationToken);
    }

    private async Task<IStorageFolder?> ResolveEvidenceFilePickerStartLocationAsync()
    {
        if (!evidenceChartMode || evidenceFilePickerStartDirectory == null) return null;
        var folder = await StorageProvider.TryGetFolderFromPathAsync(
            evidenceFilePickerStartDirectory);
        return folder ?? throw new InvalidOperationException(
            $"Evidence file-picker start directory is unavailable: {evidenceFilePickerStartDirectory}");
    }

    private async Task<IStorageFolder?> ResolveFolderPickerStartLocationAsync(
        string evidenceOperation)
    {
        ReportLibraryLauncherEvidencePhase(
            $"{evidenceOperation}:resolve-start-location");
        var path = evidenceFocusLibraryLauncher &&
                   evidenceFilePickerStartDirectory != null
            ? evidenceFilePickerStartDirectory
            : viewModel.WorkspaceRoot;
        if (string.IsNullOrWhiteSpace(path) || !Directory.Exists(path))
            return null;
        var folder = await StorageProvider.TryGetFolderFromPathAsync(path);
        ReportLibraryLauncherEvidencePhase(
            $"{evidenceOperation}:start-location-resolved:{folder != null}");
        if (folder != null || !evidenceFocusLibraryLauncher) return folder;
        throw new InvalidOperationException(
            $"Evidence folder-picker start directory is unavailable: {path}");
    }

    private void ReportLibraryLauncherEvidencePhase(string phase)
    {
        if (!evidenceFocusLibraryLauncher) return;
        AutomationProperties.SetHelpText(
            libraryStatusText,
            $"LibraryLauncherEvidence={phase}");
    }

    /// <summary>
    /// Save As for a platform whose save picker cannot return a writable path.
    /// The copy stays in the chart's own app-owned folder so its audio and
    /// images remain beside it and the tab can keep editing the new file;
    /// reaching storage outside the sandbox stays Export's job.
    /// </summary>
    private async Task<string?> PickInAppSaveAsPathAsync(
        DesktopChartTab tab,
        string inAppSaveAsRoot,
        string defaultExtension)
    {
        var directory = InAppSaveAsPolicy.ResolveDirectory(tab.SourcePath, inAppSaveAsRoot);
        Directory.CreateDirectory(directory);
        var folderLabel = Path.GetFileName(directory.TrimEnd(
            Path.DirectorySeparatorChar,
            Path.AltDirectorySeparatorChar));

        while (true)
        {
            var result = await new InAppSaveAsDialog(
                    Path.GetFileNameWithoutExtension(tab.SourcePath),
                    "." + defaultExtension,
                    AvaloniaLocalizationCatalog.Format("保存到应用曲库：{0}", folderLabel),
                    displayScaleSettings.UiScale,
                    displayScaleSettings.FontScale)
                .ShowDialog<InAppSaveAsResult?>(this);
            if (result == null) return null;

            var fileName = InAppSaveAsPolicy.SanitizeFileName(result.FileName);
            if (fileName == null)
            {
                await ShowSettingsMessageAsync(
                    "文件名无效",
                    "请输入不含路径分隔符的文件名。");
                continue;
            }

            var path = Path.Combine(directory, fileName + result.Extension);
            if (PathsEqual(path, tab.SourcePath))
            {
                await ShowSettingsMessageAsync(
                    "无法另存",
                    "所选名称与当前谱面相同。请换一个名称，或直接使用保存。");
                continue;
            }

            if (File.Exists(path) &&
                !await ShowSettingsConfirmationAsync(
                    "覆盖已有文件",
                    AvaloniaLocalizationCatalog.Format("{0}{1} 已存在，继续将覆盖它。", fileName, result.Extension),
                    "覆盖",
                    dangerous: true))
                continue;

            return path;
        }
    }

    private Task<SaveRoundTripResult?> PickAndSaveAsAsync(
        Guid? tabId = null,
        bool preflightComplete = false)
    {
        // Resolve the tab now: a save still holding the slot may activate
        // another tab before this Save As gets its turn.
        var requestedTabId = tabId ?? viewModel.ActiveTab?.Id;
        if (requestedTabId is not { } id)
            return Task.FromResult<SaveRoundTripResult?>(null);
        return RunExclusiveSaveAsync(
            () => PickAndSaveAsCoreAsync(id, preflightComplete));
    }

    private async Task<SaveRoundTripResult?> PickAndSaveAsCoreAsync(
        Guid? tabId = null,
        bool preflightComplete = false)
    {
        var tab = tabId.HasValue
            ? viewModel.Tabs.FirstOrDefault(candidate => candidate.Id == tabId.Value)
            : viewModel.ActiveTab;
        if (tab == null) return null;
        if (!ReferenceEquals(viewModel.ActiveTab, tab)) viewModel.Activate(tab.Id);
        if (!ApplyMetadataEditor(enforceCommunityRules: true))
        {
            // Same explicit reason as Save (see SaveAndVerifyWithPreflightCoreAsync).
            if (lastMetadataApplyError is { Length: > 0 } metadataError)
                await ShowSettingsMessageAsync(
                    "保存失败",
                    AvaloniaLocalizationCatalog.Format("谱面信息未应用：{0}", AvaloniaLocalizationCatalog.Text(metadataError)));
            return null;
        }

        var sourceExtension = Path.GetExtension(tab.SourcePath);
        var defaultExtension = sourceExtension.Equals(".osu", StringComparison.OrdinalIgnoreCase)
            ? "osu"
            : "mc";
        string? path;
        if (PlatformFileExportServices.Current?.InAppSaveAsRoot is { } inAppSaveAsRoot)
        {
            path = await PickInAppSaveAsPathAsync(tab, inAppSaveAsRoot, defaultExtension);
        }
        else
        {
            var mcType = new FilePickerFileType("Malody MC") { Patterns = ["*.mc"] };
            var osuType = new FilePickerFileType("osu!mania") { Patterns = ["*.osu"] };
            var suggestedType = defaultExtension == "osu" ? osuType : mcType;
            IStorageFolder? suggestedStartLocation = null;
            var sourceDirectory = Path.GetDirectoryName(tab.SourcePath);
            if (!string.IsNullOrWhiteSpace(sourceDirectory) && Directory.Exists(sourceDirectory))
                suggestedStartLocation = await StorageProvider.TryGetFolderFromPathAsync(sourceDirectory);
            var destination = await StorageProvider.SaveFilePickerAsync(new FilePickerSaveOptions
            {
                Title = "另存谱面",
                SuggestedFileName = Path.GetFileNameWithoutExtension(tab.SourcePath),
                SuggestedStartLocation = suggestedStartLocation,
                DefaultExtension = defaultExtension,
                FileTypeChoices = [mcType, osuType],
                SuggestedFileType = suggestedType,
                ShowOverwritePrompt = true
            });
            path = destination?.TryGetLocalPath();
        }

        if (string.IsNullOrWhiteSpace(path)) return null;
        if (!preflightComplete && !await EnsureChartCanSaveAsync(tab)) return null;

        var previousSourcePath = tab.SourcePath;
        var previousChartOffset = keySoundSettings.GetChartOffset(previousSourcePath);
        try
        {
            var saved = await viewModel.SaveAsAndVerifyAsync(tab.Id, path);
            if (saved?.StructurallyEqual == true)
            {
                var clearedRetainedState =
                    retainedOnlineRoomTabIds.Remove(tab.Id);
                if (!string.Equals(
                        previousSourcePath,
                        tab.SourcePath,
                        StringComparison.OrdinalIgnoreCase) &&
                    previousChartOffset != 0)
                {
                    keySoundSettings = keySoundSettings
                        .SetChartOffset(tab.SourcePath, previousChartOffset)
                        .SetChartOffset(previousSourcePath, 0);
                    keySoundSettingsDirty = true;
                    ScheduleKeySoundSettingsSave();
                }
                if (IsCurrentKeySoundTab(tab))
                {
                    RefreshKeySoundSettingsUi();
                    ObserveKeySoundDocumentState(tab);
                    ScheduleKeySoundPlanRebuild();
                }
                if (clearedRetainedState) RebuildTabs();
            }
            return saved;
        }
        catch (Exception exception)
        {
            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("另存谱面失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
            WindowsNativeMessageBox.Show(
                this,
                WindowsLibraryLauncherParityPolicy.CreateOperationError(
                    "无法保存原谱面；软件旁缓存已保留",
                    exception));
            return null;
        }
    }

    private async Task PickAndExportChartAsync(CancellationToken cancellationToken)
    {
        cancellationToken.ThrowIfCancellationRequested();
        var tab = viewModel.ActiveTab;
        if (tab == null) return;

        var optionsDialog = new ChartExportDialog(
            displayScaleSettings.UiScale,
            displayScaleSettings.FontScale);
        if (!await optionsDialog.ShowDialog<bool>(this) ||
            optionsDialog.Options is not { } options)
            return;
        cancellationToken.ThrowIfCancellationRequested();

        var plan = ChartExportPlanner.Create(options);
        var extension = plan.DestinationExtension;
        var fileTypeLabel = (options.Format, options.Mode) switch
        {
            (ChartExportFormat.Malody, ChartExportMode.SingleChart) => "Malody 谱面",
            (ChartExportFormat.OsuMania, ChartExportMode.SingleChart) => "osu!mania 谱面",
            (ChartExportFormat.Malody, _) => "Malody 谱包",
            _ => "osu! 谱包"
        };
        var fileType = new FilePickerFileType(fileTypeLabel)
        {
            Patterns = ["*" + extension]
        };
        var suggestedName = ChartExportFileNamePolicy.SuggestedFileName(
            tab.Session.Document,
            extension);
        if (PlatformFileExportServices.Current is { } exportPlatform)
        {
            await ExportThroughPlatformDestinationAsync(
                exportPlatform,
                tab,
                options,
                suggestedName,
                extension,
                cancellationToken);
            return;
        }

        var exportStartLocation = await ResolveChartExportStartLocationAsync(
            tab.SourcePath);
        var destination = await StorageProvider.SaveFilePickerAsync(new FilePickerSaveOptions
        {
            Title = "选择导出位置",
            SuggestedFileName = suggestedName,
            SuggestedStartLocation = exportStartLocation,
            DefaultExtension = extension[1..],
            FileTypeChoices = [fileType],
            SuggestedFileType = fileType,
            ShowOverwritePrompt = true
        });
        var path = destination?.TryGetLocalPath();
        if (string.IsNullOrWhiteSpace(path))
        {
            if (exportButton != null)
                AutomationProperties.SetHelpText(
                    exportButton,
                    "导出文件选择器未返回可用的本地写入路径");
            return;
        }
        var destinationResolution =
            WindowsChartExportDialogParityPolicy.ResolveDestinationPath(
                path,
                extension);
        if (exportButton != null)
            AutomationProperties.SetHelpText(
                exportButton,
                $"Selected={destinationResolution.SelectedPath}; " +
                $"Destination={destinationResolution.DestinationPath}; " +
                $"Corrected={destinationResolution.ExtensionCorrected}; " +
                $"Overwrite={destinationResolution.RequiresOverwriteConfirmation}");
        if (destinationResolution.RequiresOverwriteConfirmation)
        {
            var overwriteResult = await new ChartExportOverwriteDialog(
                    destinationResolution.DestinationPath,
                    displayScaleSettings.UiScale,
                    displayScaleSettings.FontScale)
                .ShowDialog<bool>(this);
            if (exportButton != null)
                AutomationProperties.SetHelpText(
                    exportButton,
                    $"Selected={destinationResolution.SelectedPath}; " +
                    $"Destination={destinationResolution.DestinationPath}; " +
                    $"Corrected={destinationResolution.ExtensionCorrected}; " +
                    $"Overwrite={destinationResolution.RequiresOverwriteConfirmation}; " +
                    $"OverwriteResult={overwriteResult}");
            if (!overwriteResult)
                return;
        }
        path = destinationResolution.DestinationPath;
        cancellationToken.ThrowIfCancellationRequested();

        var previousStatus = viewModel.Status;
        try
        {
            var progress = new Progress<ChartExportProgress>(value =>
                viewModel.SetStatus($"{value.Stage}  {value.Completed}/{value.Total}"));
            var result = await viewModel.ExportChartAsync(
                tab.Id,
                path,
                options,
                progress,
                cancellationToken);
            viewModel.SetStatus(previousStatus);
            if (cancellationToken.IsCancellationRequested) return;

            WindowsNativeMessageBox.Show(
                this,
                WindowsChartExportDialogParityPolicy.CreateSuccessResult(
                    result.DestinationPath));
            await RevealExportedFileAsync(result.DestinationPath);
        }
        catch
        {
            viewModel.SetStatus(previousStatus);
            throw;
        }
    }

    /// <summary>
    /// Export on a platform whose destination is not a writable filesystem path.
    /// The shared pipeline still writes and verifies a real file; the platform
    /// only supplies the staging path and moves the finished bytes across, so
    /// the export itself stays identical to the desktop one.
    /// </summary>
    private async Task ExportThroughPlatformDestinationAsync(
        IPlatformFileExportService platform,
        DesktopChartTab tab,
        ChartExportOptions options,
        string suggestedName,
        string extension,
        CancellationToken cancellationToken)
    {
        var destination = await platform.PickExportDestinationAsync(
            suggestedName,
            extension,
            cancellationToken);
        if (destination == null) return;

        cancellationToken.ThrowIfCancellationRequested();
        var previousStatus = viewModel.Status;
        await using (destination)
        {
            try
            {
                var progress = new Progress<ChartExportProgress>(value =>
                    viewModel.SetStatus($"{value.Stage}  {value.Completed}/{value.Total}"));
                await viewModel.ExportChartAsync(
                    tab.Id,
                    destination.StagingPath,
                    options,
                    progress,
                    cancellationToken);
                if (cancellationToken.IsCancellationRequested) return;

                viewModel.SetStatus("正在写入导出位置…");
                await destination.CommitAsync(cancellationToken);
                viewModel.SetStatus(previousStatus);
                WindowsNativeMessageBox.Show(
                    this,
                    WindowsChartExportDialogParityPolicy.CreateSuccessResult(
                        destination.DisplayName));
            }
            catch
            {
                viewModel.SetStatus(previousStatus);
                throw;
            }
        }
    }

    private async Task BeginChartExportAsync()
    {
        if (exportInProgress) return;
        if (viewModel.ActiveTab is not { } tab ||
            !TryApplyPendingMetadataEditor(
                tab,
                enforceCommunityRules: false))
            return;

        exportInProgress = true;
        if (exportButton != null) exportButton.IsEnabled = false;
        var cancellation = new CancellationTokenSource();
        activeExportCancellation = cancellation;
        var operation = ExecuteChartExportSafelyAsync(cancellation.Token);
        activeExportTask = operation;
        try
        {
            await operation;
        }
        finally
        {
            if (ReferenceEquals(activeExportTask, operation)) activeExportTask = Task.CompletedTask;
            if (ReferenceEquals(activeExportCancellation, cancellation))
                activeExportCancellation = null;
            cancellation.Dispose();
            exportInProgress = false;
            if (exportButton != null) exportButton.IsEnabled = viewModel.ActiveTab != null;
        }
    }

    private async Task ExecuteChartExportSafelyAsync(CancellationToken cancellationToken)
    {
        try
        {
            await PickAndExportChartAsync(cancellationToken);
        }
        catch (OperationCanceledException)
        {
            viewModel.SetStatus("导出已取消");
        }
        catch (Exception exception)
        {
            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("导出失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
            if (windowClosePreflightInProgress) return;

            try
            {
                WindowsNativeMessageBox.Show(
                    this,
                    WindowsChartExportDialogParityPolicy.CreateFailureResult(
                        "导出失败",
                        exception.Message));
            }
            catch
            {
                // The status line remains the final fallback if the native picker
                // or result-window infrastructure itself is unavailable.
            }
        }
    }

    private async Task<IStorageFolder?> ResolveChartExportStartLocationAsync(
        string sourcePath)
    {
        var evidenceLocation = await ResolveEvidenceFilePickerStartLocationAsync();
        if (evidenceLocation != null) return evidenceLocation;

        var downloads = await StorageProvider.TryGetWellKnownFolderAsync(
            WellKnownFolder.Downloads);
        if (downloads != null) return downloads;

        var conventionalDownloads = Path.Combine(
            Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),
            "Downloads");
        if (Directory.Exists(conventionalDownloads))
        {
            downloads = await StorageProvider.TryGetFolderFromPathAsync(
                conventionalDownloads);
            if (downloads != null) return downloads;
        }

        var sourceDirectory = Path.GetDirectoryName(sourcePath);
        return !string.IsNullOrWhiteSpace(sourceDirectory) &&
               Directory.Exists(sourceDirectory)
            ? await StorageProvider.TryGetFolderFromPathAsync(sourceDirectory)
            : null;
    }

    private Task RevealExportedFileAsync(string path)
    {
        // Formal Windows GUI evidence must not open or steal focus with Explorer.
        // The switch is accepted only through the existing evidence command-line
        // surface; ordinary launches continue through the WPF-compatible reveal.
        if (evidenceChartMode && evidenceSuppressExportReveal)
            return Task.CompletedTask;

        // Off Windows there is nothing to reveal the file in, and the export
        // itself already succeeded — the platform export destination put the
        // bytes where the user chose. Reporting "无法打开导出目录" there turns a
        // completed export into what reads like a failure.
        if (!OperatingSystem.IsWindows()) return Task.CompletedTask;

        try
        {
            var fullPath = Path.GetFullPath(path);
            Process.Start(new ProcessStartInfo
            {
                FileName = "explorer.exe",
                Arguments = $"/select,\"{fullPath}\"",
                UseShellExecute = true
            });
        }
        catch (Exception exception)
        {
            const string title = "导出已完成，但无法打开导出目录";
            viewModel.SetStatus($"{title}：{exception.Message}");
            WindowsNativeMessageBox.Show(
                this,
                WindowsChartExportDialogParityPolicy.CreateFailureResult(
                    title,
                    exception.Message));
        }

        return Task.CompletedTask;
    }

    private async Task PickAndOpenProjectAsync()
    {
        ReportLibraryLauncherEvidencePhase("open-project:invoked");
        var startLocation = await ResolveFolderPickerStartLocationAsync(
            "open-project");
        ReportLibraryLauncherEvidencePhase("open-project:show-picker");
        var folders = await StorageProvider.OpenFolderPickerAsync(new FolderPickerOpenOptions
        {
            Title = WindowsLibraryLauncherParityPolicy.OpenProjectPickerTitle,
            AllowMultiple = false,
            SuggestedStartLocation = startLocation
        });
        ReportLibraryLauncherEvidencePhase(
            $"open-project:picker-returned:{folders.Count}");
        var path = folders.FirstOrDefault()?.TryGetLocalPath();
        if (string.IsNullOrWhiteSpace(path)) return;
        try
        {
            var chartPaths = await viewModel.InspectProjectDirectoryAsync(path);
            foreach (var chartPath in chartPaths) await OpenChartAsync(chartPath);
            viewModel.SetStatus(chartPaths.Count == 1
                ? AvaloniaLocalizationCatalog.Format("已打开项目：{0}", Path.GetFileName(path))
                : AvaloniaLocalizationCatalog.Format("已打开项目：{0} · {1:N0} 张谱面标签", Path.GetFileName(path), chartPaths.Count));
        }
        catch (DesktopProjectDirectoryValidationException exception)
        {
            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("打开项目失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
            WindowsNativeMessageBox.Show(
                this,
                WindowsLibraryLauncherParityPolicy.CreateProjectDirectoryNotice(
                    exception));
        }
        catch (Exception exception)
        {
            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("打开项目失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
            WindowsNativeMessageBox.Show(
                this,
                WindowsLibraryLauncherParityPolicy.CreateOperationError(
                    "无法打开项目目录",
                    exception));
        }
    }

    private async Task OpenChartOrArchiveAsync(string path)
    {
        var extension = Path.GetExtension(path);
        if (extension.Equals(".mcz", StringComparison.OrdinalIgnoreCase) ||
            extension.Equals(".osz", StringComparison.OrdinalIgnoreCase))
        {
            try
            {
                var imported = await viewModel.ImportArchiveAsync(path);
                ShowLibraryScanErrorIfNeeded();
                var open = await new ArchiveImportDialog(
                        imported.Archive.DestinationRoot,
                        imported.SupportedChartPaths.Count,
                        imported.UnsupportedChartPaths.Count,
                        imported.BrokenChartPaths.Count,
                        displayScaleSettings.UiScale,
                        displayScaleSettings.FontScale)
                    .ShowDialog<bool>(this);
                if (open)
                {
                    foreach (var chartPath in imported.SupportedChartPaths)
                        await OpenChartAsync(chartPath);
                    viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("已处理谱包中的 {0:N0} 张有效谱面", imported.SupportedChartPaths.Count));
                }
            }
            catch (Exception exception)
            {
                viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("导入谱包失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
                WindowsNativeMessageBox.Show(
                    this,
                    WindowsLibraryLauncherParityPolicy.CreateOperationError(
                        "无法导入谱包",
                        exception));
            }
            return;
        }

        await OpenChartAsync(path);
    }

    private async Task<bool> OpenChartAsync(string path)
    {
        try
        {
            path = Path.GetFullPath(path);
            var existing = viewModel.Tabs.FirstOrDefault(tab =>
                string.Equals(tab.SourcePath, path, StringComparison.OrdinalIgnoreCase));
            if (existing != null)
            {
                viewModel.Activate(existing.Id);
                ShowEditorSurface();
                return true;
            }

            if (Path.GetExtension(path).Equals(".osu", StringComparison.OrdinalIgnoreCase))
            {
                var mode = await viewModel
                    .TryGetSynchronizedSuspendedOsuTimingModeAsync(path);
                if (!mode.HasValue && shortcutSettings.Profile == EditorInteractionProfile.OsuMania && !evidenceShowOsuImportDialog)
                    mode = OsuNoteTimingImportMode.PreserveMilliseconds;
                if (!mode.HasValue)
                {
                    var choice = await new OsuImportModeDialog(
                            Path.GetFileName(path),
                            displayScaleSettings.UiScale,
                            displayScaleSettings.FontScale)
                        .ShowDialog<OsuImportChoice>(this);
                    mode = choice switch
                    {
                        OsuImportChoice.Calibrate =>
                            OsuNoteTimingImportMode.CalibrateCommonSubdivisions,
                        OsuImportChoice.Preserve =>
                            OsuNoteTimingImportMode.PreserveMilliseconds,
                        _ => (OsuNoteTimingImportMode?)null
                    };
                }
                if (!mode.HasValue) return false;
                await viewModel.OpenAsync(path, mode.Value);
                ShowEditorSurface();
                return true;
            }

            await viewModel.OpenAsync(path);
            ShowEditorSurface();
            return true;
        }
        catch (Exception exception)
        {
            viewModel.SetStatus(AvaloniaLocalizationCatalog.Format("打开谱面失败：{0}", AvaloniaLocalizationCatalog.Text(exception.Message)));
            WindowsNativeMessageBox.Show(
                this,
                WindowsLibraryLauncherParityPolicy.CreateOperationError(
                    "无法打开谱面",
                    exception));
            return false;
        }
    }

