    private void ShowLibrary(bool focusSearch = false)
    {
        audioAnalysisCancellation?.Cancel();
        libraryVisible = true;
        UpdateUi();
        if (!focusSearch) return;
        Dispatcher.UIThread.Post(() =>
        {
            if (!libraryVisible) return;
            librarySearchBox.Focus();
