    private void ShowEditorSurface(bool focusTimeline = true)
    {
        if (viewModel.ActiveTab == null) return;
        libraryVisible = false;
        UpdateUi();
        if (!focusTimeline) return;
        Dispatcher.UIThread.Post(() =>
        {
