    private void AddTimelineToolButton(StackPanel toolbar, TimelineTool tool, string text)
    {
        var button = PrimaryButton(text, (_, _) => SetTimelineTool(tool));
        button.Padding = new Thickness(10, 6);
        AutomationProperties.SetName(button, $"Timeline Tool {tool}");
        AutomationProperties.SetAutomationId(button, $"Timeline.Tool.{tool}");
        timelineToolButtons.Add(tool, button);
        toolbar.Children.Add(button);
    }

    private void SetTimelineTool(TimelineTool tool)
    {
        var session = viewModel.ActiveTab?.Session;
        if (!WindowsAvaloniaEditorInputPolicy.CanUseTimelineTool(session, tool))
        {
            viewModel.SetStatus(tool == TimelineTool.Erase
                ? "当前谱面没有编辑 Note 或 Timing / Effect 的权限；选择工具仍可使用"
                : "当前谱面没有编辑 Note 的权限；选择工具仍可使用");
            return;
        }
        if (tool == TimelineTool.Erase &&
            session != null &&
            (session.Selection.Count > 0 || timeline.SelectedTimingIds.Count > 0))
            DeleteMixedSelection();
        timeline.Tool = tool;
        UpdateTimelineToolButtons();
        timeline.Focus();
    }

    private void UpdateTimelineToolButtons()
    {
        RefreshFixedTools();
        var session = viewModel.ActiveTab?.Session;
        foreach (var pair in timelineToolButtons)
        {
            var selected = pair.Key == timeline.Tool;
            pair.Value.IsEnabled = WindowsAvaloniaEditorInputPolicy.CanUseTimelineTool(session, pair.Key);
            pair.Value.Background = selected ? AccentBrush : RaisedBrush;
            pair.Value.Foreground = selected ? Brushes.Black : Brushes.White;
            pair.Value.BorderBrush = selected ? AccentBrush : StrokeBrush;
            AutomationProperties.SetHelpText(
                pair.Value,
                selected ? "当前编辑工具" : "可切换编辑工具");
        }
        foreach (var pair in quickTimelineToolButtons)
        {
            var selected = pair.Key == timeline.Tool;
            pair.Value.IsEnabled = WindowsAvaloniaEditorInputPolicy.CanUseTimelineTool(session, pair.Key);
            ApplyQuickPaletteModeState(pair.Value, selected);
            AutomationProperties.SetHelpText(
                pair.Value,
                selected ? "当前编辑工具" : "可切换编辑工具");
        }
    }

    private static void ApplyQuickPaletteModeState(Button button, bool active)
    {
        button.Background = active ? QuickActiveBrush : Brushes.Transparent;
        button.Foreground = active ? QuickActiveForegroundBrush : Brushes.White;
        button.BorderBrush = active ? QuickActiveBorderBrush : Brushes.Transparent;
    }

    private static Button LibraryLauncherButton(
        string glyph,
        string title,
        string description,
        EventHandler<RoutedEventArgs> handler,
        bool primary,
        Thickness margin)
    {
        var button = new Button
        {
            Height = 52,
            Width = 468,
            Margin = margin,
            HorizontalContentAlignment = HorizontalAlignment.Center,
            Padding = new Thickness(12, 7),
            Content = new StackPanel
            {
                Orientation = Orientation.Horizontal,
                Children =
                {
                    new TextBlock
                    {
                        Text = glyph,
                        FontSize = 20,
                        Width = 38,
                        Foreground = primary
                            ? Brushes.White
                            : new SolidColorBrush(Color.Parse("#AFC2C4")),
                        VerticalAlignment = VerticalAlignment.Center
                    },
                    new StackPanel
                    {
                        VerticalAlignment = VerticalAlignment.Center,
                        Children =
                        {
                            new TextBlock
                            {
                                Text = title,
                                FontSize = 14,
                                FontWeight = FontWeight.SemiBold
                            },
                            new TextBlock
                            {
                                Text = description,
                                FontSize = 10,
                                Foreground = primary
                                    ? new SolidColorBrush(Color.Parse("#D0DEDF"))
                                    : new SolidColorBrush(Color.Parse("#87969A")),
                                Margin = new Thickness(0, 3, 0, 0)
                            }
                        }
                    }
                }
            }
        };
        if (primary)
            ApplyWpfPrimaryButtonStyle(button);
        else
            ApplyWpfToolButtonStyle(button);
        button.Click += handler;
        AutomationProperties.SetName(button, $"{title}；{description}");
        return button;
    }

    private static Button PrimaryButton(string text, EventHandler<RoutedEventArgs> handler)
    {
        var button = new Button
        {
            Content = text,
            Padding = new Thickness(12, 7),
            Background = RaisedBrush,
            Foreground = Brushes.White,
            BorderBrush = StrokeBrush,
            BorderThickness = new Thickness(1),
            CornerRadius = new CornerRadius(4)
        };
        button.Click += handler;
        return button;
    }

    private static Button CommandIconTextButton(
        string text,
        string geometry,
        EventHandler<RoutedEventArgs> handler,
        bool primary = false,
        double iconWidth = 16)
    {
        var button = CommandButton(string.Empty, handler);
        IBrush foreground = primary
            ? Brushes.White
            : new SolidColorBrush(Color.Parse("#ADB5B9"));
        var icon = new AvaloniaPath
        {
            Width = iconWidth,
            Height = 16,
            Data = Geometry.Parse(geometry),
            Stroke = foreground,
            StrokeThickness = 1.5,
            Stretch = Stretch.Uniform,
            VerticalAlignment = VerticalAlignment.Center
        };
        var label = new TextBlock
        {
            Text = text,
            Foreground = primary ? Brushes.White : new SolidColorBrush(Color.Parse("#D0D4D6")),
            Margin = new Thickness(7, 0, 0, 0),
            VerticalAlignment = VerticalAlignment.Center,
            FontWeight = primary ? FontWeight.SemiBold : FontWeight.Normal
        };
        button.Content = new StackPanel
        {
            Orientation = Orientation.Horizontal,
            Children = { icon, label }
        };
        if (primary)
        {
            button.Background = new SolidColorBrush(Color.Parse("#38676C"));
            button.BorderBrush = new SolidColorBrush(Color.Parse("#4A777B"));
            button.Foreground = Brushes.White;
        }
        return button;
    }

    private static Button CommandIconButton(
        string geometry,
        EventHandler<RoutedEventArgs> handler,
        bool filled = false,
        double width = 36)
    {
        var button = CommandButton(string.Empty, handler);
        button.Width = width;
        button.Height = 34;
        button.Padding = new Thickness(7);
        var foreground = new SolidColorBrush(Color.Parse("#ADB5B9"));
        button.Content = new AvaloniaPath
        {
            Width = 18,
            Height = 16,
            Data = Geometry.Parse(geometry),
            Fill = filled ? foreground : null,
            Stroke = filled ? null : foreground,
            StrokeThickness = 1.6,
            Stretch = Stretch.Uniform
        };
        return button;
    }

    private static Button CommandGlyphButton(
        string glyph,
