    }

    private sealed record PreparedOnlineRoomUpload(
        Guid TabId,
        long ChangeSerial,
        WindowsOnlineRoomUploadPackage Package);
}

public static class WindowsAvaloniaEditorInputPolicy
{
    public static bool CanUseTimelineTool(EditorSession? session, TimelineTool tool) => tool switch
    {
        TimelineTool.Select => true,
        TimelineTool.Erase => session != null && !session.IsReadOnly &&
                              (session.CanEditNotes || session.CanEditTiming),
        TimelineTool.Tap or TimelineTool.Hold =>
            session != null && !session.IsReadOnly && session.CanEditNotes,
        _ => false
    };

    public static bool PreserveNotesForTimingListSelection(KeyModifiers modifiers) =>
        modifiers.HasFlag(KeyModifiers.Shift);

    public static bool IsTextEditingShortcut(Key key, KeyModifiers modifiers) =>
        key is Key.Delete or Key.Back ||
        modifiers.HasFlag(KeyModifiers.Control) &&
        key is Key.C or Key.V or Key.X or Key.Z or Key.Y or Key.A;

    public static bool DeferToTextInputMethod(Key reportedKey, KeyModifiers modifiers)
    {
        if (reportedKey is Key.System or Key.ImeProcessed or Key.DeadCharProcessed)
            return true;
        return !modifiers.HasFlag(KeyModifiers.Control) &&
               !modifiers.HasFlag(KeyModifiers.Alt) &&
               !modifiers.HasFlag(KeyModifiers.Meta);
    }

    public static bool IsTextEditingControl(Control? control) =>
        FindTextEditingControl(control) != null;

    public static Control? FindTextEditingControl(Control? control)
    {
        for (var current = control; current != null; current = current.Parent as Control)
            if (current is TextBox or ComboBox) return current;
        return null;
    }
}

public readonly record struct WindowsOnlineRoomEditorAccess(
    bool IsReadOnly,
    bool CanEditMetadata,
    bool CanEditTiming,
    bool CanEditNotes);

public static class WindowsOnlineRoomPermissionPolicy
{
    public static WindowsOnlineRoomEditorAccess Resolve(
        bool isOwner,
        string? memberRole,
        bool canEditMetadata,
        bool canEditTiming,
        bool canEditNotes)
    {
        if (isOwner)
            return new WindowsOnlineRoomEditorAccess(false, true, true, true);
        if (memberRole?.Equals("viewer", StringComparison.OrdinalIgnoreCase) == true)
            return new WindowsOnlineRoomEditorAccess(true, false, false, false);
        return new WindowsOnlineRoomEditorAccess(
            false,
            canEditMetadata,
            canEditTiming,
            canEditNotes);
    }
}
